  entries = {
    ["draenor"] = {
      title = "Draenor", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Rise of the Horde", "호드의 등장", "La montée de la Horde", "Aufstieg der Horde", "部落的崛起", "El levantamiento de la Horda", "Возвышение Орды", "A Ascensão da Horda" } }, { area = 72 }, { read = { "The Invasion of Draenor", "드레노어 침략", "L'invasion de Draenor", "Die Invasion von Draenor", "远征德拉诺", "La invasión de Draenor", "Вторжение в Дренор", "A Invasão de Draenor", "遠征德拉諾" } } },
      also = { "orcs", "the-dark-portal", "shadow-council", "burning-legion", "frostwolf-clan", "the-lost-ones" },
      text = {
        { "Before the orcs came through the Portal they lived on a green world of their own, called Draenor, in clans that roamed and hunted and quarrelled much as clans do. Their shamans spoke with the spirits of the elements and of the ancestors, and of all of them the elder shaman Ner'zhul was the most respected. They shared the world with the draenei, exiles from somewhere else, who built their cities in the cliffs and gave the orcs little reason for war." },
        { "The demon Kil'jaeden gave them one. He worked on Ner'zhul until the shaman's people grew hungry for blood, and when Ner'zhul balked at the last step, the demon found a more willing pupil in his apprentice, Gul'dan. The shamans became warlocks. Arenas were built for the clans to fight in. Gul'dan gathered the chieftains and they drank the blood of the pit lord Mannoroth. Of them all, the book in our library says, only Durotan of the Frostwolves refused." },
        { "The Horde that followed all but wiped out the draenei, and the warlocks' magic began to kill the land itself, until the prairies the orcs had roamed for generations were red and barren. By the time the Dark Portal opened, there was little left on Draenor worth staying for. The exiles at the Harborage in the Swamp of Sorrows say they came from that world. I would be careful what you say to them about orcs." },
      },
    },
    ["sargeras-and-the-betrayal"] = {
      title = "Sargeras and the Betrayal", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Sargeras and the Betrayal", "살게라스와 배반", "Sargeras et la trahison", "Sargeras und der Verrat", "萨格拉斯的背叛", "Sargeras y la traición", "Саргерас и Предательство", "Sargeras e a Traição", "薩格拉斯的背叛" } } },
      also = { "burning-legion", "the-ordering", "dreadlords", "the-guardians-of-tirisfal", "the-sundering" },
      text = {
        { "Sargeras was once the Titans' champion. When demons began to slip out of the Twisting Nether into the worlds the Titans had ordered, the Pantheon chose its greatest warrior, a noble giant of molten bronze, to hunt them, and he did so for countless ages. He defeated the eredar, sorcerers who turned whole worlds into demons, and the nathrezim, who turned nations against one another, and he locked both away." },
        { "Their corruption stayed with him. He fell into a brooding despair, then into the belief that order itself was folly and chaos the only truth, and at last into hatred of the Titans themselves, whom he blamed for creation's failure. His bronze skin split open on a furnace of rage. He broke the prisons he had built and set the demons free, and they bowed to him." },
        { "From the eredar he chose two lieutenants: Kil'jaeden the Deceiver, to find the darkest races and bring them in, and Archimonde the Defiler, to lead the army. He called that army the Burning Legion. How many worlds it has burned since, the book in our library says, is still unclear. We know of one it has not managed to finish." },
      },
    },
    ["the-battle-of-mount-hyjal"] = {
      title = "The Battle of Mount Hyjal", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Archimonde's Return and the Flight to Kalimdor", "아키몬드의 귀환과 칼림도어로의 비행", "Le retour d'Archimonde et la fuite vers Kalimdor", "Archimondes Rückkehr und die Flucht nach Kalimdor", "阿克蒙德的归来和卡里姆多之旅", "El retorno de Archimonde y el vuelo a Kalimdor", "Возвращение Архимонда и побег в Калимдор", "O Retorno de Arquimonde e Fuga para Kalimdor", "阿克蒙德的歸來和卡林多之旅" } }, { area = 616 } },
      also = { "night-elves", "tyrande-whisperwind", "thrall", "jaina-proudmoore", "demon-fall-canyon", "burning-legion" },
      text = {
        { "When the Burning Legion returned, it came for the World Tree. Archimonde, who had led the Legion's host ten thousand years before, was summoned back into the world at Dalaran and followed the Scourge across the sea to Kalimdor, bent on Nordrassil at the summit of Mount Hyjal." },
        { "A prophet went ahead of him: Medivh, the last Guardian, returned from beyond death to make amends. He urged humans and orcs to sail west together, and when neither would hear of it, he brought them over separately, by prophecy and trickery. Thrall's Horde crossed the Barrens and found allies in Cairne Bloodhoof's tauren. Jaina Proudmoore brought the survivors of Lordaeron. In the forests they met the night elves, whose priestess, Tyrande Whisperwind, had woken Malfurion Stormrage and his druids from their long sleep." },
        { "On the mountain, three peoples who had never trusted one another fought side by side, giving ground slowly while Malfurion readied his trap. When Archimonde reached the World Tree, the spirits of the forest swarmed him and the Tree's own power was spent to destroy him. With its blessing gone, the night elves lost the immortality they had held for ten thousand years." },
        { "The peace made on Hyjal still holds in Durotar and Theramore, though not everyone on either side is glad of it." },
      },
    },
    ["the-broken-alliance"] = {
      title = "The Broken Alliance", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Aftermath of the Second War", "2차 대전쟁의 여파", "Au lendemain de la Deuxième Guerre", "Folgen des Zweiten Krieges", "第二次兽人战争的结局", "Las secuelas de la Segunda Guerra", "Последствия Второй войны", "As Consequências da Segunda Guerra", "第二次獸人戰爭的結局" } }, { read = { "Lethargy of the Orcs", "오크족의 무기력증", "La léthargie des orcs", "Die Lethargie der Orcs", "兽人的消沉", "El letargo de los orcos", "Долгий сон Орков", "Letargia dos Orcs", "獸人的消沉" } } },
      also = { "the-second-war", "internment-camps", "greymane-wall", "treason-of-alterac", "black-dragonflight", "the-seven-kingdoms" },
      text = {
        { "The Alliance of Lordaeron won the Second War and did not survive the peace. The Horde had razed Khaz Modan, half of Lordaeron's provinces and the edges of Quel'Thalas. What was left had to be rebuilt, and the orcs who surrendered had to be kept somewhere. King Terenas chose mercy and built camps for them. Some of his fellow kings would rather have seen them executed, and all of them were taxed to pay for it." },
        { "Then Doomhammer escaped, and every kingdom suspected the others of incompetence. A nobleman called Lord Prestor came to Terenas's court offering help, set the lords against one another, and very nearly talked his way onto the empty throne of Alterac. He was Deathwing, and by the time anyone knew it, the damage was done." },
        { "One by one the kingdoms went their own way. Gilneas walled itself off behind the Greymane Wall. Stromgarde withdrew. The high elves of Quel'Thalas, who had never cared much for the war in the first place, left the Alliance altogether. Only a few remained true to Terenas when the plague came, and by then there was little he could ask of them." },
      },
    },
    ["the-fall-of-quelthalas"] = {
      title = "The Fall of Quel'Thalas", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Sunwell - The Fall of Quel'Thalas", "태양샘 - 쿠엘탈라스의 몰락", "Puits de soleil - La chute de Quel'Thalas", "Sonnenbrunnen - Der Fall von Quel’Thalas", "太阳之井 - 奎尔萨拉斯的陷落", "La Fuente del Sol: la caída de Quel'Thalas", "Солнечный Колодец - Падение Кель'Таласа", "Nascente do Sol: a Queda de Quel'thalas", "太陽之井 - 奎爾薩拉斯的陷落" } }, { area = 2276 } },
      also = { "high-elves", "sylvanas-windrunner", "kelthuzad", "queldanil-lodge", "blood-elves" },
      text = {
        { "For thousands of years the high elves kept their kingdom in the forests north of Lordaeron, behind a ring of runestones, with the Sunwell at its heart. In the Third War, Prince Arthas came to it at the head of the Scourge." },
        { "He came for a corpse. The spirit of Kel'Thuzad told him that the necromancer could only be raised again in the Sunwell's waters, and so Arthas laid siege to Quel'Thalas. Sylvanas Windrunner, Ranger-General of Silvermoon, fought him with everything the elves had, and lost. Arthas raised her as a banshee to serve him, cut his way to the Sunwell and plunged Kel'Thuzad's remains into it. The lich rose. The waters were fouled." },
        { "When the Scourge turned south again, the book says, not one living elf remained in Quel'Thalas. That is not quite true, traveller: a few still hold Quel'Lithien Lodge at the very edge of the Plaguelands, and others keep a lodge in the Hinterlands. But it is near enough to true that I would not argue the point with them." },
      },
    },
    ["the-first-war"] = {
      title = "The First War", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Dark Portal and the Fall of Stormwind", "어둠의 문과 스톰윈드의 함락", "La Porte des ténèbres et la chute de Stormwind", "Das Dunkle Portal und der Untergang von Stormwind", "黑暗之门和暴风城的陷落", "El Portal Oscuro y la caída de Ventormenta", "Темный портал и падение Штормграда", "O Portal Negro e a Queda de Ventobravo", "黑暗之門和暴風城的陷落" } }, { area = 1519 }, { read = { "King Llane I of the House of Wrynn", "린 가문의 국왕 레인 1세", "Roi Llane Ier de la maison Wrynn", "König Llane I. aus dem Hause Wrynn", "乌瑞恩家族的国王，莱尼一世", "El rey Llane I de la Casa de Wrynn", "Король Ллейн I из рода Риннов", "Rei Llane I da Casa de Wrynn", "烏瑞恩家族的國王，萊尼一世" } } },
      also = { "stormwind-city", "karazhan", "the-dark-portal", "the-second-war", "shadow-council" },
      text = {
        { "The orcs came through the Dark Portal a few clans at a time, into the swamps east of Stormwind, and for years the kingdom knew them only by their raids. King Llane did not believe such creatures could take his city. His champion, Anduin Lothar, last of the Arathi line, was less sure, and less sure still of their old friend Medivh, whose tower at Karazhan had grown dark indeed." },
        { "Lothar acted on his doubts. With Medivh's young apprentice, Khadgar, he stormed Karazhan and killed the Guardian, and found that Medivh had been behind the invasion from the start. It did not save the kingdom. The Horde, under a new warchief, Orgrim Doomhammer, laid siege to Stormwind Keep, and Llane was killed inside his own walls by Garona, a half-orc assassin of the Shadow Council." },
        { "Lothar came home to a city in smoking ruins and swore, with the men left to him, to take it back. He led the survivors of Azeroth across the sea to Lordaeron, to ask the other human kingdoms for help. The alliance they made would fight the Second War. Stormwind was rebuilt afterwards. Its people have not underestimated an enemy since." },
      },
    },
    ["the-five-aspects"] = {
      title = "The Five Aspects", kind = "history", chapter = "ages-past",
      unlock = { { read = { "Charge of the Dragonflights", "용군단의 임무", "Le fardeau des Vols draconiques", "Der Bund der Drachenschwärme", "巨龙军团", "Encomienda a los Vuelos", "Создание Драконов", "O Ataque das Revoadas", "巨龍軍團" } }, { npc = 15192 } },
      also = { "the-ordering", "red-dragonflight", "black-dragonflight", "blue-dragonflight", "green-dragonflight", "bronze-dragonflight" },
      text = {
        { "Before they left the world, the Titans chose five dragonflights to watch over it, and gave each of their leaders a share of their own power. Those five dragons became the Aspects." },
        { "Aman'Thul gave the bronze Nozdormu the keeping of time itself: he is the Timeless One. Eonar gave the red Alexstrasza the care of all living things, and the crown of her kind with it. To Alexstrasza's younger sister, the green Ysera, she gave the wild places, and Ysera fell into a trance from which she watches them still, in the Emerald Dream. Norgannon gave the blue Malygos the care of magic. Khaz'goroth, the shaper of the world, gave the black Neltharion the earth and its deep places, and the Earth-Warder was Alexstrasza's greatest supporter." },
        { "You will know how that last one ended. Neltharion forged the Demon Soul to master the other flights and turned it on them in the War of the Ancients. The world has called him Deathwing ever since. Malygos's flight was nearly wiped out. Ages later the same disc chained the Dragonqueen herself at Grim Batol." },
        { "Five guardians were set over the world, traveller. One of them became what the others guard it against." },
      },
    },
    ["the-guardians-of-tirisfal"] = {
      title = "The Guardians of Tirisfal", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Guardians of Tirisfal", "티리스팔의 수호자", "Les Gardiens de Tirisfal", "Die Wächter von Tirisfal", "提瑞斯法的守护者", "Los guardianes de Tirisfal", "Хранители Тирисфаля", "Os Guardiões de Tirisfal", "提里斯法的守護者" } }, { read = { "Aegwynn and the Dragon Hunt", "에이그윈과 용 사냥", "Aegwynn et la chasse au dragon", "Aegwynn und die Drachenjagd", "艾格文和猎龙之战", "Aegwynn y la caza del dragón", "Эгвин и Драконья Охота", "Aegwynn e a Caça aos Dragões", "艾格文和獵龍之戰" } }, { read = { "The Last Guardian", "최후의 수호자", "Le dernier gardien", "Der letzte Wächter", "最后的守护者", "El último guardián", "Последний хранитель", "O Último Guardião", "最後的守護者" } }, { area = 2562 }, { area = 2837 } },
      also = { "karazhan", "dalaran", "burning-legion", "the-seven-kingdoms" },
      text = {
        { "Dalaran learned the price of magic early. Its young magi spent power freely, and the more they spent, the thinner the world grew around their city, until small demons of the Burning Legion began to slip through. The Magocrats who ruled the city hid what they could. When the people began to whisper of revolution, they went to the elves of Quel'Thalas for help." },
        { "The elves told them what the Legion was, and what it had done to the world once before. Between them, the Council of Silvermoon and the Magocrats made a secret pact: one mortal champion, given the combined might of elven and human magic, would fight the Legion's agents in a war no one else was ever to hear of. A hidden council, meeting in the glades of Tirisfal where the elves had first settled in Lordaeron, chose each Guardian, and when one grew old or weary, it passed the power on under its own careful control." },
        { "It worked for generations. Then the Council chose Aegwynn, who did not care to be controlled. She struck down the avatar of Sargeras himself in the frozen north and believed she had finished him. Nearly nine hundred years later, refusing to let the Council name her successor, she bore a son to inherit her power and named him Medivh, 'keeper of secrets' in the high elven tongue. What he kept is told under Karazhan." },
        { "An order that keeps its war secret from the whole world cannot easily be corrected when it goes wrong, traveller. The Council learned that too late." },
      },
    },
    ["the-lich-king"] = {
      title = "The Lich King", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Birth of the Lich King", "리치 왕의 탄생", "La naissance du roi-liche", "Die Geburt des Lichkönigs", "巫妖王的诞生", "El naciminento del rey Exánime", "Рождение Короля-лича", "O Nascimento do Lich Rei", "巫妖王的誕生" } }, { read = { "Icecrown and the Frozen Throne", "얼음왕관과 얼음 왕좌", "La Couronne et le Trône de glace", "Eiskrone und Frost-Thron", "冰冠冰川和寒冰王座", "Corona de Hielo y el Trono Helado", "Ледяная Корона и Ледяной Трон", "A Coroa e o Trono de Gelo", "寒冰皇冠和冰封王座" } }, { read = { "The Lich King Triumphant", "리치 왕의 승리", "Le triomphe du roi-liche", "Der Triumph des Lichkönigs", "巫妖王的胜利", "El triunfante rey Exánime", "Триумф Короля-лича", "O Triunfo do Lich Rei", "巫妖王的勝利" } }, { read = { "Kel'Thuzad and the Forming of the Scourge", "켈투자드와 스컬지의 형성", "Kel'Thuzad et l'avènement du Fléau", "Kel’Thuzad und das Entstehen der Geißel", "克尔苏加德和天灾军团的建立", "Kel'Thuzad y la formación de la Plaga", "Кел'Тузад и создание Плети", "Kel'Thuzad e a Formação do Flagelo", "科爾蘇加德和天譴軍團的建立" } } },
      also = { "draenor", "scourge", "kelthuzad", "fall-of-lordaeron", "the-war-of-the-spider", "cult-of-the-damned" },
      text = {
        { "The Lich King began as an orc. Ner'zhul, the old shaman who first led his people to the Legion, fled into the Twisting Nether after the orcs' last war, and Kil'jaeden was waiting for him. The demon tore his body apart piece by piece and kept his spirit alive, then offered him one last bargain. Ner'zhul accepted. His spirit was sealed in a block of ice from the far reaches of the Nether, and the Lich King was born. His death knights and followers were remade as liches to serve him." },
        { "Kil'jaeden flung the ice into the world. It struck the glacier of Icecrown in Northrend and came to rest in the shape of a throne. From the Frozen Throne the Lich King reached into the minds of the north, ice trolls and wendigo first, then a human village on the edge of the Dragonblight, where he tested the plague that was meant for Lordaeron. The dreadlords were set to watch him. Kil'jaeden trusted no one, least of all a prisoner." },
        { "What came of it fills half the pages of this ledger. The book in our library ends with Prince Arthas climbing to the Frozen Throne and putting on Ner'zhul's helm, the two of them becoming one. It says he is rumoured to be rebuilding the citadel of Icecrown, and that Kel'Thuzad rules the Plaguelands in his name. The League has no expedition in Northrend, traveller, and I see no reason to start one." },
      },
    },
    ["the-ordering"] = {
      title = "The Ordering of Azeroth", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Old Gods and the Ordering of Azeroth", "고대의 신들과 아제로스의 질서 구현", "Les Dieux très anciens et l'ordonnancement d'Azeroth", "Die Alten Götter und die Ordnung von Azeroth", "上古之神和艾泽拉斯的秩序", "Los dioses antiguos y el orden de Azeroth", "Древние Боги и формирование Азерота", "Os Deuses Antigos e a Ordenação de Azeroth", "上古之神和艾澤拉斯的秩序" } }, { area = 1897 }, { read = { "Mythology of the Titans", "티탄 신화", "Mythologie des Titans", "Mythologie der Titanen", "泰坦神话", "Mitología de los titanes", "\"Мифология Титанов\"", "Mitologia dos Titãs", "泰坦神話" } } },
      also = { "uldaman", "platinum-discs", "ragnaros", "the-five-aspects", "cthun" },
      text = {
        { "The oldest account in the League's library begins before anyone was here to keep one. The Titans, it says, went from world to world putting each in order, and came at last to this one. They found it held by elementals, and the elementals served older masters: the Old Gods." },
        { "The Titans' Pantheon made war on them. Four great lords of the elements led the Old Gods' armies, Ragnaros the Firelord, Therazane the Stonemother, Al'Akir the Windlord and Neptulon the Tidehunter, and one by one they fell. The Old Gods' citadels were broken and the gods themselves, five of them, chained far beneath the earth. Without their masters, the elementals were cast out into a plane of their own, to fight one another for ever." },
        { "Then the Titans set to work. They made the earthen from living stone to carve the deep places, and the sea giants to lift the land out of the sea. When they were done there was one continent, Kalimdor, and at its heart a lake of shining power they named the Well of Eternity." },
        { "We are still digging up their work at Uldaman and on the terraces of the Badlands. Now and then something they buried comes back up as well: a Firelord under Blackrock, a god in the sands of Silithus. The Titans, I suspect, left the world tidier than they found it, but not finished." },
      },
    },
    ["the-second-war"] = {
      title = "The Second War", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Alliance of Lordaeron", "로데론의 얼라이언스", "L'Alliance de Lordaeron", "Die Allianz von Lordaeron", "洛丹伦联盟", "La alianza de Lordaeron", "Альянс Лордерона", "A Aliança de Lordaeron", "羅德隆聯盟" } }, { area = 1583 } },
      also = { "the-first-war", "the-seven-kingdoms", "grim-batol", "red-dragonflight", "blackrock-spire", "the-dark-portal", "nethergarde-keep" },
      text = {
        { "In Lordaeron, Lothar found the human kings willing to listen, for once. They agreed to unite as the Alliance of Lordaeron, the first time the heirs of Arathor had stood under one banner in nearly three thousand years, and named Lothar Supreme Commander. Uther the Lightbringer, Admiral Daelin Proudmoore and Turalyon served under him. Ironforge joined, and so, more reluctantly, did a few high elves, who owed a debt to the Arathi line." },
        { "Doomhammer brought ogres from Draenor and Amani trolls from the forests, overran Khaz Modan and marched north. The Horde had found the Demon Soul and with it enslaved the Dragonqueen, so that red dragons fought for the orcs. The borderlands of Quel'Thalas burned, which settled the elves' doubts, and the towns of Lordaeron were razed one by one." },
        { "The Horde was at the gates of Lordaeron's capital when Gul'dan deserted with half its strength to raise the Tomb of Sargeras from the sea, and found only maddened demons inside. Doomhammer had to turn back to punish him. The Alliance drove him south to Blackrock Spire, where Lothar fell at the mountain's foot. Turalyon rallied the army, broke the Horde and destroyed the Dark Portal behind it. The orcs who survived were rounded up into camps." },
        { "The Spire, I note, is full of orcs again." },
      },
    },
    ["the-seven-kingdoms"] = {
      title = "The Seven Kingdoms", kind = "history", chapter = "ages-past",
      unlock = { { read = { "The Seven Kingdoms", "일곱 왕국", "Les sept royaumes", "Die sieben Königreiche", "七大王国", "Los siete reinos", "Семь королевств", "Os Sete Reinos", "七大王國" } }, { area = 281 } },
      also = { "thoradins-wall", "stromgarde-keep", "dalaran", "treason-of-alterac", "humans", "the-second-war" },
      text = {
        { "Arathor did not end in a war. It drifted apart. Strom remained the heart of the empire while new cities rose across the north. Dalaran was where the magi went to practise more freely. Gilneas and Alterac pushed their armies into the mountains of Khaz Modan and so met the dwarves of Ironforge. Kul Tiras, on its island, grew rich on fish and trade and built a fleet to carry both." },
        { "Then the lords of Strom tired of the dry south. They went north and built a new city, Lordaeron, and in time the whole continent took its name. The last of Thoradin's line, who had argued that Strom should not be abandoned, went the other way, south past the mountains, and founded Stormwind in a fertile valley of the land they called Azeroth. A few warriors stayed to guard the old walls, and Strom became Stromgarde." },
        { "Seven kingdoms, then, each with its own customs and its own grudges, and none of them ruling the rest. It took an invasion from another world to bring them under one banner again, nearly three thousand years later, and the banner did not long outlive the war that raised it. The League has always found the dwarves easier to keep track of." },
      },
    },
    ["the-war-of-the-spider"] = {
      title = "The War of the Spider", kind = "history", chapter = "ages-past",
      unlock = { { read = { "War of the Spider", "거미 전쟁", "La Guerre de l'araignée", "Der Krieg der Spinne", "蜘蛛之战", "La guerra de la Araña", "Война пауков", "A Guerra da Aranha", "蜘蛛之戰" } }, { kill = 8555 }, { kill = 8556 }, { kill = 8557 }, { kill = 10412 }, { kill = 10437 } },
      also = { "the-lich-king", "scourge", "naxxramas", "stratholme" },
      text = {
        { "While Thrall was freeing his people from the camps, the Lich King was raising a citadel above the glacier of Icecrown, and one kingdom of Northrend refused him. Azjol-Nerub lay underground, ruled by the nerubians, spider-lords whose tunnels ran under half the continent. They were immune to his plague and to his voice in their minds, and they struck at his strongholds and were gone again before he could answer." },
        { "He won by attrition. With the dreadlords and an endless supply of dead, he invaded Azjol-Nerub and brought its temples down on the spider-lords' heads. The plague could not take them living, but his necromancy could raise them dead, and so the nerubians came to serve the master they had fought. He admired their buildings, too: the Scourge's fortresses are built in their style." },
        { "You can see both in the Plaguelands. The crypt fiends that crawl among the Scourge are nerubians, or what is left of them, and the ziggurats of the dead are the spider-lords' architecture. The Lich King keeps his trophies close." },
      },
    },
    ["alterac-mountains"] = {
      title = "Alterac Mountains", kind = "place", chapter = "alterac",
      unlock = { { area = 36 } },
      also = { "dalaran", "treason-of-alterac", "alterac-valley", "syndicate", "ogres" },
      text = {
        { "Snow covers much of Alterac, but it has done little to conceal the kingdom's fall. Broken castles stand above Syndicate-held towns, ogres occupy the old capital, and the roads climb past caves that now belong to yetis. These were once the heights of a small, proud human realm whose king betrayed the Alliance in the Second War." },
        { "Beside Lordamere Lake, Dalaran's rebuilding has run into another calamity. Disrupted ley lines have turned the city's constructs against its inhabitants, and Archmage Modera is seeking the outside help the council would prefer not to need." },
        { "Farther into the mountains, the Frostwolves and Stormpike fight over Alterac Valley. The kingdom has vanished, traveller. The arguments over who may live in its hills have outlasted it." },
      },
    },
    ["alterac-valley"] = {
      title = "Alterac Valley", kind = "place", chapter = "alterac",
      unlock = { { area = 2597 }, { area = 2839 } },
      also = { "frostwolf-clan", "stormpike-guard", "explorers-league" },
      text = {
        { "In the south of the Alterac Mountains lies a hidden valley, and two peoples claim it. The orcs of the Frostwolf clan have lived in its southern reaches for a generation, since the warlock Gul'dan exiled them there. The dwarves of the Stormpike clan came later, to dig: for minerals, and for relics of our people's ancient past, which the Explorers' League believes lie under the valley's ice." },
        { "The Frostwolves saw invaders. The Stormpikes saw orcs blocking honest scholarship, and King Magni has since given them a royal command to take the valley for Ironforge. Now the two fight across it with armies, keeps, graveyards and mines, and both sides send for help from their whole alliance. I wish I could say the League had no part in it." },
      },
    },
    ["dalaran"] = {
      title = "Dalaran", kind = "place", chapter = "alterac",
      unlock = { { area = 279 }, { npc = 2543 } },
      also = { "alterac-mountains", "ambermill", "the-high-order" },
      text = {
        { "Dalaran's spires stood beside Lordamere Lake for centuries, home to the Kirin Tor and to generations of students of magic. In the Third War the Scourge took the city and killed Antonidas. Archimonde then destroyed what its defenders had failed to save." },
        { "The rebuilding has been overtaken by a crisis within the city. Something has disrupted its ley lines, leaving its constructs erratic and destructive. The council wants the trouble kept private. Modera, whose image waits beside Lordamere Lake, has called for outside aid. The mages have survived one city's destruction. She is unwilling to let their pride help bring about another." },
      },
    },
    ["durotan-and-draka"] = {
      title = "Durotan and Draka", kind = "figure", chapter = "alterac",
      unlock = { { read = { "Rock of Durotan", "듀로탄 바위", "Rocher de Durotan", "Fels von Durotan", "杜隆坦之石", "Roca de Durotan", "Обелиск Дуротана", "Rocha de Durotan" } }, { npc = 11946 } },
      also = { "frostwolf-clan", "thrall", "draenor", "alterac-valley", "shadow-council" },
      text = {
        { "Durotan was chieftain of the Frostwolf clan, and the one chieftain who would not drink. When Gul'dan gathered the clans to drink Mannoroth's blood, Durotan refused, and kept warning anyone who would listen that the warlocks were destroying what the orcs had been. Gul'dan could not kill so popular a hero openly, so he exiled him and his whole clan to the far edge of the new world: these mountains." },
        { "His mate, Draka, went into exile with him, and their infant son with them. Durotan went back once more, to warn his old friend Orgrim Doomhammer about Gul'dan. Gul'dan's assassins followed him home and murdered him and Draka both. Their infant son was found beside them by a human officer, Aedelas Blackmoore, who raised him as a slave and named him Thrall." },
        { "The Frostwolves keep a grave for Durotan in Alterac Valley. Their Far Seer, Drek'Thar, wrote the words on it: the bravest of their kind, betrayed by those who would see the orcs enslaved. The Warchief's father, traveller, never saw what his son became. The Frostwolves make sure his son's people know whose son he is." },
      },
    },
    ["frostwolf-clan"] = {
      title = "The Frostwolf Clan", kind = "faction", chapter = "alterac", portrait = 11894,
      unlock = { { npc = 11946 }, { faction = 729, standing = 5 } },
      also = { "alterac-valley", "thrall", "stormpike-guard" },
      text = {
        { "Durotan's Frostwolves refused the demon blood that bound much of the Horde. When he opposed the warlocks and their invasion of Azeroth, Gul'dan exiled his clan. They made a hard living in the Alterac Mountains. Durotan was murdered, but the clan endured." },
        { "His son Thrall found them after escaping Durnholde. They taught him the life of his people, and their shaman Drek'Thar taught him to follow the elements. When Thrall later freed the internment camps and led the Horde across the sea, the Frostwolves remained in their valley." },
        { "Drek'Thar, now blind, still leads them there. They want to retain their home. The Stormpike expedition has brought a claim from Ironforge against it." },
      },
    },
    ["helcular"] = {
      title = "Helcular", kind = "figure", chapter = "alterac",
      unlock = { { area = 1683 }, { quest = 552 } },
      also = { "southshore", "hillsbrad-foothills", "alterac-mountains" },
      text = {
        { "Helcular was a wizard of the hills above Southshore, and he was nearly a lich when the people of Southshore found his ritual lair and killed him. They buried him in their own cemetery, to keep an eye on him, one supposes. His apprentice took it badly." },
        { "The yetis have the lair now, and with it the rod Helcular worked his rites through. He had built three ceremonial pyres in the caves of these mountains, the Flames of Azel, Veraz and Uzel, and his apprentice wants the rod recovered, charged at each of them, and driven into his master's grave in the middle of the human town." },
        { "What will come up out of Southshore's cemetery, the apprentice does not say. Southshore has a good many enemies, traveller. It made this one itself." },
      },
    },
    ["internment-camps"] = {
      title = "The Internment Camps", kind = "history", chapter = "alterac",
      unlock = { { area = 278 } },
      also = { "durnholde-keep", "thrall", "frostwolf-clan", "dalaran", "treason-of-alterac", "orgrim-doomhammer" },
      text = {
        { "After the Second War the Alliance had a problem it had never had before: a whole people for prisoners. The orcs were rounded up into camps, and when the camps overflowed, new ones were built on the plains south of these mountains. King Terenas taxed the other kingdoms to pay for them, and the tax nearly broke the Alliance." },
        { "Then the wardens noticed something strange. The orcs stopped trying to escape. They stopped even fighting one another. They sat. Some called it a disease. Archmage Antonidas of Dalaran thought otherwise: the orcs had been fed on demon magic for generations, and what the wardens were seeing was withdrawal. There was no cure, he concluded, but a spiritual one, and many in the Alliance thought it unwise to look for one at all." },
        { "The chief warden, Aedelas Blackmoore, ruled the camps from Durnholde and kept an orc slave of his own, raised to be a weapon. The slave was Thrall. He found his people sitting behind these walls, and in the end he came back to break the camps open. No orcs are held here now. The Kirin Tor's wizards have taken the old camp for their own use." },
        { side = "Horde", aside = true, sign = "P. F.", "Those camps stood in my kingdom, on my king's orders. She tells it fairly." },
      },
    },
    ["ravenholdt-manor"] = {
      title = "Ravenholdt Manor", kind = "place", chapter = "alterac",
      unlock = { { area = 3486 }, { npc = 6768 } },
      also = { "syndicate", "alterac-mountains" },
      text = {
        { "Ravenholdt Manor lies hidden in the hills above Hillsbrad. Lord Jorach Ravenholdt directs the Assassins' League from it, training thieves and killers whom the house selects for itself. Prospective students receive invitations. An application would be an unusual way to announce your talents here." },
        { "The League has long opposed the Syndicate, whose members it regards as amateurs. Stealing their emblems is a useful part of the quarrel: a Syndicate man who loses his can expect punishment from his own side." },
      },
    },
    ["stormpike-guard"] = {
      title = "The Stormpike Guard", kind = "faction", chapter = "alterac", portrait = 11896,
      unlock = { { npc = 11948 }, { faction = 730, standing = 5 } },
      also = { "alterac-valley", "frostwolf-clan", "magni-bronzebeard", "explorers-league" },
      text = {
        { "The Stormpike Guard came to Alterac Valley to mine and to seek relics of dwarven ancestry, with the Explorers' League accompanying the expedition. They say the Frostwolves attacked without provocation. The Frostwolves give the same account with the names reversed." },
        { "Vanndar Stormpike commands the Guard, and King Magni has ordered him to take the valley for Ironforge. The Frostwolves already live there and resist the order. I serve the king who gave that order, but the League's interest in what lies beneath the ground does not settle the claims of those living above it." },
      },
    },
    ["treason-of-alterac"] = {
      title = "The Treason of Alterac", kind = "history", chapter = "alterac",
      unlock = { { area = 281 }, { quest = 507 } },
      also = { "syndicate", "durnholde-keep", "alterac-mountains" },
      text = {
        { "King Aiden Perenolde judged that the Horde would win the Second War. While the other human kingdoms fought together, Alterac opened a way for the orcs and supplied them with Alliance plans. When the Alliance won, Lordaeron imposed martial law. The rulers then disputed what should become of the kingdom." },
        { "Alterac's capital is ruined and its libraries scattered. Stormwind sends scholars to recover the books. Perenolde's son Aliden has pursued another inheritance: he leads the Syndicate, including former Alterac nobles, and plans to enslave the orcs as his mentor Blackmoore intended. There are several kinds of salvage being attempted here, traveller. The scholars' is the one I would commend." },
        { side = "Horde", aside = true, sign = "P. F.", "I am glad someone is saving Alterac's books. Whether any of them will ever reach the Undercity is another matter." },
      },
    },
    ["arathi-basin"] = {
      title = "Arathi Basin", kind = "place", chapter = "arathi",
      unlock = { { area = 3358 } },
      also = { "arathi-highlands", "refuge-pointe", "the-forsaken" },
      text = {
        { "In the south of the Highlands lies a fertile basin of farms, mines and mills, the richest land left in Arathi, and the Alliance and the Horde both want what it produces. The League of Arathor, sworn to Stromgarde's memory, fights for it from the west. The Defilers, raised by the Forsaken, fight from the east." },
        { "They fight over a farm, a mine, a lumber mill, a stable and a smithy, raising and tearing down each other's banners, all day and all night. Arathor would have understood: the first empire of men was built on just such land." },
      },
    },
    ["arathi-highlands"] = {
      title = "Arathi Highlands", kind = "place", chapter = "arathi",
      unlock = { { area = 45 } },
      also = { "stromgarde-keep", "thoradins-wall", "refuge-pointe", "hammerfall", "myzrael", "syndicate", "forest-trolls" },
      text = {
        { "The Arathi Highlands are windswept country between Hillsbrad and the Wetlands. Here Thoradin united the human tribes into Arathor, with its capital at Strom. Every later human kingdom grew from that beginning." },
        { "Strom became Stromgarde. Its ruins are now divided among its defenders, Syndicate thieves and ogres. Witherbark trolls occupy settlements in the hills, while giants guard strange circles of standing stones. Refuge Pointe holds the Alliance's camp and Hammerfall the Horde's. Their forces fight over the basin's farms, mines and mills to the south." },
        { "Look at the old stonework as you cross Arathi, traveller. The human kingdoms began here. The people defending Stromgarde are still trying to keep a part of that beginning their own." },
      },
    },
    ["hammerfall"] = {
      title = "Hammerfall", kind = "place", chapter = "arathi",
      unlock = { { area = 321 } },
      also = { "thrall", "arathi-highlands", "durnholde-keep" },
      text = {
        { "Hammerfall was a great orc internment camp after the Second War. Thrall and Orgrim Doomhammer broke it open together. During the fighting, a knight struck Doomhammer from behind with a lance, and the former Warchief died here." },
        { "The Horde has rebuilt the camp as a fortress and named it in his memory. Some of the orcs within its stockade were once prisoners on this ground." },
      },
    },
    ["myzrael"] = {
      title = "Myzrael", kind = "figure", chapter = "arathi", portrait = 1165,
      unlock = { { quest = 656 } },
      also = { "arathi-highlands", "kobolds", "masters-glaive" },
      text = {
        { "The Shards of Myzrael offer a voice from beneath the Arathi Highlands. An imprisoned princess of the earth asks a passing traveller to help her escape, and the crystals lend the encounter a feeling of warmth and safety." },
        { "Theldurin the Lost gives a different account. He fears what she will do once she regains her strength, and asks why the giants chained her if she is so easily controlled. His answer is to summon and defeat her, then bind her shackles to the shards again." },
        { "Afterward, a cry rises from far below the ground. The crystals remain, but their old reassurance is gone. What pulses through them now feels like hatred for the world above. The voice that asked so gently for help has become the most troubling thing about the quiet hillside." },
      },
    },
    ["orgrim-doomhammer"] = {
      title = "Orgrim Doomhammer", kind = "figure", chapter = "arathi",
      unlock = { { area = 321 } },
      also = { "hammerfall", "thrall", "orgrimmar", "blackrock-clan", "anduin-lothar", "durotan-and-draka", "the-second-war" },
      text = {
        { "Orgrim Doomhammer was Durotan's friend on Draenor, a chieftain of the Blackrock clan who saw what the warlocks were doing to his people and, unlike Durotan, waited for his moment. It came in the First War. When Gul'dan's assassins murdered Durotan, Doomhammer killed Blackhand, the puppet warchief Gul'dan had set up, and took the Horde for himself. He destroyed Stormwind and broke the Shadow Council." },
        { "In the Second War he drove the Horde to the gates of Lordaeron's capital, until Gul'dan's desertion forced him back. He killed Anduin Lothar in single combat in the Burning Steppes, and lost the war anyway. Captured at the Dark Portal and taken to Lordaeron, he escaped and lived for years as a hermit." },
        { "Thrall found him there. The old warchief, his father's friend, followed the young one, and fell freeing one of the camps. Thrall took up his hammer and his black armour and became Warchief. This town carries his name, and so does the Horde's capital. They remember him as the warchief who lost a war and still made sure there was a Horde left at the end of it." },
      },
    },
    ["refuge-pointe"] = {
      title = "Refuge Pointe", kind = "place", chapter = "arathi",
      unlock = { { area = 320 } },
      also = { "stromgarde-keep", "arathi-basin" },
      text = {
        { "Refuge Pointe is the Alliance's camp in the middle of the Arathi Highlands, held by the survivors of Stromgarde and the soldiers who have come to help them: a few tents, a stable, a flight master and a great deal of resolve. From here they fight the Syndicate in the ruins of their city and the Witherbark in the hills, and from here, too, the League of Arathor rides out to the basin in the south." },
        { "The people of Stromgarde are proud, and their kingdom has been reduced to this camp. They have not stopped calling it a kingdom." },
      },
    },
    ["stromgarde-keep"] = {
      title = "Stromgarde Keep", kind = "place", chapter = "arathi",
      unlock = { { area = 324 } },
      also = { "arathi-highlands", "refuge-pointe", "syndicate", "forest-trolls" },
      text = {
        { "Stromgarde occupies the site of Strom, the first human city. Its Trollbane rulers held the oldest crown of the human kingdoms. Lord Ignaeus fought the trolls with the sword they called Trol'kalar, the troll-slayer, and the family's name remembers that war." },
        { "The present city is divided. Lord Falconcrest's Syndicate holds its towers, ogres occupy one quarter, and Stromgarde's defenders retain another. Other survivors fight from Refuge Pointe to recover their home. Trol'kalar remains in Trollbane's tomb, behind wards that the reunited sigils can open." },
      },
    },
    ["thoradins-wall"] = {
      title = "Thoradin's Wall", kind = "history", chapter = "arathi",
      unlock = { { area = 1857 }, { read = { "Arathor and the Troll Wars", "아라소르와 트롤 전쟁", "Arathor et les Guerres trolls", "Arathor und die Trollkriege", "阿拉索与巨魔战争", "Arathor y las guerras de los trols", "Аратор и Тролльские Войны", "Arathor e a Guerra dos Trolls", "阿拉索與食人妖戰爭" } } },
      also = { "arathi-highlands", "stromgarde-keep", "forest-trolls" },
      text = {
        { "Thoradin was the chieftain of the Arathi tribe, long ago, who conquered or persuaded the scattered human tribes of the north into a single nation, the empire of Arathor, and built its capital at Strom. When the trolls of the Amani empire made war on the elves of Quel'Thalas, it was Thoradin who led men to fight beside them, and the human mages the elves trained in that war were the beginning of all human magic." },
        { "His wall still runs across the hills between Arathi and Hillsbrad, broken now, overgrown, but still great. The men who built it are long gone, and the empire with them, but every human king has claimed to be his heir." },
      },
    },
    ["ashenvale"] = {
      title = "Ashenvale", kind = "place", chapter = "ashenvale",
      unlock = { { area = 331 } },
      also = { "astranaar", "splintertree-post", "warsong-lumber-camp", "demon-fall-canyon", "furbolgs", "satyrs" },
      text = {
        { "Ashenvale is the ancient forest of the night elves: vast trees, silver moonlight, still lakes and ruins older than any kingdom of men. For ten thousand years the night elves lived here hidden, guarded by their Sentinels and the demigod Cenarius, and let no one in." },
        { "Then the orcs came to Kalimdor, needing timber for their new land, and the forest has been at war ever since. In the last war the Warsong clan cut into Ashenvale and killed Cenarius while under Mannoroth's corruption. The night elves have not forgiven them, and the Horde has not stopped cutting. Now Sentinels and Warsong outriders skirmish along the forest's eastern edge, while furbolgs gone mad, satyrs and naga trouble everyone alike." },
      },
    },
    ["astranaar"] = {
      title = "Astranaar", kind = "place", chapter = "ashenvale",
      unlock = { { area = 415 } },
      also = { "ashenvale", "demon-fall-canyon" },
      text = {
        { "Astranaar stands on an island in an Ashenvale lake, joined to the forest by bridges. Its moonwell, inn and Sentinel barracks give the night elves a centre from which to defend the country around it. It is a beautiful town with very little ease." },
        { "A father here seeks help for his daughter's fever and nightmares. Ordinary remedies have failed her. Herbalists speak of sickness in the forest itself, while the Sentinels blame corruption left by the demons of the war. A traveller coming to help defend Astranaar may find the town's troubles begin well inside its guarded approaches." },
      },
    },
    ["blackfathom-deeps"] = {
      title = "Blackfathom Deeps", kind = "place", chapter = "ashenvale",
      unlock = { { area = 719 }, { area = 2797 }, { read = { "Lorgalis Manuscript", "로르갈리스 초본", "Manuscrit de Lorgalis", "Lorgalis-Manuskript", "洛迦里斯手稿", "Manuscrito de Lorgalis", "Манускрипт Лоргалиса" } } },
      also = { "twilights-hammer", "naga", "ashenvale" },
      text = {
        { "On the coast of Ashenvale, at the Zoram Strand, there are caverns flooded by the sea, and in them lie the ruins of a temple to Elune that sank when the Well of Eternity was destroyed. The naga found it first. Then the Twilight's Hammer did, led by a Twilight Lord named Kelris." },
        { "Their papers say what they are doing there. They are gathering the power of the deep waters to feed a creature they call Aku'mai, which sleeps in the temple's depths, so that one day the world will return to what they call its greatest era: an era of rule by the Old Gods. The night elves and the Horde both send their young to stop them, which may be the only thing the two agree on in Ashenvale." },
      },
    },
    ["dartols-rod"] = {
      title = "Dartol's Rod", kind = "history", chapter = "ashenvale",
      unlock = { { quest = 1046 } },
      also = { "furbolgs", "astranaar", "sentinels", "ashenvale" },
      text = {
        { "Teronis, a friend of Raene Wolfrunner's, was helping the Sentinels of Astranaar against the furbolgs, and he believed a rod made by Dartol, an evil wizard now dead, could slow their attacks. He went after its gem at the shrine on an island in Lake Falathim and did not come back. His body was found there, cut by murloc blades, with his journal still on him." },
        { "From the journal and a dryad named Shael'dryn, the rod came together piece by piece: the gem from the murlocs, one part from a chest whose key a corrupted treant carried near the Felwood border, the last from the barrow den of the druids of Dor'danil, who had been killed not long before. Rebuilt and charged again at a shrine hidden in the mountains, Dartol's Rod lets its bearer take a furbolg's shape." },
        { "In that shape a traveller can reach Krolg, a furbolg cast out of his tribe and still free of the fel moss that maddens the rest. He blames the night elves, whose pride, he says, brought the corruption down on his people. But he wishes no harm on the elves' children, and he will not excuse his own kind, who are still answerable for what they do. Ran Bloodtooth, whom the corruption has only made stronger, is the evil he names, and he asks the traveller in furbolg shape to put him down: the furbolgs, he says, must police their own. Raene set Ran's skull and the rod in a place of honour for Teronis. Krolg stayed where he was, south-east of Mystral Lake, watching his old tribe's fires at night." },
      },
    },
    ["demon-fall-canyon"] = {
      title = "Demon Fall Canyon", kind = "history", chapter = "ashenvale",
      unlock = { { area = 435 }, { area = 436 } },
      also = { "grom-hellscream", "warsong-lumber-camp", "burning-legion", "orgrimmar" },
      text = {
        { "After Grom Hellscream drank the demon's blood and killed Cenarius, Thrall and Jaina Proudmoore hunted him down and freed him from its curse. Then Grom went looking for the demon. In a canyon in Ashenvale he found Mannoroth, the pit lord whose blood had damned the orcs, and killed him with his axe, and died of it." },
        { "The orcs remember him as the one who freed them, and named their great hall in Orgrimmar for him. The canyon is still a place of demons: the Burning Legion's servants hold it, and the ground where Mannoroth fell has never been clean." },
      },
    },
    ["grom-hellscream"] = {
      title = "Grom Hellscream", kind = "figure", chapter = "ashenvale",
      unlock = { { read = { "Monument to Grom Hellscream", "그롬 헬스크림의 기념비", "Monument à Grom Hellscream", "Denkmal für Grom Hellscream", "格罗姆·地狱咆哮的纪念碑", "Monumento a Grom Grito Infernal", "Памятник Грому Адскому Крику", "Monumento para Grom Grito Infernal", "葛羅·地獄吼的紀念碑" } }, { area = 435 }, { read = { "The Armor of Mannoroth", "만노로스의 갑옷", "L'armure de Mannoroth", "Die Rüstung von Mannoroth", "玛诺洛斯的护甲", "La armadura de  Mannoroth", "Броня Маннорота", "A Armadura de Mannoroth", "瑪諾洛斯的護甲" } } },
      also = { "demon-fall-canyon", "warsong-lumber-camp", "thrall", "orcs", "cenarius", "draenor" },
      text = {
        { "Grommash Hellscream, chieftain of the Warsong, was the first of the orc chieftains to drink Mannoroth's blood on Draenor, and he led the others to it. The strength it gave them bound the clans to the demon whose blood they shared." },
        { "When the Horde fell and the clans were driven into the camps, his Warsong kept fighting from hiding, and Grom remained an undefeated chieftain. The young Thrall learned from him what the Horde had once been, and found an ally in bringing the scattered clans together. The two sailed for Kalimdor as friends, carrying the hope of a home beyond the camps and the old wars." },
        { "Grom did not live to see the Horde's new home built. Thrall set a stone where he fell in Demon Fall Canyon. 'In many ways,' it reads, 'the curse of our people began and ended with Grom.' His name meant giant's heart, the Warchief writes, and he earned it a hundred times over." },
      },
    },
    ["splintertree-post"] = {
      title = "Splintertree Post", kind = "place", chapter = "ashenvale",
      unlock = { { area = 431 } },
      also = { "warsong-lumber-camp", "ashenvale" },
      text = {
        { "Splintertree Post is the Horde's fort on the eastern edge of Ashenvale, a stockade of raw timber where the Warsong's loggers and riders keep their camp. The Sentinels attack it constantly, and the orcs give as good as they get." },
        { "The orcs say they need the wood: Durotar is a land of red rock, and a people must build. The night elves say every tree in this forest is older than the Horde. Both are right, which is what makes it so hard." },
      },
    },
    ["warsong-gulch"] = {
      title = "Warsong Gulch", kind = "place", chapter = "ashenvale",
      unlock = { { area = 3277 } },
      also = { "warsong-lumber-camp", "ashenvale", "splintertree-post" },
      text = {
        { "In Warsong Gulch, on Ashenvale's southern edge, the night elves have drawn their stand against further Warsong logging. Silverwing Sentinels hold one end of the valley and Warsong Outriders the other. Their fighters cross between the camps to seize the enemy's banner." },
        { "The Horde regards this as defence of a logging operation. The Alliance regards the operation as an invasion. Both send fighters from far beyond Ashenvale." },
      },
    },
    ["warsong-lumber-camp"] = {
      title = "The Warsong Lumber Camp", kind = "history", chapter = "ashenvale",
      unlock = { { area = 437 }, { area = 3177 } },
      also = { "demon-fall-canyon", "ashenvale", "burning-legion", "cenarion-circle" },
      text = {
        { "When the orcs landed on Kalimdor, Thrall sent Grom Hellscream and his Warsong clan into Ashenvale for timber. The forest's guardians did not want them there, and the demigod Cenarius, the lord of the forest himself, rose against them." },
        { "Grom could not beat him. So he did what the orcs had sworn never to do again: he drank the blood of the demon Mannoroth, and with its strength the Warsong killed Cenarius in his own forest. The demon's curse was on them again. The Warsong lumber camps are still here, and still cutting, and the night elves have long memories." },
      },
    },
    ["azshara"] = {
      title = "Azshara", kind = "place", chapter = "azshara",
      unlock = { { area = 16 } },
      also = { "the-sundering", "ruins-of-eldarath", "naga", "satyrs", "furbolgs", "azuregos" },
      text = {
        { "Azshara wears the colours of autumn among the white ruins of the Highborne. It bears the name of the queen who ruled ten thousand years ago, and lies beside the sea that swallowed so much of her empire. Few places offer a lovelier view of so great a loss." },
        { "Naga occupy the coast and old temples. Satyrs haunt the woods, and ghosts remain among the broken walls. Valormok and Talrendis Point are small footholds in a country still crowded with older claims. Azuregos watches the southern hills, while an archmage keeps a tower and a waterlord inhabits an island in the bay." },
        { "The northern stone gate leads into Blackmaw Hold, where corruption has taken a furbolg tribe. These are not the Timbermaw who guard the tunnels in Felwood. An old name on a map can be a poor guide to the people behind a gate." },
      },
    },
    ["azuregos"] = {
      title = "Azuregos", kind = "figure", chapter = "azshara", portrait = 11460,
      unlock = { { kill = 6109 }, { npc = 6109 } },
      also = { "azshara", "the-sundering", "the-scepter-of-the-shifting-sands" },
      text = {
        { "Azuregos watches southern Azshara, where the Highborne left enough arcane treasure to occupy a blue dragon for a very long time. His flight guards magic, and this ruined coast has much to explain about why such guardians are needed." },
        { "His charge also included the blue shard of the Scepter of the Shifting Sands. The search for it leads through a magical ledger and an elaborate means of drawing a great shark called Maws from the Bay of Storms. A missing piece of an ancient sceptre has become a matter of translation, engineering and very large teeth." },
        { "There are solemn guardians in the world, traveller. Azuregos's arrangements suggest that centuries of responsibility need not extinguish a dragon's capacity to make work for somebody else." },
      },
    },
    ["captain-varothen"] = {
      title = "Captain Varo'then", kind = "figure", chapter = "azshara", portrait = 10771,
      unlock = { { kill = 6118 }, { area = 1235 } },
      also = { "queen-azshara", "the-sundering", "ravencrest-monument", "malfurion-stormrage", "highborne" },
      text = {
        { "Captain Varo'then commanded Queen Azshara's guard in the War of the Ancients: a scarred soldier who claimed to be immune to her charms and was, the stories say, hopelessly in love with her. He served her every whim instead. He fetched the Demon Soul for the Legion and nursed a feud with Malfurion Stormrage to the end." },
        { "At the last battle above the Well he led the Highborne still loyal to the queen, and told Malfurion that he lived only to serve her, even if it meant the end of Kalimdor. They were nearly the last words he said. Kalimdor, the tale goes, took him at his word and rejected him." },
        { "His ghost walks the ruins of the Shadowsong Shrine, still in the armour of the queen's guard. Whatever he is guarding now, ten thousand years have not relieved him of it." },
      },
    },
    ["hydraxian-waterlords"] = {
      title = "The Hydraxian Waterlords", kind = "faction", chapter = "azshara", portrait = 10849,
      unlock = { { npc = 13278 }, { faction = 749, standing = 5 } },
      also = { "ragnaros", "molten-core", "azshara" },
      text = {
        { "On an island in the bay of Azshara lives Duke Hydraxis, a lord of the elementals of water, and the Hydraxian Waterlords he leads are at war with the other elements, above all with fire. Their great enemy is Ragnaros, the Firelord, in his Molten Core." },
        { "They are not friends of mortals, but they will make allies of those who fight their foes: the elementals of earth and air in the Plaguelands' wells and Silithus, and the lords of fire under Blackrock Mountain. To those they trust, they give the water that quenches the runes in the Molten Core, and a way to call out the Firelord's majordomo." },
      },
    },
    ["loramus-thalipedes"] = {
      title = "Loramus Thalipedes", kind = "figure", chapter = "azshara", portrait = 6879,
      unlock = { { npc = 7783 }, { quest = 3141 }, { quest = 2744 } },
      also = { "razelikh-the-defiler", "burning-legion", "azshara", "blasted-lands" },
      text = {
        { "On an island off the coast of Azshara, a demon hunter named Loramus Thalipedes lives alone with his felhounds. If you wish to battle demons, he says, you would do well to listen to his tale first." },
        { "Travellers come to him from the Blasted Lands, where Razelikh the Defiler keeps three servants who cannot die while the amulet pieces bound to them stay in that land. Loramus knows how such wards are broken. It takes the demon lord's true name, which a lesser god of Azshara's coast will trade for a price, and a weapon forged to bear it, made from the crystal the cliff giants of the south leave behind and worked by a smith who can handle fel fire." },
        { "He laughs at most of those who try. He does not refuse them, and he does not stop them. Whatever he hunted demons for, he seems to have decided long ago that the world needs more people doing it." },
      },
    },
    ["queen-azshara"] = {
      title = "Queen Azshara", kind = "figure", chapter = "azshara",
      unlock = { { area = 1223 } },
      also = { "azshara", "the-sundering", "naga", "satyrs", "ruins-of-eldarath", "burning-legion" },
      text = {
        { "This land carries the name of the night elves' last queen, and it is not a compliment. Azshara was beautiful and gifted and, in the beginning, loved by all her people. She built her palace on the shore of the Well of Eternity and filled it with her favoured servants, the Highborne, and set them to learn what the Well's power could do." },
        { "They learned magic, and it changed them. Azshara withdrew from her people and spoke only to her Highborne. Then the ripples of their spellcraft reached Sargeras, and the queen, overwhelmed by her own power, agreed to open the way for him. She and her Highborne made a portal in the depths of the Well, and the Burning Legion came through it." },
        { "At the end of the War of the Ancients the Well collapsed and the sea took her palace, her city and her court. The night elves say she was dragged down with them. The naga who haunt these shores were once her Highborne, and the ruins along this coast are what was left above the water." },
      },
    },
    ["ravencrest-monument"] = {
      title = "The Ravencrest Monument", kind = "history", chapter = "azshara",
      unlock = { { area = 1232 } },
      also = { "the-sundering", "azshara", "naga" },
      text = {
        { "The broken legs of a great statue stand on Azshara's southern cliffs. The place is called Ravencrest Monument. Naga occupy the ruins, and the remainder of the colossus lies scattered or beneath the sea. Even what is left makes a substantial landmark." },
        { "Lord Kur'talos Ravencrest commanded night elf resistance in the War of the Ancients from Black Rook Hold. His name recalls those who opposed Azshara and the Legion. Keep them in the history of these shores too, traveller. The queen's court was not the whole of the people whose world was destroyed." },
      },
    },
    ["ruins-of-eldarath"] = {
      title = "The Ruins of Eldarath", kind = "place", chapter = "azshara",
      unlock = { { area = 1221 } },
      also = { "azshara", "the-sundering", "naga", "explorers-league" },
      text = {
        { "Eldarath's Highborne ruins cling to Azshara's eastern cliffs above the Bay of Storms. Much of the city fell into the sea during the Sundering. Its inhabitants had carved their arcane learning into runes and tablets in public places, and some remain readable among the broken stone." },
        { "Warlord Krellian's naga now hold the ruins from the Temple of Zin-Malor. The night elves avoid the place, but the Explorers' League wants rubbings of the inscriptions. If you can get past the naga, traveller, those tablets may preserve something the sea has not yet taken." },
      },
    },
    ["the-sundering"] = {
      title = "The Sundering", kind = "history", chapter = "azshara",
      unlock = { { area = 1228 }, { read = { "The War of the Ancients", "고대의 전쟁", "La guerre des Anciens", "Der Krieg der Urtume", "上古战争", "La Guerra de los Ancestros", "Война Древних", "A Guerra dos Antigos", "上古戰爭" } } },
      also = { "burning-legion", "tyrande-whisperwind", "ravencrest-monument", "naga", "highborne-ruins" },
      text = {
        { "Ten thousand years ago, the night elves ruled Kalimdor from the shores of the Well of Eternity, a lake of pure magic at the heart of the world. Their queen was Azshara, the fairest of them all, and her Highborne drew on the Well's power without limit. Their magic drew the eye of Sargeras, the lord of the Burning Legion, and Azshara and her Highborne opened the way for him, believing the demons would make the world perfect." },
        { "The night elves who would not bow fought the Legion in the War of the Ancients. Lord Kur'talos Ravencrest led them at first, believing his queen a prisoner of her own advisers, until an assassin sent by her captain of the guard killed him on the battlefield. Command fell at last to a young officer, Jarod Shadowsong, who did what Ravencrest had refused to do and called on the other races, the earthen, the tauren, the furbolgs, and the demigods of the forest, Cenarius among them. The young druid Malfurion Stormrage and the priestess Tyrande fought at the heart of it. Malfurion's brother Illidan went over to the Highborne, and the dragon Neltharion turned on the other flights." },
        { "In the end, Malfurion saw that the Well itself was the Legion's door, and the Well of Eternity was destroyed. It tore itself apart and took the heart of the continent with it, and the sea rushed into the hole it left. Azshara and her Highborne went down with their palace. From this shore, the Shattered Strand, you look out over the place where the world broke." },
      },
    },
    ["angor-fortress"] = {
      title = "Angor Fortress", kind = "place", chapter = "badlands",
      unlock = { { quest = 762 }, { quest = 1139 } },
      also = { "hammertoes-digsite", "uldaman", "dark-iron-dwarves", "ragnaros", "explorers-league" },
      text = {
        { "Angor Fortress is the Shadowforge clan's hold in the Badlands, the Dark Iron keep from which they dig at Uldaman. They have been after the titans' secrets for a long time, and what they want most is the knowledge to make stronger golems. Hammertoe Grez was after it too, to keep it out of their hands, and he and Historian Karnik of the Hall of Explorers had been hunting the lost artifacts together." },
        { "The Shadowforge took Hammertoe into Uldaman to find out what he knew. The help Prospector Ryedol sent after him found him dying. Hammertoe asked for one thing, his amulet, which Magregan Deepshadow had taken and which could lead its bearer to the scrolls they were all after. Once it was recovered, Hammertoe had it carried to Ryedol, and Ryedol sent it on to Karnik. Hammertoe had been seeking the origins of our people, Ryedol said, and stopping the Shadowforge was part of the same work. Karnik went to consult his old partner's spirit, and Advisor Belgrum, on the king's authority, ordered a strike at Angor." },
        { "Ragnaros himself, it turned out, had sent an ambassador to Angor to oversee the Shadowforge's digging. When Ambassador Infernus fell, the clan lost its link to Blackrock Spire. Belgrum then sent the next traveller after Hammertoe's last dream, the Tablet of Will, a stone shard the titans are said to have inscribed to give their creations a will of their own. Hammertoe died for it without ever seeing it." },
      },
    },
    ["hammertoes-digsite"] = {
      title = "Hammertoe's Digsite", kind = "place", chapter = "badlands",
      unlock = { { area = 346 }, { area = 345 } },
      also = { "uldaman", "explorers-league", "dark-iron-dwarves", "rockjaw-troggs" },
      text = {
        { "Hammertoe's Digsite is the Explorers' League's camp at the gates of Uldaman, named for the prospector who led it, and it has had a hard time. The troggs came up out of the vault and overran the diggers. Prospector Agmond, who ran the southern sites, went quiet, and when someone went to look, they found his camp, and what was left of him. Hammertoe himself was taken by the Dark Irons of the Shadowforge clan, who want to know what he knows about the titans' works." },
        { "Prospector Ryedol holds what remains of the dig, and he does not give up easily. Neither, I hope, does Hammertoe. The Shadowforge have been hunting in Uldaman for the secrets of the titans' golems, and Hammertoe was hunting for them first, to keep them out of Dark Iron hands." },
      },
    },
    ["kargath"] = {
      title = "Kargath", kind = "place", chapter = "badlands",
      unlock = { { area = 340 } },
      also = { "dark-iron-dwarves", "the-badlands", "blackrock-depths" },
      text = {
        { "Kargath is the Horde's fortress in the north-west of the Badlands, a stockade on a cliff named for Kargath Bladefist, the one-handed chieftain of the Shattered Hand clan in the Second War. It is the camp of the Kargath Expeditionary Force, and its business is war with the Dark Iron dwarves of Blackrock Mountain to the west." },
        { "The orcs have reason. The Dark Irons of General Angerforge slaughtered a whole division of the Expeditionary Force, the hundred and ninth, and the warlord of Kargath has posted a standing order: kill on sight. On this one matter, a dwarf of Ironforge and an orc of Kargath see eye to eye." },
      },
    },
    ["platinum-discs"] = {
      title = "The Platinum Discs", kind = "history", chapter = "badlands",
      unlock = { { quest = 2278 } },
      also = { "uldaman", "rockjaw-troggs", "explorers-league" },
      text = {
        { "Deep in Uldaman, beyond the stone keeper Archaedas, four platinum discs preserve an account spoken by a stone watcher. It calls the Titans the Creators. They made the earthen from Azeroth's stone to shape its deep places: strong workers, tireless and difficult to harm." },
        { "The watcher says their making broke down under strain. One result retained their strength but lost their reason: the troggs, judged a failure and sealed beneath the earth. Another retained strength and wit but lost the stone. Those were the dwarves." },
        { "You can understand why the League values this record, traveller. It gives us dwarves a beginning to investigate, and makes the creatures disturbing the League's digs part of the same question as our own ancestors." },
      },
    },
    ["talvashs-necklace"] = {
      title = "Talvash's Necklace", kind = "history", chapter = "badlands", portrait = 5647,
      unlock = { { quest = 2361 }, { quest = 2341 } },
      also = { "uldaman", "the-lost-dwarves", "ironforge", "kargath", "orgrimmar" },
      text = {
        { "Talvash del Kissel is a gnome jeweller of Ironforge, of great renown until lately, and the necklace is one of his finest works. He made it for a paladin who had set himself to cleanse Uldaman of its evil taint, with three gems to bind its magic, and the city's seal and his own initials on the back. The paladin died in Uldaman. A rival in the trade then put it about that the necklace had cursed the paladin, and the orders have dried up ever since." },
        { "The gems stayed below. The paladin's journal, found on his remains, says where: the ruby behind the Shadowforge dwarves' barricades, the topaz in a trogg urn near some Alliance dwarves, of all people, the sapphire with Grimlok, the troggs' chief. To wake the necklace again Talvash needed a power source, and the strongest construct in the place had one. The restored necklace went to the one who brought it all back, with a request to mention its maker loudly and often, and to add that it is not cursed." },
        { "The Horde tells it otherwise. Droffers and Son Salvage of Orgrimmar heard of the dead paladin's necklace and sent for it, and Jarkal Mossmeld, a troll of Kargath with a spell for the human tongue, translated the journal on condition that he could study the necklace in the meantime. He kept the power source, made two necklaces from it, one for himself and one for whoever had done his fetching, and has enough left for at least three more. The Droffers know nothing of it. Talvash, I suspect, knows nothing of it either. I am not going to be the one to tell him." },
      },
    },
    ["the-badlands"] = {
      title = "The Badlands", kind = "place", chapter = "badlands",
      unlock = { { area = 3 } },
      also = { "uldaman", "hammertoes-digsite", "kargath", "dark-iron-dwarves", "ogres", "black-dragonflight" },
      text = {
        { "South of Loch Modan the land breaks open into the Badlands: red rock, dry canyons, mesas and dust, with hardly a tree or a stream in it. Buzzards circle, coyotes slink, ogres of the Dustbelcher clan hold the hills, and black dragons nest in Lethlor Ravine in the east." },
        { "Dwarves come here anyway, because under the Badlands lies Uldaman, the vault of the titans, and the Explorers' League has been digging at its door for years. So have the Dark Irons, from their fortress at Angor, and so have the troggs, who came up out of it. The Horde has a camp here too, at Kargath, to watch the Dark Irons. It is a busy wasteland." },
      },
    },
    ["the-lost-dwarves"] = {
      title = "The Lost Dwarves", kind = "figure", chapter = "badlands", portrait = 5710,
      unlock = { { read = { "Baelog's Journal", "밸로그의 일지", "Journal de Baelog", "Baelogs Tagebuch", "巴尔洛戈的日记", "Diario de Baelog", "Дневник Бейлога", "Diário de Baelog", "巴爾洛戈的日記" } }, { npc = 6906 }, { npc = 6907 }, { npc = 6908 }, { quest = 2240 } },
      also = { "uldaman", "explorers-league", "rockjaw-troggs", "hammertoes-digsite" },
      text = {
        { "When the troggs came up out of Uldaman, they came so fast that some of Ironforge's people were caught behind them. Baelog was one. A friend of Prospector Stormpike's at the Explorers' League, he had led a small band deep into the site just before the attack, and Stormpike sent travellers to learn whether any of them still lived." },
        { "They did, and in good spirits. Olaf had wagered that his beard would reach his knees before they saw another living soul, and when help arrived it still had a few inches to go. Eric, called the Swift, was the third. Trapped or not, Baelog had not been idle. His journal describes the way into the Chamber of Khaz'mul, behind a great locked door: take the Medallion of Gni'kiv from Baelog's chest, win the Shaft of Tsol from the trogg Revelosh, join the two into the Staff of Prehistoria and use it in the map room. Do these things, he wrote, and the chamber will be yours." },
        { "Baelog is sure the chamber is there. Uldaman was Ironforge's before the troggs came, and the Explorers' League has not given it up. Travellers of the Horde will find Baelog's band rather less glad to see them." },
      },
    },
    ["theldurin-the-lost"] = {
      title = "Theldurin the Lost", kind = "figure", chapter = "badlands", portrait = 4903,
      unlock = { { npc = 2785 } },
      also = { "myzrael", "twilights-hammer", "uldaman", "ironforge", "undercity" },
      text = {
        { "Theldurin the Lost lives rough in the Badlands and talks to himself, and some of what he says is worth hearing. He was once a member of the Twilight's Hammer. By the cult's own account he lost his mind, scorned its teachings and fled, taking with him the scroll that could call Myzrael to the surface. Theldurin's account is that he came to his senses. Something waits beneath the earth, the powers his old order calls the dwellers beneath, and he will not say their names in case they hear him." },
        { "What he wants now is to understand them well enough to keep them down. He sends travellers into Uldaman for a tablet kept in a chest older than any dwarven work, then for Yagyin's Digest, an old book his former order keeps in many places for its most learned to study. One copy is held in a shop in Ironforge's Forlorn Cavern, by a dwarf named Gerrig Bonegrip who greets the cult's sigil with praise to the dwellers beneath. Another is kept in the Undercity by Keeper Bel'dugur." },
        { "I would rather that first copy were anywhere but here. His shop, Bonegrip's Runes and Dooms, has sold books of unpronounceable names and living sacrifices under our king's mountain. Bonegrip, and Zaruk at Hammerfall for the Horde, send travellers after Theldurin with the same words: \"our order, the Twilight's Hammer\". They call him mad. Having seen what his old order keeps on its shelves, I think he may be the sanest member it ever had. If the dwellers beneath are ever freed, he says, we are all worm food. On that point the Royal Historian and the madman agree." },
        { side = "Horde", aside = true, sign = "P. F.", "Keeper Bel'dugur collects the workings of Ur for the Dark Lady, so he says, and keeps Yagyin's Digest for someone else. A keeper of books ought to know whose shelf he is filling." },
      },
    },
    ["uldaman"] = {
      title = "Uldaman", kind = "place", chapter = "badlands",
      unlock = { { area = 1337 }, { kill = 2748 } },
      also = { "platinum-discs", "hammertoes-digsite", "rockjaw-troggs", "dark-iron-dwarves" },
      text = {
        { "Uldaman lies beneath the Badlands, a Titan vault of carved halls and great stone guardians. The League's excavations opened a way into it. Troggs poured out, giving the League's diggers an unwelcome answer to a question long asked about those creatures." },
        { "Troggs now occupy the outer halls, and Shadowforge Dark Irons seek the secrets within. The League contends with both. Beyond Archaedas, the vault's final guardian, lie the Discs of Norgannon and their account of the Titans' work. The League has good reason to keep digging, even after learning what else its excavations can release." },
      },
    },
    ["agamaggan"] = {
      title = "Agamaggan", kind = "history", chapter = "barrens",
      unlock = { { area = 1700 }, { quest = 5052 } },
      also = { "quilboar", "razorfen-kraul", "razorfen-downs", "camp-taurajo" },
      text = {
        { "In the War of the Ancients, ten thousand years ago, the demigods of the wild rose against the Burning Legion, and among them was Agamaggan, a great boar. He fell. Where his blood soaked into the earth of the Barrens, colossal thorns grew, and blood-red stones formed in the ground. The quilboar live among the thorns, call themselves his children, and carry the stones as totems." },
        { "The quilboar's shamans still draw on his power, and a prisoner at Camp Taurajo will share its blessings for the right price. The great thorn-warrens of the south, the Razorfen, are his grave, and the quilboar treat them as holy." },
      },
    },
    ["bael-modan"] = {
      title = "Bael Modan", kind = "place", chapter = "barrens",
      unlock = { { area = 359 }, { area = 2157 } },
      also = { "the-barrens", "explorers-league", "rockjaw-troggs" },
      text = {
        { "General Twinbraid's dwarves have built Bael Modan beside their dig in the south-eastern Barrens, with a cannon and flying machines to support the settlement. Prospector Khazgorm of the Explorers' League works among them. An old site, a defended camp and one of the League's own prospectors: the beginnings of a familiar expedition." },
        { "Gann Stonespire describes what preceded it. This was his tribe's home, he says, before the blasts and machines tore the hills apart and drove its people away. Diplomacy has failed him. He now seeks Khazgorm's death and the destruction of the dwarves' flying machine." },
        { "Within the expedition, Feegly has suffered a curse from an unearthed stone. The dig has brought trouble to the people doing the digging as well as to those displaced by it. I would like to be proud of every place the League's name appears. Bael Modan makes that difficult." },
      },
    },
    ["barrens-oases"] = {
      title = "The Oases", kind = "place", chapter = "barrens",
      unlock = { { area = 387 }, { area = 388 }, { area = 386 } },
      also = { "wailing-caverns", "druids-of-the-fang", "the-barrens" },
      text = {
        { "The oases of the Barrens are its life: pools of fresh water in the dry grass, where the beasts and the travellers come to drink. Lately they have gone strange. Animals near them grow twisted, plants grow too fast and wrongly, and the druids of Thunder Bluff felt a power leaking into the land and sent one of their own to find it." },
        { "He found fissures at the bottom of the pools, reaching down into the earth. The oases are fed from below, from the caverns beneath the Barrens, and whatever is wrong in those caverns is coming up with the water." },
      },
    },
    ["camp-taurajo"] = {
      title = "Camp Taurajo", kind = "place", chapter = "barrens",
      unlock = { { area = 378 } },
      also = { "agamaggan", "quilboar", "the-barrens" },
      text = {
        { "Camp Taurajo is a tauren camp in the south of the Barrens, tents and totems around a fire, the last friendly place on the road to Thousand Needles. Its people hunt the southern plains and keep watch on the quilboar of the Razorfen thorns." },
        { "It has an odd guest: a quilboar named Mangletooth, a captive of the tauren, who knows the blessings of the boar-god Agamaggan and will teach them to anyone who brings him the right stones. The tauren tolerate him. He is, I am told, very rude." },
      },
    },
    ["druids-of-the-fang"] = {
      title = "The Druids of the Fang", kind = "faction", chapter = "barrens", portrait = 4213,
      unlock = { { kill = 3669 }, { kill = 3671 }, { kill = 3670 }, { kill = 3673 }, { quest = 914 } },
      also = { "wailing-caverns", "cenarion-circle" },
      text = {
        { "The Druids of the Fang were Naralex's disciples, an order of noble druids who went into the Wailing Caverns to heal the Barrens. The nightmare that took their master took them too. Now they mean to remake the land after their own twisted dreams, and have taken the shapes and names of serpents." },
        { "There are four leaders among them, Lord Cobrahn, Lady Anacondra, Lord Pythas and Lord Serpentis, and each carries a gem of the dream. The druids of Thunder Bluff say that their faces haunt them. They would like the gems brought home." },
      },
    },
    ["morshan-rampart"] = {
      title = "The Mor'shan Rampart", kind = "place", chapter = "barrens",
      unlock = { { area = 1703 }, { area = 1599 } },
      also = { "warsong-lumber-camp", "the-barrens", "ashenvale" },
      text = {
        { "Mor'shan stands at the Barrens' northern edge, where grassland gives way to Ashenvale. The Horde guards the route through the rampart, towards the Warsong logging operations and their conflict with the Sentinels." },
        { "The wall marks a border neither side regards as settled. The orcs need timber, and the night elves defend the forest supplying it." },
      },
    },
    ["northwatch-hold"] = {
      title = "Northwatch Hold", kind = "place", chapter = "barrens",
      unlock = { { area = 385 } },
      also = { "ratchet", "the-barrens", "tiragarde-keep" },
      text = {
        { "Soldiers of Theramore hold Northwatch above the Merchant Coast, south of Ratchet. Captain Thalo'thas Brightsun accuses its gunners of sinking ships from his fleet. He asks adventurers to silence the cannons and kill Captain Fairmount." },
        { "Jaina Proudmoore made peace with Thrall, yet fighting continues around the hold. A traveller along this coast can see why a ruler's agreement and a soldier's conduct must both be recorded when describing that peace." },
      },
    },
    ["ratchet"] = {
      title = "Ratchet", kind = "place", chapter = "barrens",
      unlock = { { area = 392 } },
      also = { "steamwheedle-cartel", "southsea-freebooters", "northwatch-hold", "the-barrens" },
      text = {
        { "Ratchet is a goblin port on the coast of the Barrens, one of the neutral towns of the Steamwheedle Cartel, where ships for Booty Bay come and go and nobody draws a blade on anybody without regretting it. Its master is Gazlowe, the same goblin engineer who helped Thrall build Orgrimmar, and he runs it as a business." },
        { "His troubles are mostly at sea: the Southsea Freebooters raid his ships from the Merchant Coast, and the Alliance gunners at Northwatch Hold, to the south, have sunk a few of them by mistake, or so they claim." },
      },
    },
    ["razorfen-downs"] = {
      title = "Razorfen Downs", kind = "place", chapter = "barrens",
      unlock = { { kill = 7895 }, { area = 722 }, { kill = 7358 } },
      also = { "agamaggan", "quilboar", "scourge", "razorfen-kraul" },
      text = {
        { "South of the Kraul lies another of Agamaggan's thorn-warrens, Razorfen Downs, and something terrible has happened there. The Death's Head quilboar who hold it have made a bargain with the Scourge. A lich, Amnennar the Coldbringer, rules the Downs now, the Scourge keep an ambassador among the quilboar, and the dead walk among the thorns of the boar-god's grave." },
        { "How the Lich King's servants reached so far into Kalimdor, no one can tell me. That they have, and that they are building there, is reason enough for every people in the Barrens to worry." },
      },
    },
    ["razorfen-kraul"] = {
      title = "Razorfen Kraul", kind = "place", chapter = "barrens",
      unlock = { { area = 491 }, { kill = 4421 } },
      also = { "agamaggan", "quilboar", "razorfen-downs" },
      text = {
        { "Charlga Razorflank rules Razorfen Kraul, a great maze of briars and tunnels in the southern Barrens. The quilboar shaman's warriors keep the boar Agathelos in its depths. The warren is a stronghold at the heart of their people." },
        { "Henrig Lonebrow's journal records his captivity there beside the wounded druid Heralath. Heralath asked him to warn Falfindel Waywarder at Thalanaar of Charlga's growing power. Lonebrow reached the Great Lift, but his body lies there with the journal. Falfindel asks others to complete their work." },
      },
    },
    ["the-barrens"] = {
      title = "The Barrens", kind = "place", chapter = "barrens",
      unlock = { { area = 17 } },
      also = { "the-crossroads", "ratchet", "barrens-oases", "centaurs", "quilboar", "harpies" },
      text = {
        { "The Barrens is the great savannah at the heart of Kalimdor: a sea of yellow grass and thorn trees under a huge sky, with herds of zhevra and kodo, lions and raptors, and a few precious oases where everything that lives here comes to drink. It is hot, dry and enormous, and it belongs, as far as anyone can say, to whoever holds the next waterhole." },
        { "That is a great many people. The Horde holds the Crossroads at its heart and the roads around it. The goblins hold Ratchet on the coast. The Alliance holds Northwatch in the east and a dwarven dig in the south. Centaurs raid from the hills, quilboar hold the thorn-warrens of the south, harpies nest in the gullies, and the Burning Blade and the Venture Company have their camps. A traveller in the Barrens learns to drink when he can and sleep with one eye open." },
      },
    },
    ["the-crossroads"] = {
      title = "The Crossroads", kind = "place", chapter = "barrens",
      unlock = { { area = 380 } },
      also = { "the-barrens", "centaurs" },
      text = {
        { "The Barrens' great roads meet at the Crossroads: north towards Orgrimmar, west to Mulgore, east to Ratchet and south to Thousand Needles. The Horde keeps a stockade, an inn and a wind rider's roost here, with a garrison serving the traffic between them." },
        { "Centaur activity and stolen supplies give that garrison work beyond its walls. Sergra Darkthorn offers hunting trials as well." },
      },
    },
    ["the-great-hunts"] = {
      title = "The Great Hunts", kind = "creature", chapter = "barrens", portrait = 1934,
      unlock = { { kill = 3475 }, { kill = 3257 }, { kill = 3474 }, { kill = 3472 }, { kill = 3476 }, { quest = 881 }, { quest = 882 }, { quest = 883 }, { quest = 885 }, { quest = 873 } },
      also = { "the-crossroads", "camp-taurajo", "tauren", "hunters" },
      text = {
        { "The tauren give the great beasts of the Barrens names, and hunting one is a lesson as much as a trial. Sergra Darkthorn sets travellers on that path at the Crossroads, and Jorn Skyseer at Camp Taurajo and Mahren Skyseer on the coast south of Ratchet take them further along it. I have the account from those who walked it, and from the tauren names themselves, which say more than our names would." },
        { "Echeyakee, Whitemist, is king of the savannah cats, so quiet in the hunt that his prey has no time for fear or pain: mercy and death at once, the tauren say. He keeps his lair among the bones of giant kodo north-east of the Crossroads and answers a horn. Ishamuhale, Speartooth, is the fiercest sunscale raptor of the plains, who kills because killing is his nature, and comes to a fresh zhevra left at a dead tree. Lakota'mani, Earthshaker, is a great kodo whose steps are like gathered thunder. Washte Pawne, Spirit Biter, is a thunderhawk whose death may mean great fortune or great doom, and whose feather hurts to hold. Isha Awak, Deep Doom, is lord of the waters off the coast, and the humans on that coast fear him for good reason." },
        { "What the hunter brings back is a fang, a hoof, a feather or a heart, and with it, the Skyseers say, something of the beast: the strength in subtlety and the honour in mercy, strength held with temperance, courage, the wisdom that regret becomes, and eyes that will one day learn to see. We dwarves hunt to eat and to boast. I am not sure we have ever thought to ask the boar what it had to teach." },
      },
    },
    ["wailing-caverns"] = {
      title = "Wailing Caverns", kind = "place", chapter = "barrens",
      unlock = { { area = 718 } },
      also = { "druids-of-the-fang", "barrens-oases", "cenarion-circle", "dragons-of-nightmare" },
      text = {
        { "Steam sounds like mourning in the caverns below the Barrens, where rivers pass through a maze of rock. Naralex saw their waters as a means of healing the dry country above. By linking them to the Emerald Dream, he hoped to make the Barrens green." },
        { "He descended with his disciples and slept. The dream became a nightmare. Naralex has not woken, the caverns' creatures have changed, and most of his followers have fallen with him. One disciple still seeks help to reach his master and perform a waking ritual." },
      },
    },
    ["blackrock-depths"] = {
      title = "Blackrock Depths", kind = "place", chapter = "blackrock-mountain",
      unlock = { { area = 1584 } },
      also = { "dagran-thaurissan", "moira-bronzebeard", "marshal-windsor", "molten-core", "dark-iron-dwarves" },
      text = {
        { "Blackrock Depths is the Dark Irons' city under the mountain: Shadowforge City, with its prisons, its arena, its vaults, its golem works and its tavern, the Grim Guzzler, where they brew a dark ale. At the bottom of it, in his palace, sits the emperor, and beyond him lies the way down into the Firelord's own domain." },
        { "The Alliance and the Horde both come here, the Horde for the Dark Irons' golems and their secrets, the Alliance for a captured marshal and for King Magni's daughter. There is a great deal of history here, and most of it is on fire." },
      },
    },
    ["blackrock-mountain"] = {
      title = "Blackrock Mountain", kind = "place", chapter = "blackrock-mountain",
      unlock = { { area = 25 }, { area = 254 }, { area = 1445 } },
      also = { "blackrock-depths", "blackrock-spire", "ragnaros", "nefarian", "dark-iron-dwarves", "blackrock-clan" },
      text = {
        { "Blackrock Mountain stands between the Searing Gorge and the Burning Steppes, a mountain of black stone with fire at its heart. It rose when Ragnaros came, and the Dark Irons, his slaves, built their city inside it. In the Second War, it was the Horde's great fortress, and after the war the orcs who escaped the Alliance took refuge in it." },
        { "Today the mountain is at war with itself. The Dark Irons hold the depths for the Firelord, and the orcs of the Dark Horde, with Nefarian's black dragons, hold the Spire above. Between them, in the middle of the mountain, chains hang over a lake of lava." },
      },
    },
    ["blackrock-spire"] = {
      title = "Blackrock Spire", kind = "place", chapter = "blackrock-mountain",
      unlock = { { area = 1583 } },
      also = { "rend-blackhand", "nefarian", "blackrock-clan", "black-dragonflight", "blackrock-mountain" },
      text = {
        { "The Dark Irons carved Blackrock Spire above their city, then lost it to the orcs. Orgrim Doomhammer held it in the Second War. The Alliance besieged the fortress near the war's end. Anduin Lothar fell at its gates before the Horde was broken." },
        { "Rend Blackhand now commands its orcs in Nefarian's service. Orcs, trolls and ogres fill the lower Spire, while the dragon and his followers hold the heights. The climb is through an occupied fortress, with a different master from the one its builders intended." },
      },
    },
    ["blackwing-lair"] = {
      title = "Blackwing Lair", kind = "place", chapter = "blackrock-mountain",
      unlock = { { area = 2677 } },
      also = { "nefarian", "black-dragonflight", "red-dragonflight", "blackrock-spire" },
      text = {
        { "Nefarian holds Blackwing Lair at the summit of Blackrock Spire. Here he breeds chromatic dragons by combining the blood of the dragonflights, seeking an army capable of overwhelming his enemies. The lair is both his fortress and the place where he makes its future soldiers." },
        { "The red dragon Vaelastrasz is there under Nefarian's control. Once a friend to mortals, he begs those who reach him to end his suffering. There is little comfort in reaching a friend here, traveller, when this is what he must ask of you." },
      },
    },
    ["dagran-thaurissan"] = {
      title = "Emperor Dagran Thaurissan", kind = "figure", chapter = "blackrock-mountain", portrait = 8807,
      unlock = { { kill = 9019 } },
      also = { "ruins-of-thaurissan", "moira-bronzebeard", "ragnaros", "blackrock-depths", "dark-iron-dwarves", "mekgineer-thermaplugg" },
      text = {
        { "Dagran Thaurissan rules the Dark Irons in Shadowforge City, descended from the Sorcerer-Thane who summoned Ragnaros. He keeps his ancestor's name, and I keep his ancestor's history. I doubt we would agree on much of it. The emperor calls himself the Firelord's most powerful servant. His crown has not freed his clan from the power his ancestor brought upon it." },
        { "He carries Ironfoe, and his agents have reached as far as Gnomeregan. He also made King Magni's daughter Moira his bride. Magni sent champions to kill him and bring her home. They killed the emperor. Moira's answer made the rest of their errand rather less simple." },
      },
    },
    ["franclorn-forgewright"] = {
      title = "Franclorn Forgewright", kind = "figure", chapter = "blackrock-mountain", portrait = 8698,
      unlock = { { npc = 8888 }, { npc = 9056 }, { kill = 9056 }, { quest = 3801 }, { quest = 3802 } },
      also = { "blackrock-depths", "dark-iron-dwarves", "dagran-thaurissan", "stonewrought-dam" },
      text = {
        { "Franclorn Forgewright was the chief architect of the Dark Iron dwarves and the inventor of the stonewrought method of building. He will tell you that you have almost certainly stood on something he made, and the great dam of Loch Modan bears his method's name. Shadowforge City, the Dark Irons' capital under the mountain, was his work." },
        { "He is dead. His ghost keeps to his tomb in Blackrock Mountain, seen only by those who are dead themselves, and his successor as architect, Fineous Darkvire, has taken his great hammer, Ironfel. Franclorn wants it put back in the hands of the statue the Dark Irons raised to him at the Shrine of Thaurissan. In return he gives up the key to the depths of what he calls his accursed city." },
        { "He built it all the same. A dwarf can disown a city and still be proud of its stonework, traveller. I have met several." },
      },
    },
    ["moira-bronzebeard"] = {
      title = "Princess Moira Bronzebeard", kind = "figure", chapter = "blackrock-mountain", portrait = 8705,
      unlock = { { quest = 4363 }, { quest = 4004 } },
      also = { "magni-bronzebeard", "dagran-thaurissan", "ironforge", "blackrock-depths" },
      text = {
        { "Moira Bronzebeard is Magni's only daughter and heir to Ironforge. The Dark Irons carried her away, and she became Emperor Dagran Thaurissan's wife. Her father believed the emperor had placed her under a spell and sent champions to release her." },
        { "They killed Thaurissan. Moira called him a great and honourable dwarf, and told them she carried his child. She declared that child would inherit Ironforge, regardless of Magni's approval. You may have carried Magni's orders, traveller, but Moira has an answer of her own." },
        { "I have kept the history of Magni's house for a long time. This is the first chapter of it I would rather not have to write." },
      },
    },
    ["molten-core"] = {
      title = "Molten Core", kind = "place", chapter = "blackrock-mountain",
      unlock = { { area = 2717 }, { quest = 7848 } },
      also = { "ragnaros", "blackrock-depths", "blackrock-mountain" },
      text = {
        { "Below Blackrock Depths, below everything, lies the Molten Core, a world of lava in the roots of the mountain, the Firelord's own domain. Ragnaros has lived there since Thaurissan summoned him, and his servants guard it: giants of fire and stone, the fallen lords of flame, and his majordomo, Executus, who alone may wake him." },
        { "A strange creature at the mountain's door, Lothos Riftwaker, sees tears in the world all around him and will show the way in to anyone bold enough. The Hydraxian Waterlords, Ragnaros's ancient enemies, will help anyone who goes." },
      },
    },
    ["nefarian"] = {
      title = "Nefarian", kind = "figure", chapter = "blackrock-mountain", portrait = 11380,
      unlock = { { kill = 11583 }, { npc = 10162 } },
      also = { "onyxia", "black-dragonflight", "blackwing-lair", "rend-blackhand", "ragnaros" },
      text = {
        { "Nefarian is Deathwing's son and Onyxia's brother. Like his sister, he takes human form: Lord Victor Nefarius commands the orcs of Blackrock Spire. The name conceals a dragon with designs far beyond the fortress." },
        { "From Blackwing Lair he fights Ragnaros for control of the mountain and breeds chromatic dragons with the Dark Horde's help. He intends them for wider conquest. Alliance and Horde champions have been sent against him, with the promise that his severed head will be displayed. A traveller seeking that prize must first pass through the army he has already gathered." },
      },
    },
    ["ragnaros"] = {
      title = "Ragnaros", kind = "figure", chapter = "blackrock-mountain", portrait = 11121,
      unlock = { { kill = 11502 } },
      also = { "molten-core", "dagran-thaurissan", "ruins-of-thaurissan", "war-of-the-three-hammers", "nefarian" },
      text = {
        { "Ragnaros, the Firelord, is an elemental lord summoned by the Dark Irons centuries ago in the hope of winning their war. He has held them in service ever since. Their emperor proclaims himself his servant, while fire elementals roam the gorge and steppes his arrival devastated." },
        { "In the Molten Core he waits amid lava, to be called forth by his majordomo. Nefarian contests his hold on the mountain, and the Hydraxian Waterlords continue their ancient opposition to him. The Dark Irons live between those powers, still bound to the one their ancestors asked for help." },
      },
    },
    ["rend-blackhand"] = {
      title = "Warchief Rend Blackhand", kind = "figure", chapter = "blackrock-mountain", portrait = 9778,
      unlock = { { kill = 10429 } },
      also = { "blackrock-clan", "blackrock-spire", "nefarian", "thrall", "eitrigg" },
      text = {
        { "Rend is the son of Blackhand the Destroyer, the Horde's first Warchief. He and his brother Maim led the Black Tooth Grin under Orgrim Doomhammer, their father's killer, while seeking both vengeance and the position Blackhand had lost." },
        { "Rend now claims the title of Warchief from Blackrock Spire, serving Nefarian and commanding the dragon's orcs. Thrall rejects that claim and sends champions to kill him, with Eitrigg's knowledge of the Blackrock helping guide the response. You will hear two claims to the Horde here, but only one of these leaders answers to a black dragon." },
      },
    },
    ["the-chromatic-flight"] = {
      title = "The Chromatic Flight", kind = "creature", chapter = "blackrock-mountain", portrait = 14367,
      unlock = { { kill = 10442 }, { kill = 10447 }, { kill = 10814 }, { kill = 14020 }, { kill = 14261 }, { kill = 14262 }, { kill = 14263 }, { kill = 14264 }, { kill = 14265 }, { kill = 14302 }, { npc = 10740 }, { area = 2677 } },
      also = { "nefarian", "blackwing-lair", "vaelastrasz", "black-dragonflight", "blue-dragonflight", "blackrock-spire" },
      text = {
        { "Vaelastrasz, who meets travellers in Blackrock Spire as Vaelan, says that before his banishment Deathwing was trying to breed offspring of his own: half-breeds immune to the powers of the Aspects, and wholly under his control. He failed. His son Nefarian, to judge by what crawls about the upper Spire, has at least partly succeeded. The abominations came to light through Ysera, the Aspect of Dreams, and she would not let the dragons stand by." },
        { "Awbee, a young whelp of the blue flight held captive in the Spire, knows how they are made. Riders on black dragons, he says, fell on the nests by night and carried off whelps like him. He saw his own brothers and sisters taken for Nefarian's experiments, and it was their essence that went into the chromatic flight. Nefarian wanted the failures killed at once. Their keepers made sport of them first, and what was left went into the lava or to the legion waiting below." },
        { "What came of it can be met in the upper Spire and in the lair above it: whelps and dragonspawn in the colours of every flight, drakonids bred from each of the five, and Chromaggus, the greatest of them, deep in Blackwing Lair. The blood of all five flights went into this brood, and only the black flight had any say in it." },
      },
    },
    ["the-veiled-blade"] = {
      title = "The Veiled Blade", kind = "history", chapter = "blackrock-mountain", portrait = 14308,
      unlock = { { quest = 8996 } },
      also = { "blackrock-spire", "stratholme", "dire-maul", "scholomance", "ras-frostwhisper", "balnazzar", "booty-bay" },
      text = {
        { "Blackrock Spire had a master before Drakkisath: Valthalak, a lord of the draconids and a warlock besides, and a powerful one. The Veiled Blade killed him. They were a company of mercenaries under Anthion Harmon, hired by Gremnik Rizzlesprang, a goblin smuggler of Booty Bay with an interest in wizardry, to bring him Valthalak's spellbook. They reached the upper Spire, killed Valthalak in his lair and took the book. Then Kormok, the company's two-headed ogre necromancer, tore the amulet from the dead lord's neck." },
        { "Nobody knew yet that the amulet held a great part of Valthalak's spirit. The company fought over it, broke it in three and diced for the pieces, and Valthalak's ghost rose among them with his spectral assassins. They fled, and Mor Grayhoof, a tauren druid, fell, or was pushed, into the lower Spire, where the trolls took him. The company broke up, and one by one its members died. The assassins finished Mor while War Master Voone had him under torture. Isalien died on her way into Dire Maul, and the Crusade-minded siblings Jarien and Sothos at the Grand Crusader's own hand. Kormok died in the Scholomance in front of Ras Frostwhisper. Gremnik, who had hired them, died as well, and Anthion fell outside Stratholme, trying to free his wife. Valthalak's assassins found some of them, and the world found the rest." },
        { "Bodley, a gnome of the company who died trying to get back into the Spire, haunts Blackrock Mountain still, seen only through a goblin's ghost-revealing device. It was Bodley who set about undoing it all. The pieces were won back from those who held them, Valthalak was raised in what is now the Beast's chamber and killed a second time, and his amulet was given back to him whole. He spared the one who had brought it, called off his assassins and promised the survivors they were safe, for now. Bodley wrote the whole affair down afterwards in a user's manual for a brazier. It is the most cheerful account of a massacre I have read." },
      },
    },
    ["vaelastrasz"] = {
      title = "Vaelastrasz", kind = "figure", chapter = "blackrock-mountain", portrait = 13992,
      unlock = { { npc = 10296 }, { kill = 13020 } },
      also = { "red-dragonflight", "nefarian", "blackwing-lair", "blackrock-spire", "the-chromatic-flight", "the-scepter-of-the-shifting-sands" },
      text = {
        { "Vaelastrasz is a red dragon of the Dragonqueen's flight, and a thousand years ago he was entrusted with a shard of the scepter that sealed Ahn'Qiraj. In Blackrock Spire he appears to mortals as Vaelan, in a form, as he puts it, that they can bear to look at, and he helps the bold forge the Seal of Ascension that opens the upper citadel to them." },
        { "He has seen the dragons brought to the edge of extinction, he says: by the Burning Legion's onslaught and the Demon Soul, by the Aspects' division and Deathwing's rise, and by the Dragonmaw, who enslaved his own queen, Alexstrasza. Deathwing was Neltharion once, the Aspect of the world's strength, given power over it by the titan Khaz'goroth, and he talked the other four Aspects into giving their powers to the Demon Soul, which left them weak and divided. Now his son Nefarian holds the Spire and carries on his father's work, behind ancient wards that no dragon of another flight can pass. A mortal with the Seal can." },
        { "The forging takes gems from three of the Spire's generals and the breath of a black drake whose will has been broken. The red flight has never minded borrowing its enemy's fire." },
        { "Nefarian caught him in the end. In Blackwing Lair he waits, twisted by the black dragon's corruption, and begs those who reach him to take the scepter shard back before it is destroyed. 'Too late, friends,' he says, and turns on them. Those who bring him down are told afterwards that his soul is at ease. I hope so." },
      },
    },
    ["blasted-lands"] = {
      title = "Blasted Lands", kind = "place", chapter = "blasted-lands",
      unlock = { { area = 4 } },
      also = { "nethergarde-keep", "the-dark-portal", "burning-legion", "swamp-of-sorrows" },
      text = {
        { "South of the Swamp of Sorrows, past a single road and a single keep, lie the Blasted Lands: a red, cracked waste of dust and dead trees, where the beasts are twisted and the soil is tainted. This is where the orcs first came into our world, through the Dark Portal, and where they were driven back. The land has never recovered." },
        { "Demons of the Burning Legion still walk here. The Alliance keeps watch from Nethergarde, the ogres hold their own camps, and the Horde has its own business with the demons. Everyone who comes here comes for the Portal, or for what it left behind." },
      },
    },
    ["kirith-the-damned"] = {
      title = "Kirith the Damned", kind = "figure", chapter = "blasted-lands", portrait = 6688,
      unlock = { { quest = 2721 } },
      also = { "the-fallen-hero", "razelikh-the-defiler", "loramus-thalipedes", "blasted-lands" },
      text = {
        { "Lieutenant Kirith served the hero of the Horde whose ghost now waits outside Stonard. The two of them were taken in the Blasted Lands by Archmage Allistarj and imprisoned in a cave there. The hero held out. Kirith's will gave way. His commander heard the experiments from his own cage, the screams ringing through the halls, and after that he saw and heard no more of him." },
        { "What the experiments made of him walks the Serpent's Coil now as Kirith the Damned. Put an end to it and what is left of the lieutenant will speak to you, and even grin: he knows how Razelikh the Defiler guards himself, with three servants each wearing a third of an amulet, and he sends you back to his commander with the news. Putting an end to it is one of the few kind things that has happened in the Blasted Lands in a long time." },
      },
    },
    ["lord-kazzak"] = {
      title = "Lord Kazzak", kind = "figure", chapter = "blasted-lands", portrait = 12449,
      unlock = { { kill = 12397 }, { area = 73 } },
      also = { "burning-legion", "blasted-lands", "the-dark-portal" },
      text = {
        { "Lord Kazzak holds the Tainted Scar in the southern Blasted Lands. Since the Third War, this great doomguard has occupied it with felguard and others of his kind. He walks openly among them, a horned servant of the Burning Legion with little need for concealment." },
        { "Heroes of both factions have gone against him. Each one he kills strengthens him. Bear that in mind, traveller, if you join them: a failed attack can leave the next party facing a stronger enemy." },
      },
    },
    ["nethergarde-keep"] = {
      title = "Nethergarde Keep", kind = "place", chapter = "blasted-lands",
      unlock = { { area = 1438 } },
      also = { "the-dark-portal", "dalaran", "blasted-lands" },
      text = {
        { "Khadgar urged the building of Nethergarde after the Second War, to keep watch over the Dark Portal. The Alliance kingdoms paid for it with varying degrees of enthusiasm, and Dalaran supplied its mages. When the orcs reopened the Portal, they besieged the keep. The watch had been needed." },
        { "Nethergarde now relies on Stormwind's caravans. Its mages study the Portal and the waste around it. One scholar preserves Khadgar's essays on dimensional convergence. Elsewhere in the Blasted Lands, the draenei Kum'isha seeks relics that might open a route home. A traveller will find several reasons to study a passage that has brought so much harm." },
      },
    },
    ["razelikh-the-defiler"] = {
      title = "Razelikh the Defiler", kind = "figure", chapter = "blasted-lands", portrait = 10543,
      unlock = { { kill = 7664 }, { quest = 3628 } },
      also = { "the-fallen-hero", "burning-legion", "blasted-lands" },
      text = {
        { "Razelikh the Defiler is a demon who rules from a lair at the top of the highest mountain in the Blasted Lands, with three lieutenants under him: Grol the Destroyer, Lady Sevine and Archmage Allistarj. They took the warriors of the Horde's Fallen Hero, and bound their spirits in stones of torment." },
        { "The Fallen Hero has sent travellers to free his men, kill the three lieutenants and take their amulets, and with the amulet made whole, climb to Razelikh's altar and call the demon out. His horn, he says, will be proof that heroes still exist in this war-torn world." },
      },
    },
    ["the-dark-portal"] = {
      title = "The Dark Portal", kind = "history", chapter = "blasted-lands",
      unlock = { { area = 72 }, { area = 2517 }, { read = { "Beyond the Dark Portal", "어둠의 문 저편", "Au-delà de la Porte des ténèbres", "Jenseits des Dunklen Portals", "跨越黑暗之门", "Más allá de El Portal Oscuro", "За Темным порталом", "Além do Portal Negro", "跨越黑暗之門" } } },
      also = { "nethergarde-keep", "karazhan", "blackrock-clan", "burning-legion" },
      text = {
        { "The Dark Portal is a great gate of stone between our world and Draenor, the orcs' world. The warlock Gul'dan opened it from the other side, and the Guardian Medivh helped him from ours, and through it, some twenty-five years ago, came the Horde. The First War, the Second War, everything that followed, came through that gate." },
        { "After the Second War it was shattered, and opened again by Ner'zhul, who wanted new worlds to conquer. An Alliance expedition under Khadgar and Turalyon went through it to Draenor to end the threat, and destroyed the Portal from the other side, cutting their route back to Azeroth. Its great stone frame stands in the middle of the waste, its passage dormant, and the demons gather around it." },
      },
    },
    ["altar-of-storms"] = {
      title = "The Altar of Storms", kind = "history", chapter = "burning-steppes",
      unlock = { { area = 255 } },
      also = { "blackrock-clan", "ogres", "blackrock-spire" },
      text = {
        { "The Altar of Storms stands in Blackrock Spire's shadow, a surviving place of the old Horde's warlock rites. In the Second War, magic worked at such altars turned ogres into ogre magi, giving them cunning and the power to cast spells." },
        { "Blackrock warlocks still gather here. Mor'zul Bloodbringer, who has studied the altar, camps nearby and sends other warlocks on errands of his own." },
      },
    },
    ["anduin-lothar"] = {
      title = "Anduin Lothar", kind = "figure", chapter = "burning-steppes",
      unlock = { { area = 46 } },
      also = { "the-first-war", "the-second-war", "sons-of-lothar", "blackrock-spire", "karazhan", "orgrim-doomhammer" },
      text = {
        { "Anduin Lothar was the last of the Arathi bloodline, the line of Thoradin who first united mankind, and he served King Llane of Stormwind as his champion and lieutenant-at-arms. It was Lothar who stormed Karazhan with young Khadgar and killed Medivh, his old friend, when he understood what the Guardian had done." },
        { "He came home too late to save Stormwind, led its people across the sea to Lordaeron and became Supreme Commander of the Alliance. Even the elves of Quel'Thalas came, however reluctantly, because of the debt they owed his ancestors." },
        { "He died here. With the Horde penned in Blackrock Spire, Orgrim Doomhammer charged out with his lieutenants and met Lothar's paladins in the middle of these plains. The two fought until both were spent, and Doomhammer killed him. His lieutenant, Turalyon, took up Lothar's bloodstained shield and broke the Horde in the rout that followed. The expedition that later marched through the Dark Portal went as the Sons of Lothar." },
      },
    },
    ["burning-steppes"] = {
      title = "Burning Steppes", kind = "place", chapter = "burning-steppes",
      unlock = { { area = 46 } },
      also = { "morgans-vigil", "ruins-of-thaurissan", "blackrock-mountain", "blackrock-clan", "black-dragonflight", "redridge-mountains" },
      text = {
        { "The Burning Steppes lie south of Blackrock Mountain, a wide plain of ash, lava and black rock under a red sky. Once all of this was the northern end of the Redridge Mountains, before Thaurissan woke the Firelord. The explosion that followed took the mountains, the forests and the Dark Irons' own city, and left this." },
        { "It is a land at war. The Blackrock orcs of the Dark Horde hold the Spire and the passes, the black dragonflight nests on the heights, and ogres hold Dreadmaul Rock. The Alliance has a foothold at Morgan's Vigil in the south-east, and there is a little neutral outpost at Flame Crest, on a rock above the lava, where anyone can rest." },
      },
    },
    ["marshal-windsor"] = {
      title = "Marshal Windsor", kind = "figure", chapter = "burning-steppes", portrait = 8707,
      unlock = { { npc = 9023 }, { quest = 4241 } },
      also = { "morgans-vigil", "blackrock-depths", "katrana-prestor", "great-masquerade" },
      text = {
        { "Marshal Reginald Windsor commanded Alliance soldiers at Morgan's Vigil and gathered evidence linking the Blackrock orcs to the black dragonflight. He came to suspect that someone in Stormwind wanted the evidence lost. The Dark Irons captured him and took his notes, then set about deciphering their code." },
        { "Windsor is held in Shadowforge City's prison. He insists that Bolvar Fordragon is blind to the truth, though the proof stands two feet from him. Whoever gets him out will learn what he means." },
      },
    },
    ["morgans-vigil"] = {
      title = "Morgan's Vigil", kind = "place", chapter = "burning-steppes",
      unlock = { { area = 2418 } },
      also = { "burning-steppes", "marshal-windsor", "black-dragonflight", "lakeshire", "katrana-prestor" },
      text = {
        { "Morgan's Vigil occupies a burned village in the south-eastern Burning Steppes. A ruined mage tower and tents shelter Alliance soldiers under Marshal Maxwell. They stand between the Blackrock forces and Lakeshire, beyond the mountains." },
        { "Their reports identify the black dragonflight as the power driving the orcs. Stormwind asked for proof. Lady Prestor saw no cause for alarm. A traveller can learn here both what the soldiers have discovered and how little help that discovery has yet brought them." },
      },
    },
    ["ruins-of-thaurissan"] = {
      title = "The Ruins of Thaurissan", kind = "history", chapter = "burning-steppes",
      unlock = { { area = 250 } },
      also = { "war-of-the-three-hammers", "ragnaros", "dark-iron-dwarves", "blackrock-mountain" },
      text = {
        { "These are the ruins of the city of Thaurissan, the capital of the Dark Iron clan after they left Ironforge, centuries ago, when the Burning Steppes were green. When their armies were destroyed at Ironforge and Grim Batol, the Sorcerer-Thane Thaurissan and seven of his greatest dwarves went down to call on the powers sleeping beneath the world, to turn the war." },
        { "What answered was Ragnaros, the Lord of Fire. The mountain burst. The city was destroyed, the valleys burned, and the Dark Irons who lived became the Firelord's slaves. The relics of the city still remember: those who touch them see eight dwarves at a ritual, and then one alone, kneeling among seven corpses before a pillar of flame. I have told this story at the High Seat more times than I can count, and those relics explain a good deal of it that I had only guessed. A goblin in Morgan's Vigil, Maxwort, will tell you that the Seven were dwarves of great knowledge, and that knowledge brings wealth. Goblins." },
      },
    },
    ["druids"] = {
      title = "Druids", kind = "calling", chapter = "callings",
      unlock = { { calling = "DRUID" } },
      also = { "cenarion-circle", "moonglade", "keeper-remulos", "hamuul-runetotem" },
      text = {
        { "The first druid was Malfurion Stormrage, taught by the demigod Cenarius before the War of the Ancients. After the Well's destruction, the night elves who had given up the arcane followed him, and for thousands of years the druids slept in the Emerald Dream, waking only when the world needed them." },
        { "They wake now, and they are not only night elves: the tauren have druids of their own, and both answer to the Cenarion Circle in Moonglade. A druid takes the shapes of the wild, bear, cat and seal among them, heals with the Dream's green magic and calls the moon and the stars down on enemies." },
        { "Skyborne druids now practise on both sides of the Alliance's quarrel with the Horde." },
        { "Malfurion himself has gone into the Dream and not come back. For all the Circle's work in the waking world, its greatest teacher remains beyond the reach of an ordinary messenger." },
      },
    },
    ["hunters"] = {
      title = "Hunters", kind = "calling", chapter = "callings",
      unlock = { { calling = "HUNTER" } },
      also = {  },
      text = {
        { "Every people that lives close to the wild has its hunters. The dwarves have their mountaineers, sure of their aim on any slope, and the night elves their huntresses and Sentinels. The orcs and trolls have their trackers and beast-tamers, and the tauren their braves, who still follow the herds as their grandparents did." },
        { "What sets a hunter apart is a companion. A wolf, a cat, a bear, a raptor, an owl: tamed in the wild, it learns to fight at the hunter's side. Feeding and tending it are as much a part of the calling as learning to shoot. The beast has to be persuaded that this new arrangement is worth its while." },
        { "Humans now train as hunters too, and the Skyborne bring hunters to both the Alliance and the Horde." },
        { "The League has employed hunters as guides for as long as it has existed, traveller. They find the road and the dinner, and they keep both from finding the diggers first." },
      },
    },
    ["mages"] = {
      title = "Mages", kind = "calling", chapter = "callings",
      unlock = { { calling = "MAGE" } },
      also = { "dalaran", "jaina-proudmoore", "archmage-arugal" },
      text = {
        { "The human art of magic began with a hundred students. During the Troll Wars, the high elves of Quel'Thalas taught them to work spells in exchange for help against the Amani, and their heirs founded Dalaran and its ruling council, the Kirin Tor. The city became the great centre of human arcane learning." },
        { "Dalaran fell in the Third War, and its students scattered: to Theramore with Jaina Proudmoore, to Stormwind, to the Undercity among the Forsaken, some of whom studied there in their first lives. Gnomes and Darkspear trolls have mages of their own. A Kirin Tor education is one road into the art, though its graduates sometimes speak as if it were the only one." },
        { "Orcs have been seen at the mages' trade too, and the Skyborne's High Order has come down looking for the arcane lore their people lost." },
        { "A mage conjures fire, frost and pure arcane force, and a good deal of fresh water. I recommend one on every dig, traveller, for the water alone." },
      },
    },
    ["paladins"] = {
      title = "Paladins", kind = "calling", chapter = "callings",
      unlock = { { calling = "PALADIN" } },
      also = { "church-of-the-holy-light", "uthers-tomb", "tirion-fordring", "argent-dawn", "whitemane-and-mograine" },
      text = {
        { "The first paladins were the Knights of the Silver Hand, founded in the Second War by Archbishop Alonsus Faol to carry the Holy Light onto the battlefield. Uther the Lightbringer led them, and they fought for the Alliance through the war and the long peace after it." },
        { "The Third War shattered the order. Prince Arthas, a paladin himself, turned on everything it stood for, and Uther fell to him at Andorhal. Its surviving knights scattered to Stormwind, Ironforge and the Plaguelands, where some serve the Argent Dawn and others the Scarlet Crusade's harsher idea of the Light. The same oath has led its bearers to bitterly different company." },
        { "Humans and dwarves still swear to the Light in Stormwind and Ironforge, while some of the Forsaken now take up the paladin's calling too. Death has not closed the Light to them." },
      },
    },
    ["priests"] = {
      title = "Priests", kind = "calling", chapter = "callings",
      unlock = { { calling = "PRIEST" } },
      also = { "church-of-the-holy-light", "northshire-abbey", "tyrande-whisperwind" },
      text = {
        { "Priests serve their people's faith, and their people's faith differs. In Stormwind and Ironforge they serve the Holy Light. The night elves' priestesses serve Elune, the moon, and have kept her temples for ten thousand years." },
        { "On the Horde's side, the Darkspear have priests of their own, and the Forsaken keep theirs too, whose prayers lean towards the shadow as readily as the Light. A priest of any of them can mend a wound, shield a friend, raise the fallen, or turn the same power on an enemy." },
        { "Gnomes now count priests among their people, adding another calling to the company in Tinker Town." },
        { "They are the most welcome company a dig can have, traveller, and the least appreciated until somebody falls into a shaft." },
      },
    },
    ["rogues"] = {
      title = "Rogues", kind = "calling", chapter = "callings",
      unlock = { { calling = "ROGUE" } },
      also = { "si-7", "ravenholdt-manor", "defias-brotherhood", "syndicate" },
      text = {
        { "Every city has its quiet trades, and the rogues practise all of them: the lock that opens without a key, the purse that changes hands without its owner knowing, the blade from behind. Some serve a crown, as Stormwind's SI:7 does. Some serve no one but the coin, like the Defias in Westfall and the Syndicate in Alterac." },
        { "Between the two stand the assassins of Ravenholdt, in the hills of Alterac above Hillsbrad, who are said to choose their contracts and their students with equal care. Rogues of every people pass through its gates, and few talk about what they learned there." },
        { "A rogue fights with poisons, quick hands and surprise, and leaves when the odds turn. The League has hired a few to recover what others had already taken from it, traveller. It is not the proudest line in the League's accounts, but it is one of the longest." },
      },
    },
    ["shamans"] = {
      title = "Shamans", kind = "calling", chapter = "callings",
      unlock = { { calling = "SHAMAN" } },
      also = { "thrall", "frostwolf-clan", "earth-mother", "the-windshapers" },
      text = {
        { "On Draenor the orcs' shamans spoke with the elements and their ancestors, until Gul'dan's warlocks turned many of them to fel magic and the spirits fell silent. Among the Frostwolves in Alterac, the old shaman Drek'Thar kept the ways alive, and taught them to a young escaped slave called Thrall." },
        { "Thrall brought shamanism back to his people, and in Kalimdor they found others who had never lost it: the tauren, who honour the Earth Mother, and the trolls, whose witch doctors had kept their own. A shaman asks earth, fire, water and air for help, and carries a totem of each, and the elements, mostly, answer." },
        { "Lately dwarves have been seen calling on the stone and the storm too, and the Skyborne's Windshapers have come down looking for their lost wind spirits among the shamans of the Horde." },
        { "The League has learned to ask a shaman's leave before a dig, traveller. The ground has opinions, and they hear them." },
      },
    },
    ["the-charger"] = {
      title = "The Charger", kind = "creature", chapter = "callings", portrait = 14590,
      unlock = { { quest = 7647 } },
      also = { "paladins", "scholomance", "church-of-the-holy-light", "eastern-plaguelands", "dire-maul" },
      text = {
        { "A paladin's charger is not bought or bred. It has to be won back. Lord Grayson Shadowbreaker, who guides the order's knights to their chargers from Stormwind's Cathedral District, tells them that the work will try two things above all, sacrifice and judgment, and that none of it is a schoolroom exercise: their future companion is in the hands of the evil they have spent their lives fighting." },
        { "Sacrifice begins in coin, paid to High Priest Rohan of Ironforge for his exorcism censer. Judgment begins in Terrordale in the Eastern Plaguelands, where the censer, seasoned with the place's own tainted soil, is carried among the tormented spirits to drive them out. The barding comes from Grimand Elmore of Stormwind's Dwarven District, one of the finest armourers living by Grayson's account and the finest by his own. The blessing comes from an Ancient Equine Spirit held in Dire Maul by the corrupted treant Tendris Warpwood. Once the treant is dead, the spirit has to be fed before it will give it." },
        { "The charger itself is in the Scholomance. Its bones lie in the Great Ossuary, and the death knight Darkreaver rides what is left of its soul. A scryer built around the same censer calls up the spirits there, and after them the death knight, and when he falls the paladin hands the charger back its soul. Of all the mounts I have recorded, it is the only one that has to be saved first." },
      },
    },
    ["the-dreadsteeds-of-xoroth"] = {
      title = "The Dreadsteeds of Xoroth", kind = "creature", chapter = "callings", portrait = 14552,
      unlock = { { quest = 7631 } },
      also = { "warlocks", "dire-maul", "shadow-council", "jaedenar", "dreadlords", "burning-legion" },
      text = {
        { "The dreadsteeds live on another world, the burning Plains of Xoroth, which Hel'nurath, a lord among demons, counts as his own, and a warlock who wants one must open a way there and take it. Mor'zul Bloodbringer, camped by the Altar of Storms in the Burning Steppes, sells the knowledge, at a price paid in blood, sweat and a good deal of gold." },
        { "The glyphs are inked in the blood of Winterspring's owlbeasts, maddened by the demons of Darkwhisper Gorge. Mor'zul's servant Gorzeeki Wildeyes, a goblin alchemist who prefers his blood still warm inside a rodent, makes the rest from what the warlock brings him: a bell named for the late warlock Dethmoora Darkeyes, a wheel and a candle for the circle, and a lodestone of arcanite to hold it together. The parchment needs Xorothian stardust, which only the dreadlord Banehollow, in the Shadow Council's seat at Jaedenar, can supply, and not for nothing. He wanted the heart of his own servant Ulathek, who had been spying for Hel'nurath. He meant to eat it once it had rotted for a week. The stardust goes into the paper by way of an imp in a jar, let out in the Scholomance's alchemy lab." },
        { "The ritual is done in Dire Maul: a Circle of Greater Summoning, the parchment, a portal to Xoroth, and something comes through that has to be beaten before its spirit will bend. A demon lord, a dreadlord, the Shadow Council and that imp all have a hand in it. I record it because it is true, traveller, not because I recommend it." },
      },
    },
    ["warlocks"] = {
      title = "Warlocks", kind = "calling", chapter = "callings",
      unlock = { { calling = "WARLOCK" } },
      also = { "burning-blade", "burning-legion" },
      text = {
        { "Gul'dan brought warlock magic into the orcish Horde. He and his Shadow Council learned it from Kil'jaeden, and with it they turned their people into weapons of the Burning Legion. The Horde's warlocks raised the dead, called demons and burned whole lands, and their art outlived their masters." },
        { "Its students are found on both sides now. The Burning Blade still serves the Legion in Durotar. Stormwind's warlocks keep to the cellar of the Slaughtered Lamb. Gnomes and Forsaken study it too. A warlock binds demons to serve, lays curses, and pays for power with their own life when nothing else will do." },
        { "The Darkspear now count warlocks among their own spellcasters as well." },
        { "Most cities tolerate warlocks without trusting them, traveller, and the warlocks seem to prefer it that way." },
      },
    },
    ["warriors"] = {
      title = "Warriors", kind = "calling", chapter = "callings",
      unlock = { { calling = "WARRIOR" } },
      also = {  },
      text = {
        { "There is no single order of warriors, traveller, only a craft as old as the first quarrel. Lordaeron's footmen and Stormwind's knights, the orc grunts who broke those same walls, the tauren braves of the plains and the Darkspear's hunters of the islands learned the same lessons by different roads." },
        { "The craft has its schools all the same. A warrior learns to stand three ways. Battle stance is for striking first and hard. Defensive stance holds a line behind a shield. A berserker's fury spends the body's strength freely and asks for it back later. Most of the work is learning which the moment needs." },
        { "Every capital keeps a hall where warriors train the young. The League hires a good many of them as escorts, and I have yet to meet one who did not have an opinion about where the diggers should dig." },
      },
    },
    ["auberdine"] = {
      title = "Auberdine", kind = "place", chapter = "darkshore",
      unlock = { { area = 442 } },
      also = { "darkshore", "remtravels-excavation" },
      text = {
        { "Auberdine is the night elves' harbour on Darkshore, a village of graceful houses on the shore, with ships for Teldrassil and for Menethil Harbor across the sea. For most travellers from the Eastern Kingdoms it is the first night elf town they ever see." },
        { "The Sentinels who keep it have their hands full, and they are glad of help. The League has a friend here too. Ask after Prospector Remtravel, and be prepared for a long story." },
      },
    },
    ["darkshore"] = {
      title = "Darkshore", kind = "place", chapter = "darkshore",
      unlock = { { area = 148 } },
      also = { "auberdine", "highborne-ruins", "furbolgs", "naga", "twilights-hammer", "teldrassil" },
      text = {
        { "Darkshore is a long strip of misty coast on the northern edge of Kalimdor, dark pine forest on one side and grey sea on the other, with Teldrassil standing up out of the water to the west. The night elves have lived here since before the Sundering, and the coast is full of their ruins: towers and halls of the Highborne, the old nobility of Queen Azshara's court, whose ghosts walk them still." },
        { "It has been a troubled coast of late. Great sea creatures have been washing up on the beaches to die, the Blackwood furbolgs have turned savage, naga prowl the shores, and the Twilight's Hammer have set up camp in the south. The night elves of Auberdine are worried, and say so, which for night elves is a great deal." },
      },
    },
    ["highborne-ruins"] = {
      title = "The Highborne Ruins", kind = "history", chapter = "darkshore",
      unlock = { { area = 447 }, { area = 446 }, { area = 443 }, { read = { "The Lay of Ameth'Aran", "아메스아란의 부흥", "Le Lai d'Ameth'Aran", "Die Lage von Ameth’Aran", "亚米萨兰的衰落", "La instauración de Ameth'Aran", "Песнь об Амет'Аране", "A Fundação de Ameth'Aran" } }, { read = { "The Fall of Ameth'Aran", "아메스아란의 멸망", "La Chute de Ameth'Aran", "Der Untergang von Ameth’Aran", "亚米萨兰的毁灭", "La caída de Ameth'Aran", "Падение Амет'Арана", "A Queda de Ameth'Aran" } } },
      also = { "darkshore", "satyrs", "auberdine" },
      text = {
        { "Ten thousand years ago the Highborne, the sorcerer-nobles of Queen Azshara, dwelt in towers along this coast, Ameth'Aran and Bashal'Aran among them, and practised their magics freely. The war at the Well of Eternity destroyed them. Tablets in Ameth'Aran still tell the story of its fall, for anyone who can read the old runes and is not frightened off by the spirits." },
        { "The dead have not left. The ghosts of the Highborne haunt both ruins, and in Ameth'Aran there is the spirit of a woman named Anaya Dawnrunner, whose lover Cerellean Whiteclaw survived her by ten thousand years and still dreams of her in Auberdine. In Bashal'Aran another spirit, Asterion, lies imprisoned behind a seal set by one of the most powerful of his kind, and the satyrs and sprites who feed on the ruins' magic will not go near his shrine." },
      },
    },
    ["masters-glaive"] = {
      title = "The Master's Glaive", kind = "place", chapter = "darkshore",
      unlock = { { area = 449 } },
      also = { "onu", "twilights-hammer", "darkshore" },
      text = {
        { "In the south of Darkshore a vast blade stands driven into the earth, too great for any hand that walks the world now, and the night elves call the place the Master's Glaive. Onu, the Ancient of Lore, says it marks a place where one of the old lords of the earth fell, long, long ago." },
        { "That is why the Twilight's Hammer have come. The cult worships those old lords, and its people have gathered at the Glaive and in the caves around it with books of names that should not be spoken." },
      },
    },
    ["onu"] = {
      title = "Onu", kind = "figure", chapter = "darkshore", portrait = 1455,
      unlock = { { npc = 3616 }, { area = 448 } },
      also = { "masters-glaive", "darkshore", "cenarion-circle" },
      text = {
        { "Onu, an Ancient of Lore, stands in the Grove of the Ancients in southern Darkshore. He asks travellers to investigate the Master's Glaive, where the Twilight's Hammer searches among the remains of a fallen power. Onu believes that something of its strength may still be found there, long after its death." },
        { "He supplies a phial that creates a scrying bowl, allowing him to speak with the person carrying out his investigation. Take it with you, traveller. An Ancient need not walk to the Glaive to take an interest in what the cult discovers there." },
      },
    },
    ["remtravels-excavation"] = {
      title = "Remtravel's Excavation", kind = "place", chapter = "darkshore",
      unlock = { { area = 450 } },
      also = { "darkshore", "auberdine", "explorers-league" },
      text = {
        { "When golems overran Remtravel's excavation in southern Darkshore, his assistant fled to Auberdine for help. The celebrated prospector remained at work. Hollee's admiration for his discoveries survives beside a desperate wish that he would occasionally notice what is happening around him." },
        { "His mysterious fossil has drawn Chief Archaeologist Greywhisker's interest, and a resemblance to another find carries the enquiry onward to Flagongut in Menethil Harbor. Remtravel has found something worth investigating. Keeping him alive long enough to finish investigating it has become a second expedition in its own right." },
      },
    },
    ["tower-of-althalaxx"] = {
      title = "The Tower of Althalaxx", kind = "place", chapter = "darkshore",
      unlock = { { area = 444 } },
      also = { "darkshore", "burning-legion", "argent-dawn" },
      text = {
        { "Balthule Shadowstrike watches the ruined tower of Althalaxx north-east of Auberdine. He stays at his post rather than risk missing a clue. The activity around it leads to the Dark Strand, a cult of night elves practising warlock magic. Their people have reason enough to remember what such arts can bring." },
        { "The investigation reaches south into Ashenvale, to an orc warlock at Fire Scar Shrine. Delgren the Purifier of the Argent Dawn takes up the hunt there." },
      },
    },
    ["deadwind-pass"] = {
      title = "Deadwind Pass", kind = "place", chapter = "deadwind-pass",
      unlock = { { area = 41 } },
      also = { "karazhan", "duskwood", "swamp-of-sorrows" },
      text = {
        { "Deadwind Pass cuts a grey valley between Duskwood and the Swamp of Sorrows. Dead trees, crows and ruined camps line the route. There are no working villages or farms, and the ogres offer little reason to linger." },
        { "Medivh's tower, Karazhan, stands at its heart, above abandoned buildings. The pass joins two inhabited regions without offering their comforts." },
      },
    },
    ["karazhan"] = {
      title = "Karazhan", kind = "history", chapter = "deadwind-pass",
      unlock = { { area = 2562 }, { area = 2837 } },
      also = { "deadwind-pass", "the-dark-portal", "burning-legion" },
      text = {
        { "Karazhan was the home of Medivh, the last Guardian of Tirisfal. He inherited Aegwynn's extraordinary power, and with it a secret she had failed to see: Sargeras had hidden within her son before his birth. Through the Guardian meant to oppose the Legion, its lord helped Gul'dan open the Dark Portal." },
        { "Khadgar and Anduin Lothar killed Medivh in this tower before the First War ended. Years later he returned to warn Azeroth of the Legion's invasion. Even death had failed to bring the Guardian's story to an end." },
        { "The village below is ruined, and the Master's Cellar lies beneath its abandoned buildings. Karazhan itself remains closed. The tower has outlasted the man who lived there and the certainty that he was ever entirely alone." },
      },
    },
    ["desolace"] = {
      title = "Desolace", kind = "place", chapter = "desolace",
      unlock = { { area = 405 } },
      also = { "khans-of-desolace", "kodo-graveyard", "maraudon", "mannoroc-coven", "centaurs", "burning-blade" },
      text = {
        { "Desolace is well named: a grey, dry, dead-looking country west of Stonetalon, all ash-coloured rock, withered trees and bones. Nothing much grows. Plenty dies: the kodo come here to do it, and their skeletons lie piled in a great graveyard in the middle of the land." },
        { "It belongs, if it belongs to anyone, to the centaurs, whose clans fight each other across it and whose holiest place, Maraudon, lies in its south-west. The Burning Blade hold a fortress in the north and open doors for demons, naga haunt the coast, and the Alliance and the Horde each keep a small, nervous outpost. It is not a land anyone loves." },
      },
    },
    ["khans-of-desolace"] = {
      title = "The Khans of Desolace", kind = "faction", chapter = "desolace", portrait = 9433,
      unlock = { { area = 609 }, { area = 606 }, { area = 604 }, { faction = 92, standing = 5 }, { faction = 93, standing = 5 } },
      also = { "centaurs", "zaetar-and-theradras", "maraudon" },
      text = {
        { "Desolace is centaur country, and its clans are many: the Kolkar in the north, the Gelkis in the south-west, the Magram in the south-east, the Maraudine guarding the holy tomb. The Gelkis and Magram are bitter rivals, and each offers work against the other." },
        { "The Alliance and the Horde have both realised that a united centaur nation would sweep them out of Desolace, and that the clans' hatred of one another is the best weapon they have. So both play the same game: ally with the Gelkis or the Magram, kill the other clan's warriors until the friendship is earned, and learn from your new friends how to break the rest. It works. I find it a little sad that it does." },
      },
    },
    ["kodo-graveyard"] = {
      title = "The Kodo Graveyard", kind = "place", chapter = "desolace",
      unlock = { { area = 596 } },
      also = { "desolace", "centaurs" },
      text = {
        { "In the middle of Desolace lies the place where the kodo go to die: a vast field of bones and tusks, great ribcages arching out of the dust, and among them old kodos lumbering slowly in from the plains to lie down. No one knows why they come here, and the tauren treat it with respect." },
        { "Not everyone does. Ghosts of centaurs and kodos wander it at night, and a goblin has invented a device that jolts the dying beasts back into service and sells them to the caravans. I cannot decide whether that is clever or monstrous. I suspect the kodos have an opinion." },
      },
    },
    ["mannoroc-coven"] = {
      title = "Mannoroc Coven", kind = "place", chapter = "desolace",
      unlock = { { area = 602 } },
      also = { "burning-blade", "burning-legion", "shadowprey-village" },
      text = {
        { "In the south of Desolace there is a scorched valley where demons walk openly: doomguard, felhounds, infernals and worse, among broken altars and green fire. It is called the Mannoroc Coven, and the demons did not come there by chance." },
        { "They were let in. The Burning Blade, from their fortress in the north, hold a relic called the Hand of Iruxos, and with it they have opened portals to the demons' realm in the valley. The tauren of Shadowprey are trying to close them. Every portal shut is a door the Legion has to open again, and the Legion is patient." },
      },
    },
    ["maraudon"] = {
      title = "Maraudon", kind = "place", chapter = "desolace",
      unlock = { { area = 2100 } },
      also = { "zaetar-and-theradras", "centaurs", "satyrs", "twilights-hammer" },
      text = {
        { "Maraudon is the centaurs' holy place in south-western Desolace. Their father Zaetar lies buried within its vast caverns, and their mother Theradras dwells beyond chambers of glittering crystal. Only the most devout among the centaurs may enter." },
        { "The tomb is troubled. Lord Vyletongue spreads poison through the caves and has made a creature of rot. Zaetar's nephew Celebras wanders there under a curse. A woman of the Twilight's Hammer asks for carvings from the crystal caverns, claiming they hold relics of the Old Gods. I would be careful whose purposes your journey serves, traveller. There are several parties interested in what lies beneath this sacred ground." },
      },
    },
    ["nijels-point"] = {
      title = "Nijel's Point", kind = "place", chapter = "desolace",
      unlock = { { area = 608 } },
      also = { "khans-of-desolace", "desolace" },
      text = {
        { "Nijel's Point is the Alliance's camp in northern Desolace, fortified in the hills beneath Stonetalon. Its soldiers watch the roads, the centaur clans and the demons of the Mannoroc Coven. Visitors willing to help will find no shortage of work." },
        { "The captains have chosen to exploit the centaurs' rivalries, making allies of one clan to learn how to defeat the others. It is a practical answer to a difficult position, traveller. The friendship you help establish here may begin with a request for the deaths of someone else's neighbours." },
      },
    },
    ["rexxar"] = {
      title = "Rexxar", kind = "figure", chapter = "desolace", portrait = 11660,
      unlock = { { npc = 10182 }, { npc = 10204 } },
      also = { "thrall", "durotar", "tiragarde-keep", "jaina-proudmoore", "desolace" },
      text = {
        { "The giant walking the road through Desolace with a bear at his side is Rexxar, Champion of the Horde. He is half orc and half ogre, of the Mok'Nathal, and he belongs to no town. Misha, his bear, goes wherever he goes." },
        { "He came to Durotar in its first days, when the land was new and the Horde still finding its feet, and Thrall trusted him with work no one else could do. When Admiral Daelin Proudmoore landed his fleet to finish the old war, Rexxar was at the heart of the fighting that ended it, beside Thrall and Cairne and, as it happened, with Jaina Proudmoore's leave. The Horde owes him a good part of its home." },
        { "He did not stay to enjoy it. He prefers the wild to the cities he helped defend, and he keeps to the paths between Stonetalon and Feralas. The Warchief still sends travellers to him when the work is hard. He will see you before you see him, traveller. Misha will see you first." },
      },
    },
    ["shadowprey-village"] = {
      title = "Shadowprey Village", kind = "place", chapter = "desolace",
      unlock = { { area = 2408 } },
      also = { "mannoroc-coven", "maraudon", "desolace" },
      text = {
        { "Shadowprey Village is the Horde's camp on the western coast of Desolace, a troll and tauren village of huts on stilts by the sea, the last stop before the long road south to Feralas. Its people hunt in the dead country and keep an eye on the centaurs and the demons alike." },
        { "A tauren of Shadowprey has taken it on herself to close the Burning Blade's demon portals, and a druid of the Cenarion Circle camps nearby, waiting for someone strong enough to go into Maraudon. It is a small village with large problems." },
      },
    },
    ["zaetar-and-theradras"] = {
      title = "Zaetar and Theradras", kind = "history", chapter = "desolace",
      unlock = { { kill = 12201 }, { quest = 7064 }, { quest = 7065 } },
      also = { "maraudon", "centaurs", "cenarion-circle", "keeper-remulos" },
      text = {
        { "Zaetar was Cenarius's son, a being of the forest. Theradras was a princess of elemental earth. Their union produced the centaurs, who killed their own father. Theradras laid him in Maraudon's caverns, where his children still revere him and guard his tomb." },
        { "A druid of the Cenarion Circle waits near Shadowprey, seeking someone able to face Theradras and recover Zaetar's remains. The centaurs' sacred ground is also the resting place of a member of Cenarius's family." },
      },
    },
    ["archesonus"] = {
      title = "Royal Historian Archesonus", kind = "figure", chapter = "dun-morogh", portrait = 8171,
      unlock = { { npc = 8879 } },
      also = { "magni-bronzebeard", "ironforge", "explorers-league", "war-of-the-three-hammers", "ruins-of-thaurissan", "parqual-fintallas" },
      text = {
        { "So you have found me. I keep Ironforge's history from the High Seat, a few steps from King Magni's throne, and anyone who asks me about it had better have an afternoon to spare." },
        { "The story I am asked for most is the Dark Irons'. The War of the Three Hammers ended with Sorcerer-Thane Thaurissan calling up Ragnaros, and the Firelord's waking turned their own country to ash. Relics still lie in the ruins of Thaurissan, in the Burning Steppes, holding more of that story than I have been able to read. A traveller who brings me what they say will have my thanks." },
        { "This ledger is my work, traveller, with a great deal of help from the Explorers' League, who bring home more than any one historian could read. If a page has served you well, I am glad of it. If one has failed you, come and tell me so." },
        { side = "Horde", aside = true, sign = "P. F.", "I have never met her. Hers is still the fairest account of the world I have read in a living hand." },
      },
    },
    ["coldridge-valley"] = {
      title = "Coldridge Valley", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 132 } },
      also = { "war-of-the-three-hammers", "rockjaw-troggs", "frostmane-trolls" },
      text = {
        { "Anvilmar gathers dwarven and gnomish recruits in Coldridge Valley, south of Kharanos. Here they find their trainers, their first orders, and the mountain pass that will take them out into Dun Morogh. A modest beginning, perhaps, but every road has one." },
        { "The orders concern more than practice. Rockjaw troggs threaten the valley, Frostmane trolls have made a camp nearby, and Balir Frosthammer and Grelin Whitebeard need help against them. Keep your weapon close, traveller. The recruits are needed before they have even left the valley." },
      },
    },
    ["deeprun-tram"] = {
      title = "The Deeprun Tram", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 2257 } },
      also = { "ironforge", "gnomeregan-exiles" },
      text = {
        { "The Deeprun Tram carries passengers between Ironforge and Stormwind on moving platforms beneath the earth. It has reduced a journey of days to a matter of minutes. Even a dwarf fond of walking can appreciate that achievement." },
        { "The tunnel gives our friendship with Stormwind a practical form: two capitals joined by a route that spares their travellers the long road overland. Gnomish ingenuity has saved a great many pairs of boots." },
        { "Watch the windows where the tunnel passes through water, traveller. Some passengers say they have seen something large looking back. You should have time for a glance before the platform carries you on." },
      },
    },
    ["dun-morogh"] = {
      title = "Dun Morogh", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 1 } },
      also = { "kharanos", "ironforge", "frostmane-trolls" },
      text = {
        { "Dun Morogh is the snowy high country around Ironforge, home to the dwarves of the Bronzebeard clan and their gnomish neighbours." },
        { "It is ours, but we share it, and not always by choice. The Frostmane trolls keep the western hills, troggs dig where they please, and since the fall of Gnomeregan the gnomes have been our neighbours in their own valleys as well as in our city." },
        { "Learn its roads well, traveller. Most of the dwarves you will ever meet took their first steps along them." },
      },
    },
    ["explorers-league"] = {
      title = "The Explorers' League", kind = "faction", chapter = "dun-morogh", portrait = 3596,
      unlock = { { npc = 5387 }, { npc = 1356 }, { npc = 2916 }, { npc = 8256 } },
      also = { "ironforge", "magni-bronzebeard", "archesonus", "ironbands-excavation-site", "whelgars-excavation-site" },
      text = {
        { "I could hardly leave the League out. The Explorers' League is Ironforge's society of historians, archaeologists and diggers: the dwarves who would rather read a ruin than build a hall. A royal historian could not ask for better company." },
        { "They are after the oldest question there is, which is where the dwarves came from. Their digs in Uldaman suggest that the answer lies with the Titans, the makers of the world, and if that is so, it changes how every dwarf should think of himself. King Magni takes it very seriously indeed." },
        { "You will find them in the Hall of Explorers, under High Explorer Magellas. Bring them anything old, traveller, and anything strange. They will want to hear where you found it, and so will I." },
      },
    },
    ["frostmane-trolls"] = {
      title = "The Frostmane Trolls", kind = "faction", chapter = "dun-morogh", portrait = 5608,
      unlock = { { kill = 706 }, { kill = 946 }, { kill = 1120 }, { kill = 1121 }, { kill = 1122 }, { kill = 1123 }, { kill = 1124 }, { kill = 1397 }, { area = 135 } },
      also = { "kharanos" },
      text = {
        { "The Frostmane occupy the snowy country west of Kharanos and camps as far as Coldridge Valley. Their hold shelters headhunters, seers and shadowcasters, giving the mountaineers more than spearpoints to watch for among the drifts." },
        { "Grelin Whitebeard warns of renewed attacks, and young dwarves are sent out against them almost as soon as they leave home. The quarrel becomes familiar very early: a troll camp beyond the last friendly fire, a report brought back to the guards, and another patrol sent into the same snow." },
      },
    },
    ["gates-of-ironforge"] = {
      title = "The Gates of Khaz Modan", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 808 }, { area = 806 } },
      also = { "ironforge", "loch-modan" },
      text = {
        { "The North Gate and South Gate passes carry travellers between Dun Morogh and Loch Modan. Mountaineers keep outposts along both routes. In mountain country, a narrow road can demand as much guarding as a broad frontier." },
        { "Captain Rugelfuss explains the difficulty from the Loch Modan side. His regiment must hold the gate rather than pursue nearby troggs, while the Ironforge Reserve is committed to the Alliance front. He asks adventurers to defend the land his soldiers cannot leave their posts to cover." },
      },
    },
    ["gnomeregan-exiles"] = {
      title = "The Gnomeregan Exiles", kind = "faction", chapter = "dun-morogh", portrait = 7006,
      unlock = { { people = "Gnome" }, { area = 189 }, { npc = 7937 } },
      also = { "gnomeregan", "high-tinker-mekkatorque", "ironforge" },
      text = {
        { "A people without a home, and the most cheerful exiles you will ever meet. The gnomes who escaped Gnomeregan live now in Tinker Town, in the heart of Ironforge, and in outposts such as Steelgrill's Depot within sight of their old gates." },
        { "Do not let the cheer fool you. Every invention they test, every recruit they train, is meant for one day: the day they march back into Gnomeregan and take it back." },
        { "Ironforge has offered them shelter as long as they need it. Most dwarves are glad of the company, if not of the noise." },
      },
    },
    ["gnomeregan"] = {
      title = "Gnomeregan", kind = "history", chapter = "dun-morogh",
      unlock = { { area = 133 } },
      also = { "gnomeregan-exiles", "high-tinker-mekkatorque", "leper-gnomes", "rockjaw-troggs" },
      text = {
        { "Gnomeregan lies beneath western Dun Morogh, the old gnomish capital brought to ruin during the crisis of the Third War. Troggs invaded its halls. To stop them, the gnomes released radiation through their own city." },
        { "The troggs survived. Many gnomes died, and others were transformed into the violent survivors now called leper gnomes. Those who escaped found shelter in Ironforge. The cost of the attempt is still plain in the poisoned halls." },
        { "Sicco Thermaplugg remains there. High Tinker Mekkatorque calls him a traitor and asks adventurers to kill him. If you enter, traveller, remember that this was a capital full of homes and workshops. Its people are still trying to recover what is left." },
      },
    },
    ["hall-of-thanes"] = {
      title = "The Hall of Thanes", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 16919 }, { quest = 96393 } },
      also = { "ironforge", "magni-bronzebeard", "war-of-the-three-hammers" },
      text = {
        { "Under Ironforge lie the caverns of Old Ironforge, and in them a place the dwarves call the Hall of Thanes. The Dark Irons have found their way to it. A map taken from their spies at Ironband's Compound shows tunnels and old highways converging beneath the city, and Earthseer Farsen, a visitor from Aerie Peak, followed them down to the hall and to the Dark Iron commanding there, one Durgen Dirgehammer." },
        { "The hall's own dead are restless. Afadra Dunwall, a lorekeeper of Ironforge, asks travellers to lay the spirits of Anvilmar to rest, and one of them, Faldrim Anvilmar, seems to have kept an old grudge well past the grave. King Magni wants the commander's head. I should like the League to have a proper look at the place once the Dark Irons are out of it." },
      },
    },
    ["high-tinker-mekkatorque"] = {
      title = "High Tinker Mekkatorque", kind = "figure", chapter = "dun-morogh", portrait = 7006,
      unlock = { { npc = 7937 } },
      also = { "gnomeregan", "gnomeregan-exiles" },
      text = {
        { "Gelbin Mekkatorque leads the gnomes from Tinker Town in Ironforge. The dwarves have given his people a refuge, but their own capital remains beneath Dun Morogh. A home borrowed from friends cannot settle the loss of Gnomeregan." },
        { "The radiation released against its invading troggs failed to eradicate them and devastated the gnomes as well. Mekkatorque once trusted Sicco Thermaplugg. Now he accuses him of betraying the city and asks adventurers to enter it and kill him." },
      },
    },
    ["ironforge"] = {
      title = "Ironforge", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 1537 } },
      also = { "magni-bronzebeard", "archesonus", "explorers-league", "war-of-the-three-hammers", "rockjaw-troggs" },
      text = {
        { "Ironforge is not built on the mountain. It is built in it. Its halls lie within Ironforge Mountain, and at its centre burns the Great Forge." },
        { "The city turns around the forge like a wheel. King Magni holds court in the High Seat, the Military Ward trains the mountain's defenders, the mages keep to the Mystic Ward, and since the fall of Gnomeregan the gnome exiles have made Tinker Town their own: loud, clever and homesick. Beneath it all runs the Deeprun Tram, gnomish work, carrying travellers under the mountains to Stormwind." },
        { "Below Old Ironforge lies the Hall of Thanes. Dark Iron intruders have breached it, and Magni wants the head of their commander, Durgen Dirgehammer. Even here, a city's oldest halls can become its newest trouble." },
        { "And then there is the Hall of Explorers, where the League keeps its library and its finds: relics from Uldaman, the bones of beasts no one has seen alive, and maps of places most dwarves will only ever read about. As for me, you will find me in the High Seat, a few steps from the king's throne. Come and see me. I am always short of people who have actually been somewhere." },
        { side = "Horde", aside = true, sign = "P. F.", "She means the invitation kindly. I would not advise accepting it in the Horde's colours." },
      },
    },
    ["kharanos"] = {
      title = "Kharanos", kind = "place", chapter = "dun-morogh",
      unlock = { { area = 131 } },
      also = { "war-of-the-three-hammers" },
      text = {
        { "Kharanos sits in the cold heart of Dun Morogh, on the road between the training grounds of Coldridge Valley and the gates of Ironforge. It is a small town by dwarven reckoning: a smithy, a few stout houses, and the building that makes it famous, the Thunderbrew Distillery, where the Thunderbrew family has been perfecting its ales for longer than anyone cares to admit." },
        { "Do not mistake the warm hearth for safety. Frostmane trolls hold the hills to the west, troggs keep crawling up from the deep places, and since the fall of Gnomeregan its exiles share these roads with us. The town keeps its doors open all the same: a dwarf who turns away a cold traveller is no dwarf at all." },
      },
    },
    ["leper-gnomes"] = {
      title = "The Leper Gnomes", kind = "creature", chapter = "dun-morogh", portrait = 6921,
      unlock = { { kill = 1211 } },
      also = { "gnomeregan", "gnomeregan-exiles" },
      text = {
        { "Not every gnome escaped Gnomeregan. Some lived through the radiation and were changed by it, their bodies ruined and their minds gone strange and violent. The dwarves call them leper gnomes, and the exiles do not like to talk about them at all." },
        { "They haunt the approaches to the old city and the depots around it, scavenging what they can and attacking those who come too close." },
        { "If you must fight them, traveller, remember that they were someone's neighbours once." },
      },
    },
    ["magni-bronzebeard"] = {
      title = "King Magni Bronzebeard", kind = "figure", chapter = "dun-morogh", portrait = 3597,
      unlock = { { npc = 2784 } },
      also = { "war-of-the-three-hammers", "archesonus" },
      text = {
        { "King Magni Bronzebeard holds court in Ironforge's High Seat, ruling the city his clan has held since the War of the Three Hammers. He is the eldest of three brothers. Muradin went north with the prince of Lordaeron during the Third War and has not been heard from since. Brann is the League's most famous explorer, and one of the hardest to keep track of." },
        { "Magni follows the League's work closely. The finds at Uldaman suggest that the dwarves were shaped long ago by the Titans. A king with so long a lineage has reason to ask where it began, and a historian who stands a few steps from his throne has every reason to welcome his interest." },
        { "His daughter concerns him more urgently. Princess Moira is in the Dark Iron city beneath Blackrock Mountain, wed to Emperor Dagran Thaurissan. Ironforge calls it an abduction, and Magni promises a hero's reward for bringing her home. If you take up that charge, traveller, you carry a father's hopes as well as a king's orders." },
      },
    },
    ["mekgineer-thermaplugg"] = {
      title = "Mekgineer Thermaplugg", kind = "figure", chapter = "dun-morogh", portrait = 6980,
      unlock = { { kill = 7800 }, { quest = 2929 } },
      also = { "gnomeregan", "high-tinker-mekkatorque", "leper-gnomes", "rockjaw-troggs", "dark-iron-dwarves" },
      text = {
        { "Sicco Thermaplugg remains in Gnomeregan while High Tinker Mekkatorque leads its exiles from Ironforge. The High Tinker once trusted him. That trust has ended in a charge of betrayal and a request for his death." },
        { "The radiation released in the city failed to eradicate the troggs and devastated its gnomish inhabitants. Thermaplugg rules in the ruins, among the creatures the attempt was meant to destroy and the survivors it left behind." },
        { "Mekkatorque asks adventurers to carry his judgement into those halls." },
      },
    },
    ["timber"] = {
      title = "Timber", kind = "creature", chapter = "dun-morogh", portrait = 11422,
      unlock = { { kill = 1132 } },
      also = { "kharanos" },
      text = {
        { "The hunters of Kharanos call him Timber: a wolf larger than his fellows, with a troublesome understanding of traps. They say he chooses his ground and doubles back on his own trail. Every hunter sent after him has been outlived by the quarry." },
        { "Wolves seldom trouble a royal history. This one has made a fair case for inclusion, though I doubt he would appreciate the distinction." },
        { "If you have killed him, traveller, set down what happened while you remember it. The hunters will have their own account soon enough." },
      },
    },
    ["war-of-the-three-hammers"] = {
      title = "The War of the Three Hammers", kind = "history", chapter = "dun-morogh",
      unlock = { { area = 77 }, { read = { "War of the Three Hammers", "세 망치단의 전쟁", "La guerre des trois clans", "Krieg der drei Hämmer", "三锤之战", "La guerra de los Tres Martillos", "Война Трех Кланов", "A Guerra dos Três Martelos", "三錘之戰" } } },
      also = { "magni-bronzebeard", "kharanos" },
      text = {
        { "Some two and a half centuries ago, Ironforge belonged to three clans at once. The Bronzebeards, the Wildhammers and the Dark Irons lived under a single High King, Modimus Anvilmar, and when he died they could not agree on who should follow him." },
        { "The quarrel became a war under the mountain. The Bronzebeards held the city. The Wildhammers, under Thane Khardros, were driven out and raised their own fortress at Grim Batol, and the Dark Irons of Sorcerer-Thane Thaurissan withdrew to the mountains of the south." },
        { "The Dark Irons were not finished. They marched on Ironforge and Grim Batol at once, and lost both battles. In his fury Thaurissan reached for a power far older than any clan and woke Ragnaros, the Lord of Fire. The south burned: the Searing Gorge and the Burning Steppes are what remained, and the Dark Irons have served the Firelord in Blackrock Mountain ever since." },
        { "The Wildhammers did not stay in Grim Batol either. The death of Queen Modgud, slain at its gates, left a darkness in the stone, and they made a new home at Aerie Peak in the Hinterlands. Ironforge still remembers which clan stayed." },
      },
    },
    ["wendigos"] = {
      title = "The Wendigos", kind = "creature", chapter = "dun-morogh", portrait = 950,
      unlock = { { kill = 1134 }, { kill = 1135 }, { area = 136 } },
      also = { "dun-morogh" },
      text = {
        { "The Grizzled Den offers shelter from Dun Morogh's snow, provided you can persuade its wendigos to share it. A courier who fled them left a shipment of ammunition behind. The creatures made the stronger argument." },
        { "Pilot Stonegear wants their manes for a rug inside his siege engine, Trollplow. Even machinery needs a little comfort in this country, traveller. Retrieving the ammunition and furnishing the engine both require getting rather closer to a wendigo than the courier cared to stay." },
      },
    },
    ["daelin-proudmoore"] = {
      title = "Daelin Proudmoore", kind = "figure", chapter = "durotar",
      unlock = { { area = 372 }, { read = { "Grand Admiral Daelin Proudmoore", "댈린 프라우드무어 제독", "Grand-amiral Daelin Proudmoore", "Großadmiral Daelin Proudmoore", "海军上将戴林·普罗德摩尔", "Almirante general Daelin Valiente", "Великий адмирал Даэлин Праудмур", "Grão-almirante Daelin Proudmore", "海軍上將戴林·普勞德摩爾" } } },
      also = { "tiragarde-keep", "jaina-proudmoore", "rexxar", "the-second-war", "durotar" },
      text = {
        { "Daelin Proudmoore, Lord Admiral of Kul Tiras, was a hero of the Second War: he commanded the Alliance's fleets beside Anduin Lothar and Uther the Lightbringer, and he never forgave the orcs. He also had a daughter, Jaina, who went to study magic in Dalaran." },
        { "He sailed from Lordaeron with his fleet before Arthas destroyed it, searching the seas for survivors, and after many months found Kalimdor, and his daughter, at peace with the Horde. He would not have it. He landed his marines on Durotar's coast, raised this keep, and set out to destroy the orcs before they could take root." },
        { "Jaina had to choose between her father and the peace, and she chose the peace. Daelin died in the fighting before they could be reconciled. His fleet lies wrecked off this beach, and a few of his men still hold the keep, in the middle of a land named for an orc." },
      },
    },
    ["darkspear-trolls"] = {
      title = "The Darkspear Trolls", kind = "faction", chapter = "durotar", portrait = 10357,
      unlock = { { people = "Troll" }, { area = 367 }, { faction = 530, standing = 5 } },
      also = { "voljin", "senjin-village", "echo-isles", "murlocs" },
      text = {
        { "The Darkspear are jungle trolls related to Stranglethorn's Gurubashi. When Thrall's fleet reached their islands on its journey to Kalimdor, the tribe was fighting murlocs and their sea witch. The orcs fought beside them. Chieftain Sen'jin died, and the surviving Darkspear followed Thrall across the sea." },
        { "Vol'jin now leads them from Orgrimmar, close to the Warchief. Their hunters, shamans and witch doctors serve throughout the Horde, keeping the trolls' old loa as they make a home among new allies." },
      },
    },
    ["durotar"] = {
      title = "Durotar", kind = "place", chapter = "durotar",
      unlock = { { area = 14 }, { read = { "Old Hatreds - The Colonization of Kalimdor", "오랜 증오 - 칼림도어에서의 식민지 건설", "Anciennes haines - La colonisation de Kalimdor", "Alter Hass - Die Kolonialisierung von Kalimdor", "古老的仇恨 - 卡利姆多的开拓", "Antiguas rencillas: la colonización de Kalimdor", "Древняя ненависть - Колонизация Калимдора", "Velhos Ódios: a Colonização de Kalimdor", "古老的仇恨 - 卡林多的開拓" } } },
      also = { "orgrimmar", "thrall", "razor-hill", "tiragarde-keep", "burning-blade", "centaurs", "quilboar" },
      text = {
        { "Durotar is a hard country: red earth, red rock, thorn and scorpion, burned by the sun and cut by dry canyons, with the sea on one side and the long plains of the Barrens on the other. The orcs chose it anyway. Thrall named it for his father, Durotan, chieftain of the Frostwolf clan, who was murdered before his son could know him." },
        { "The Horde came here after the last war, having crossed the sea from the camps of Lordaeron and fought beside the night elves and men at Mount Hyjal. It was not left in peace for long: Admiral Daelin Proudmoore of Kul Tiras, Jaina Proudmoore's father, sailed his fleet against the orcs, and was defeated. The orcs have been building ever since: Orgrimmar in the north, Razor Hill on the road, Sen'jin Village for their troll allies." },
        { "They have not finished clearing the land. Centaurs raid from the west, quilboar hold the south, and in the caves of Skull Rock, within sight of the capital, the Burning Blade worship the demons that once enslaved the orcs. Durotar is young, and it knows it." },
      },
    },
    ["echo-isles"] = {
      title = "The Echo Isles", kind = "place", chapter = "durotar",
      unlock = { { area = 368 }, { kill = 3205 }, { quest = 826 } },
      also = { "darkspear-trolls", "senjin-village" },
      text = {
        { "The Echo Isles were meant to be the Darkspear trolls' new home, a scatter of jungle islands off the coast of Durotar much like the ones they had left. A witch doctor named Zalazane changed that. He turned to dark magics, hexed his own people and bent them to his will, and the loyal Darkspear had to flee the isles to the mainland." },
        { "Zalazane still rules the islands, and from them he sends his enthralled trolls across the water to drag more of the tribe under his sway. His victims do not always rest when they die: the souls of some, the trolls say, are trapped in their own skulls, in a circle of power on the largest isle." },
      },
    },
    ["eitrigg"] = {
      title = "Eitrigg", kind = "figure", chapter = "durotar", portrait = 1619,
      unlock = { { npc = 3144 } },
      also = { "thrall", "blackrock-clan" },
      text = {
        { "Eitrigg advises Thrall in Orgrimmar, an old warrior with knowledge the new Horde still needs. When Warlord Goretooth learned that Rend Blackhand lived, he sent adventurers to consult Eitrigg about the Blackrock." },
        { "Rivalry among Horde leaders had cost Eitrigg his sons and driven him away from its wars. Living alone near Hearthglen, he fought Tirion Fordring, then saved the paladin from a collapsing tower. Tirion later defended him at the cost of his standing in the Silver Hand." },
        { "During Thrall's attack on Stratholme, Tirion freed Eitrigg. Outside the city, Thrall asked him to help restore the Horde's old ways, and he accepted." },
      },
    },
    ["orgrimmar"] = {
      title = "Orgrimmar", kind = "place", chapter = "durotar",
      unlock = { { area = 1637 } },
      also = { "thrall", "durotar", "ragefire-chasm", "voljin", "eitrigg" },
      text = {
        { "Orgrimmar is the capital of the Horde, built in a great canyon in the north of Durotar and named for Orgrim Doomhammer, the Warchief who led the Horde in the Second War and died fighting to free it from the camps. Thrall carries his hammer still. The goblins helped build it, and you can tell: it is all timber, spikes and hide on stone, hot as a forge and loud as a war camp." },
        { "At its heart stands Grommash Hold, named for Grom Hellscream, who drank the blood of the demon Mannoroth and doomed his people, and then killed Mannoroth with his own axe and freed them. In the Valley of Spirits the shamans and the trolls keep their fires, and in the Cleft of Shadow, I am told, there are warlocks whom the Horde tolerates rather than trusts." },
        { "It is not a city that welcomes dwarves. But it is a real city, and the orcs built it in a handful of years out of nothing, which is more than can be said for most." },
      },
    },
    ["ragefire-chasm"] = {
      title = "Ragefire Chasm", kind = "place", chapter = "durotar",
      unlock = { { area = 2437 } },
      also = { "orgrimmar", "burning-blade", "rockjaw-troggs" },
      text = {
        { "Beneath Orgrimmar there are caverns of fire and molten rock, and the Horde built its capital over them without, it seems, looking very carefully. Troggs came up through them first. Then the Searing Blade did: a cult of the Burning Blade that has made its home in the depths under the Warchief's own feet, with a demon called Taragaman the Hungerer among them." },
        { "Thrall's people have sent the young of the Horde down to clear it out. I can think of few better lessons in what a capital is built on." },
      },
    },
    ["razor-hill"] = {
      title = "Razor Hill", kind = "place", chapter = "durotar",
      unlock = { { area = 362 } },
      also = { "durotar", "tiragarde-keep" },
      text = {
        { "Razor Hill is a garrison town on the road from the Valley of Trials to Orgrimmar: a barracks, an inn, a watchtower and a palisade of sharpened timber on a hill above the sea. Its commander, Gar'Thok, holds it for the Warchief and spends most of his days fending off everything that comes up out of the canyons or in from the coast." },
        { "Just to the south lies Tiragarde Keep, where the men of Kul Tiras still cling to Durotar's shore, and the wreck of their admiral's fleet lies rotting off the beach. The grunts of Razor Hill keep a close eye on both." },
      },
    },
    ["senjin-village"] = {
      title = "Sen'jin Village", kind = "place", chapter = "durotar",
      unlock = { { area = 367 } },
      also = { "darkspear-trolls", "voljin", "echo-isles" },
      text = {
        { "Sen'jin Village is the home of the Darkspear trolls on the coast of Durotar, a settlement of huts and watchtowers looking out across the strait to the Echo Isles. It is named for Sen'jin, the Darkspear's old witch doctor and chieftain, who welcomed Thrall when the orcs' fleet put in at his islands, and was killed by a sea witch's servants in the fighting that followed." },
        { "His son Vol'jin leads the tribe now. The trolls had meant to live on the Echo Isles, but one of their own witch doctors went mad there, and the Darkspear have been crowded onto this strip of shore ever since, looking across the water at the home they have lost." },
      },
    },
    ["thrall"] = {
      title = "Thrall", kind = "figure", chapter = "durotar", portrait = 4527,
      unlock = { { npc = 4949 }, { read = { "The New Horde", "새로운 호드", "La nouvelle Horde", "Die neue Horde", "新的部落", "La nueva Horda", "Новая Орда", "A Nova Horda" } } },
      also = { "orgrimmar", "durotar", "eitrigg", "voljin" },
      text = {
        { "Thrall is the Warchief of the Horde, and his life reads like a ballad no one would believe. He was the son of Durotan, chieftain of the Frostwolves, found as an infant beside his murdered parents and raised as a slave and a gladiator in Durnholde Keep by its master, Lord Aedelas Blackmoore, who meant to make him the general of a tame orcish army. He was given the name Thrall, which means slave, and he kept it." },
        { "He escaped, helped by a human girl who had befriended him, found his father's clan in the mountains of Alterac and learned the ways of the shaman. Then, with Grom Hellscream and the old Warchief Orgrim Doomhammer, he broke open the internment camps and freed his people. Doomhammer fell in that war and left the Horde and his hammer to Thrall." },
        { "He led the Horde across the sea to Kalimdor, fought beside the night elves and the humans against the Burning Legion, and built Durotar. He wants peace with the Alliance, and has made it with Jaina Proudmoore of Theramore. Whether the rest of the Alliance wants it is another question." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron made him a slave, and he still found room for Lordaeron's dead in his Horde. I am not sure I would have." },
      },
    },
    ["tiragarde-keep"] = {
      title = "Tiragarde Keep", kind = "place", chapter = "durotar",
      unlock = { { kill = 5809 }, { area = 372 } },
      also = { "durotar", "razor-hill" },
      text = {
        { "Tiragarde Keep is a fortress of Kul Tiras on the coast of Durotar, and it should not be here at all. When the Horde had settled its new land, Admiral Daelin Proudmoore, lord of the island kingdom of Kul Tiras, brought his fleet across the sea to finish the war his people never forgave, in defiance of the peace his own daughter had made with Thrall at Mount Hyjal. He was defeated and killed, and his fleet lies wrecked off this beach." },
        { "The keep fell with him. But some of his men stayed on, and under a Lieutenant Benedict and a watch commander named Zalaphil they have taken it back and fortified it, a handful of Kul Tirans in the middle of the Horde's homeland. The orcs of Razor Hill call them betrayers. The Kul Tirans would say much the same of Theramore." },
      },
    },
    ["valley-of-trials"] = {
      title = "The Valley of Trials", kind = "place", chapter = "durotar",
      unlock = { { area = 363 } },
      also = { "durotar", "burning-blade" },
      text = {
        { "The Valley of Trials is where the young of the Horde are tested: orcs and trolls alike, sent out among the boars and scorpids of the canyon to show what they are made of. It is a narrow, sunbaked place south of Razor Hill, and its trials are meant to be hard." },
        { "Not all of its dangers are beasts. In the caves of the valley the Burning Blade have hidden their cultists and their imps, close enough to the Horde's own young to be insulting, and the first lesson many orcs learn is that their people's oldest enemy is sometimes wearing an orc's face." },
      },
    },
    ["voljin"] = {
      title = "Vol'jin", kind = "figure", chapter = "durotar", portrait = 10357,
      unlock = { { npc = 10540 } },
      also = { "darkspear-trolls", "thrall", "orgrimmar" },
      text = {
        { "Vol'jin leads the Darkspear and is a shadow hunter, one of their priest-warriors who walk with the loa. His father Sen'jin died during the fighting on the islands where Thrall's fleet first met the tribe. Vol'jin has maintained his father's pledge to the Horde." },
        { "He stays near Thrall in Orgrimmar while his people hold Sen'jin Village and look towards reclaiming the Echo Isles. A traveller seeking the Darkspear's leader will therefore find him in the capital, with the tribe's lost home still among his concerns." },
      },
    },
    ["darkshire"] = {
      title = "Darkshire", kind = "place", chapter = "duskwood",
      unlock = { { area = 42 } },
      also = { "night-watch", "duskwood", "stalvan-mistmantle", "the-embalmer" },
      text = {
        { "Darkshire is the only town left in Duskwood, a huddle of houses, a town hall and an inn behind lamps that are kept burning day and night. Its lord mayor, Ello Ebonlocke, governs it with a council, and his kin command the Night Watch. A historian, Sirra Von'Indi, keeps its records and will translate anything you bring, eventually." },
        { "It is a town of grim people and grim jokes, and of more stories than any town that size should have. Ask the old fortune teller, Madame Eva, about any of them. She already knows which one you will ask about." },
      },
    },
    ["duskwood"] = {
      title = "Duskwood", kind = "place", chapter = "duskwood",
      unlock = { { area = 10 } },
      also = { "darkshire", "night-watch", "raven-hill", "worgen", "dragons-of-nightmare" },
      text = {
        { "South of Elwynn the trees close in, the light goes grey, and you are in Duskwood. It was once part of the same green forest. Men lived and farmed here as they did in Elwynn. Then a darkness fell on these woods that has never lifted. No one in Darkshire can tell you for certain why, though many will glance east, towards the dead lands of Deadwind Pass and the tower that stands in them." },
        { "What the darkness brought is plain enough. The dead rise from the cemetery at Raven Hill, worgen hunt in the woods, spiders grow to the size of ponies, and ogres have moved into the hills. The farms are abandoned, and the people who remain have gathered behind the lamps of Darkshire under their own militia, because Stormwind has withdrawn its guards. It is a place for brave travellers, and for stories told by the fire with the door barred." },
      },
    },
    ["morbent-fel"] = {
      title = "Morbent Fel", kind = "figure", chapter = "duskwood", portrait = 4272,
      unlock = { { quest = 55 } },
      also = { "raven-hill", "the-third-fleet", "scythe-of-elune", "darkshire", "duskwood" },
      text = {
        { "Morbent Fel is the necromancer of Duskwood, the one who keeps the dead of Raven Hill walking, and an ally of the dark riders who come out of Deadwind Pass. He lives in a house at the top of the Forlorn Rowe, above the cemetery, behind his dead and a ward that turns aside every blow struck at him." },
        { "Sven Yorgen, a woodsman whose wife and children the riders killed, wants him dead, and the way to it is long. A Defias man's journal told Sven what happened at his farm. Bishop Farthing in Stormwind's cathedral pointed the way to a weapon that could break the ward. The iron for it came from the wrecks of the Third Fleet off the Wetlands, where a cargo of Lightforge iron went down, and a dwarven smith in Stormwind forged it into Morbent's Bane." },
        { "It is a great deal of trouble to go to for one necromancer, traveller. Sven does not think so, and I find I cannot blame him." },
      },
    },
    ["morladim"] = {
      title = "Mor'Ladim", kind = "figure", chapter = "duskwood", portrait = 612,
      unlock = { { kill = 522 }, { quest = 228 }, { read = { "The Story of Morgan Ladimore", "모건 래디모어의 이야기", "L'histoire de Morgan Ladimore", "Die Geschichte von Morgan Ladimore", "摩根·拉迪莫尔的故事", "La historia de Morgan Ladimor", "\"Роман о Моргане Ладиморе\"", "A História de Morgan Ladimore", "摩根·拉迪莫爾的故事" } } },
      also = { "raven-hill", "night-watch" },
      text = {
        { "Morgan Ladimore was a knight of this country, known for defending the poor and the afflicted, married young to a girl named Lys and the father of three children. When the war broke out in Lordaeron he went north to fight beside Uther the Lightbringer, and he saw everything that war became: the Silver Hand disbanded, Uther dead, the plague. What kept him sane was the thought of coming home." },
        { "He came home to a forest gone dark and a house in ruins, and at last, in the cemetery at Raven Hill, to his wife's grave. Something in him snapped. When the cemetery's attendants tried to restrain him he killed them, and when he understood what he had done he killed himself. He was buried quickly, outside the cemetery, and within days his grave was empty. He walks Duskwood now as Mor'Ladim, and kills whoever he meets." },
      },
    },
    ["night-watch"] = {
      title = "The Night Watch", kind = "faction", chapter = "duskwood", portrait = 4322,
      unlock = { { npc = 264 } },
      also = { "darkshire", "morladim", "duskwood" },
      text = {
        { "Commander Althea Ebonlocke leads the Night Watch, the militia Darkshire raised after Stormwind withdrew its commissioned guards. The townsfolk defend their road and gates against Raven Hill's dead, the worgen, the ogres, and whatever else comes out of the forest." },
        { "Most are not soldiers, and there are too few of them. They have nevertheless kept Darkshire alive. Sarah Ladimore serves among them. Her father's history is elsewhere in this ledger." },
      },
    },
    ["raven-hill"] = {
      title = "Raven Hill", kind = "place", chapter = "duskwood",
      unlock = { { area = 94 }, { area = 492 } },
      also = { "the-embalmer", "morladim", "darkshire", "scourge" },
      text = {
        { "Raven Hill's village stands empty beside a cemetery that has spread across the hillside. Skeletons walk its rows, ghouls dig among the graves, and the Night Watch cannot keep the dead at rest. The graveyard has become more dangerous than the abandoned houses around it." },
        { "Morbent Fel, a necromancer, lives in a house above the cemetery. A woodsman whose family he killed wants him dead. Nearby, an old hermit occupies a shack overlooking the graves. He once came into Darkshire for supplies, but has not been seen there for some time." },
      },
    },
    ["scythe-of-elune"] = {
      title = "The Scythe of Elune", kind = "history", chapter = "duskwood",
      unlock = { { area = 2161 }, { quest = 1043 } },
      also = { "worgen", "duskwood", "archmage-arugal", "sentinels", "elune" },
      text = {
        { "The worgen of Duskwood did not come from Arugal, or not only from him. The other half of the story begins in Ashenvale, with a priestess of Elune named Velinde Starsong, who prayed for a way to avenge her fallen comrades against the demons of Felwood and was given one: the Scythe of Elune, a twisted, gnarled branch of wood that may be older than the night elves themselves." },
        { "Her journal says that holding it weakened the walls of the world. Through it she saw the worgen fighting a war of their own, learned to speak to them without words, and drew a score and a half of them into this world to fight at her side. More followed. Then packs went missing, and their numbers kept growing even when she stopped calling them, as if the Scythe no longer needed her. She went east across the sea, the journal says, to seek out a Kirin Tor wizard named Arugal who was rumoured to have done the same thing. That is the last entry." },
        { "The Scythe turned up in the mine south of Darkshire that the locals call Roland's Doom. A Defias man nicknamed Jitters pulled it from a pile of rubble, and the worgen poured out of the walls. He lost it again in his flight, and where it lies now the records do not say. A gift from a goddess, somewhere in the dark of a Duskwood mine, perhaps still opening doors. I would rather it were found by a priestess than a prospector." },
      },
    },
    ["stalvan-mistmantle"] = {
      title = "Stalvan Mistmantle", kind = "figure", chapter = "duskwood", portrait = 1562,
      unlock = { { quest = 98 } },
      also = { "duskwood", "darkshire" },
      text = {
        { "Stalvan Mistmantle was a teacher at Moonbrook and a tutor to families in the countryside. He imagined that his pupil Tilloa returned his affection. When she introduced a suitor and called her tutor a kindly old uncle, his own account turned to rage. The murders followed." },
        { "Letters and journals trace his movements through Westfall and Stormwind to the manor north-east of Darkshire, where Duskwood's darkness has changed him further. Madame Eva's foreboding begins the search, but Stalvan's own words carry much of it onward." },
        { "It is an ugly history to recover from such ordinary papers. A teaching post, a family's correspondence, a pupil's name: the things that should have belonged to a quiet life remain among the traces of those he destroyed." },
      },
    },
    ["the-embalmer"] = {
      title = "The Embalmer", kind = "creature", chapter = "duskwood", portrait = 1693,
      unlock = { { quest = 252 } },
      also = { "raven-hill", "darkshire", "night-watch" },
      text = {
        { "The children of Darkshire know the story of the Embalmer: a kindly alchemist whose wife, Eliza, died, and who would not let her go. He used dark magic to place his own heart in her breast, and it brought her back, with a hunger for human flesh, so that he had to keep her buried." },
        { "It is not a children's story. The Embalmer is the old hermit Abercrombie, who lives in a shack above Raven Hill, and his bride still waits in her grave. His last gift to Darkshire was Stitches, a monster sewn together from the dead, sent lurching up the road to the town. The Night Watch remember the night it came." },
      },
    },
    ["brackenwall-village"] = {
      title = "Brackenwall Village", kind = "place", chapter = "dustwallow",
      unlock = { { area = 496 } },
      also = { "ogres", "onyxia", "dustwallow-marsh" },
      text = {
        { "Brackenwall Village is the Horde's camp in Dustwallow, held by orcs and by the ogres of the Stonemaul clan. The Stonemaul are allies of the Horde, thanks to the beast-master Rexxar, who made their overlord Mok'Morokk leader of the clan. The ogres tell you so, frequently." },
        { "They came to Brackenwall because they had to. Onyxia's brood descended on their old home in the south of the marsh and burned them out, and the clan's cleverest member, a two-headed ogre who speaks better than most dwarves, has been trying to find out why. The Horde would also like to know why the daughter of Deathwing has taken an interest in a small band of ogres." },
      },
    },
    ["dustwallow-marsh"] = {
      title = "Dustwallow Marsh", kind = "place", chapter = "dustwallow",
      unlock = { { area = 15 } },
      also = { "theramore-isle", "brackenwall-village", "onyxias-lair", "shady-rest-inn", "black-dragonflight" },
      text = {
        { "Dustwallow Marsh is a wide, wet swamp on the eastern coast of Kalimdor, south of the Barrens: reeds, black pools, crocolisks, raptors and a great deal of fog. On an island off its coast stands Theramore, the human city of Lady Jaina Proudmoore, and in the swamp's southern reaches lies the Wyrmbog, where Onyxia keeps her lair." },
        { "Between them are the ogres of Brackenwall, who serve the Horde, the burned ruin of an inn that everyone has a theory about, and a great many black dragons. It is a marsh where the Alliance and the Horde have agreed to live as neighbours, and where both are watching very carefully." },
      },
    },
    ["jaina-proudmoore"] = {
      title = "Lady Jaina Proudmoore", kind = "figure", chapter = "dustwallow", portrait = 2970,
      unlock = { { npc = 4968 } },
      also = { "theramore-isle", "thrall", "tiragarde-keep", "fall-of-lordaeron" },
      text = {
        { "Jaina Proudmoore was a young sorceress of Dalaran, the daughter of the admiral of Kul Tiras, and a friend of Prince Arthas in happier days. When the plague came she rode beside him, until Stratholme, where she would not follow him. Then a prophet sent her west across the sea, and she led what was left of Lordaeron's people to Kalimdor." },
        { "There she did what no one in the Alliance thought possible: she fought beside Thrall and the night elves against the Burning Legion at Mount Hyjal, and afterwards made peace with the Horde. When her father, Admiral Daelin Proudmoore, came with his fleet to finish the old war, she did not stand in the Horde's way, and he died for it. She has carried that ever since." },
        { "Keeping the peace has not been easy. A few years after Hyjal, raids and sunk ships nearly set Theramore and Durotar at each other's throats again, until Jaina, working quietly with Thrall, found the Burning Blade behind it and her own chamberlain in its pay. The search took her to a warded corner of Durotar where she met the last person she expected to find alive: Aegwynn, the Guardian, Medivh's mother, living alone. Jaina rules Theramore still, and keeps the peace with Thrall, and I think she is the bravest person in this ledger." },
      },
    },
    ["onyxia"] = {
      title = "Onyxia", kind = "figure", chapter = "dustwallow", portrait = 8570,
      unlock = { { kill = 10184 } },
      also = { "onyxias-lair", "katrana-prestor", "great-masquerade", "black-dragonflight" },
      text = {
        { "Onyxia, Deathwing's daughter and Nefarian's sister, spent years advising Stormwind's regent as Lady Katrana Prestor. She bent the kingdom's will and kept its troops at home while her brother's orcs threatened Redridge. Marshal Windsor exposed her before the court. She fled to Dustwallow Marsh." },
        { "Her lair is another matter from her place at court. She is an ancient, formidable dragon, and champions of both factions seek a way inside. A traveller who has learned her human name has learned why to oppose her. Reaching her cave still leaves the dragon herself to contend with." },
      },
    },
    ["onyxias-lair"] = {
      title = "Onyxia's Lair", kind = "place", chapter = "dustwallow",
      unlock = { { area = 2159 }, { area = 511 } },
      also = { "onyxia", "black-dragonflight", "dustwallow-marsh" },
      text = {
        { "Onyxia keeps her lair in the Wyrmbog, in the south of Dustwallow Marsh: a great cave in the cliffs, with her brood's eggs inside and black dragonkin all over the bog around it. Crossing the marsh is the easy part." },
        { "The entrance is warded, and only a Drakefire Amulet opens the way. Alliance and Horde alike are sent the long way round to make one: through Blackrock Spire, for the blood of General Drakkisath, who commands the Spire's dragons. The Horde's road also passes the drake Emberstrife, who must be fooled with an illusion, but it is the amulet that lets you in." },
      },
    },
    ["shady-rest-inn"] = {
      title = "The Shady Rest Inn", kind = "history", chapter = "dustwallow",
      unlock = { { area = 403 } },
      also = { "theramore-isle", "brackenwall-village", "dustwallow-marsh" },
      text = {
        { "On the road between the Barrens and Theramore there used to be an inn, the Shady Rest, where travellers of both factions stopped for a drink and no questions. It burned down. Its skeleton still stands by the road, and around it the investigators of both sides have found things that do not fit together." },
        { "There are hoofprints in the mud, leading away. There is a black iron shield fixed to the chimney. And there is a badge in the ashes, the gold anchor of Theramore, with the name of a lieutenant, a Kul Tiran marine who came across the sea with Lady Proudmoore and has been listed as missing, and seems to have fallen in with a band of deserters in the marsh. Who burned the Shady Rest, and why, I do not know. I suspect that someone wanted the Alliance and the Horde to blame each other for it." },
      },
    },
    ["the-missing-diplomat"] = {
      title = "The Missing Diplomat", kind = "history", chapter = "dustwallow",
      unlock = { { quest = 1324 }, { quest = 1267 } },
      also = { "regency-of-stormwind", "theramore-isle", "jaina-proudmoore", "defias-brotherhood" },
      text = {
        { "Stormwind says its king is missing. A few people know a little more, and the trail they followed began, of all places, in a cheese shop. Bishop DeLavey of Stormwind Keep quietly let it be known that a diplomat sent to meet Lady Jaina Proudmoore in Theramore had never arrived, and that he suspected the Defias. His old friend Jorgen, in the Valley of Heroes, passed the matter to Elling Trias, a cheesemonger in the Trade District with a remarkable range of contacts." },
        { "The trail ran through a Defias gathering at Addle's Stead in Duskwood and a brawler in Old Town called Dashel Stonefist, then north to Menethil Harbor, where a retired agent turned barman pointed out a man listening too closely. Tapoke Jahn, called Slim, gave up the rest once he had been beaten. The Defias had not taken a diplomat. They had taken the king, on his way to a secret meeting in Theramore. Slim's part had been to get their man aboard the king's ship in the harbour: a Private Hendel, one of Theramore's own soldiers. And the Defias, he said, were working with someone bigger than themselves." },
        { "Hendel was found on guard duty in the marsh, outside Theramore, and taken back to the isle to be questioned. That is where the account ends. The king has not been found, and whoever the Defias were working with has not been named. Stormwind still has a boy on the throne and a regent beside him." },
      },
    },
    ["theramore-isle"] = {
      title = "Theramore Isle", kind = "place", chapter = "dustwallow",
      unlock = { { area = 513 } },
      also = { "jaina-proudmoore", "dustwallow-marsh", "northwatch-hold", "shady-rest-inn" },
      text = {
        { "Theramore is the city Jaina Proudmoore built when she led the survivors of Lordaeron across the sea to Kalimdor, a fortress-port of white stone on an island off the coast of Dustwallow. It is the Alliance's strongest hold on the continent, and the only place in the world where a human ruler has made a lasting peace with the Horde." },
        { "Many of its soldiers came across the sea with Lady Proudmoore, Kul Tiran marines among them, and not all of them have made their peace with that peace. Theramore keeps watchtowers through the marsh and a fort in the Barrens, and its captains have more mysteries on their desks than they would like." },
      },
    },
    ["arthas-menethil"] = {
      title = "Arthas Menethil", kind = "figure", chapter = "eastern-plaguelands",
      unlock = { { area = 2279 } },
      also = { "stratholme", "fall-of-lordaeron", "the-lich-king", "uthers-tomb", "jaina-proudmoore", "the-fall-of-quelthalas" },
      text = {
        { "Arthas Menethil was the only son of King Terenas of Lordaeron, a paladin of the Silver Hand trained by Uther himself, and, in happier days, close to the young sorceress Jaina Proudmoore. When the plague came, he rode against it." },
        { "He followed it here ahead of the Scourge and found the grain already eaten. Rather than let the city rise against him, he put its people to the sword. Uther and Jaina would not follow him. The dreadlord Mal'Ganis, who had been waiting for him, withdrew north, and Arthas chased him to Northrend, burned his own ships so his men could not turn back, and took up the runeblade Frostmourne. With it he killed Mal'Ganis, and lost his soul." },
        { "He came home a death knight, killed his father in his own throne room, and led the Scourge through the kingdom he was meant to rule. At Andorhal he killed Uther. Then he went north to the Frozen Throne and, the book in our library says, became the Lich King himself. Stratholme remembers him better than anywhere. Its streets are still full of the people he set out to save." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron's histories had a chapter waiting for him: the heir, the paladin, the king to come. None of them were wrong about his gifts." },
      },
    },
    ["balnazzar"] = {
      title = "Balnazzar", kind = "figure", chapter = "eastern-plaguelands", portrait = 10691,
      unlock = { { kill = 10813 } },
      also = { "scarlet-crusade", "varimathras", "sylvanas-windrunner", "stratholme", "burning-legion" },
      text = {
        { "Balnazzar was one of the dreadlords left in Lordaeron to oversee the Scourge for the Burning Legion. After the Legion's defeat, they challenged Arthas's rule. Arthas escaped their rebellion and went to Northrend. Sylvanas later took their kingdom from them. At her command, Varimathras appeared to kill his brother Balnazzar." },
        { "The death was believed, but the demon survived. He assumed the identity of Grand Crusader Dathrohan and ruled the Scarlet bastion in Stratholme. Defeating the apparent crusader reveals what stands beneath the disguise. It is an ugly discovery for an order devoted to destroying the very evil issuing its commands." },
      },
    },
    ["baron-rivendare"] = {
      title = "Baron Rivendare", kind = "figure", chapter = "eastern-plaguelands", portrait = 10729,
      unlock = { { kill = 10440 } },
      also = { "stratholme", "kelthuzad", "argent-dawn" },
      text = {
        { "Baron Rivendare rules the Scourge's half of Stratholme from its slaughterhouse, a death knight mounted on a dead horse. The Argent Dawn calls him Kel'Thuzad's errand boy. Duke Zverenhoff at Light's Hope Chapel asks for his head." },
        { "Rivendare also holds the Argent Dawn crusader Ysida Harmon captive. Her husband seeks her rescue. Keep her in mind, traveller, if the Duke's bounty brings you into the city. Someone there still needs to come out alive." },
      },
    },
    ["darrowshire"] = {
      title = "Darrowshire", kind = "history", chapter = "eastern-plaguelands",
      unlock = { { area = 2262 }, { quest = 5721 } },
      also = { "eastern-plaguelands", "scourge", "lights-hope-chapel" },
      text = {
        { "Darrowshire was a village in the south of the Eastweald. When the Scourge came, its people stood and fought, with the paladin Davil Lightfire of the Silver Hand and Joseph Redpath at their head, against the ghoul lord Horgus and the death knight Marduk Blackpool. For a while they held. In the end, Marduk tore loose and corrupted Redpath's spirit, turning it against the defenders, and the village died." },
        { "The battle goes on in Darrowshire still, among the ghosts. A little girl, Pamela Redpath, wanders the ruins waiting for her father to come home. With the relics of the battle, it is said, the spirits of Darrowshire can be raised to fight it again, and this time Joseph Redpath's soul may be saved." },
        { side = "Horde", aside = true, sign = "P. F.", "Every village in the Eastweald had its Joseph Redpath. Darrowshire is the one whose dead may yet finish the story differently. Help them, if you can." },
      },
    },
    ["eastern-plaguelands"] = {
      title = "Eastern Plaguelands", kind = "place", chapter = "eastern-plaguelands",
      unlock = { { area = 139 } },
      also = { "lights-hope-chapel", "stratholme", "tyrs-hand", "scourge", "western-plaguelands" },
      text = {
        { "The Eastweald once held Lordaeron's eastern villages, abbeys and the city of Stratholme. The plague transformed it into the Eastern Plaguelands. Its trees are dead or dying, great fungus rises among them, and foul water runs through country the Scourge largely controls." },
        { "Light's Hope Chapel shelters the Argent Dawn in the east. The Scarlet Crusade retains Tyr's Hand in the south-east. Tirion Fordring lives in exile beside the Thondroril River, and Nathanos Blightcaller occupies his old farmhouse at the Marris Stead. These scattered inhabitants have very different purposes." },
      },
    },
    ["kelthuzad"] = {
      title = "Kel'Thuzad", kind = "figure", chapter = "eastern-plaguelands", portrait = 15945,
      unlock = { { kill = 15990 }, { quest = 9120 } },
      also = { "cult-of-the-damned", "andorhal", "dalaran", "naxxramas", "scourge", "fall-of-lordaeron" },
      text = {
        { "Kel'Thuzad was an archmage of Dalaran and a member of its ruling council, who went looking for forbidden power. Antonidas found it first, in his warehouses in the north: dead rats he had been trying to keep moving. The Kirin Tor put him on trial and confiscated his work, and Kel'Thuzad, with a friendly voice in his head that had been helping him all along, left them and went north to find its owner." },
        { "In Northrend a crypt lord, Anub'arak, showed him round a ziggurat called Naxxramas: laboratories, armouries, and cauldrons brewing a fluid that turned the dying into the dead. He was sick at the sight and tried to run, and the Lich King's wraiths would not let him. At the foot of the Frozen Throne he crawled, begged, and swore himself to its master. The Lich King answered with a vision of Naxxramas rising into the air, a fortress from which Kel'Thuzad would spread his master's power." },
        { "He came back to found the Cult of the Damned among the poor of Lordaeron, and with them he spread the plague through the grain of Andorhal. Prince Arthas killed him there. His body was carried to Quel'Thalas, to the Sunwell, and raised by its power as a lich." },
        { "He led the Scourge into Dalaran to summon Archimonde himself, and he stood by Arthas when the dreadlords turned on him. When Arthas went north to the Frozen Throne, Kel'Thuzad stayed to rule the Plaguelands in his name, and he rules them still, from Naxxramas. Even destroyed, a lich is not finished while his phylactery lasts." },
      },
    },
    ["lights-hope-chapel"] = {
      title = "Light's Hope Chapel", kind = "place", chapter = "eastern-plaguelands",
      unlock = { { area = 2268 } },
      also = { "argent-dawn", "church-of-the-holy-light", "naxxramas", "kelthuzad", "the-ashbringer", "scarlet-crusade" },
      text = {
        { "Light's Hope is a small stone chapel on consecrated ground in the Eastern Plaguelands. Lord Maxwell Tyrosus leads the Argent Dawn there. Anyone fighting the Scourge may find a welcome, whether they come from the Alliance or the Horde." },
        { "When Naxxramas appeared above the country, even the Scarlet Crusade met the Argent Dawn here to agree on a common fight. Kel'Thuzad's captured phylactery was later brought to the chapel. To a traveller passing its walls it looks too modest for a place where so many enemies have had reason to meet." },
        { "Korfax, Champion of the Light, speaks there for the Brotherhood of the Light, which he describes as the Argent Dawn with its conscience taken out, or the Scarlet Crusade without the fanaticism. He also tells of the first Dreadnaught armour, made for Highlord Mograine alone. In it, Korfax says, the Highlord looked like a creature of the Nether, and the Scourge fell around him by the hundred as he cut his way through them with the Ashbringer. After Mograine's death the knights of Lordaeron wore suits like it in his honour, and for every one of them who fell, more took up the fight. Korfax calls that death controversial, which is a kind word for it." },
      },
    },
    ["nathanos-blightcaller"] = {
      title = "Nathanos Blightcaller", kind = "figure", chapter = "eastern-plaguelands", portrait = 11814,
      unlock = { { npc = 11878 } },
      also = { "sylvanas-windrunner", "the-forsaken", "tyrs-hand", "si-7", "eastern-plaguelands" },
      text = {
        { "Nathanos Marris was a ranger lord of Lordaeron, respected by all, and the only human ever allowed to train with the high elves of Quel'Thalas. He died in the Plaguelands. He walks there still, as Nathanos Blightcaller, the Champion of the Banshee Queen, with his blighthounds, at his own old farmhouse at the Marris Stead." },
        { "He gives the Horde's hunters their hardest work, against the beasts of the Plaguelands, the high elves of Quel'Lithien Lodge and the Scarlet Crusade, and calls them all imbeciles. SI:7 sent five agents to learn what had become of him. One came back, and died. The word he brought back was Blightcaller. When the Alliance learned the truth, Highlord Bolvar Fordragon asked for the Blightcaller's head." },
        { side = "Horde", aside = true, sign = "P. F.", "He calls everyone an imbecile. As a historian I am obliged to record that he is not always wrong." },
      },
    },
    ["naxxramas"] = {
      title = "Naxxramas", kind = "place", chapter = "eastern-plaguelands",
      unlock = { { area = 3456 }, { quest = 9033 } },
      also = { "kelthuzad", "scourge", "argent-dawn", "lights-hope-chapel" },
      text = {
        { "Naxxramas hangs above the Plaguelands, a floating Scourge citadel and Kel'Thuzad's seat. From it came forces for a great invasion of Azeroth's cities, bringing the Argent Dawn to call on everyone willing to oppose the dead." },
        { "Five years after the last war, the Lich King stirs again and Kel'Thuzad gathers armies for another attack. Abominations, spiders and plague-bringers occupy the necropolis, along with four horsemen who were once champions of the Light. Look up when you cross the Plaguelands, traveller. Their commander has a fortress that need not depend on holding the road beneath it." },
      },
    },
    ["stratholme"] = {
      title = "Stratholme", kind = "history", chapter = "eastern-plaguelands",
      unlock = { { area = 2279 }, { area = 2017 } },
      also = { "fall-of-lordaeron", "jaina-proudmoore", "baron-rivendare", "balnazzar", "scourge", "scarlet-crusade" },
      text = {
        { "Stratholme was the second city of Lordaeron, its jewel in the north. When the plague came there in grain wagons, Prince Arthas arrived with Uther and Jaina and found the whole city sick and turning. He ordered it purged. Uther refused and Jaina left him. Arthas put Stratholme to the sword, house by house, before the dead could rise, and the dreadlord Mal'Ganis was waiting for him at the end of it. The Culling, they call it now, and it was the beginning of Arthas's fall." },
        { "It has seen worse betrayals since. A Stromgarde mage named Ras Frostwhisper gave his life to the Scourge on its bloodied ground, freely, and rose as the lich of Scholomance. And it was here that the Highlord Mograine, the Ashbringer, was led into an ambush by his own son and killed with his own blade." },
        { "The city still burns. The Scourge hold half of it, under Baron Rivendare, and the Scarlet Crusade the other half, from their bastion, under the Grand Crusader. The dead who were not culled still wander its streets, and some of them, the ghosts, would like very much to be set free." },
        { side = "Horde", aside = true, sign = "P. F.", "There are still those who say the prince was right at Stratholme. I am not one of them." },
      },
    },
    ["tirion-fordring"] = {
      title = "Tirion Fordring", kind = "figure", chapter = "eastern-plaguelands", portrait = 9477,
      unlock = { { npc = 1855 } },
      also = { "eitrigg", "hearthglen", "scarlet-crusade", "stratholme" },
      text = {
        { "You may find Tirion Fordring in a little hut beside the Thondroril River. He was once lord of Mardenholde Keep at Hearthglen and a paladin of the Silver Hand. There is little in his present lodging to suggest either distinction." },
        { "The orc Eitrigg saved his life. Tirion resisted his capture and, at his trial in Stratholme, refused to abandon the oath he had sworn to him. His titles and holdings were taken away, and he was sent into exile. His wife told their son Taelan that he was dead." },
        { "Taelan now leads the Scarlet Crusade at Hearthglen. Tirion asks travellers to recover a toy hammer he gave the boy, the Silver Hand standard Taelan cast down at Northdale, and a painting hidden in Stratholme. These are the things he hopes will reach his son. If he entrusts you with the errand, traveller, remember that he is trying to bring Taelan home." },
      },
    },
    ["tyrs-hand"] = {
      title = "Tyr's Hand", kind = "place", chapter = "eastern-plaguelands",
      unlock = { { area = 2266 }, { area = 2267 } },
      also = { "scarlet-crusade", "stratholme", "nathanos-blightcaller", "treason-of-alterac" },
      text = {
        { "Tyr's Hand is a fortified city in the south-east of the Plaguelands, by Tyr's Bay, full of churches, and one of the oldest holy places of Lordaeron. It has been through war before: in the Second War, Alterac's spies stirred its peasants to revolt to hide an orcish mine, and the Silver Hand was sent to keep the peace. In the Third War, it held against the Scourge, and it holds still, for the Scarlet Crusade." },
        { "Crusader Lord Valdelmar rules it, High General Abbendis commands its soldiers, and a seer the Crusaders call the Scarlet Oracle advises the Grand Crusader. Couriers ride every day through the Plaguelands between Tyr's Hand and Stratholme. The Forsaken watch every one." },
      },
    },
    ["bolvar-fordragon"] = {
      title = "Highlord Bolvar Fordragon", kind = "figure", chapter = "elwynn", portrait = 5566,
      unlock = { { npc = 1748 } },
      also = { "stormwind-city", "regency-of-stormwind", "katrana-prestor", "great-masquerade", "marshal-windsor", "noble-conspiracy" },
      text = {
        { "Highlord Bolvar Fordragon commands Stormwind's armies and stands beside the boy king, Anduin Wrynn, while his father Varian is missing. He is a paladin of the old school, devout, honest and immovable, and he keeps the kingdom's soldiers where the kingdom needs them most, which is rarely where the provinces would like them." },
        { "He is a careful man, perhaps too careful. When Lakeshire's magistrate sent word that the Blackrock orcs had dragons behind them, Bolvar would not move troops on speculation and sent the messenger to ask Lady Katrana Prestor's advice. Marshal Windsor, who had found the proof, called him a fool: it stood two feet away from him, he said, and he did not see it. When Windsor exposed the lady in the throne room as Onyxia, daughter of Deathwing, he said that even the Highlord had been her puppet, held by a dragon's medallion. Bolvar was left holding it, shattered, at the end." },
        { "He is not a fool. He is an honest man who took a dragon at her word, and I doubt he will do it again." },
      },
    },
    ["church-of-the-holy-light"] = {
      title = "The Church of the Holy Light", kind = "faction", chapter = "elwynn", portrait = 5072,
      unlock = { { npc = 1284 }, { npc = 1212 }, { read = { "Lady Mara Fordragon", "여군주 마라 포드래곤", "Dame Mara Fordragon", "Fürstin Mara Fordragon", "玛拉·弗塔根", "Леди Мара Фордрагон", "瑪拉·弗塔根" } } },
      also = { "northshire-abbey", "stormwind-city" },
      text = {
        { "The Church of the Holy Light teaches that virtue, compassion and sacrifice draw on a power that can heal and protect. The faith came south from Lordaeron, and Stormwind's Cathedral of Light is now its seat, under Archbishop Benedictus. Dwarves have learned its ways from their human neighbours too." },
        { "In the Second War, Archbishop Alonsus Faol founded the Knights of the Silver Hand. These first paladins, led by Uther the Lightbringer, brought the Light to the battlefield alongside their swords. Since Lordaeron's fall, Stormwind has become the church's centre, and its priests and paladins serve throughout the Alliance." },
        { "Questions of faith may occupy a scholar for years. A wounded traveller has a more immediate reason to be grateful for a priest's learning." },
      },
    },
    ["elwynn-forest"] = {
      title = "Elwynn Forest", kind = "place", chapter = "elwynn",
      unlock = { { area = 12 } },
      also = { "northshire-abbey", "goldshire", "stormwind-city", "hogger", "defias-brotherhood", "kobolds", "gnolls" },
      text = {
        { "Elwynn is the forest that feeds Stormwind: tall old trees, open meadows, farms and vineyards and the slow river running down to Westfall. It is the gentlest country in the human lands, and it is hard, walking its roads on a summer morning, to believe what happened here." },
        { "In the First War the orcs came through these woods. They burned the farms, the abbey and the villages one after another, and then they took the city itself. The kingdom was rebuilt after the Second War, and the woods shelter farms and settlements again." },
        { "The peace is thinner than it looks. Kobolds have taken the mines, the Riverpaw gnolls raid from the west, and the red-masked Defias have spread out of Westfall into the woods. Ask any farmer in Elwynn whether the king's soldiers come when they are called." },
      },
    },
    ["goldshire"] = {
      title = "Goldshire", kind = "place", chapter = "elwynn",
      unlock = { { area = 87 } },
      also = { "elwynn-forest", "hogger" },
      text = {
        { "Goldshire stands at an Elwynn crossroads, with the Lion's Pride Inn ready for travellers and Marshal Dughan ready to give them work. The village is older than the wars. It burned when the orcs came through Elwynn in the First War." },
        { "After the Second War, Stormwind's people returned from exile in Lordaeron and rebuilt it. The smithy and market are busy again, and young adventurers stop here on their way to make a name. Look over Dughan's bounty board while you are here, traveller. The village has recovered. The marshal still has plenty to worry about." },
      },
    },
    ["great-masquerade"] = {
      title = "The Great Masquerade", kind = "history", chapter = "elwynn",
      unlock = { { quest = 6403 } },
      also = { "katrana-prestor", "black-dragonflight", "regency-of-stormwind" },
      text = {
        { "Marshal Reginald Windsor gathered proof against Highlord Bolvar Fordragon's adviser, only to lose it in the dungeons of Blackrock Mountain. After his rescue, he returned with fresh evidence and companions willing to stand beside him. He brought both into Stormwind Keep." },
        { "There he exposed Lady Katrana Prestor as Onyxia, daughter of Deathwing and sister of Nefarian. She had kept Stormwind's army at home while her brother's orcs threatened Redridge, and bent Bolvar to her will. Windsor broke her disguise before the court. She fled to her lair in Dustwallow Marsh." },
        { "Windsor died in the confrontation. Set down his name, traveller, if you record the dragon's defeat. His part in it began long before anyone reached her lair." },
      },
    },
    ["hogger"] = {
      title = "Hogger", kind = "creature", chapter = "elwynn", portrait = 384,
      unlock = { { kill = 448 } },
      also = { "gnolls", "goldshire" },
      text = {
        { "The wanted notice at Westbrook Garrison describes Hogger as a huge gnoll, camped to the south in south-western Elwynn. He belongs to the Riverpaw, and the Stormwind guards have been unable to capture him. A reward is offered for his claw." },
        { "The notice advises bringing a group. Follow that advice, traveller. A guard's admission that he needs help is more useful than an adventurer's confidence that he does not." },
      },
    },
    ["katrana-prestor"] = {
      title = "Lady Katrana Prestor", kind = "figure", chapter = "elwynn", portrait = 8769,
      unlock = { { npc = 1749 } },
      also = { "regency-of-stormwind", "great-masquerade" },
      text = {
        { "Lady Katrana Prestor is the Highlord's closest adviser, and much admired at court: learned, gracious and very beautiful. She knows a great deal about a great many things, dragons among them, and Bolvar Fordragon trusts her completely." },
        { "Not everyone does. When Magistrate Solomon of Lakeshire begged the throne for soldiers against the Blackrock orcs, it was Lady Prestor's counsel that kept them at home, and there is at least one marshal of Stormwind who has never forgiven her for it. I set down only what is known. A scholar who writes more than that about a lady of the court had better be very sure of himself." },
      },
    },
    ["noble-conspiracy"] = {
      title = "The Noble Conspiracy", kind = "history", chapter = "elwynn",
      unlock = { { kill = 1754 }, { quest = 434 } },
      also = { "defias-brotherhood", "si-7", "the-stockade" },
      text = {
        { "A letter found on Edwin VanCleef's body carried the Defias investigation back inside Stormwind. It led to Bazil Thredd in the Stockade, a visitor using a false name, and at last the assassin called Marzon the Silent Blade." },
        { "Marzon worked for Lord Gregor Lescovar, who was passing the court's secrets to the Brotherhood. The noble's connections made a public prosecution difficult. SI:7's allies arranged a meeting in the castle gardens, where Lescovar and Marzon were killed." },
        { "The masons' grievance began with nobles refusing to pay for Stormwind's rebuilding. Lescovar was now helping the rebellion that refusal had helped create. VanCleef's reach into the city extended well beyond the people wearing red masks." },
      },
    },
    ["northshire-abbey"] = {
      title = "Northshire Abbey", kind = "place", chapter = "elwynn",
      unlock = { { area = 9 }, { area = 24 } },
      also = { "elwynn-forest", "church-of-the-holy-light" },
      text = {
        { "Northshire Abbey stands in a valley at Elwynn's northern edge. Its clerics served Stormwind during the First War, before the kingdom fell to the Horde. After the Second War, Alonsus Faol helped rebuild the city and reform the Brotherhood of Northshire." },
        { "The abbey now instructs the kingdom's recruits in arms as well as faith. There is use for both close at hand: kobolds occupy the mine, wolves roam the valley, and Defias thieves have taken the vineyards." },
      },
    },
    ["regency-of-stormwind"] = {
      title = "The Regency of Stormwind", kind = "history", chapter = "elwynn",
      unlock = { { npc = 1748 }, { npc = 1747 } },
      also = { "katrana-prestor", "stormwind-city" },
      text = {
        { "King Varian Wrynn has vanished. He was the son of King Llane, murdered in the First War, and grew up among Stormwind's refugees in Lordaeron. His own fate remains unknown in the city he ruled." },
        { "His young son Anduin wears the crown. Highlord Bolvar Fordragon holds the kingdom for him, commands its forces and guards the boy. The royal adviser, Lady Katrana Prestor, stands at Bolvar's side." },
        { "Stormwind's army is spread thin, and demands arrive from every quarter." },
      },
    },
    ["si-7"] = {
      title = "SI:7", kind = "faction", chapter = "elwynn", portrait = 1736,
      unlock = { { npc = 332 } },
      also = { "noble-conspiracy", "defias-brotherhood" },
      text = {
        { "From the barracks in Old Town, Mathias Shaw directs Stormwind's intelligence service. SI:7 follows the dealings that seldom reach a public notice: the Defias, the secrets of the nobles, and the places where the two meet." },
        { "A description of Bazil Thredd's visitor led Shaw to an assassin using the name Marzon, in the employ of Lord Gregor Lescovar. The resulting investigation ended with both men dead in the castle gardens, beyond the easy reach of ordinary justice." },
        { "The barracks give the service an unremarkable home. Its work leads into rooms where the city's enemies can dress very respectably." },
      },
    },
    ["sons-of-lothar"] = {
      title = "The Sons of Lothar", kind = "history", chapter = "elwynn",
      unlock = { { area = 1617 }, { read = { "Kurdran Wildhammer", "쿠르트란 와일드해머", "库德兰·蛮锤", "Kurdran Martillo Salvaje", "Курдран Громовой Молот", "Kurdran Martelo Feroz", "庫德蘭·蠻錘" } }, { read = { "General Turalyon", "투랄리온 장군", "Général Turalyon", "图拉扬将军", "Генерал Туралион", "圖拉揚將軍" } }, { read = { "Ranger Captain Alleria Windrunner", "순찰대장 알레리아 윈드러너", "Capitaine des forestiers Alleria Windrunner", "Waldläufercaptain Alleria Windrunner", "游侠队长奥蕾莉亚·风行者", "Capitán guardabosques Alleria Brisaveloz", "Капитан следопытов Аллерия Ветрокрылая", "Capitão-patrulheira Alleria Correventos", "遊俠隊長奧蕾莉亞·風行者" } }, { read = { "Danath Trollbane", "다나스 트롤베인", "达纳斯·托尔贝恩", "Danath Aterratrols", "Данат Троллебой", "Danath Matatroll", "達納斯·托爾貝恩" } }, { read = { "Archmage Khadgar of the Kirin Tor", "키린 토의 대마법사 카드가", "Archimage Khadgar du Kirin Tor", "Erzmagier Khadgar von den Kirin Tor", "肯瑞托的大法师卡德加", "Archimago Khadgar del Kirin Tor", "Верховный маг Кадгар из Кирин-Тора", "Arquimago Hadggar do Kirin Tor", "肯瑞托的大法師卡德加" } } },
      also = { "the-second-war", "the-dark-portal", "nethergarde-keep", "stormwind-city", "sylvanas-windrunner", "wildhammer-clan" },
      text = {
        { "Five statues stand at the gate of Stormwind, and each plaque ends the same way: presumed deceased. They are the commanders of the Alliance Expedition, who marched through the Dark Portal into the orcs' own world after the Second War, when Ner'zhul and the last of the clans came back through it." },
        { "Khadgar, once Medivh's apprentice, led them, with General Turalyon at his side. The elven ranger Alleria Windrunner scouted for them, Kurdran Wildhammer led the gryphon riders, and Danath Trollbane of Stromgarde advised them. They could not stop Ner'zhul from opening his portals to other worlds, and as Draenor tore itself apart they chose to destroy the Dark Portal from the far side, so that Azeroth would not be dragged down with it. They succeeded. Whether any of them escaped, the book in our library says, remains to be seen." },
        { "Read the plaques themselves. Each was written by someone who knew the hero: Falstad for Kurdran, Uther for Turalyon, Thoras Trollbane for his nephew, Antonidas for Khadgar, wishing him well wherever he is. Alleria's was written by her sister, Sylvanas, Ranger-General of Quel'Thalas, before she became what she is now." },
      },
    },
    ["stonefields-and-maclures"] = {
      title = "The Stonefields and the Maclures", kind = "history", chapter = "elwynn",
      unlock = { { area = 63 }, { area = 64 }, { npc = 251 }, { npc = 252 } },
      also = { "elwynn-forest", "goldshire" },
      text = {
        { "The Stonefields and the Maclures farm on either side of the Fargodeep Mine, south of Goldshire, and the two families have been at odds for longer than anyone bothers to explain. Naturally, Maybell Maclure is in love with Tommy Joe Stonefield. He waits by the river west of his family's farm for her letters. She waits for a chance to slip away." },
        { "The Stonefields' grandmother is on the young people's side. She sends a note to her old friend William Pestle in Goldshire, who can brew an invisibility liquor if someone brings him crystal kelp from the murlocs of Crystal Lake. With it Maybell can walk out of her family's vineyards unseen. She feels guilty deceiving them, she says, but not guilty enough to stay." },
        { "The feud goes on around them: a Stonefield aunt accusing young Billy Maclure of stealing her necklace, Ma Stonefield vowing death to the Brackwells' prize sow for eating her vegetables. Elwynn has seen the Defias, the kobolds and the gnolls come and go. The feud has outlasted all of them so far." },
      },
    },
    ["stormwind-city"] = {
      title = "Stormwind City", kind = "place", chapter = "elwynn",
      unlock = { { area = 1519 } },
      also = { "regency-of-stormwind", "defias-brotherhood", "church-of-the-holy-light", "si-7", "the-stockade", "elwynn-forest" },
      text = {
        { "Stormwind is the greatest city of men, and it is the second Stormwind to stand in this place. The first was sacked by the Horde in the First War and burned to the ground. King Llane was murdered, and his people fled north to Lordaeron with the champion Anduin Lothar. When the Second War was won, they came home and built it again." },
        { "The masons of the Stonemasons' Guild raised it in white stone, finer than before: the Cathedral of Light, the canals and the keep above them all. The House of Nobles then refused to pay them, and the masons' grievance has since become the Defias Brotherhood, so that the most beautiful city in the Alliance is also the most bitterly remembered." },
        { "It is a city of trade and soldiers, with ships in its harbour, of priests and spies, and of a court that whispers. The boy on the throne is its king. The men and women around him rule it." },
      },
    },
    ["the-stockade"] = {
      title = "The Stockade", kind = "place", chapter = "elwynn",
      unlock = { { area = 717 } },
      also = { "defias-brotherhood", "noble-conspiracy", "stormwind-city" },
      text = {
        { "Stormwind's prison lies beneath its canals, cut into the rock below the city. Among the Defias confined there was Edwin VanCleef's lieutenant, Bazil Thredd. Under his leadership the inmates rose and took control of the cells." },
        { "The Warden called for adventurers to put down the revolt. Thredd was not the only dangerous prisoner within: the orc Targorr the Dread was among the rioters. It is an uncomfortable place to have an enemy stronghold underneath the streets of your own capital." },
      },
    },
    ["bloodvenom-post"] = {
      title = "Bloodvenom Post", kind = "place", chapter = "felwood",
      unlock = { { area = 1997 } },
      also = { "felwood", "jaedenar", "royal-apothecary-society" },
      text = {
        { "Bloodvenom Post is the Horde's camp in the heart of Felwood, beside the poisoned falls of the Bloodvenom. Its people fight the Shadow Council in Jaedenar and the corrupted things of the forest, and a widow waits there for vengeance on the furbolg that killed her husband." },
        { "Not everyone at the Post wants Felwood healed. A Forsaken apothecary, Winna Hazzard, studies the corrupted moonwell of the Jadefire satyrs, looking for an advantage against the Alliance in its water. I would keep an eye on her cat." },
      },
    },
    ["emerald-sanctuary"] = {
      title = "The Emerald Sanctuary", kind = "place", chapter = "felwood",
      unlock = { { area = 2479 } },
      also = { "felwood", "cenarion-circle", "satyrs", "jaedenar" },
      text = {
        { "The Emerald Sanctuary is a grove in the south of Felwood, held by the Emerald Circle, druids of the Cenarion Circle who have sworn to heal the forest. They fight the Jadefire satyrs and the Shadow Council, and study the blood amber of the corrupted elementals, hoping to learn how to save the rest." },
        { "Their patience is enormous. They cleanse the tainted songflowers and windblossoms one by one, and they purify the spirits of the ancients the satyrs bound with fel magic. It is slow work, and they know it may take longer than any of them will live. They are night elves. They may well be right." },
      },
    },
    ["felwood"] = {
      title = "Felwood", kind = "place", chapter = "felwood",
      unlock = { { area = 361 } },
      also = { "emerald-sanctuary", "jaedenar", "bloodvenom-post", "talonbranch-glade", "satyrs", "furbolgs", "ashenvale" },
      text = {
        { "Felwood was the northern part of the great forest of Ashenvale. It is a poisoned land now, its trees black and twisted, its rivers green, its furbolgs mad and its very plants tainted. The demons did this. In the last war, the dreadlord Tichondrius held the Skull of Gul'dan here, and its corruption spread through the woods. When Illidan Stormrage took the Skull's power for himself, the forest was not healed." },
        { "The Shadow Council and its demons hold Jaedenar, the Jadefire satyrs the old ruins, and corrupted ancients and elementals walk the woods. The druids of the Emerald Circle are trying to heal it, plant by plant. The Horde keeps Bloodvenom Post in the middle of it, and the night elves a glade in the north, at the gates of Timbermaw." },
      },
    },
    ["illidan-stormrage"] = {
      title = "Illidan Stormrage", kind = "figure", chapter = "felwood",
      unlock = { { area = 361 }, { read = { "Mount Hyjal and Illidan's Gift", "하이잘 산과 일리단의 선물", "Le Mont Hyjal et le Cadeau d'Illidan", "Der Berg Hyjal und Illidans Geschenk", "海加尔山和伊利丹的礼物", "El Monte Hyjal y el obsequio de Illidan", "Гора Хиджал и Дар Иллидана", "O Monte Hyjal e a Dádiva de Illidan", "海加爾山和伊利丹的禮物" } }, { read = { "The Betrayer Ascendant", "떠오르는 배반자", "Les parents du Traître", "Der aufstrebende Verräter", "背叛者的胜利", "El ascendiente traidor", "Восход Предателя", "O Domínio do Traidor", "背叛者的勝利" } } },
      also = { "felwood", "malfurion-stormrage", "tyrande-whisperwind", "naga", "blood-elves", "jaedenar" },
      text = {
        { "Illidan was Malfurion's twin brother, and he loved Tyrande too. She chose Malfurion. In the War of the Ancients he fought the Legion with his brother, but he never gave up the Highborne's magic, and when the Well of Eternity was destroyed he carried vials of its waters to the top of Mount Hyjal and poured them into a lake, making a new Well. He thought it a gift. Malfurion called it a crime and, with Cenarius's help, sealed him in a barrow prison, chained and guarded, for ten thousand years." },
        { "Tyrande freed him when the Legion came back, hoping he would help. In these woods he did something else. The dreadlord Tichondrius held the Skull of Gul'dan here, a warlock's relic full of fel power, and Illidan took it and drank its strength. He came out of it a demon in shape, with some of Gul'dan's memories, and killed Tichondrius. Malfurion banished him for it." },
        { "The book in our library has him flee after that, beyond the world, to the broken remains of the orcs' homeland, with the naga and the blood elves at his back. Felwood has not recovered from that night either." },
      },
    },
    ["jaedenar"] = {
      title = "Jaedenar", kind = "place", chapter = "felwood",
      unlock = { { area = 1763 }, { area = 1770 } },
      also = { "felwood", "burning-legion", "emerald-sanctuary", "burning-blade" },
      text = {
        { "Jaedenar was a place of the night elves, with ruins and barrow dens in the west of Felwood. The Shadow Council holds it now, the old cult of warlocks who once made the orcs a tool of the Burning Legion. Orc and Forsaken warlocks, demons and satyrs fill its halls, and below them, in the Shadow Hold, Shadow Lord Fel'dan makes his pacts with the Legion." },
        { "The Emerald Circle wants the Council destroyed. Even inside, the cult is at war with itself: its masters plot against each other, and each of their rivals has spies at the others' sides." },
      },
    },
    ["talonbranch-glade"] = {
      title = "Talonbranch Glade", kind = "place", chapter = "felwood",
      unlock = { { area = 1998 } },
      also = { "felwood", "furbolgs", "moonglade", "winterspring" },
      text = {
        { "Talonbranch Glade is a small night elf outpost in the north of Felwood, with a moonwell and a few houses among the corrupted trees, just south of Timbermaw Hold, the furbolgs' tunnel that leads on to Moonglade and Winterspring." },
        { "It is a little island of clean ground in a sick forest, and the Sentinels who keep it guard the road north for every traveller who must pass through Felwood." },
      },
    },
    ["camp-mojache"] = {
      title = "Camp Mojache", kind = "place", chapter = "feralas",
      unlock = { { area = 1099 } },
      also = { "feralas", "dire-maul", "grimtotem", "ogres", "thunder-bluff" },
      text = {
        { "Camp Mojache is the Horde's camp in the east of Feralas, a ring of tauren tents and totems on a hill among the giant trees, near the road to Dire Maul. The tauren here watch the Gordunni ogres, whose numbers are growing, and their Grimtotem cousins in the hills to the south, who are no friends of Thunder Bluff." },
        { "The camp's sages have their own interest in the ruins. They are looking for an elven master who fled the fall of Quel'Thalas with ancient artifacts, and they think he went into Dire Maul." },
      },
    },
    ["dire-maul"] = {
      title = "Dire Maul", kind = "place", chapter = "feralas",
      unlock = { { area = 2557 } },
      also = { "shendralar", "ogres", "satyrs", "feralas", "highborne-ruins" },
      text = {
        { "Dire Maul was Eldre'Thalas, a city of the Highborne, built in Queen Azshara's day to keep her most prized arcane secrets. It survived the Sundering, and much of it stands still, a city of white stone in the forest, its halls full of books and ghosts." },
        { "Now it is broken into three. The Gordok ogres hold the north, and crown a new king whenever the old one is killed. The satyr Alzzin the Wildshaper holds the east, and has corrupted the city's Fruit of Fertility into a foul thing called the Felvine. The west is still held by the last of the Highborne, the Shen'dralar, around their library, which I would give a great deal to read." },
      },
    },
    ["feathermoon-stronghold"] = {
      title = "Feathermoon Stronghold", kind = "place", chapter = "feralas",
      unlock = { { area = 1116 } },
      also = { "shandris-feathermoon", "feralas", "naga" },
      text = {
        { "Feathermoon Stronghold stands on Sardor Isle off Feralas's coast, reached by boat from the mainland. General Shandris Feathermoon commands its Sentinels from white walls above a harbor. The fortress bears her name." },
        { "Its soldiers oppose the Hatecrest naga at Solarsal and watch the forest's ogres. Scholars also work among Feralas's old elven ruins." },
      },
    },
    ["feralas"] = {
      title = "Feralas", kind = "place", chapter = "feralas",
      unlock = { { area = 357 } },
      also = { "feathermoon-stronghold", "camp-mojache", "dire-maul", "ogres", "grimtotem", "naga" },
      text = {
        { "Feralas is a land of rain and giants, on the west coast of Kalimdor: a forest of trees so tall their crowns are lost in the mist, with ancient ruins in their roots. The night elves built here long before the Sundering, and their stones are everywhere, overgrown and broken. The scholars of Feathermoon spend their lives among them, and still cannot say what half of them were." },
        { "Today the forest belongs to the Gordunni ogres, whose growing numbers concern the nearby settlements, to gnolls, yetis, naga on the coast and the Grimtotem in the hills. The Sentinels keep an island stronghold off the coast, the Horde a camp in the east, and in the heart of the forest stands the broken Highborne city the ogres call Dire Maul." },
      },
    },
    ["shandris-feathermoon"] = {
      title = "Shandris Feathermoon", kind = "figure", chapter = "feralas", portrait = 2035,
      unlock = { { npc = 3936 } },
      also = { "tyrande-whisperwind", "feathermoon-stronghold", "burning-legion", "satyrs" },
      text = {
        { "General Shandris Feathermoon commands the Sentinels from the stronghold bearing her name. Her service beside Tyrande began in the War of the Ancients, when she was a child fleeing Ara-Hinam, separated from her family and believed orphaned. Tyrande took her into her care." },
        { "Shandris followed her into danger despite orders to remain behind. One of her arrows struck Xavius. Malfurion used the wood of its embedded shaft to overcome the satyr. The child had a part in the war before anyone would have chosen to give her one." },
        { "She has stood beside Tyrande through the Sundering and the ages since. Today her command lies far from Darnassus, in Feralas." },
      },
    },
    ["shendralar"] = {
      title = "The Shen'dralar", kind = "faction", chapter = "feralas", portrait = 14407,
      unlock = { { npc = 14368 }, { kill = 11486 }, { kill = 11496 } },
      also = { "dire-maul", "burning-legion", "highborne-ruins" },
      text = {
        { "The Shen'dralar have remained in Eldre'Thalas since before the Sundering. Cut off from the Well of Eternity, they bound the demon Immol'thar beneath their city with five pylons. For thousands of years they have drained his power to sustain themselves." },
        { "Prince Tortheldrin still rules, surrounded by halls haunted with his people's ghosts. Some Shen'dralar have chosen freedom over immortality. The Shen'dralar Ancient asks for Tortheldrin's death and peace for the spirits, while keepers of the Athenaeum reward help with their knowledge. There is a remarkable library here, but the history of how its people survived deserves equal attention." },
      },
    },
    ["foreword-dwarf"] = {
      title = "A Word from the Royal Historian", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Dwarf = true },
      text = {
        { "Traveller, welcome to this ledger of Azeroth. I have begun with the country around Ironforge, where a dwarf may know every road and still have questions about the stones beside it." },
        { "The pages follow our clans, the wars that divided them, and the older works the League is trying to understand. They follow other peoples too. Our history has crossed theirs often enough that a book confined to dwarves would leave much unexplained." },
        { "Carry it with you, and read a page when a place gives you reason to pause. A ruin is easier to notice than the life it once sheltered. Both deserve a place in the record." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-gnome"] = {
      title = "A Word to a Child of Gnomeregan", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Gnome = true },
      text = {
        { "Traveller, I have written this first page for a gnome with some care. Gnomeregan still lies beneath Dun Morogh, and your people cannot yet return to it. A ledger of old places ought to recognise that some losses are still being lived through." },
        { "Ironforge has offered your people shelter. You have brought ingenuity and a considerable quantity of noise into our halls. We are glad of the company, with occasional reservations about the noise. The account of Gnomeregan is here, along with the country its exiles now share." },
        { "Read these pages wherever your work takes you. I hope the entry about your home will one day need a happier addition. Until then, its history belongs beside the inventions and errands that may help you recover it." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-human"] = {
      title = "A Word to a Son or Daughter of Stormwind", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Human = true },
      text = {
        { "Traveller, I am glad to send this ledger to a reader of Stormwind. Your people and mine have stood together since the Second War. Our accounts of the battles since have seldom lacked names from both." },
        { "Stormwind was destroyed and rebuilt. Its new stonework is a great achievement, and the unpaid masons who raised it are part of its history too. You will find that account here beside the stories your kingdom has more reason to celebrate." },
        { "Use the book as you travel. Towns, ruins and roads can tell you how a country came to be as you find it, provided someone keeps track of the people who made them." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-nightelf"] = {
      title = "A Word to One of the Kaldorei", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { NightElf = true },
      text = {
        { "Traveller, this ledger was bound for one of the kaldorei, and I confess that it is an odd thing to offer a history to a people who remember ten thousand years. Forgive a dwarf her presumption. We count our ages in stone. You count yours in the lives of trees." },
        { "For most of those years your people kept to their forests and let no one in. Now you have planted a new World Tree off the coast of Darkshore and opened your gates to the Alliance, and the League has followed its curiosity into your ruins, as it always does. Where we have guessed wrong, I would be grateful to be told." },
        { "Wherever history was made, I have left a page for you. Read them by the fire, and remember that every ruin was once someone's home." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-orc"] = {
      title = "A Word to One of the Horde", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Orc = true },
      text = {
        { "Traveller, the ledger in your hands was written in Ironforge, by Archesonus, King Magni's Royal Historian, and you may wonder why a Forsaken of the Undercity has sent a dwarf's history on to an orc. I was a historian of Lordaeron before the plague took me, and I know a fair account when I read one. Hers is fair more often than I expected." },
        { "Your people's road is in it. The Dark Portal brought them here. Defeat brought them into Lordaeron's internment camps. Thrall led them out and across the sea to Durotar, named for his father. Those camps stood in my kingdom while I was still alive, and I find I read those pages more slowly than the others." },
        { "Take the book on your journeys. Strength will carry you a long way, but knowledge goes further, and the more you know of a place, the more of it you will see. If your road ever brings you to the Undercity, come and find me. I may have a question for you." },
        { italic = true, "Parqual Fintallas, the Apothecarium, Undercity" },
      },
    },
    ["foreword-other"] = {
      title = "A Word from the Royal Historian", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { other = true },
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, the Apothecarium, Undercity", "This ledger was written in Ironforge, by Archesonus, its Royal Historian, and it comes to you from the Undercity by way of my desk. She writes as a dwarf of the Alliance, and says so. Where she forgets the Horde, read her with that in mind, as I did." },
        { "Traveller, welcome. This ledger follows Azeroth's towns, ruins and roads, and the people whose lives have left them as you find them. You need no particular ancestry to take an interest in where you are standing." },
        { "I write from the High Seat in Ironforge, a few steps from the king's throne, and the Explorers' League brings home more for me to read than I will ever finish. A dwarf's account will have a dwarf's interests, but the world has given us more to investigate than the affairs of our own clans." },
        { "Read a page when your travels bring you to its place. The stones may have survived better than the names. I have tried to keep both within reach." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-skyborne"] = {
      title = "A Word to One of the Skyborne", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = { "dire-maul", "shendralar" }, race = { Skyborne = true },
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, the Apothecarium, Undercity", "This ledger was written in Ironforge, by Archesonus, its Royal Historian, and it comes to you from the Undercity by way of my desk. Her word to your people was too good to rewrite, so here it is as she wrote it." },
        { "Traveller, this ledger was bound for one of the Skyborne, and I confess I had to begin it twice. Until your people came down out of the sky, no historian in Ironforge knew you existed. Your own name for yourselves, the shen'dorei, the hidden people, is fairer than anything we could have written." },
        { "We knew your beginning without knowing it was yours. Your ancestors lived in Eldre'Thalas, the city the ogres now call Dire Maul, and when its prince meant to bind a demon to feed his people's magic, they rose against him behind a masked leader, the Shal'nan. They fled west by sea with the prince's ships behind them, and wind spirits lifted their island into Skywall, out of the world entirely. The Explorers' League knows those halls in Feralas well. None of us guessed that some of the city had got away." },
        { "Now the spirits are gone, the isle is failing, and your people have come looking for help, the High Order to Dalaran's mages, the Windshapers to the shamans. This ledger knows the world you have come back to better than the one you left. Wherever history was made, I have left a page for you. Read them by the fire, and remember that every ruin was once someone's home." },
        { italic = true, "Royal Historian Archesonus, the High Seat, Ironforge" },
      },
    },
    ["foreword-tauren"] = {
      title = "A Word to One of the Shu'halo", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Tauren = true },
      text = {
        { "Traveller, your people keep their history in songs and in the memory of the land. Mine kept it in books, and a plague can empty a library as surely as a city. Perhaps the songs were the wiser choice." },
        { "The pages that follow were written in Ironforge, by Archesonus, its Royal Historian, and they come to you from the Undercity by way of my desk. They tell how the tauren wandered Kalimdor's plains for generations under pressure from the centaur, and how Cairne Bloodhoof, with the orcs' help, gathered the tribes into Mulgore. Thunder Bluff now stands above the grasslands as a home for a people long denied a settled one." },
        { "Read them with the attention you give your elders. Where a page and an elder disagree, I would be grateful to hear which, and why. A historian collects such disagreements the way others collect coin." },
        { italic = true, "Parqual Fintallas, the Apothecarium, Undercity" },
      },
    },
    ["foreword-troll"] = {
      title = "A Word to One of the Darkspear", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Troll = true },
      text = {
        { "Traveller, this ledger was bound for one of the Darkspear, and I owe you two admissions. Its pages were written in Ironforge, by Archesonus, the Royal Historian there. I have only sent them on from the Undercity. And troll history is older than anything either of us keeps on a shelf. Your kind built empires in the jungles of the south and the forests of the north long before the kingdoms of men arose." },
        { "Your tribe was small and hard pressed when Thrall's ships found you on your islands, and you have kept faith with the Horde ever since, on the shores of Durotar beneath Sen'jin's name. My own people came to the Horde later, and by a stranger road. We have a good deal to learn from those who stood by it first." },
        { "Wherever history was made, the dwarf has left a page for you. Where her pages fall short of what your elders could tell, trust your elders, and then, if you can spare the time, tell me what they said." },
        { italic = true, "Parqual Fintallas, the Apothecarium, Undercity" },
      },
    },
    ["foreword-undead"] = {
      title = "A Word to One of the Forsaken", kind = "note", chapter = "",
      unlock = { { always = true } },
      also = {  }, race = { Scourge = true },
      text = {
        { "Traveller, you and I have both outlived our kingdom. I was a historian of Lordaeron before the plague took me, and you may remember its towns as they were, when its capital stood above the ground. This ledger knows them only through records, for it was written in Ironforge, by Archesonus, King Magni's Royal Historian. I have sent it on all the same. It is a fair account, and fair accounts of our home are rare." },
        { "The Forsaken freed themselves from the Lich King and now follow Sylvanas beneath the ruins of the city we knew. Much about the life we lead now lies beyond a dwarf's understanding. Where she writes of the Scarlet Crusade, she is kinder to them than I would be." },
        { "Carry the ledger if it is useful to you. Where a place recalls something these pages cannot tell, trust your own memory over her records, and over mine." },
        { italic = true, "Parqual Fintallas, the Apothecarium, Undercity" },
      },
    },
    ["dun-garok"] = {
      title = "Dun Garok", kind = "place", chapter = "hillsbrad",
      unlock = { { area = 290 } },
      also = { "hillsbrad-foothills", "southshore", "ironforge" },
      text = {
        { "Dun Garok is a dwarven fortress built into the hills of south-eastern Hillsbrad, a long way from home, and its garrison under Captain Ironhill holds the passes and protects the people of the foothills and the mines nearby. It is a stubborn little outpost of Ironforge in a land of the dead, and I am proud of it." },
        { "The Forsaken hate it, and send their raiders against it. The dwarves send them back." },
      },
    },
    ["durnholde-keep"] = {
      title = "Durnholde Keep", kind = "history", chapter = "hillsbrad",
      unlock = { { area = 275 }, { quest = 508 } },
      also = { "thrall", "syndicate", "hillsbrad-foothills" },
      text = {
        { "Durnholde controlled the orc internment camps after the Second War. Its master, Aedelas Blackmoore, raised an orc child as a slave and gladiator, intending him to command an obedient army. The child was Thrall. Taretha Foxton, a girl of Blackmoore's household, befriended him and helped him escape." },
        { "Thrall went on to free his people. Blackmoore is dead, and the Syndicate holds the keep. His ambitions outlived him elsewhere: at a manor beside Lordamere Lake, Aliden Perenolde plans to enslave orcs in his turn. His companion Elysa carries Taretha's pendant." },
        { "Thrall wants it back. A pendant is a small thing to set beside the fall of a fortress, traveller. It preserves the name of someone whose help made that fall possible." },
        { side = "Horde", aside = true, sign = "P. F.", "A girl of a Lordaeron household did more for the orcs than the whole of its Alliance. Her name belongs in more histories than this one." },
      },
    },
    ["hillsbrad-foothills"] = {
      title = "Hillsbrad Foothills", kind = "place", chapter = "hillsbrad",
      unlock = { { area = 267 } },
      also = { "southshore", "tarren-mill", "durnholde-keep", "dun-garok", "syndicate", "the-forsaken" },
      text = {
        { "The Hillsbrad Foothills are green, rolling country between the mountains of Alterac and the sea: orchards, farms and pasture, the old town of Hillsbrad and the harbour of Southshore. It was a prosperous corner of Lordaeron, and somehow it is still alive, which in the north is no small thing." },
        { "It is also a battlefield. The Forsaken hold Tarren Mill in the hills, and they raid the farms of Hillsbrad Fields, kill the farmers and burn the crops. The men of Southshore strike back. The Syndicate hold the old fortress of Durnholde, the mages of Dalaran keep the internment camp by Lordamere Lake, and in the east the dwarves of Dun Garok stand watch over the passes. Hillsbrad has more armies than it has harvests." },
      },
    },
    ["southshore"] = {
      title = "Southshore", kind = "place", chapter = "hillsbrad",
      unlock = { { area = 271 } },
      also = { "hillsbrad-foothills", "tarren-mill", "syndicate" },
      text = {
        { "Southshore is a fishing town and harbor on Hillsbrad's coast, with an inn, a town hall and a garrison fighting the Forsaken of Tarren Mill. It remains a stronghold of the living in a country where that distinction matters." },
        { "Kundric Zanden keeps its history, and Stormwind's loremasters send scholars through the town towards Alterac's ruined libraries. I am glad to find records kept in such a place. A traveller can obtain supplies here, but can also learn something of the country those supplies must carry them through." },
        { side = "Horde", aside = true, sign = "P. F.", "Kundric Zanden keeps Southshore's history, and I keep what is left of Lordaeron's. I doubt we would agree on the last chapter." },
      },
    },
    ["tarren-mill"] = {
      title = "Tarren Mill", kind = "place", chapter = "hillsbrad",
      unlock = { { area = 272 } },
      also = { "the-forsaken", "royal-apothecary-society", "southshore", "varimathras" },
      text = {
        { "Millers and farmers once occupied Tarren Mill. The Forsaken now hold it as a southern stronghold, with Deathguard serving a High Executor who answers to Varimathras. Southshore is only a short ride away." },
        { "Darthalia orders raids against Hillsbrad's farms and calls their human inhabitants an infestation. She means to subdue them while the apothecaries finish their new plague. The war between these towns reaches well beyond their guards: the farmers and their crops are named in its orders." },
        { side = "Horde", aside = true, sign = "P. F.", "We are told the apothecaries' new plague is meant for the Scourge. The last plague killed me, and I should like to see that in writing." },
      },
    },
    ["aerie-peak"] = {
      title = "Aerie Peak", kind = "place", chapter = "hinterlands",
      unlock = { { area = 348 } },
      also = { "wildhammer-clan", "falstad-wildhammer", "the-hinterlands" },
      text = {
        { "Aerie Peak is the home of the Wildhammer dwarves, a town of stone halls and gryphon roosts built into a crag on the western edge of the Hinterlands. It has the finest gryphon aviary in the world, and every dwarf of Ironforge who has flown on a gryphon has a Wildhammer to thank for it." },
        { "It is not Ironforge. There are no great forges here, few walls and fewer ceilings. The Wildhammer live in the open air, paint their skin with tattoos and speak to the spirits of the land. An Ironforge dwarf feels a little out of place at Aerie Peak, and is meant to." },
      },
    },
    ["falstad-wildhammer"] = {
      title = "Falstad Wildhammer", kind = "figure", chapter = "hinterlands", portrait = 7005,
      unlock = { { npc = 5635 } },
      also = { "wildhammer-clan", "aerie-peak" },
      text = {
        { "High Thane Falstad Wildhammer rules Aerie Peak among its gryphon roosts. The riders' work reaches far beyond the Hinterlands: when Brohann Caskbelly seeks a pilot lost over the Swamp of Sorrows, he sends adventurers to Falstad for news." },
        { "The Wildhammer govern themselves. Their independence does not erase their history with the Alliance, and Falstad remains a useful contact for those seeking its gryphon riders. Do not mistake a shared cause for rule from Ironforge, traveller. His clan has its own thane and its own home." },
      },
    },
    ["jinthaalor"] = {
      title = "Jintha'Alor", kind = "place", chapter = "hinterlands",
      unlock = { { area = 354 } },
      also = { "forest-trolls", "hakkar", "the-hinterlands" },
      text = {
        { "Jintha'Alor is the great temple-city of the Vilebranch trolls in the south of the Hinterlands, a mountain of stepped stone rising out of the forest. At its top, the Vile Priestess Hexx and her priests keep the old rites of the Amani, and some older and worse: they have taken prisoners for sacrifice to Hakkar the Soulflayer, the blood god of the trolls." },
        { "The Atal'ai priests who once served Hakkar in the south have a reach even here: one of them, a priest sentenced by his own people to exile, lives among the trolls of the Hinterlands. The Vilebranch, I gather, were not sorry to have him." },
      },
    },
    ["queldanil-lodge"] = {
      title = "Quel'Danil Lodge", kind = "place", chapter = "hinterlands",
      unlock = { { area = 350 } },
      also = { "wildhammer-clan", "revantusk-village", "forest-trolls" },
      text = {
        { "Quel'Danil Lodge is the Highvale elves' home in the Hinterlands, well south of Quel'Thalas. Its rangers hunt the hills, oppose the forest trolls and keep company with the Wildhammer. Their alliance with the dwarves is part of a much older quarrel between the elves and the Amani." },
        { "Their homeland lies beyond the Plaguelands, devastated by the Scourge. Here the lodge remains a place of communication, with ambassadors seeking relations among other peoples." },
      },
    },
    ["revantusk-village"] = {
      title = "Revantusk Village", kind = "place", chapter = "hinterlands",
      unlock = { { area = 3317 } },
      also = { "forest-trolls", "jinthaalor", "queldanil-lodge" },
      text = {
        { "The Revantusk hold a village on the Hinterlands' eastern coast. They are forest trolls allied with the Horde, a small tribe pressed by larger neighbours. The Vilebranch took their elder for sacrifice, and the Wildhammer's friendship with the high elves gives them another quarrel close at hand." },
        { "The Amani and the elves of Quel'Thalas have been enemies since the elves settled these lands. That older hostility lives on among the Revantusk." },
      },
    },
    ["shadra"] = {
      title = "Shadra", kind = "figure", chapter = "hinterlands", portrait = 7536,
      unlock = { { kill = 2707 }, { quest = 2937 } },
      also = { "forest-trolls", "royal-apothecary-society", "the-hinterlands" },
      text = {
        { "Shadra is a spider god of the trolls, a loa of venom and webs, and the Witherbark worship her at the altar of Shadra'Alor in the Hinterlands. She is not an idol. Read the right words at her altar, and she comes, as large as a house." },
        { "The Witherbark keep bottles of her venom in their villages, and the Forsaken apothecaries of Tarren Mill want it very badly, which tells you what they mean to do with it. I would rather Shadra kept her venom." },
      },
    },
    ["the-hinterlands"] = {
      title = "The Hinterlands", kind = "place", chapter = "hinterlands",
      unlock = { { area = 47 } },
      also = { "aerie-peak", "wildhammer-clan", "jinthaalor", "forest-trolls" },
      text = {
        { "North of Arathi lie the Hinterlands: high green hills, deep valleys, waterfalls and old forest, wild country that no king has ever really ruled. The Wildhammer dwarves live here, at Aerie Peak, with their gryphons. So do the forest trolls of the old Amani empire, whose ruined temples crown half the hills, and whose living tribes still hold the rest." },
        { "It is a beautiful, dangerous country. Owlbeasts in the woods, oozes in the swamps, Witherbark and Vilebranch trolls in the ruins, and on top of the great temple of Jintha'Alor, priests who still sacrifice to the blood god. The gryphon riders of Aerie Peak keep an eye on all of it from the air." },
      },
    },
    ["wildhammer-clan"] = {
      title = "The Wildhammer Clan", kind = "faction", chapter = "hinterlands", portrait = 7859,
      unlock = { { area = 348 }, { faction = 471, standing = 5 } },
      also = { "aerie-peak", "falstad-wildhammer", "war-of-the-three-hammers", "grim-batol" },
      text = {
        { "The Wildhammer were one of the three hammers of the old kingdom of Khaz Modan, and after the war that split the three, they made their home in Grim Batol. When the Dark Iron queen Modgud died there, her death left a darkness in the stone, so the Wildhammer left it and went north to the Hinterlands, and have lived there in the open ever since, riding gryphons and keeping the old ways of the spirits." },
        { "They are proud, fierce, very independent, and they think we of Ironforge have spent too long underground. In the Second War their gryphon riders fought for the Alliance and were the terror of the Horde's dragons. They keep their own counsel now, and their own friends: the high elves of Quel'Danil among them, which the trolls of the Hinterlands resent." },
      },
    },
    ["algaz"] = {
      title = "Algaz", kind = "place", chapter = "loch-modan",
      unlock = { { area = 925 }, { area = 145 }, { area = 837 }, { area = 836 } },
      also = { "loch-modan", "wetlands" },
      text = {
        { "The road north out of Loch Modan runs through Dun Algaz, a narrow pass cut through the mountains to the Wetlands, and it is guarded at both ends." },
        { "On our side, the mountaineers of Algaz Station watch the road and the hills around it. Troggs come up in the pass more often than anyone likes, and the Wetlands beyond are no friend to dwarves since the Dark Irons came." },
        { "When you walk through the pass, look at the stone. It has been worked by dwarven hands for a very long time." },
      },
    },
    ["farstrider-lodge"] = {
      title = "The Farstrider Lodge", kind = "place", chapter = "loch-modan",
      unlock = { { area = 147 } },
      also = { "loch-modan" },
      text = {
        { "Hunters gather at the Farstrider Lodge in south-eastern Loch Modan. Marek Ironheart trades in crocolisk meat and skins, while Daryl the Young offers challenges to anyone willing to test their skill. There is ample work here for a bow, and no shortage of conversation about who handles one best." },
        { "Vyrin Swiftwind proposes a different test. She wants Ol' Sooty killed as part of a scheme to expose Daryl's boasting. You may learn something about hunting at the lodge, traveller, but you will learn a good deal about hunters too." },
      },
    },
    ["ironbands-excavation-site"] = {
      title = "Ironband's Excavation Site", kind = "place", chapter = "loch-modan",
      unlock = { { area = 142 } },
      also = { "explorers-league", "rockjaw-troggs" },
      text = {
        { "One of the League's digs, in the hills of southern Loch Modan, led by Prospector Ironband. What the prospector hoped to find down there I will keep to myself. What he found were troggs." },
        { "The Stonesplinter came up through the workings in numbers, and the site is now more battlefield than dig. The prospector has not given up, being a dwarf and a member of the League, but he would be very glad of help." },
        { "This is what the League means when it says digging is dangerous work. The earth is full of things that would rather stay buried, and some that would rather not." },
      },
    },
    ["loch-modan"] = {
      title = "Loch Modan", kind = "place", chapter = "loch-modan",
      unlock = { { area = 38 } },
      also = { "stonewrought-dam", "thelsamar", "gates-of-ironforge" },
      text = {
        { "East of the gates lies the gentlest country in Khaz Modan: green hills, pine woods and a long blue loch, all held in place by the great dam at its northern end." },
        { "It is farming and hunting land, and the dwarves who live here are a little slower to anger and a great deal quicker to offer you a drink than their cousins in Ironforge. They need the good humour. Troggs dig in the southern valleys, ogres hold the north-east, and the Dark Irons have been seen in the hills." },
        { "Rest in Thelsamar, look at the dam, and visit the Valley of Kings. Then mind your step." },
      },
    },
    ["mogrosh-ogres"] = {
      title = "The Mo'grosh Ogres", kind = "faction", chapter = "loch-modan", portrait = 1122,
      unlock = { { kill = 1178 }, { kill = 1179 }, { kill = 1180 }, { kill = 1181 }, { kill = 1183 }, { area = 143 } },
      also = { "loch-modan", "ogres" },
      text = {
        { "In the north-east of Loch Modan, the Mo'grosh ogres have made a stronghold of their own and dare anyone to come and take it." },
        { "Ogres are huge, brutal and much cleverer than dwarves like to admit. Their shamans and mystics in particular are not to be taken lightly. The Mo'grosh raid the farms and roads of the loch when they please, and so far no one has had the strength to stop them for good." },
        { "Do not go into their stronghold alone, traveller. Do not go in at all, if you can avoid it." },
      },
    },
    ["stonewrought-dam"] = {
      title = "The Stonewrought Dam", kind = "place", chapter = "loch-modan",
      unlock = { { area = 146 }, { area = 556 } },
      also = { "loch-modan", "dark-iron-dwarves" },
      text = {
        { "The Stonewrought Dam holds the northern end of the Loch. Its wall and waterfall are among the great sights of Khaz Modan. Take time to admire them, traveller. A great deal of work went into giving you that view." },
        { "Chief Engineer Hinderweir has found a Dark Iron plot against the dam. His investigation leads to an explosive keg and the mixture needed to disarm it. The dwarves guard this work closely, with good reason. People depend on the wall holding, and Hinderweir has rather more at stake than an engineer's pride." },
      },
    },
    ["thelsamar"] = {
      title = "Thelsamar", kind = "place", chapter = "loch-modan",
      unlock = { { area = 144 } },
      also = { "loch-modan" },
      text = {
        { "Thelsamar is the heart of Loch Modan: a village of stone houses on the road between Ironforge and the Wetlands, with a forge, a good inn and a gryphon master for those in a hurry." },
        { "It is the kind of place where everyone knows everyone and the news travels faster than the gryphons. Ask at the inn about anything happening in the loch country and you will hear it three times, each version better than the last." },
        { "The mountaineers here are stretched thin. If you have a strong arm and a free afternoon, they will find you something to do." },
      },
    },
    ["valley-of-kings"] = {
      title = "The Valley of Kings", kind = "place", chapter = "loch-modan",
      unlock = { { area = 924 } },
      also = { "loch-modan", "war-of-the-three-hammers" },
      text = {
        { "In the south-west of Loch Modan, two great kings of stone stand watch: Madoran Bronzebeard and Khardros Wildhammer, who led their clans in the War of the Three Hammers." },
        { "Their sons raised these statues after their deaths, to honour them and to warn whoever came up that road that the dwarven kingdoms would not be taken. The Dark Irons were to the south then, as they are now. The message has not changed." },
        { "Stop and look up, traveller. Bronzebeard and Wildhammer stand side by side here, as they rarely have anywhere since." },
      },
    },
    ["keeper-remulos"] = {
      title = "Keeper Remulos", kind = "figure", chapter = "moonglade", portrait = 11906,
      unlock = { { npc = 11832 }, { area = 2362 } },
      also = { "moonglade", "cenarion-circle", "dragons-of-nightmare", "eranikus", "tyrande-whisperwind" },
      text = {
        { "Keeper Remulos is Cenarius's son, with his father's stag-like lower body. Druids come to his shrine in Moonglade for aid. The Nightmare spreading through the Emerald Dream has given them urgent reason to seek it." },
        { "When Eranikus, Ysera's consort, was summoned here, the Nightmare came with him. Remulos defended Nighthaven while his allies fought to free the dragon. Tyrande arrived to redeem Eranikus. A traveller may know Moonglade as a place of peace. Its keeper has had to fight for that peace at the heart of the village." },
      },
    },
    ["malfurion-stormrage"] = {
      title = "Malfurion Stormrage", kind = "figure", chapter = "moonglade",
      unlock = { { area = 2363 }, { npc = 11832 } },
      also = { "stormrage-barrow-dens", "cenarius", "tyrande-whisperwind", "illidan-stormrage", "the-emerald-dream", "druids", "the-battle-of-mount-hyjal" },
      text = {
        { "Malfurion Stormrage was a young scholar of the night elves when the Highborne began to change, and he was among the first to suspect why. When the Burning Legion came through the Well of Eternity, he went with his brother Illidan and the priestess Tyrande to find Cenarius, who became his teacher. What Cenarius taught him became druidism. At the end of the War of the Ancients it was Malfurion who saw that the Well itself had to be destroyed, and the Sundering followed." },
        { "He led the survivors to Mount Hyjal, found that Illidan had made a new Well there, and sealed his own brother in a barrow beneath the earth. He forbade his people magic, made the pact of the World Tree with the dragons, and went to sleep in the Emerald Dream for centuries at a time, leaving Tyrande to keep the watch." },
        { "Tyrande woke him when the Legion returned, and he destroyed Archimonde at the foot of the Tree. He is lost in the Dream again now, and the druids who sleep in these barrow dens do not say when he will come back. His people are learning to grow old without him." },
      },
    },
    ["moonglade"] = {
      title = "Moonglade", kind = "place", chapter = "moonglade",
      unlock = { { area = 493 }, { area = 2361 } },
      also = { "cenarion-circle", "keeper-remulos", "stormrage-barrow-dens", "felwood", "winterspring" },
      text = {
        { "Moonglade is a hidden valley in the mountains of northern Kalimdor, between Felwood and Winterspring, around Lake Elune'ara. It is the most sacred place of the druids, night elf and tauren alike, and the Cenarion Circle has its home in the village of Nighthaven, on the lake's shore. It is a place of peace, open to Alliance and Horde alike." },
        { "Druids come here to learn, and the Circle's scholars keep their archives here. At the Lunar Festival, the whole world comes to honour the elders and the moon." },
      },
    },
    ["stormrage-barrow-dens"] = {
      title = "The Stormrage Barrow Dens", kind = "place", chapter = "moonglade",
      unlock = { { area = 2363 } },
      also = { "moonglade", "keeper-remulos", "dragons-of-nightmare", "tyrande-whisperwind" },
      text = {
        { "Druids sleep beneath Moonglade's hills while their spirits walk the Emerald Dream, sometimes for years. These barrow dens bear Malfurion Stormrage's name, recalling the first druid and the long practice of his followers." },
        { "During the Third War, Tyrande called sleeping druids back to face the Legion. Malfurion is now missing, his fate unknown to the druids. With the Nightmare spreading, the keepers of the dens and Remulos have reason to fear for those within the Dream. Tread carefully here, traveller. The stillness above the sleeping druids tells little of what their spirits may be facing." },
      },
    },
    ["the-emerald-dream"] = {
      title = "The Emerald Dream", kind = "history", chapter = "moonglade",
      unlock = { { area = 2362 }, { npc = 11832 }, { quest = 8447 }, { read = { "The World Tree and the Emerald Dream", "세계수와 에메랄드의 꿈", "L'Arbre monde et le Rêve d'émeraude", "Der Weltbaum und der Smaragdgrüne Traum", "世界之树和翡翠梦境", "El Árbol del Mundo y el Sueño Esmeralda", "Древо Жизни и Изумрудный сон", "A Árvore do Mundo e o Sonho Esmeralda", "世界之樹和翡翠夢境" } } },
      also = { "stormrage-barrow-dens", "keeper-remulos", "green-dragonflight", "dragons-of-nightmare", "druids", "malfurion-stormrage" },
      text = {
        { "The Emerald Dream is a spirit world outside the waking one, ever-changing and vast, from which Ysera the Dreamer guides the growth of every wild thing. The druids walk it because of a bargain struck long ago, after the Sundering, when the night elves planted a World Tree on Mount Hyjal." },
        { "Three dragons blessed that tree. Alexstrasza set the acorn in the waters of the new Well of Eternity. Nozdormu promised that while it stood, the night elves would never grow old or fall sick. Ysera bound it to her Dream. The price was the druids' sleep. Malfurion and his followers agreed to pass centuries at a time in hibernation, their spirits roaming the Dreamways, and they kept the bargain." },
        { "That is why the barrow dens of the Moonglade are full of sleepers, and why a druid who has walked the Dream may wake with the look of a traveller back from very far away. Lately they have woken troubled. Something dark has come into the Dream, and Remulos, who keeps the Moonglade, does not say what." },
      },
    },
    ["bloodhoof-village"] = {
      title = "Bloodhoof Village", kind = "place", chapter = "mulgore",
      unlock = { { area = 222 } },
      also = { "earth-mother", "cairne-bloodhoof", "mulgore" },
      text = {
        { "Bloodhoof Village is the heart of the plains, a town of longhouses and kodo pens on the road between Camp Narache and Thunder Bluff. Its chief is Baine Bloodhoof, son of the High Chieftain Cairne, and it is here that the young take the second of the Rites, the Rite of Vision: they drink the Water of the Seers before the village fire and follow where the vision leads." },
        { "It is a busy, friendly, practical place. The tauren of Bloodhoof are farmers and herders as much as hunters, and they will feed a stranger before they ask his business." },
      },
    },
    ["cairne-bloodhoof"] = {
      title = "Cairne Bloodhoof", kind = "figure", chapter = "mulgore", portrait = 4307,
      unlock = { { npc = 3057 } },
      also = { "thunder-bluff", "thrall", "centaurs", "grimtotem" },
      text = {
        { "Cairne Bloodhoof is the High Chieftain of the tauren, chief of the Bloodhoof tribe, and the oldest friend the Horde has on Kalimdor. When Thrall's orcs came ashore he was leading his people across the plains with the centaur at their heels, and the orcs fought beside them. Cairne repaid them with friendship and with counsel, and the tauren have been part of the Horde ever since." },
        { "He is very old now, and very large, and he speaks slowly and seldom. He built Thunder Bluff, gathered the tribes to it, and gave the tauren a home for the first time in their memory. His son Baine keeps Bloodhoof Village, and once, they say, was taken by the centaur, and returned by a beast-master of the Horde." },
        { "The orcs revere him and the Alliance trusts him further than any other leader of the Horde. Both, I think, are right." },
      },
    },
    ["camp-narache"] = {
      title = "Camp Narache", kind = "place", chapter = "mulgore",
      unlock = { { area = 221 } },
      also = { "earth-mother", "mulgore" },
      text = {
        { "Camp Narache sits on Red Cloud Mesa in the south of Mulgore, a ring of hide tents and totems around a fire, and it is where young tauren begin. Chief Hawkwind and his family keep the camp, and they set the young the first of the Rites of the Earth Mother: the Rite of Strength, proven against the quilboar who have crept into the ravine below." },
        { "It is a hunting camp first. The tauren hunt for need and for pleasure, and a young tauren is expected to bring back feathers and meat before anyone asks what else they can do." },
      },
    },
    ["earth-mother"] = {
      title = "The Earth Mother", kind = "history", chapter = "mulgore",
      unlock = { { quest = 776 }, { area = 1640 } },
      also = { "camp-narache", "bloodhoof-village", "red-rocks", "thunder-bluff" },
      text = {
        { "The tauren revere the Earth Mother as the source of the world and its life. Their traditions teach respect for the land's gifts and care against waste. Shamans speak with its spirits, seers follow visions, and the ancestors remain part of the lives of those who come after them." },
        { "Young tauren undertake the Rites of the Earth Mother before the elders of Thunder Bluff accept them. Strength is proved against the tribe's enemies. Vision comes through the Water of the Seers and what appears in the fire. Wisdom requires the ancestors' blessing at Red Rocks. The journey ends before the High Chieftain." },
        { "Attend to the rites if you wish to understand your hosts, traveller. Hunting, memory and the land are joined in the way a young tauren earns a place among them." },
      },
    },
    ["ghost-howl"] = {
      title = "Ghost Howl", kind = "creature", chapter = "mulgore", portrait = 720,
      unlock = { { quest = 770 } },
      also = { "mulgore", "burning-legion", "bloodhoof-village" },
      text = {
        { "Ghost Howl is a great wolf of Mulgore whose hide bears a terrible wound from fighting the Burning Legion. The scar gives the hunter's trophy a history beyond the chase across the plains." },
        { "Skorn Whitecloud recognises the hide at Bloodhoof Village. He offers the hunter one of his weapons and hopes the wolf's spirit has found peace." },
      },
    },
    ["hamuul-runetotem"] = {
      title = "Arch Druid Hamuul Runetotem", kind = "figure", chapter = "mulgore", portrait = 4519,
      unlock = { { npc = 5769 } },
      also = { "cairne-bloodhoof", "cenarion-circle", "thunder-bluff" },
      text = {
        { "Arch Druid Hamuul Runetotem stands on Thunder Bluff's Elder Rise, among the tauren's teachers and spiritual leaders. His place there gives the druids a voice in the city as well as a home." },
        { "Reports from the Wailing Caverns bring adventurers to him from beyond Mulgore. He sends them to Nara Wildmane to continue the enquiry." },
      },
    },
    ["mulgore"] = {
      title = "Mulgore", kind = "place", chapter = "mulgore",
      unlock = { { area = 215 } },
      also = { "thunder-bluff", "cairne-bloodhoof", "bloodhoof-village", "venture-company", "quilboar" },
      text = {
        { "After the red dust of Durotar and the yellow grass of the Barrens, Mulgore comes as a surprise: rolling green plains, clear lakes and streams, herds of kodo and plainstrider, and great flat-topped mesas standing up out of the grass. It is the homeland of the tauren, and they hold it, for the first time in their long history, as their own." },
        { "For generations the tauren wandered the plains of Kalimdor, harried by the centaur wherever they went. When the orcs came to Kalimdor, Thrall helped Cairne Bloodhoof's people drive the centaur back and take these grasslands, and the tribes have gathered here since. Even so, Mulgore is not untroubled: the Bristleback quilboar raid from the ravines, the Palemane gnolls hunt its beasts, and the goblins of the Venture Company have dug a mine into its cliffs and fouled its water wells against the tauren's express refusal." },
      },
    },
    ["red-rocks"] = {
      title = "Red Rocks", kind = "place", chapter = "mulgore",
      unlock = { { area = 225 } },
      also = { "earth-mother", "thunder-bluff", "quilboar" },
      text = {
        { "East of Thunder Bluff, among great red stones, lies the sacred burial ground of the tauren. Only the most valiant are laid to rest at Red Rocks: the warriors who helped found and defend Thunder Bluff, and those who gave their lives for their tribes and chieftains. The ancestral spirits are said to walk there still." },
        { "The young come here for the last of the Rites, the Rite of Wisdom, to receive the blessing of those ancestors. Lately the quilboar have been digging in the graves, and the old lorekeeper who tends them is past fighting them off. If you want to make a friend of every tauren in Mulgore, there is no quicker way." },
      },
    },
    ["thunder-bluff"] = {
      title = "Thunder Bluff", kind = "place", chapter = "mulgore",
      unlock = { { area = 1638 } },
      also = { "cairne-bloodhoof", "hamuul-runetotem", "mulgore", "grimtotem" },
      text = {
        { "Thunder Bluff stands high on Mulgore's mesas, reached by great lifts or a wind rider. Rope bridges join its rises. An Ironforge dwarf accustomed to solid floors may want to look where he puts his feet before looking at the view." },
        { "Cairne built this refuge after the tauren and orcs drove back the centaur. Tribes long accustomed to wandering gathered here. Traders and artisans now share it with hunters, Elder Rise's druids, and the shamans and seers of Spirit Rise." },
        { "Cairne remains High Chieftain at its centre. The Grimtotem are among those who oppose his leadership. A traveller sees a people with a city at last, though a permanent home has not ended the disagreements among its tribes." },
      },
    },
    ["ancients"] = {
      title = "The Ancients", kind = "creature", chapter = "peoples", portrait = 2429,
      unlock = { { npc = 2041 }, { npc = 3468 }, { npc = 3469 }, { npc = 3616 }, { npc = 9598 }, { npc = 11491 }, { npc = 13419 }, { npc = 14241 }, { kill = 11459 }, { kill = 11489 }, { area = 448 } },
      also = { "onu", "cenarius", "night-elves", "darnassus", "the-battle-of-mount-hyjal" },
      text = {
        { "The ancients are the oldest trees of the night elves' forests, grown wise enough to think and strong enough to walk. In the War of the Ancients, Cenarius called them up from the enchanted woods and led them against the Burning Legion, an army of tree-men marching on the queen's own city. In the Third War they marched again." },
        { "They still keep watch. Ancient protectors stand guard on Teldrassil, an Ancient of Lore and an Ancient of War keep their place in Darnassus, and Onu, another Ancient of Lore, speaks for the forest at the Grove of the Ancients in Darkshore." },
        { "They are slow to speak and slower to change their minds. A people who planted their capital in a tree, I suppose, learns to listen to trees." },
      },
    },
    ["argent-dawn"] = {
      title = "The Argent Dawn", kind = "faction", chapter = "peoples", portrait = 10211,
      unlock = { { npc = 10839 }, { npc = 10856 }, { npc = 10840 }, { npc = 10857 }, { npc = 11034 }, { npc = 11039 }, { faction = 529, standing = 5 } },
      also = { "scourge", "scarlet-crusade", "the-bulwark" },
      text = {
        { "The Argent Dawn recruits against the Scourge from both Alliance and Horde. Its knights, priests and scholars ask what a traveller is prepared to fight, rather than which banner they follow. Lord Maxwell Tyrosus leads it from Light's Hope Chapel in the Eastern Plaguelands." },
        { "Officers at Chillwind Camp and the Bulwark issue commissions and accept the scourgestones carried by the dead. Envoys work in Stormwind, Darnassus and Everlook. The Dawn has made its war a cause people of either faction can join." },
        { "It shares an enemy with the Scarlet Crusade and little affection for its methods. The Dawn regards the Crusade's suspicion of every stranger as aid to the Lich King. There is practical sense in that objection: the fight already has enemies enough." },
      },
    },
    ["black-dragonflight"] = {
      title = "The Black Dragonflight", kind = "creature", chapter = "peoples", portrait = 6374,
      unlock = { { kill = 441 }, { kill = 2725 }, { kill = 4323 }, { kill = 4324 }, { kill = 7040 }, { kill = 7041 }, { kill = 7042 }, { kill = 7043 }, { kill = 7044 }, { kill = 7045 }, { kill = 7046 }, { kill = 7047 }, { kill = 7048 }, { kill = 7049 }, { kill = 9096 }, { kill = 9461 }, { kill = 10083 }, { kill = 10366 }, { kill = 10371 }, { kill = 10372 }, { kill = 11262 }, { kill = 12129 }, { kill = 12260 }, { kill = 12422 }, { kill = 12460 }, { kill = 12463 }, { kill = 12464 }, { kill = 12465 }, { kill = 12467 }, { kill = 12468 }, { kill = 14388 } },
      also = { "red-dragonflight", "blackrock-clan", "great-masquerade", "katrana-prestor" },
      text = {
        { "Neltharion was the Earth-Warder, charged with the world's deep places. His betrayal of the other dragonflights gave him the name Deathwing. After the Second War he entered the councils of human kings as Lord Prestor, hiding a dragon behind a nobleman's face. He escaped the Aspects after the struggle at Grim Batol. Where he has withdrawn remains unknown." },
        { "His children occupy places we can name. Onyxia keeps her brood in Dustwallow Marsh. Nefarian holds Blackrock Spire, commands its orcs and breeds chromatic dragons above them. Black whelps inhabit Redridge and the Badlands, while dragonspawn guard the flight's greater holdings." },
        { "The lairs are formidable enough. Lord Prestor showed what a black dragon could accomplish with a seat at a council table." },
      },
    },
    ["blackrock-clan"] = {
      title = "The Blackrock Clan", kind = "faction", chapter = "peoples", portrait = 6044,
      unlock = { { kill = 334 }, { kill = 435 }, { kill = 436 }, { kill = 437 }, { kill = 440 }, { kill = 485 }, { kill = 486 }, { kill = 615 }, { kill = 4064 }, { kill = 4065 }, { kill = 4462 }, { kill = 4463 }, { kill = 4464 }, { kill = 7025 }, { kill = 7026 }, { kill = 7027 }, { kill = 7028 }, { kill = 7029 }, { kill = 9237 }, { kill = 9522 }, { kill = 9583 }, { kill = 9605 }, { kill = 9693 }, { kill = 9716 }, { kill = 9717 }, { kill = 9817 }, { kill = 9818 }, { kill = 9819 }, { kill = 10316 }, { kill = 10317 }, { kill = 10319 }, { kill = 10429 }, { kill = 10742 }, { kill = 10762 } },
      also = { "black-dragonflight", "eitrigg" },
      text = {
        { "The Blackrock were the greatest clan of the old Horde. Their chieftain Blackhand led it as Warchief in the First War, until Orgrim Doomhammer broke his skull and took the title, and Doomhammer was a Blackrock too. When the Horde fell, most of the clan went into the camps with everyone else, and many of those who came out followed Thrall." },
        { "Not all of them. Blackhand's sons, Rend and Maim, gathered survivors inside Blackrock Mountain. Rend's followers still keep the old ways: the conquest, the cruelty and the cult of the Warchief. Rend calls himself Warchief to this day, and gives Thrall's name nothing but contempt. Worse, he has thrown in with the black dragons who roost in the upper Spire." },
        { "From the mountain the clan raids north and west. They hold the Burning Steppes, they have taken Stonewatch Keep in Redridge, and the people of Lakeshire live within sight of their fires. Whatever the Horde has become in Durotar, this is what it was." },
      },
    },
    ["blood-elves"] = {
      title = "The Blood Elves", kind = "faction", chapter = "peoples", portrait = 7923,
      unlock = { { npc = 4198 }, { npc = 7505 }, { npc = 7506 }, { npc = 7826 }, { npc = 8395 }, { npc = 9836 }, { npc = 14387 }, { kill = 6198 }, { kill = 6199 }, { kill = 8578 }, { kill = 8581 }, { kill = 14327 }, { area = 1220 }, { read = { "Rise of the Blood Elves", "블러드 엘프의 등장", "La montée des elfes de sang", "Aufstieg der Blutelfen", "血精灵的崛起", "El levantamiento de los elfos de sangre", "Возвышение эльфов крови", "A Ascensão dos Elfos Sangrentos", "血精靈的崛起" } } },
      also = { "high-elves", "the-fall-of-quelthalas", "illidan-stormrage", "naga", "satyrs", "azshara" },
      text = {
        { "After Quel'Thalas fell, the last of its royal line, Prince Kael'thas Sunstrider, led what remained of the high elves in the Alliance's struggle against the Scourge. They renamed themselves blood elves in honour of their fallen people. Cut off from the Sunwell that had fed them for thousands of years, they also learned how badly they needed its magic, and they suffered for the lack of it." },
        { "With the Alliance demanding battles his depleted forces could not win alone, Kael'thas accepted help from Lady Vashj and her naga. His commander, Garithos, condemned the blood elves as traitors and sentenced them to death. Vashj freed them from the dungeons of Dalaran and led them to Outland, the broken remnant of the orcs' world. There they freed Illidan Stormrage from his captor, and Kael'thas pledged himself to him in return for the magic his people needed." },
        { "Some of his people are much nearer. Blood elves search the cliffs and ruins of Azshara for the magic the Highborne left behind, and grind what they find into a glittering dust. A goblin who took their coin and an orc warband that lent them guards have both learned what their employment is worth. Another has gone into Dire Maul to bleed its ruins of their power. Gershala Nightwhisper in Auberdine fears they are going the way of the satyrs and the naga. I fear he may be right." },
      },
    },
    ["blue-dragonflight"] = {
      title = "The Blue Dragonflight", kind = "creature", chapter = "peoples", portrait = 6760,
      unlock = { { npc = 6109 }, { npc = 10929 }, { npc = 15481 }, { kill = 193 }, { kill = 6109 }, { kill = 6129 }, { kill = 6130 }, { kill = 6131 }, { kill = 7435 }, { kill = 7436 }, { kill = 7437 }, { kill = 10659 }, { kill = 10660 }, { kill = 10664 } },
      also = { "the-five-aspects", "azuregos", "mazthoril", "black-dragonflight" },
      text = {
        { "Malygos, the Spell-Weaver, was given the care of magic, and his flight has paid for it. When Deathwing turned on the other dragonflights in the War of the Ancients, the blue flight suffered worst. Very few survived, and Malygos has not been the same since." },
        { "Their holds in these lands are few. Blue dragonkin guard the shores of Lake Mennar in Azshara, and the caves of Mazthoril in Winterspring hide a refuge where their matron protectorate, Haleh, receives those who hold a blue dragon's scale and stand upon the right rune. The Aspects, she will tell you, insist that their flights stay out of mortal affairs. She will also tell you that Deathwing's children make that difficult." },
        { "Azuregos keeps his own watch over the ruins of southern Azshara, searching for the arcane treasures the Highborne left behind. The coast has been ruined for ten thousand years, and still gives a blue dragon work to do." },
      },
    },
    ["bronze-dragonflight"] = {
      title = "The Bronze Dragonflight", kind = "faction", chapter = "peoples", portrait = 2719,
      unlock = { { npc = 10667 }, { npc = 15192 }, { npc = 15381 }, { kill = 8196 }, { kill = 8197 }, { kill = 8198 } },
      also = { "the-five-aspects", "caverns-of-time", "the-scepter-of-the-shifting-sands", "darrowshire", "andorhal" },
      text = {
        { "Nozdormu, the Timeless One, was given the keeping of time, and his flight guards its pathways. They are seldom seen. When they are, it is usually because something has gone wrong with when things happen." },
        { "In Andorhal one of them goes about as a strange little gnome called Chromie, and has turned a room of the ruined inn into a place that does not quite belong to the rest of the town. She says the Scourge has been tampering with time there. She hunts the parasites that feed on its broken threads, and she has helped a traveller change the fate of a man who fell at Darrowshire." },
        { "In Tanaris, near the Caverns of Time, waits Anachronos, who was at the Scarab Wall a thousand years ago when it was sealed. The bronze flight remembers the war against Ahn'Qiraj because it fought in it. Ask them what they know of tomorrow, traveller, and they will smile and say that your greatest feats are still to come." },
      },
    },
    ["burning-blade"] = {
      title = "The Burning Blade", kind = "faction", chapter = "peoples", portrait = 4188,
      unlock = { { kill = 3195 }, { kill = 3196 }, { kill = 3197 }, { kill = 3198 }, { kill = 3199 }, { kill = 3204 }, { kill = 3379 }, { kill = 3380 }, { kill = 4663 }, { kill = 4664 }, { kill = 4665 }, { kill = 4666 }, { kill = 4667 }, { kill = 4668 }, { kill = 4705 }, { kill = 5822 }, { kill = 11322 }, { kill = 11323 }, { kill = 11324 }, { kill = 11518 }, { kill = 11519 }, { kill = 12319 }, { kill = 12320 }, { kill = 13019 } },
      also = { "burning-legion", "valley-of-trials", "ragefire-chasm" },
      text = {
        { "The Burning Blade was once an orc clan, famous for its blademasters, and some of those blademasters broke free of the demons and serve Thrall still. The rest of the name has gone to a cult. The Burning Blade of today is a brotherhood of warlocks and fanatics who worship the demons that once enslaved their people, and answer to the Shadow Council that brought the Horde into this world." },
        { "They are the Horde's own shame, hiding in its own lands. They hold the caves of Skull Rock in Durotar, within sight of Orgrimmar, and Dreadmist Peak in the Barrens, where a felguard watches over what they call the Demon Seed, a link to the Legion itself. In Desolace they have taken Thunder Axe Fortress for their own, and in the chasms beneath Orgrimmar itself a branch calling itself the Searing Blade plots in the dark. Thrall's people hunt them wherever they find them." },
        { "They came closer than anyone likes to admit to starting a new war. A few years after Mount Hyjal, a minor demon named Zmodlor took the cult in hand and set Durotar and Theramore against each other: ships attacked, raids blamed on the other side, a traitor whispering in each leader's council, Lady Jaina Proudmoore's own chamberlain among them. Jaina and Thrall uncovered it together, and the peace held. The cult was not finished, as Skull Rock will tell you." },
      },
    },
    ["burning-legion"] = {
      title = "The Burning Legion", kind = "faction", chapter = "peoples", portrait = 5049,
      unlock = { { kill = 89 }, { kill = 3102 }, { kill = 3772 }, { kill = 3774 }, { kill = 4676 }, { kill = 4677 }, { kill = 4678 }, { kill = 4679 }, { kill = 4680 }, { kill = 4681 }, { kill = 4682 }, { kill = 4684 }, { kill = 4685 }, { kill = 5760 }, { kill = 6010 }, { kill = 6011 }, { kill = 6071 }, { kill = 6072 }, { kill = 6073 }, { kill = 6115 }, { kill = 7125 }, { kill = 7126 }, { kill = 7135 }, { kill = 7136 }, { kill = 7137 }, { kill = 7461 }, { kill = 7462 }, { kill = 7463 }, { kill = 7664 }, { kill = 7665 }, { kill = 7666 }, { kill = 7667 }, { kill = 7728 }, { kill = 7734 }, { kill = 7735 }, { kill = 8608 }, { kill = 8616 }, { kill = 8675 }, { kill = 8716 }, { kill = 8717 }, { kill = 8718 }, { kill = 9454 }, { kill = 9862 }, { kill = 9877 }, { kill = 10201 }, { kill = 10261 }, { kill = 10263 }, { kill = 10373 }, { kill = 11697 }, { kill = 11859 }, { kill = 12396 }, { kill = 12397 }, { kill = 14101 }, { kill = 14483 }, { kill = 14506 }, { kill = 14668 } },
      also = { "satyrs", "burning-blade" },
      text = {
        { "The Burning Legion is an army of demons, gathered from a thousand conquered worlds by the fallen titan Sargeras, and it has come for ours three times. The first time was ten thousand years ago, through the night elves' Well of Eternity. The second came through the orcs, whom its servants corrupted and sent through the Dark Portal. The third was the last war, when its general Archimonde fell at the foot of the World Tree on Mount Hyjal." },
        { "It has never entirely left. Lord Kazzak holds the Blasted Lands with a host of demons around the dormant Dark Portal. The Shadow Council's warlocks keep demons in Jaedenar, in Felwood, where the whole forest has rotted around them. Doomguard and infernals walk Ashenvale's Demon Fall Canyon, where Grom Hellscream killed Mannoroth, and Desolace's Mannoroc Coven, and the ruins of Azshara." },
        { "The Legion is patient. It has lost three wars and is still here, and I do not believe it has finished with us." },
      },
    },
    ["cenarion-circle"] = {
      title = "The Cenarion Circle", kind = "faction", chapter = "peoples", portrait = 11906,
      unlock = { { npc = 11832 }, { npc = 5769 }, { faction = 609, standing = 5 } },
      also = { "silithid", "dragons-of-nightmare", "hamuul-runetotem", "fandral-staghelm" },
      text = {
        { "The Cenarion Circle is the fellowship of the druids, named for the demigod Cenarius who taught the first of them. Its founder was Malfurion Stormrage, who led the night elves against the Burning Legion ten thousand years ago and is now missing. His fellow druids do not know what became of him. For most of its history the Circle was a night elf order. Now the tauren have their druids in it too, and Arch Druid Hamuul Runetotem represents them in Thunder Bluff." },
        { "Its seat is Nighthaven, in the Moonglade, under Keeper Remulos, son of Cenarius, and both the Alliance and the Horde may walk there in peace. It keeps posts wherever nature is wounded: at Stonetalon Peak, in the poisoned woods of Felwood, and at Cenarion Hold in Silithus, from which it watches the insect hives and the walls of Ahn'Qiraj." },
        { "The druids are patient beyond any dwarf's understanding, and they think in seasons and centuries. When the Circle says that something is wrong, the wise listen." },
      },
    },
    ["cenarius"] = {
      title = "Cenarius", kind = "figure", chapter = "peoples", portrait = 11906,
      unlock = { { npc = 4273 }, { npc = 3994 }, { npc = 4057 }, { npc = 4053 }, { npc = 11832 }, { read = { "The White Stag and the Moon", "흰 순록과 달", "Le Cerf blanc et la Lune", "Der weiße Hirsch und der Mond", "白鹿和月神", "El ciervo blanco y la Luna", "Белый Олень и Луна", "O Cervo Branco e a Lua" } }, { read = { "Forestlord and the first Druids", "숲의 군주와 첫번째 드루이드", "Le Seigneur des forêts et les premiers druides", "Waldlord und die ersten Druiden", "森林之王和最初的德鲁伊", "El Señor del Bosque y los primeros druidas", "Владыка лесов и первые друиды", "Senhor da Floresta e os Primeiros Druidas", "森林之王和最初的德魯伊" } } },
      also = { "keeper-remulos", "cenarion-circle", "demon-fall-canyon", "malfurion-stormrage", "druids", "sentinels" },
      text = {
        { "Cenarius was the lord of the forests, a demigod with a stag's body below the waist and branching antlers, and the night elves' first teacher. Long before the Sundering he grew fond of their curious young people and taught them the ways of the living world. Malfurion Stormrage was his greatest pupil, and druidism is what they made between them." },
        { "He fought the Legion in the War of the Ancients, leading the ancients of the forest against the demons, survived the Sundering, and helped Malfurion seal Illidan away. Afterwards he stayed in the Moonglade on Mount Hyjal. His sons, the Keepers of the Grove, watched over the night elves while the druids slept, and his daughters, the dryads, grew bolder about being seen." },
        { "In the Third War he came out of the forest to drive Grom Hellscream's orcs from Ashenvale, and the orcs, mad with demon blood, killed him. His children still walk the woods of Kalimdor, from Raynewood to Stonetalon, and Remulos keeps the Moonglade in his name. A keeper's memory is long. I would not raise the subject of orcs with one." },
      },
    },
    ["centaurs"] = {
      title = "The Centaurs", kind = "faction", chapter = "peoples", portrait = 9410,
      unlock = { { kill = 2967 }, { kill = 2968 }, { kill = 3119 }, { kill = 3120 }, { kill = 3272 }, { kill = 3273 }, { kill = 3274 }, { kill = 3275 }, { kill = 3394 }, { kill = 3395 }, { kill = 3396 }, { kill = 3397 }, { kill = 4093 }, { kill = 4094 }, { kill = 4095 }, { kill = 4096 }, { kill = 4097 }, { kill = 4099 }, { kill = 4632 }, { kill = 4633 }, { kill = 4634 }, { kill = 4635 }, { kill = 4636 }, { kill = 4637 }, { kill = 4638 }, { kill = 4639 }, { kill = 4640 }, { kill = 4641 }, { kill = 4642 }, { kill = 4643 }, { kill = 4644 }, { kill = 4645 }, { kill = 4646 }, { kill = 4647 }, { kill = 4648 }, { kill = 4649 }, { kill = 4651 }, { kill = 4652 }, { kill = 4653 }, { kill = 4654 }, { kill = 4655 }, { kill = 4656 }, { kill = 4657 }, { kill = 4658 }, { kill = 4659 }, { kill = 4661 }, { kill = 5402 }, { kill = 5600 }, { kill = 5601 }, { kill = 5602 }, { kill = 5808 }, { kill = 6069 }, { kill = 6070 }, { kill = 7404 }, { kill = 9523 }, { kill = 9524 }, { kill = 10617 }, { kill = 10720 }, { kill = 11685 }, { kill = 11688 }, { kill = 12976 }, { kill = 12977 }, { read = { "Hatred of the Centaur", "켄타우로스의 증오", "Haine du centaure", "Hass der Zentauren", "半人马的仇恨", "Odio del Centauro", "Ненависть Кентавра", "O Ódio do Centauro", "半人馬的仇恨" } } },
      also = { "cairne-bloodhoof" },
      text = {
        { "The centaurs descend from Zaetar, a son of Cenarius, and Theradras, a princess of elemental earth. They killed their father. Their mother buried him in Maraudon. His children still guard the tomb as sacred ground." },
        { "Their clans include the Kolkar of the Barrens and Desolace, the rival Gelkis and Magram, the Galak of Thousand Needles and the Maraudine at the tomb. For generations they pursued the tauren across Kalimdor's plains, until Cairne and his orc allies drove them back." },
        { "The clans continue to raid. Learn their names as well as the sound of their hooves, traveller. The quarrels between them matter to those trying to live within reach of their camps." },
      },
    },
    ["cult-of-the-damned"] = {
      title = "The Cult of the Damned", kind = "faction", chapter = "peoples", portrait = 10391,
      unlock = { { kill = 1853 }, { kill = 8546 }, { kill = 8547 }, { kill = 8548 }, { kill = 8550 }, { kill = 8551 }, { kill = 8553 }, { kill = 10398 }, { kill = 10399 }, { kill = 10400 }, { kill = 10469 }, { kill = 10470 }, { kill = 10471 }, { kill = 10472 }, { kill = 10476 }, { kill = 10477 }, { kill = 10827 }, { kill = 11582 } },
      also = { "scourge" },
      text = {
        { "Kel'Thuzad was an archmage of Dalaran and a member of its ruling council, and he went looking for forbidden things in the necromantic arts until something answered: the Lich King. Kel'Thuzad left the Kirin Tor, went among the poor and the desperate of Lordaeron, and promised them a world without kings or hunger. They became the Cult of the Damned, and they believed him." },
        { "The cult's work was the plague. Its people seeded the grain stores of Andorhal and the northern villages, and the dead rose wherever the grain was eaten. Prince Arthas killed Kel'Thuzad at Andorhal, but the Lich King had need of him, and he came back as a lich. The House of Barov handed over its castle at Caer Darrow to the cult, and in its vaults they keep their school of necromancy, the Scholomance." },
        { "They are living men and women, which I find worse than the dead. A ghoul has no choice in what it serves. The necromancers of the cult chose." },
      },
    },
    ["dark-iron-dwarves"] = {
      title = "The Dark Iron Dwarves", kind = "faction", chapter = "peoples", portrait = 825,
      unlock = { { kill = 1051 }, { kill = 1052 }, { kill = 1053 }, { kill = 1054 }, { kill = 1169 }, { kill = 1222 }, { kill = 1981 }, { kill = 2149 }, { kill = 2575 }, { kill = 2577 }, { kill = 2739 }, { kill = 2740 }, { kill = 2742 }, { kill = 2743 }, { kill = 2744 }, { kill = 3180 }, { kill = 4062 }, { kill = 4844 }, { kill = 4845 }, { kill = 4846 }, { kill = 4847 }, { kill = 4848 }, { kill = 4849 }, { kill = 5839 }, { kill = 5840 }, { kill = 5844 }, { kill = 5846 }, { kill = 6123 }, { kill = 6212 }, { kill = 6228 }, { kill = 6523 }, { kill = 7030 }, { kill = 7036 }, { kill = 7037 }, { kill = 7038 }, { kill = 7091 }, { kill = 7290 }, { kill = 8282 }, { kill = 8283 }, { kill = 8337 }, { kill = 8338 }, { kill = 8391 }, { kill = 8504 }, { kill = 8566 }, { kill = 8637 }, { kill = 8889 }, { kill = 8890 }, { kill = 8891 }, { kill = 8892 }, { kill = 8893 }, { kill = 8894 }, { kill = 8895 }, { kill = 8896 }, { kill = 8897 }, { kill = 8898 }, { kill = 8899 }, { kill = 8900 }, { kill = 8901 }, { kill = 8902 }, { kill = 8903 }, { kill = 8904 }, { kill = 8920 }, { kill = 9018 }, { kill = 9024 }, { kill = 9033 }, { kill = 9041 }, { kill = 9056 }, { kill = 9319 }, { kill = 9437 }, { kill = 9438 }, { kill = 9439 }, { kill = 9441 }, { kill = 9442 }, { kill = 9443 }, { kill = 9537 }, { kill = 9956 }, { kill = 14621 }, { kill = 15692 } },
      also = { "war-of-the-three-hammers", "thandol-span", "dun-modr", "stonewrought-dam" },
      text = {
        { "The third of the three hammers, and the one that never forgave. Since the Dark Irons lost their war against Ironforge, and woke Ragnaros in their fury, they have lived in Blackrock Mountain under their emperor, Dagran Thaurissan, serving the Firelord they summoned." },
        { "They have not stayed there. Their slaves dig the Cauldron in the Searing Gorge, their Shadowforge diggers loot the ruins of Uldaman and hold Angor Fortress in the Badlands, their spies creep about Dun Morogh and their raiders trouble Loch Modan. In the Wetlands they have done real harm: they took the fortress of Dun Modr and broke the Thandol Span, the great bridge to the north." },
        { "A Dark Iron fights with fire, black powder and a grudge two centuries deep. Never turn your back on one." },
      },
    },
    ["deathstalkers"] = {
      title = "The Deathstalkers", kind = "faction", chapter = "peoples", portrait = 3540,
      unlock = { { npc = 1950 }, { npc = 1951 }, { npc = 1978 }, { npc = 2058 }, { npc = 2214 }, { npc = 3849 }, { npc = 4444 }, { npc = 5418 }, { npc = 6467 }, { npc = 15022 } },
      also = { "the-forsaken", "varimathras", "sylvanas-windrunner", "silverpine-forest", "shadowfang-keep", "syndicate" },
      text = {
        { "The Deathstalkers are the Forsaken's eyes and knives: Lord Varimathras's elite guard, as one of their recruiters puts it, sent ahead of the Dark Lady's armies to see what waits for them. You meet them wherever the Forsaken are pushing their borders: scouting the farms of northern Silverpine, inside Shadowfang Keep to watch Arugal, on the hills above Hillsbrad, gathering reports from the Plaguelands for Nathanos." },
        { "Joining them is not a matter of asking. Recruits prove their worth, and their discretion, in the Undercity's own back rooms. One such errand found that the Syndicate, the fallen lords of Alterac, had a friend among the city's shopkeepers. With Varimathras's sanction, one of them boasts, their numbers grow." },
        { "They are not all as grim as the name. Rane and Quinn Yorick are brothers, and Rane, with Quinn barely mended from a ghoul's claws, wants their report delivered before anything else. Dead, but still keen. The Forsaken are full of surprises." },
      },
    },
    ["defias-brotherhood"] = {
      title = "The Defias Brotherhood", kind = "faction", chapter = "peoples", portrait = 2357,
      unlock = { { kill = 38 }, { kill = 94 }, { kill = 95 }, { kill = 116 }, { kill = 121 }, { kill = 122 }, { kill = 215 }, { kill = 449 }, { kill = 450 }, { kill = 474 }, { kill = 481 }, { kill = 504 }, { kill = 550 }, { kill = 583 }, { kill = 589 }, { kill = 590 }, { kill = 594 }, { kill = 598 }, { kill = 619 }, { kill = 634 }, { kill = 636 }, { kill = 639 }, { kill = 643 }, { kill = 644 }, { kill = 645 }, { kill = 646 }, { kill = 647 }, { kill = 657 }, { kill = 824 }, { kill = 909 }, { kill = 910 }, { kill = 1663 }, { kill = 1666 }, { kill = 1706 }, { kill = 1707 }, { kill = 1708 }, { kill = 1711 }, { kill = 1715 }, { kill = 1716 }, { kill = 1720 }, { kill = 1725 }, { kill = 1729 }, { kill = 1732 }, { kill = 1763 }, { kill = 4416 }, { kill = 4417 }, { kill = 4418 }, { kill = 5043 }, { kill = 6180 }, { kill = 6846 }, { kill = 6866 }, { kill = 6927 }, { kill = 7050 }, { kill = 7052 }, { kill = 7056 } },
      also = { "stormwind-city", "the-stockade", "noble-conspiracy" },
      text = {
        { "When the orcs razed Stormwind in the First War, it was the Stonemasons' Guild, under a master named Edwin VanCleef, who raised it again. When the work was done, the House of Nobles would not pay them. VanCleef led his masons in a riot through the new streets, and left the city swearing revenge." },
        { "The guild became a gang. In Westfall they took the name of the Defias Brotherhood, tied red cloths over their faces, and set about ruining the farmland that feeds the city: burning fields, driving out the families, and making allies of anyone who would have them. Goblin engineers work for them in the Deadmines, and their reach goes as far as Elwynn, Redridge, Duskwood and the city's own prison, where VanCleef's lieutenant Bazil Thredd raised the inmates in revolt." },
        { "The masons had a grievance over their unpaid work. But whatever the Brotherhood once stood for, the farmers of Westfall have paid for it far more dearly than any lord in Stormwind." },
      },
    },
    ["dragons-of-nightmare"] = {
      title = "The Dragons of Nightmare", kind = "creature", chapter = "peoples", portrait = 15364,
      unlock = { { kill = 14887 }, { kill = 14888 }, { kill = 14889 }, { kill = 14890 }, { npc = 14887 }, { npc = 14888 }, { npc = 14889 }, { npc = 14890 }, { area = 856 }, { area = 356 }, { area = 1111 }, { area = 438 } },
      also = { "cenarion-circle" },
      text = {
        { "Ysera's green dragons guard the Emerald Dream, the unspoiled world through which sleeping druids travel. Four lieutenants watched its great tree portals: Ysondre, Lethon, Emeriss and Taerar, stationed in Duskwood, the Hinterlands, Feralas and Ashenvale." },
        { "The Nightmare has taken them. They emerge twisted and attack those who approach. Emeriss spreads rot, Taerar divides into shades, and Lethon draws out the spirits of the fallen. Remulos gathers fragments of corruption from the portals to investigate. A traveller reaching one of these trees may find the very guardian who should have made it safe has become its danger." },
      },
    },
    ["dreadlords"] = {
      title = "The Dreadlords", kind = "creature", chapter = "peoples", portrait = 10691,
      unlock = { { npc = 2425 }, { npc = 9516 }, { kill = 7664 }, { kill = 8716 }, { kill = 10813 }, { kill = 14506 } },
      also = { "burning-legion", "varimathras", "balnazzar", "the-lich-king", "the-forsaken", "stratholme" },
      text = {
        { "The dreadlords, the nathrezim, are the Burning Legion's schemers: vampiric, patient, better at corrupting than conquering. Kil'jaeden set them to guard his most dangerous creation, the Lich King. Tichondrius, the most cunning of them, delighted in the plague. Mal'Ganis waited for Prince Arthas at Stratholme. Anetheron fought beside Archimonde on Mount Hyjal." },
        { "When the Lich King's power waned, his jailers tried to take Lordaeron for themselves. They lost it to Sylvanas and her Forsaken, who built their city beneath the ruined capital. Varimathras serves the Dark Lady there now, whether he cares for it or not. Balnazzar wears the face of the Scarlet Crusade's own leader in Stratholme." },
        { "A dreadlord rarely shows you what it is. If someone in authority seems keen for the living and the dead to go on killing each other, traveller, it is worth asking who benefits." },
      },
    },
    ["dwarves"] = {
      title = "The Dwarves of Ironforge", kind = "faction", chapter = "peoples",
      unlock = { { people = "Dwarf" } },
      also = { "ironforge", "magni-bronzebeard", "war-of-the-three-hammers", "platinum-discs", "explorers-league" },
      text = {
        { "The dwarves have held Khaz Modan from Ironforge since before anyone wrote their history down, and for a long time they did not know where they came from either. The discs the League recovered from Uldaman suggest an answer the scholars still argue over: that the first dwarves were earthen, shaped from the stone by the Titans, who in time became flesh." },
        { "Three clans once shared the mountain under one High King. When he died they went to war over his throne. The Bronzebeards kept Ironforge, the Wildhammers went north and the Dark Irons woke the Firelord in the south. King Magni Bronzebeard rules now. His brother Muradin went north with Lordaeron's prince and has not been seen since, and his brother Brann is out in the world for the League, which is more or less where we expect him to be." },
        { "They are a sturdy, careful, generous people who keep their grudges as well as their stonework, and I say that fondly. If a dwarf tells you a bridge will hold, traveller, it will. If a dwarf says the ale is good, form your own view." },
      },
    },
    ["earthen-ring"] = {
      title = "The Earthen Ring", kind = "faction", chapter = "peoples", portrait = 12953,
      unlock = { { npc = 12736 }, { npc = 16134 } },
      also = { "shamans", "tauren", "orcs", "thunder-bluff" },
      text = {
        { "The Earthen Ring is a circle of shamans dedicated to studying and preserving the elements. They have forgotten more about strange old gods, ancient legends and lore than most scholars will ever know, one of the Horde's scouts in Ashenvale says, and when something of the elements turns up that no one can explain, it is to them that it is brought." },
        { "They keep to the edges of things. One shaman at Zoram'gar on the Ashenvale coast studies what the sea throws up from Blackfathom, and another waits at Light's Hope, where the dead press closest. Their intentions have been called pure, even by those who doubt the company they keep. The Ring once extended a hand to the Forsaken, and some in Thunder Bluff wonder now whether that was wise." },
        { "A learned society that answers to the elements rather than to a king. The League recognises the type, and envies it a little." },
      },
    },
    ["earthen"] = {
      title = "The Earthen", kind = "creature", chapter = "peoples", portrait = 6025,
      unlock = { { kill = 7011 }, { kill = 7012 }, { kill = 7076 }, { kill = 7077 }, { kill = 7309 }, { kill = 7396 }, { kill = 7397 }, { read = { "Ironforge - the Awakening of the Dwarves", "아이언포지 - 드워프의 탄생", "Ironforge - l'Eveil des Nains", "Ironforge - das Erwachen der Zwerge", "铁炉堡 - 矮人的觉醒", "Forjaz: el despertar de los enanos", "Стальгорн - Пробуждение дворфов", "Altaforja: o Despertar dos Anões", "鐵爐堡 - 矮人的覺醒" } }, { read = { "Uldaman Reliefs", "울다만 유적", "Relevés d'Uldaman", "Bruchstücke aus Uldaman", "奥达曼浮雕", "Relieves de Uldaman", "Ульдаманские барельефы", "Relíquias de Uldaman", "奧達曼浮雕" } } },
      also = { "uldaman", "platinum-discs", "dwarves", "the-ordering", "rockjaw-troggs" },
      text = {
        { "The earthen were the Titans' stonemasons, made from living rock to carve the deep places of the world. When the Titans left, they went on shaping and guarding those depths, caring little for anything above. The Sundering hurt them as it hurt the earth itself. They lost much of what they had been and sealed themselves in the vaults where they were made: Uldaman, Uldum, Ulduar, as the book in our library names them." },
        { "After nearly eight thousand years, the earthen of Uldaman woke. They found their stone hides softened into skin and their power over the rock grown weak. They had become mortal. They called themselves dwarves, went out into the waking world, and founded a kingdom under the highest mountain in the land, Khaz Modan, the mountain of Khaz'goroth, around a forge raised in his honour." },
        { "Not all of them woke. Earthen still stand guard in the halls of Uldaman, and every expedition the League sends there meets them. They do not seem to know whose kin we are." },
      },
    },
    ["elementals"] = {
      title = "The Elementals", kind = "creature", chapter = "peoples", portrait = 171,
      unlock = { { kill = 92 }, { kill = 329 }, { kill = 510 }, { kill = 575 }, { kill = 691 }, { kill = 832 }, { kill = 2258 }, { kill = 2359 }, { kill = 2592 }, { kill = 2593 }, { kill = 2735 }, { kill = 2736 }, { kill = 2752 }, { kill = 2760 }, { kill = 2761 }, { kill = 2762 }, { kill = 2776 }, { kill = 2791 }, { kill = 2887 }, { kill = 3417 }, { kill = 3917 }, { kill = 4033 }, { kill = 4034 }, { kill = 4035 }, { kill = 4036 }, { kill = 4037 }, { kill = 4038 }, { kill = 4120 }, { kill = 4121 }, { kill = 4499 }, { kill = 4526 }, { kill = 4528 }, { kill = 4661 }, { kill = 5461 }, { kill = 5462 }, { kill = 5465 }, { kill = 5850 }, { kill = 5852 }, { kill = 5855 }, { kill = 5889 }, { kill = 5890 }, { kill = 5891 }, { kill = 5893 }, { kill = 5894 }, { kill = 5895 }, { kill = 5896 }, { kill = 5897 }, { kill = 5898 }, { kill = 5902 }, { kill = 6047 }, { kill = 6239 }, { kill = 6296 }, { kill = 6520 }, { kill = 6521 }, { kill = 6748 }, { kill = 7031 }, { kill = 7032 }, { kill = 7226 }, { kill = 7266 }, { kill = 7738 }, { kill = 8278 }, { kill = 8281 }, { kill = 8441 }, { kill = 8519 }, { kill = 8667 }, { kill = 8909 }, { kill = 8910 }, { kill = 8911 }, { kill = 9017 }, { kill = 9025 }, { kill = 9026 }, { kill = 9156 }, { kill = 9178 }, { kill = 9376 }, { kill = 9377 }, { kill = 9396 }, { kill = 9397 }, { kill = 9453 }, { kill = 9816 }, { kill = 10756 }, { kill = 10757 }, { kill = 10955 }, { kill = 10989 }, { kill = 11256 }, { kill = 11321 }, { kill = 11502 }, { kill = 11576 }, { kill = 11577 }, { kill = 11578 }, { kill = 11579 }, { kill = 11665 }, { kill = 11666 }, { kill = 11667 }, { kill = 11668 }, { kill = 11669 }, { kill = 11744 }, { kill = 11745 }, { kill = 11746 }, { kill = 11747 }, { kill = 11777 }, { kill = 11778 }, { kill = 11779 }, { kill = 11780 }, { kill = 11781 }, { kill = 11782 }, { kill = 11783 }, { kill = 11784 }, { kill = 12056 }, { kill = 12057 }, { kill = 12076 }, { kill = 12099 }, { kill = 12100 }, { kill = 12101 }, { kill = 12143 }, { kill = 12201 }, { kill = 12265 }, { kill = 12759 }, { kill = 12806 }, { kill = 12876 }, { kill = 13256 }, { kill = 13279 }, { kill = 13280 }, { kill = 14269 }, { kill = 14350 }, { kill = 14435 }, { kill = 14454 }, { kill = 14455 }, { kill = 14457 }, { kill = 14458 }, { kill = 14460 }, { kill = 14461 }, { kill = 14462 }, { kill = 14464 }, { kill = 14478 }, { kill = 15203 }, { kill = 15204 }, { kill = 15205 }, { kill = 15206 }, { kill = 15207 }, { kill = 15208 }, { kill = 15209 }, { kill = 15211 }, { kill = 15212 }, { kill = 15220 }, { kill = 15305 }, { kill = 15307 }, { kill = 15352 }, { kill = 15428 }, { kill = 16043 }, { kill = 17003 } },
      also = { "the-ordering", "ragnaros", "prince-thunderaan", "hydraxian-waterlords", "abyssal-council", "zaetar-and-theradras", "earthen-ring" },
      text = {
        { "The elementals are the oldest soldiers in the world. They served the Old Gods before the Titans came, and when their masters were chained beneath the earth they were cast out to a plane of their own, where the lords of fire, earth, air and water carry on the war among themselves. What a traveller meets on this side has usually slipped through, been dragged through or been left behind: rock that walks in the Badlands, a whirlwind loose in the Needles or the sands of Silithus, the restless water of the Stranglethorn coast." },
        { "Their courts are as fond of rank as any king's, with princes, dukes and barons. Ragnaros the Firelord was called into the world by a Dark Iron thane and has not left it. He consumed the essence of Prince Thunderaan of the air, and his lieutenants keep what is left of the prince in bindings. The servants of Neptulon the Tidehunter hate fire above all things: Duke Hydraxis makes allies of mortals from his island off Azshara, and an envoy of the Tribunal of the Tides at Sun Rock Retreat pays for every fire elemental put out in Stonetalon's Charred Vale. In Maraudon lives Princess Theradras, an elemental force of earth that the druids call kin to the Old Gods. In Silithus, the Twilight's Hammer summons elemental nobles and takes its orders from them." },
        { "Some are past serving anyone. The plague twisted the water elementals the Waterlords sent into the Eastern Plaguelands until they were sick and furious, and Duke Hydraxis calls it an affront to their purity. Shamans speak to the elements and are answered. The rest of us, traveller, are generally answered with a fist of stone." },
      },
    },
    ["elune"] = {
      title = "Elune", kind = "history", chapter = "peoples",
      unlock = { { npc = 7313 }, { npc = 2151 } },
      also = { "night-elves", "tyrande-whisperwind", "sentinels", "priests", "darnassus" },
      text = {
        { "Elune is the goddess of the moon and the night elves' oldest faith. In the days before the Sundering they believed she slept by day in the depths of the Well of Eternity and woke with the night. Her priestesses kept her temples then, and keep them now, in the Temple of the Moon in Darnassus." },
        { "She answers them. The night elves owe their survival of the Sundering, they say, to her grace, and a High Priestess of Elune, Tyrande Whisperwind, has led them through the ten thousand years since. Her moonwells water their towns, and her priestesses heal by her light. In battle, I am told, they can call it down as something much less gentle." },
        { "A night elf will rarely press her goddess on you. They have had a long time to learn patience with other people's faiths, and with other people." },
      },
    },
    ["forest-trolls"] = {
      title = "The Forest Trolls", kind = "faction", chapter = "peoples", portrait = 3986,
      unlock = { { kill = 2552 }, { kill = 2553 }, { kill = 2554 }, { kill = 2555 }, { kill = 2556 }, { kill = 2557 }, { kill = 2558 }, { kill = 2639 }, { kill = 2640 }, { kill = 2641 }, { kill = 2642 }, { kill = 2643 }, { kill = 2644 }, { kill = 2645 }, { kill = 2646 }, { kill = 2647 }, { kill = 2648 }, { kill = 2649 }, { kill = 2650 }, { kill = 2651 }, { kill = 2652 }, { kill = 2653 }, { kill = 2654 }, { kill = 2686 }, { kill = 4465 }, { kill = 4466 }, { kill = 4467 }, { kill = 7809 }, { kill = 8560 }, { kill = 8561 }, { kill = 8562 }, { kill = 11388 }, { kill = 11391 }, { kill = 14748 } },
      also = {  },
      text = {
        { "Long before there were men in Lordaeron, the forests of the north belonged to the trolls of the Amani empire, and they have never forgiven anyone for taking them. When the high elves came over the sea and settled Quel'Thalas, the Amani made war on them for generations, until the elves and the first human kingdom, Arathor, broke them together in the Troll Wars. Their capital, Zul'Aman, still stands deep in the eastern woods." },
        { "The trolls came back in the Second War, when their warlord Zul'jin led the forest tribes beside the Horde against the elves and the men of Lordaeron, and lost again. What remains are tribes scattered through the hills: the Witherbark in Arathi and the Hinterlands, the Vilebranch in their temple-city of Jintha'Alor, the Mossflayer in the woods of the Eastern Plaguelands, where many of them now rot with the plague." },
        { "They are tall, green-skinned and tusked, they keep the old gods of the trolls, and some keep worse customs than that. The Revantusk of the Hinterlands are the exception: they have taken the Horde's side, and their Horde allies will vouch for them." },
      },
    },
    ["furbolgs"] = {
      title = "The Furbolgs", kind = "creature", chapter = "peoples", portrait = 6800,
      unlock = { { area = 1769 }, { area = 1216 }, { faction = 576, standing = 5 }, { kill = 2006 }, { kill = 2007 }, { kill = 2008 }, { kill = 2009 }, { kill = 2010 }, { kill = 2011 }, { kill = 2012 }, { kill = 2013 }, { kill = 2014 }, { kill = 2039 }, { kill = 2152 }, { kill = 2167 }, { kill = 2168 }, { kill = 2169 }, { kill = 2170 }, { kill = 2171 }, { kill = 2324 }, { kill = 3743 }, { kill = 3745 }, { kill = 3746 }, { kill = 3748 }, { kill = 3749 }, { kill = 3750 }, { kill = 3921 }, { kill = 3922 }, { kill = 3923 }, { kill = 3924 }, { kill = 3925 }, { kill = 3926 }, { kill = 6184 }, { kill = 6185 }, { kill = 6186 }, { kill = 6187 }, { kill = 6188 }, { kill = 6189 }, { kill = 7153 }, { kill = 7154 }, { kill = 7155 }, { kill = 7156 }, { kill = 7157 }, { kill = 7158 }, { kill = 7235 }, { kill = 7438 }, { kill = 7439 }, { kill = 7440 }, { kill = 7441 }, { kill = 7442 }, { kill = 9462 }, { kill = 9464 }, { kill = 10738 }, { kill = 10916 }, { kill = 11516 }, { kill = 11552 }, { kill = 11553 }, { kill = 11690 }, { kill = 11713 }, { kill = 14342 }, { kill = 14372 } },
      also = { "burning-legion", "sickness-of-teldrassil" },
      text = {
        { "The furbolgs belong to Kalimdor's northern forests, where their villages and totems have stood beside night elf country for ages. They fought the Burning Legion alongside the elves ten thousand years ago. Their history has room for old friendships, however fiercely a stranger may now be met at a camp." },
        { "Tribe after tribe has suffered corruption: the Gnarlpine of Teldrassil, the Blackwood of Darkshore, the Deadwood of Felwood and the Winterfall of Winterspring among them. The madness has turned neighbours into enemies. In Felwood, the poisoned land gives the night elves ample reason to blame the Legion's taint." },
        { "The Timbermaw still guard the tunnels joining Felwood, Moonglade and Winterspring, and can be won over by help against their corrupted kin. Azshara's Blackmaw Hold belongs to a separate tribe, one that has succumbed to corruption." },
      },
    },
    ["gnolls"] = {
      title = "The Gnolls", kind = "creature", chapter = "peoples", portrait = 175,
      unlock = { { kill = 97 }, { kill = 98 }, { kill = 117 }, { kill = 123 }, { kill = 124 }, { kill = 125 }, { kill = 423 }, { kill = 424 }, { kill = 426 }, { kill = 429 }, { kill = 430 }, { kill = 431 }, { kill = 432 }, { kill = 433 }, { kill = 434 }, { kill = 445 }, { kill = 446 }, { kill = 448 }, { kill = 452 }, { kill = 453 }, { kill = 478 }, { kill = 500 }, { kill = 501 }, { kill = 568 }, { kill = 579 }, { kill = 580 }, { kill = 1007 }, { kill = 1008 }, { kill = 1009 }, { kill = 1010 }, { kill = 1011 }, { kill = 1012 }, { kill = 1013 }, { kill = 1014 }, { kill = 1065 }, { kill = 1426 }, { kill = 1674 }, { kill = 1675 }, { kill = 1772 }, { kill = 1773 }, { kill = 1939 }, { kill = 1940 }, { kill = 1941 }, { kill = 1942 }, { kill = 1943 }, { kill = 1944 }, { kill = 2372 }, { kill = 2373 }, { kill = 2949 }, { kill = 2950 }, { kill = 2951 }, { kill = 5249 }, { kill = 5251 }, { kill = 5253 }, { kill = 5254 }, { kill = 5255 }, { kill = 5258 }, { kill = 10991 } },
      also = { "kobolds", "defias-brotherhood", "mosshide-gnolls", "hogger" },
      text = {
        { "The Riverpaw raid Elwynn and Westfall. The Mosshide occupy the Wetlands. These packs have different histories. Hogger's wanted notice warns that he is too dangerous for a lone hunter, while Rethiel's account says the Mosshide once lived peacefully beside their neighbours." },
        { "Some packs serve other powers. Redridge's Shadowhide answer to Morganth, and Thule Ravenclaw commands the undead Rot Hide in Tirisfal and Silverpine. Across the sea, the Palemane hunt in Mulgore and the Woodpaw live in Feralas. Ask which pack you are facing, traveller. Its name will tell you more about the trouble ahead than a general opinion of gnolls." },
      },
    },
    ["goblins"] = {
      title = "The Goblins", kind = "faction", chapter = "peoples", portrait = 7052,
      unlock = { { npc = 622 }, { npc = 641 }, { npc = 643 }, { npc = 647 }, { npc = 674 }, { npc = 675 }, { npc = 676 }, { npc = 677 }, { npc = 737 }, { npc = 773 }, { npc = 921 }, { npc = 1094 }, { npc = 1095 }, { npc = 1096 }, { npc = 1097 }, { npc = 1731 }, { npc = 1763 }, { npc = 2480 }, { npc = 2481 }, { npc = 2486 }, { npc = 2490 }, { npc = 2495 }, { npc = 2496 }, { npc = 2498 }, { npc = 2548 }, { npc = 2594 }, { npc = 2624 }, { npc = 2625 }, { npc = 2627 }, { npc = 2663 }, { npc = 2670 }, { npc = 2685 }, { npc = 2699 }, { npc = 2767 }, { npc = 2778 }, { npc = 2817 }, { npc = 2832 }, { npc = 2834 }, { npc = 2836 }, { npc = 2837 }, { npc = 2838 }, { npc = 2840 }, { npc = 2842 }, { npc = 2846 }, { npc = 2848 }, { npc = 2849 }, { npc = 3000 }, { npc = 3051 }, { npc = 3053 }, { npc = 3134 }, { npc = 3149 }, { npc = 3150 }, { npc = 3203 }, { npc = 3293 }, { npc = 3391 }, { npc = 3412 }, { npc = 3413 }, { npc = 3442 }, { npc = 3445 }, { npc = 3446 }, { npc = 3453 }, { npc = 3471 }, { npc = 3491 }, { npc = 3492 }, { npc = 3493 }, { npc = 3494 }, { npc = 3495 }, { npc = 3496 }, { npc = 3497 }, { npc = 3498 }, { npc = 3499 }, { npc = 3502 }, { npc = 3537 }, { npc = 3572 }, { npc = 3655 }, { npc = 3658 }, { npc = 3665 }, { npc = 3683 }, { npc = 3684 }, { npc = 3945 }, { npc = 3947 }, { npc = 4085 }, { npc = 4086 }, { npc = 4201 }, { npc = 4276 }, { npc = 4429 }, { npc = 4496 }, { npc = 4508 }, { npc = 4624 }, { npc = 4630 }, { npc = 4631 }, { npc = 4706 }, { npc = 4708 }, { npc = 4709 }, { npc = 4723 }, { npc = 5411 }, { npc = 5594 }, { npc = 5610 }, { npc = 5836 }, { npc = 6019 }, { npc = 6248 }, { npc = 6495 }, { npc = 6568 }, { npc = 6606 }, { npc = 6791 }, { npc = 6807 }, { npc = 6846 }, { npc = 6946 }, { npc = 7057 }, { npc = 7161 }, { npc = 7287 }, { npc = 7288 }, { npc = 7307 }, { npc = 7308 }, { npc = 7407 }, { npc = 7408 }, { npc = 7564 }, { npc = 7583 }, { npc = 7607 }, { npc = 7724 }, { npc = 7733 }, { npc = 7771 }, { npc = 7799 }, { npc = 7850 }, { npc = 7853 }, { npc = 7876 }, { npc = 7882 }, { npc = 8021 }, { npc = 8119 }, { npc = 8123 }, { npc = 8124 }, { npc = 8125 }, { npc = 8126 }, { npc = 8128 }, { npc = 8129 }, { npc = 8131 }, { npc = 8137 }, { npc = 8139 }, { npc = 8203 }, { npc = 8305 }, { npc = 8320 }, { npc = 8420 }, { npc = 8496 }, { npc = 8661 }, { npc = 8736 }, { npc = 8738 }, { npc = 9179 }, { npc = 9272 }, { npc = 9316 }, { npc = 9317 }, { npc = 9336 }, { npc = 9460 }, { npc = 9536 }, { npc = 9543 }, { npc = 9544 }, { npc = 9558 }, { npc = 9559 }, { npc = 9564 }, { npc = 9566 }, { npc = 9706 }, { npc = 9857 }, { npc = 9858 }, { npc = 9985 }, { npc = 9997 }, { npc = 9998 }, { npc = 9999 }, { npc = 10060 }, { npc = 10063 }, { npc = 10257 }, { npc = 10260 }, { npc = 10267 }, { npc = 10302 }, { npc = 10305 }, { npc = 10468 }, { npc = 10941 }, { npc = 10977 }, { npc = 10978 }, { npc = 10993 }, { npc = 11017 }, { npc = 11118 }, { npc = 11119 }, { npc = 11182 }, { npc = 11183 }, { npc = 11184 }, { npc = 11185 }, { npc = 11186 }, { npc = 11187 }, { npc = 11188 }, { npc = 11189 }, { npc = 11190 }, { npc = 11438 }, { npc = 11596 }, { npc = 11625 }, { npc = 11626 }, { npc = 11753 }, { npc = 11754 }, { npc = 11755 }, { npc = 11756 }, { npc = 11757 }, { npc = 12136 }, { npc = 12137 }, { npc = 12277 }, { npc = 12724 }, { npc = 13601 }, { npc = 13917 }, { npc = 13996 }, { npc = 14338 }, { npc = 14395 }, { npc = 14401 }, { npc = 14437 }, { npc = 14480 }, { npc = 14492 }, { npc = 14508 }, { npc = 14637 }, { npc = 14742 }, { npc = 15077 }, { npc = 15078 }, { npc = 15088 }, { npc = 15116 }, { npc = 15165 }, { npc = 15189 }, { npc = 15190 }, { npc = 15677 }, { npc = 15681 }, { npc = 16014 }, { npc = 16096 }, { npc = 16416 }, { npc = 16417 }, { npc = 16418 } },
      also = { "steamwheedle-cartel", "venture-company", "southsea-freebooters", "zandalar-tribe" },
      text = {
        { "Goblins turn up wherever there is money to be made, which is to say nearly everywhere: keeping the neutral ports, digging and logging for the Venture Company, selling explosives to anyone with the coin. Their homeland is the island of Kezan in the southern seas, and their capital is Undermine, where the trade princes who rule them do their business." },
        { "The island was not always theirs. Ask the Zandalar trolls, and you will hear that Kezan was once a grand territory of the Zandalar Empire, until, as they put it, the taint of the goblin trade princes forced them out. The longer account is that the trolls set goblins to dig a strange ore, kaja'mite, out of the island's volcano, and that the ore sharpened the diggers' wits until they took Kezan for themselves. I cannot vouch for the ore. I can believe the rest." },
        { "In the Second War the goblins sold the Horde sappers and zeppelins, and were paid for both. By the Third War they had stopped choosing sides, and their merchants, laboratories and shipyards would serve anyone. That arrangement suits them still. The Steamwheedle Cartel keeps its ports open to Alliance and Horde alike, the Venture Company strips whatever land no one stops it stripping, and a goblin engineer favours the kind of device that ends in a large bang. Gnomeregan's engineers call that a difference of philosophy. I suspect it is a difference of patience." },
      },
    },
    ["green-dragonflight"] = {
      title = "The Green Dragonflight", kind = "creature", chapter = "peoples", portrait = 4494,
      unlock = { { npc = 5353 }, { npc = 15628 }, { npc = 15660 }, { kill = 740 }, { kill = 741 }, { kill = 742 }, { kill = 743 }, { kill = 744 }, { kill = 745 }, { kill = 746 }, { kill = 1063 }, { kill = 5312 }, { kill = 5314 }, { kill = 5317 }, { kill = 5319 }, { kill = 5320 }, { kill = 5709 }, { kill = 5718 }, { kill = 5719 }, { kill = 5722 }, { kill = 12474 }, { kill = 12475 }, { kill = 12476 }, { kill = 12477 }, { kill = 12478 }, { kill = 12479 }, { kill = 12496 }, { kill = 12497 }, { kill = 12498 }, { kill = 12900 }, { kill = 14445 }, { kill = 14887 }, { kill = 14888 }, { kill = 14889 }, { kill = 14890 }, { kill = 15302 }, { kill = 15491 }, { area = 356 }, { area = 1111 }, { area = 856 }, { area = 438 } },
      also = { "the-five-aspects", "the-emerald-dream", "dragons-of-nightmare", "eranikus", "cenarion-circle" },
      text = {
        { "Ysera's flight keeps the Emerald Dream, and the four great trees where the Dream touches the waking world: Seradane in the Hinterlands, Bough Shadow in Ashenvale, the Dream Bough in Feralas and the Twilight Grove in Duskwood. The druids walk the Dream through the pact their ancestors made with Ysera. The dragons walk the world rarely." },
        { "Not all of them are well. Something has crept into the Dream and twisted some of Ysera's own children. The four who now haunt the great trees have their own page. Before them there was Eranikus, sleeping above the sunken temple of the Swamp of Sorrows and caught in the same nightmare." },
        { "Itharius, another of the flight, waits in a cave in that swamp, seeking mortals who can help redeem Eranikus. While the corrupted guardians still haunt the great trees, one of their kin is asking strangers to bring a dragon home." },
      },
    },
    ["grimtotem"] = {
      title = "The Grimtotem", kind = "faction", chapter = "peoples", portrait = 6835,
      unlock = { { npc = 4046 }, { kill = 7725 }, { kill = 7726 }, { kill = 7727 }, { kill = 10758 }, { kill = 10759 }, { kill = 10760 }, { kill = 10761 }, { kill = 11910 }, { kill = 11911 }, { kill = 11912 }, { kill = 11913 } },
      also = { "thunder-bluff" },
      text = {
        { "Most tauren live by the Earth Mother's peace. The Grimtotem do not. They are a tribe that believes the other races have no right to Kalimdor at all, tauren who disagree included, and they fight to take it back with no rules and no mercy." },
        { "Their matriarch, Magatha, the Elder Crone, lives in Thunder Bluff itself and sits among the elders, which tells you something about the patience of Cairne Bloodhoof. Her warriors are less polite. They raid in the Stonetalon Mountains, hold Darkcloud Pinnacle in Thousand Needles and harry Freewind Post, and keep a compound in Feralas. Ask a tauren of Freewind what he thinks of the Grimtotem, and then step back." },
      },
    },
    ["harpies"] = {
      title = "The Harpies", kind = "creature", chapter = "peoples", portrait = 10877,
      unlock = { { kill = 2962 }, { kill = 2963 }, { kill = 2964 }, { kill = 2965 }, { kill = 3115 }, { kill = 3118 }, { kill = 3276 }, { kill = 3277 }, { kill = 3278 }, { kill = 3279 }, { kill = 3280 }, { kill = 4022 }, { kill = 4023 }, { kill = 4024 }, { kill = 4025 }, { kill = 4026 }, { kill = 4027 }, { kill = 4100 }, { kill = 4101 }, { kill = 4104 }, { kill = 5785 }, { kill = 5830 }, { kill = 12579 } },
      also = {  },
      text = {
        { "Harpies nest throughout Kalimdor, hunting and casting spells with wings and talons to carry them over the ground. The Dustwind occupy Durotar, the Windfury Mulgore, the Witchwing the Barrens and the Bloodfury Stonetalon. Their flocks have made enemies among the settlements below." },
        { "Ruul Eagletalon sends hunters against the Windfury as a trial. Stonetalon's druids seek the Charred Vale back from the Bloodfury so they can restore it. A traveller passing beneath their nesting grounds has practical reason to learn which flock holds them." },
      },
    },
    ["high-elves"] = {
      title = "The High Elves", kind = "faction", chapter = "peoples", portrait = 10375,
      unlock = { { npc = 1156 }, { npc = 1752 }, { npc = 3339 }, { npc = 3465 }, { npc = 4456 }, { npc = 5498 }, { npc = 7801 }, { npc = 10304 }, { npc = 10976 }, { npc = 11704 }, { npc = 11706 }, { npc = 12322 }, { npc = 14348 }, { kill = 2691 }, { kill = 2692 }, { kill = 2693 }, { kill = 2694 }, { kill = 8214 }, { kill = 8563 }, { kill = 8564 }, { kill = 8565 }, { kill = 10824 }, { area = 350 }, { read = { "Exile of the High Elves", "하이 엘프의 유배", "L'exil des hauts-elfes", "Die Verbannung der Hochelfen", "高等精灵的流放", "El exilio de los elfos nobles", "Изгнание Высших эльфов", "O Exílio dos Elfos Superiores", "高等精靈的流放" } }, { read = { "The Founding of Quel'Thalas", "쿠엘탈라스 건국", "La fondation de Quel'Thalas", "Die Gründung von Quel’Thalas", "奎尔萨拉斯的建立", "La fundación de Quel'Thalas", "Основание Кель'Таласа", "A Fundação de Quel'thalas", "奎爾薩拉斯的建立" } } },
      also = { "queldanil-lodge", "the-fall-of-quelthalas", "blood-elves", "night-elves", "forest-trolls", "the-guardians-of-tirisfal" },
      text = {
        { "The high elves began as night elves: Highborne of Azshara's court who survived the Sundering and could not give up their magic. When the druids forbade it on pain of death, their leader, Dath'Remar, answered with a storm of spells over Ashenvale. The druids would not kill so many of their own kin. They exiled them instead, and Dath'Remar's people sailed east across the Maelstrom, glad to be rid of their cautious cousins." },
        { "They came ashore in the north of what men would call Lordaeron and settled first in the glades of Tirisfal, until, after a few years, many of them began to go mad. Rumour said something evil slept beneath that ground, and it was never proven. Cut off from the Well, they lost their immortality on the road, grew smaller and paler, and fought the Amani trolls for every mile. At last they founded Quel'Thalas deep in the northern forests, on land the trolls held sacred, and ringed it with runestones. Dath'Remar took the name Sunstrider, 'he who walks the day', and his people have been children of the sun ever since." },
        { "Quel'Thalas is gone now. The elves a traveller meets are what remains of it: rangers holding Quel'Lithien Lodge at the edge of the Plaguelands, the Highvale elves of Quel'Danil Lodge in the Hinterlands, wanderers here and there. They are proud even in exile. Given what they have lost, I find it hard to hold that against them." },
      },
    },
    ["highborne"] = {
      title = "The Highborne", kind = "faction", chapter = "peoples", portrait = 10702,
      unlock = { { npc = 11486 }, { npc = 14355 }, { npc = 14358 }, { npc = 14364 }, { npc = 14368 }, { npc = 14369 }, { npc = 14371 }, { npc = 14381 }, { npc = 14382 }, { npc = 14383 }, { npc = 16032 }, { kill = 2176 }, { kill = 2177 }, { kill = 2178 }, { kill = 6116 }, { kill = 6117 }, { kill = 7523 }, { kill = 7524 }, { kill = 10684 }, { kill = 11467 }, { kill = 11469 }, { kill = 11470 }, { kill = 11471 }, { kill = 11472 }, { kill = 11473 }, { kill = 11475 }, { kill = 11486 }, { kill = 11487 }, { kill = 11488 }, { read = { "The Kaldorei and the Well of Eternity", "칼도레이와 영원의 샘", "Les Kaldorei et le Puits d'Eternité", "Die Kaldorei und der Brunnen der Ewigkeit", "卡多雷和永恒之井", "Los kaldorei y el Pozo de la Eternidad", "Кальдорай и Источник Вечности", "Os Kaldorei e a Nascente da Eternidade", "卡多雷和永恆之井" } } },
      also = { "queen-azshara", "the-sundering", "high-elves", "shendralar", "ruins-of-keltheril", "highborne-ruins" },
      text = {
        { "The Highborne were the night elves' upper caste, Queen Azshara's chosen servants, who studied the Well of Eternity until they learned magic, and then loved it more than anything else. It was their spellcraft that drew Sargeras to the world, and their queen and her court who opened the way for his Legion." },
        { "Not all of them shared her fate. Some survived the Sundering among the other night elves and, exiled for clinging to their magic, became the high elves. Others held on in Eldre'Thalas, where the Shen'dralar keep their own counsel still. Many simply died, and did not rest." },
        { "Their dead are easy to find: wailing in the ruins of Darkshore, drifting through Azshara as apparitions and lichlings, suffering by the frozen lake of Kel'Theril in Winterspring. Ten thousand years is a long time to be sorry, traveller. At least one of them, by the lake, seems truly to be." },
      },
    },
    ["humans"] = {
      title = "The Humans", kind = "faction", chapter = "peoples",
      unlock = { { people = "Human" } },
      also = { "stormwind-city", "regency-of-stormwind", "fall-of-lordaeron", "church-of-the-holy-light" },
      text = {
        { "Humanity's first kingdom was Arathor, raised at Strom in the highlands that still bear its name. Its king, Thoradin, gathered the scattered tribes against the Amani trolls, and in that war the high elves of Quel'Thalas taught a hundred humans to work magic. From Arathor came, in time, seven kingdoms: Stormwind, Lordaeron, Gilneas, Alterac, Stromgarde, Kul Tiras and the mages' city of Dalaran." },
        { "The orcs came through the Dark Portal and burned Stormwind first. Its people fled north, and the Alliance that won the Second War was built in Lordaeron. Then the plague and the Scourge took Lordaeron itself, Gilneas shut itself behind its wall, and Dalaran fell. Stormwind, rebuilt in white stone, is the greatest human city left, and a boy king sits on its throne under a regent while his father is missing." },
        { "They are a short-lived people and a stubborn one, traveller. They quarrel among themselves more than is good for them, and rebuild faster than anyone I know. The League has learned to take their maps seriously and their promises of payment with a little care." },
      },
    },
    ["kobolds"] = {
      title = "The Kobolds", kind = "creature", chapter = "peoples", portrait = 365,
      unlock = { { kill = 6 }, { kill = 40 }, { kill = 80 }, { kill = 257 }, { kill = 475 }, { kill = 476 }, { kill = 1172 }, { kill = 1173 }, { kill = 1174 }, { kill = 1175 }, { kill = 1176 }, { kill = 1177 }, { kill = 1202 }, { kill = 1236 }, { kill = 2572 }, { kill = 2573 }, { kill = 2574 }, { kill = 4111 }, { kill = 4112 }, { kill = 4113 }, { kill = 4114 }, { kill = 4116 } },
      also = { "gnolls", "defias-brotherhood", "elwynn-forest" },
      text = {
        { "Every miner in the Alliance has a kobold story, and most of them end with a lost pick. Kobolds are small, rat-faced creatures of the tunnels, cowardly alone and dangerous in numbers, and they are always in numbers. They wear candles on their heads to light the dark, and they will fight to the death for a candle long after they would have run from a sword." },
        { "They are everywhere there is digging to be done. A clan out of the Redridge Mountains has filled the mines of Elwynn Forest and Westfall, the Tunnel Rats have dug in above Thelsamar, the Drywhisker serve the giants of the Arathi Highlands, and the Gravelsnout grub for ore in Thousand Needles." },
        { "It is easy to laugh at them. The farmers of Elwynn, who lose their cattle and their harvests to them, do not laugh." },
      },
    },
    ["murlocs"] = {
      title = "The Murlocs", kind = "creature", chapter = "peoples", portrait = 441,
      unlock = { { kill = 46 }, { kill = 126 }, { kill = 127 }, { kill = 171 }, { kill = 285 }, { kill = 391 }, { kill = 422 }, { kill = 456 }, { kill = 458 }, { kill = 513 }, { kill = 515 }, { kill = 517 }, { kill = 544 }, { kill = 545 }, { kill = 548 }, { kill = 578 }, { kill = 732 }, { kill = 735 }, { kill = 747 }, { kill = 750 }, { kill = 751 }, { kill = 752 }, { kill = 871 }, { kill = 873 }, { kill = 875 }, { kill = 877 }, { kill = 879 }, { kill = 1024 }, { kill = 1025 }, { kill = 1026 }, { kill = 1027 }, { kill = 1028 }, { kill = 1029 }, { kill = 1083 }, { kill = 1418 }, { kill = 1543 }, { kill = 1544 }, { kill = 1545 }, { kill = 1767 }, { kill = 1768 }, { kill = 1908 }, { kill = 1909 }, { kill = 1957 }, { kill = 1958 }, { kill = 2201 }, { kill = 2202 }, { kill = 2203 }, { kill = 2204 }, { kill = 2205 }, { kill = 2206 }, { kill = 2207 }, { kill = 2208 }, { kill = 2374 }, { kill = 2375 }, { kill = 2376 }, { kill = 2377 }, { kill = 3737 }, { kill = 3739 }, { kill = 3740 }, { kill = 3742 }, { kill = 4358 }, { kill = 4359 }, { kill = 4360 }, { kill = 4361 }, { kill = 4362 }, { kill = 4363 }, { kill = 4457 }, { kill = 4458 }, { kill = 4459 }, { kill = 4460 }, { kill = 4461 }, { kill = 4818 }, { kill = 7015 }, { kill = 10323 } },
      also = { "naga", "darkspear-trolls" },
      text = {
        { "Murloc huts and fishing nets line shores on both continents, from Elwynn's waters to Darkshore. Hunters and oracles occupy their settlements, often attacking those who approach. A traveller can meet several tribes without learning much of the history behind their presence." },
        { "One tribe had a decisive part in the new Horde's journey. Murlocs serving a sea witch captured trolls and orcs on the Darkspear islands. Thrall's followers fought their way free. Sen'jin died, and the surviving Darkspear sailed with them to Kalimdor. That alliance began beside a shore defended by murlocs, long before it had a home in Durotar." },
      },
    },
    ["naga"] = {
      title = "The Naga", kind = "creature", chapter = "peoples", portrait = 4036,
      unlock = { { kill = 1907 }, { kill = 2179 }, { kill = 2180 }, { kill = 2181 }, { kill = 2182 }, { kill = 2183 }, { kill = 2320 }, { kill = 2368 }, { kill = 2369 }, { kill = 2370 }, { kill = 2371 }, { kill = 2595 }, { kill = 2596 }, { kill = 2775 }, { kill = 2779 }, { kill = 3711 }, { kill = 3712 }, { kill = 3713 }, { kill = 3715 }, { kill = 3717 }, { kill = 3944 }, { kill = 4364 }, { kill = 4366 }, { kill = 4368 }, { kill = 4370 }, { kill = 4371 }, { kill = 4374 }, { kill = 4711 }, { kill = 4712 }, { kill = 4713 }, { kill = 4714 }, { kill = 4715 }, { kill = 4716 }, { kill = 4718 }, { kill = 4719 }, { kill = 4802 }, { kill = 4803 }, { kill = 4805 }, { kill = 4807 }, { kill = 4831 }, { kill = 5331 }, { kill = 5332 }, { kill = 5333 }, { kill = 5334 }, { kill = 5335 }, { kill = 5336 }, { kill = 5337 }, { kill = 5343 }, { kill = 6190 }, { kill = 6193 }, { kill = 6194 }, { kill = 6195 }, { kill = 6196 }, { kill = 6243 }, { kill = 6649 }, { kill = 7016 }, { kill = 7017 }, { kill = 7885 }, { kill = 7886 }, { kill = 8136 }, { kill = 10559 }, { kill = 12204 }, { kill = 12205 }, { kill = 12321 } },
      also = { "murlocs" },
      text = {
        { "The Sundering carried Azshara's Highborne beneath the sea with their capital. They survived, changed into scaled beings with serpentine lower bodies, fins and, in some cases, four arms. They built a kingdom under the water. The old tales place their queen there still." },
        { "They returned to the surface during the Third War, when Lady Vashj led naga in Illidan's service. Warbands now hold the Zoram Strand and drowned Blackfathom temple, the ruined coasts of Azshara and Darkshore, and shores in Feralas, Desolace and Dustwallow." },
        { "The Highborne's story did not end when their cities sank, traveller. Those same Highborne now contend for places along the continent's coasts, changed as much as the land they once knew." },
      },
    },
    ["night-elves"] = {
      title = "The Night Elves", kind = "faction", chapter = "peoples",
      unlock = { { people = "NightElf" } },
      also = { "darnassus", "tyrande-whisperwind", "the-sundering", "fandral-staghelm", "cenarion-circle", "teldrassil" },
      text = {
        { "The kaldorei are the oldest people the League has met, and they are too polite to remind us of it often. Ten thousand years ago their Highborne drew on the Well of Eternity until the Burning Legion came for it, and the war that followed broke the world. Afterwards the survivors gave up the arcane. They turned to the druids of Malfurion Stormrage and the priestesses of Elune, and planted a World Tree on Mount Hyjal that kept them from growing old." },
        { "In the Third War the Legion came back to Hyjal. To destroy the demon Archimonde, the night elves gave up the Tree and their immortality with it. Fandral Staghelm has since grown Teldrassil off the coast of Darkshore, and Darnassus stands in its branches. Whether the new Tree is blessed as the old one was, the druids do not say out loud." },
        { "They now grow old, and they are learning what that means, traveller. Tyrande Whisperwind leads them from the Temple of the Moon while Malfurion is lost in the Dream. If a night elf seems to weigh every word, remember that until a few years ago they had all the time in the world to choose them." },
      },
    },
    ["ogres"] = {
      title = "The Ogres", kind = "creature", chapter = "peoples", portrait = 416,
      unlock = { { kill = 212 }, { kill = 678 }, { kill = 679 }, { kill = 680 }, { kill = 709 }, { kill = 710 }, { kill = 723 }, { kill = 889 }, { kill = 891 }, { kill = 892 }, { kill = 1142 }, { kill = 1144 }, { kill = 1178 }, { kill = 1179 }, { kill = 1180 }, { kill = 1181 }, { kill = 1183 }, { kill = 1251 }, { kill = 1487 }, { kill = 2252 }, { kill = 2253 }, { kill = 2254 }, { kill = 2255 }, { kill = 2256 }, { kill = 2257 }, { kill = 2287 }, { kill = 2416 }, { kill = 2417 }, { kill = 2562 }, { kill = 2564 }, { kill = 2566 }, { kill = 2567 }, { kill = 2569 }, { kill = 2570 }, { kill = 2571 }, { kill = 2701 }, { kill = 2715 }, { kill = 2716 }, { kill = 2717 }, { kill = 2718 }, { kill = 2719 }, { kill = 2720 }, { kill = 2906 }, { kill = 2907 }, { kill = 5229 }, { kill = 5232 }, { kill = 5234 }, { kill = 5236 }, { kill = 5237 }, { kill = 5238 }, { kill = 5239 }, { kill = 5240 }, { kill = 5241 }, { kill = 5471 }, { kill = 5472 }, { kill = 5473 }, { kill = 5474 }, { kill = 5475 }, { kill = 5974 }, { kill = 5975 }, { kill = 5976 }, { kill = 5977 }, { kill = 5978 }, { kill = 7033 }, { kill = 7034 }, { kill = 7035 }, { kill = 7379 }, { kill = 9197 }, { kill = 9198 }, { kill = 9199 }, { kill = 9200 }, { kill = 9201 }, { kill = 9216 }, { kill = 9217 }, { kill = 9218 }, { kill = 9219 }, { kill = 10602 }, { kill = 11440 }, { kill = 11441 }, { kill = 11443 }, { kill = 11444 }, { kill = 11445 }, { kill = 11448 }, { kill = 11450 }, { kill = 11501 }, { kill = 14324 }, { kill = 14325 }, { kill = 14351 } },
      also = { "mogrosh-ogres" },
      text = {
        { "The ogres came to this world with the Horde, from the same red land as the orcs, and fought in the Second War as its heavy fists. The warlock Gul'dan improved on them, after his fashion: he used the Altar of Storms to grant ogres the powers of the ogre magi, and their kind still rule many of the clans." },
        { "After the Horde was broken, ogre clans established themselves in the wild places, and have stayed there: the Mo'grosh in Loch Modan, the Splinter Fist in Duskwood, the Crushridge in Alterac, the Boulderfist in Arathi, the Dustbelcher in the Badlands, the Mosh'Ogg in Stranglethorn and the Dreadmaul at the Dark Portal. Across the sea are the Gordunni in Feralas and the Dunemaul in Tanaris. The Gordok have made themselves at home in the ruins of an elven city in Feralas, and crown whoever kills their king." },
        { "Not every clan has forgotten the old alliance. The Stonemaul of Dustwallow Marsh fight beside the Horde at Brackenwall, and the orcs speak well of them. The rest would rather eat you than talk." },
      },
    },
    ["orcs"] = {
      title = "The Orcs", kind = "faction", chapter = "peoples",
      unlock = { { people = "Orc" } },
      also = { "thrall", "orgrimmar", "durotar", "durnholde-keep", "frostwolf-clan", "blackrock-clan", "burning-blade" },
      text = {
        { "The orcs came from Draenor, a world of clans and shamans, and they did not come of their own will. The warlock Gul'dan and his Shadow Council, serving the demon Kil'jaeden, taught them fel magic and led their chieftains to drink the blood of Mannoroth. The Horde that crossed the Dark Portal was born of that bargain, and it burned Stormwind before the Alliance broke it in the Second War." },
        { "The defeated orcs were penned in internment camps, listless as the demons' fury drained out of them. Thrall, raised a slave at Durnholde, freed them, gave them back the old ways of the shaman and led them across the sea to Kalimdor. At Mount Hyjal they fought the Legion beside humans and night elves, and when Grom Hellscream killed Mannoroth the blood curse was broken." },
        { "They named their new land Durotar, after Thrall's father, and built Orgrimmar in its rocks. They are a proud people with a long memory of being used, traveller. Offer an orc respect and plain dealing, and never ask one to serve a master again." },
      },
    },
    ["quilboar"] = {
      title = "The Quilboar", kind = "faction", chapter = "peoples", portrait = 1218,
      unlock = { { kill = 2952 }, { kill = 2953 }, { kill = 3111 }, { kill = 3112 }, { kill = 3113 }, { kill = 3114 }, { kill = 3232 }, { kill = 3258 }, { kill = 3260 }, { kill = 3261 }, { kill = 3263 }, { kill = 3265 }, { kill = 3266 }, { kill = 3267 }, { kill = 3268 }, { kill = 3269 }, { kill = 3271 }, { kill = 3438 }, { kill = 3456 }, { kill = 3457 }, { kill = 3458 }, { kill = 3459 }, { kill = 4420 }, { kill = 4421 }, { kill = 4422 }, { kill = 4424 }, { kill = 4435 }, { kill = 4436 }, { kill = 4437 }, { kill = 4438 }, { kill = 4440 }, { kill = 4442 }, { kill = 4515 }, { kill = 4516 }, { kill = 4517 }, { kill = 4518 }, { kill = 4519 }, { kill = 4520 }, { kill = 4522 }, { kill = 4523 }, { kill = 4525 }, { kill = 4530 }, { kill = 4531 }, { kill = 4532 }, { kill = 4625 }, { kill = 5824 }, { kill = 5859 }, { kill = 5863 }, { kill = 5864 }, { kill = 6035 }, { kill = 6132 }, { kill = 6168 }, { kill = 7335 }, { kill = 7337 }, { kill = 7354 }, { kill = 7355 }, { kill = 7356 }, { kill = 7357 }, { kill = 7872 }, { kill = 7873 }, { kill = 7874 }, { kill = 8554 } },
      also = { "scourge", "red-rocks" },
      text = {
        { "In the War of the Ancients a great boar demigod, Agamaggan, fought the Burning Legion and fell. Where his blood soaked into the ground of the Barrens, colossal thorns grew, and the quilboar came to live among them: a people of boar-men, spined and tusked, who hold the thorns sacred and call themselves his children. The greatest of these thorn-warrens they call the Razorfen." },
        { "The tribes spread through the Barrens, Mulgore and Durotar: the Razormane, the Bristleback, the Razorfen in their Kraul. They fight the centaurs, the tauren and the orcs with equal fury, and they fought them long before the Horde came. Now there is worse news. In Razorfen Downs, the Death's Head tribe has made a bargain with the Scourge, and a lich named Amnennar the Coldbringer sits in the heart of Agamaggan's thorns." },
      },
    },
    ["satyrs"] = {
      title = "The Satyrs", kind = "creature", chapter = "peoples", portrait = 11344,
      unlock = { { kill = 2212 }, { kill = 3752 }, { kill = 3754 }, { kill = 3755 }, { kill = 3757 }, { kill = 3758 }, { kill = 3759 }, { kill = 3762 }, { kill = 3763 }, { kill = 3765 }, { kill = 3767 }, { kill = 3770 }, { kill = 3771 }, { kill = 4670 }, { kill = 4671 }, { kill = 4672 }, { kill = 4673 }, { kill = 4674 }, { kill = 4675 }, { kill = 4788 }, { kill = 4789 }, { kill = 4798 }, { kill = 4799 }, { kill = 6125 }, { kill = 6126 }, { kill = 6127 }, { kill = 6200 }, { kill = 6201 }, { kill = 6202 }, { kill = 7105 }, { kill = 7106 }, { kill = 7107 }, { kill = 7108 }, { kill = 7109 }, { kill = 7110 }, { kill = 7111 }, { kill = 11451 }, { kill = 11790 } },
      also = { "burning-legion", "sickness-of-teldrassil" },
      text = {
        { "Xavius helped open Queen Azshara's court to the Burning Legion. When he failed Sargeras, the demon lord remade him with horns, hooves and claws. The first satyr then offered that transformation to other elves hungry for power, and the curse spread through his followers." },
        { "Their camps remain in the old night elf lands, among the forests of Ashenvale, Felwood and Azshara. Water is fouled, trees sicken and beasts are twisted around them. The elves trying to heal those woods are contending with a corruption that first took hold among their own people." },
        { "Ten thousand years is a long time to tend a forest, traveller. It is a bitter length of time to find its old betrayers still at work within it." },
      },
    },
    ["scarlet-crusade"] = {
      title = "The Scarlet Crusade", kind = "faction", chapter = "peoples", portrait = 2471,
      unlock = { { kill = 1506 }, { kill = 1507 }, { kill = 1535 }, { kill = 1536 }, { kill = 1537 }, { kill = 1538 }, { kill = 1539 }, { kill = 1540 }, { kill = 1660 }, { kill = 1826 }, { kill = 1827 }, { kill = 1831 }, { kill = 1832 }, { kill = 1833 }, { kill = 1834 }, { kill = 1835 }, { kill = 1837 }, { kill = 1838 }, { kill = 1839 }, { kill = 1840 }, { kill = 1841 }, { kill = 1845 }, { kill = 1846 }, { kill = 1883 }, { kill = 1884 }, { kill = 1885 }, { kill = 3975 }, { kill = 3976 }, { kill = 3977 }, { kill = 3983 }, { kill = 4280 }, { kill = 4281 }, { kill = 4282 }, { kill = 4283 }, { kill = 4284 }, { kill = 4285 }, { kill = 4286 }, { kill = 4287 }, { kill = 4288 }, { kill = 4289 }, { kill = 4290 }, { kill = 4291 }, { kill = 4292 }, { kill = 4293 }, { kill = 4294 }, { kill = 4295 }, { kill = 4296 }, { kill = 4297 }, { kill = 4298 }, { kill = 4299 }, { kill = 4300 }, { kill = 4301 }, { kill = 4302 }, { kill = 4303 }, { kill = 4306 }, { kill = 4493 }, { kill = 4494 }, { kill = 4540 }, { kill = 4542 }, { kill = 4543 }, { kill = 6487 }, { kill = 6575 }, { kill = 9447 }, { kill = 9448 }, { kill = 9449 }, { kill = 9450 }, { kill = 9451 }, { kill = 9452 }, { kill = 10418 }, { kill = 10419 }, { kill = 10420 }, { kill = 10421 }, { kill = 10422 }, { kill = 10423 }, { kill = 10424 }, { kill = 10425 }, { kill = 10426 }, { kill = 10605 }, { kill = 10608 }, { kill = 10812 }, { kill = 10813 }, { kill = 11043 }, { kill = 11054 }, { kill = 12128 }, { kill = 12337 }, { kill = 12352 }, { kill = 13118 }, { kill = 15162 } },
      also = { "scourge", "argent-dawn", "scarlet-monastery", "whitemane-and-mograine" },
      text = {
        { "When Prince Arthas murdered his father and Lordaeron fell to the plague, the paladins of the Silver Hand who survived gathered what they could and swore to burn the dead from the land. Three founded the Crusade: High General Abbendis, High Inquisitor Isillien and the Highlord Mograine, the Ashbringer, and in its first days, those who were there say, it was a noble order. They became the Scarlet Crusade, and they have been burning ever since: the dead, and the living who look at them wrongly." },
        { "They trust no one. Any stranger might carry the plague, any elf or dwarf might be a spy, and the Forsaken are simply the enemy. From the Monastery in Tirisfal, from Hearthglen and Tyr's Hand, they wage a war that no one else is invited to win. Their Grand Crusader, Saidan Dathrohan, rules them from Stratholme, and their Grand Inquisitor, Isillien, from Hearthglen." },
        { "The Crusade fights the Scourge, but corruption within its own ranks gives another reason to distrust it. Ask in the Monastery about Highlord Mograine and his blade, the Ashbringer, and listen carefully to who falls silent. And ask the Argent Dawn what they found when they looked closely at the Grand Crusader himself." },
      },
    },
    ["scourge"] = {
      title = "The Scourge", kind = "faction", chapter = "peoples", portrait = 200,
      unlock = { { kill = 1520 }, { kill = 1522 }, { kill = 1523 }, { kill = 1525 }, { kill = 1526 }, { kill = 1527 }, { kill = 1528 }, { kill = 1529 }, { kill = 1530 }, { kill = 1654 }, { kill = 1655 }, { kill = 1656 }, { kill = 1657 }, { kill = 1658 }, { kill = 1753 }, { kill = 1783 }, { kill = 1784 }, { kill = 1785 }, { kill = 1787 }, { kill = 1788 }, { kill = 1789 }, { kill = 1791 }, { kill = 1793 }, { kill = 1794 }, { kill = 1795 }, { kill = 1796 }, { kill = 1802 }, { kill = 1805 }, { kill = 1847 }, { kill = 1850 }, { kill = 1852 }, { kill = 1946 }, { kill = 4474 }, { kill = 4475 }, { kill = 6412 }, { kill = 7327 }, { kill = 7328 }, { kill = 7329 }, { kill = 7332 }, { kill = 7333 }, { kill = 7334 }, { kill = 7340 }, { kill = 7341 }, { kill = 7342 }, { kill = 7343 }, { kill = 7344 }, { kill = 7345 }, { kill = 7346 }, { kill = 7347 }, { kill = 7348 }, { kill = 7349 }, { kill = 7351 }, { kill = 7352 }, { kill = 7355 }, { kill = 7357 }, { kill = 7358 }, { kill = 8477 }, { kill = 8523 }, { kill = 8524 }, { kill = 8525 }, { kill = 8526 }, { kill = 8527 }, { kill = 8528 }, { kill = 8529 }, { kill = 8530 }, { kill = 8531 }, { kill = 8532 }, { kill = 8534 }, { kill = 8535 }, { kill = 8538 }, { kill = 8539 }, { kill = 8540 }, { kill = 8541 }, { kill = 8542 }, { kill = 8543 }, { kill = 8544 }, { kill = 8545 }, { kill = 8555 }, { kill = 8556 }, { kill = 8557 }, { kill = 8558 }, { kill = 8567 }, { kill = 8585 }, { kill = 10381 }, { kill = 10382 }, { kill = 10383 }, { kill = 10390 }, { kill = 10391 }, { kill = 10393 }, { kill = 10394 }, { kill = 10405 }, { kill = 10406 }, { kill = 10407 }, { kill = 10408 }, { kill = 10409 }, { kill = 10411 }, { kill = 10412 }, { kill = 10413 }, { kill = 10414 }, { kill = 10416 }, { kill = 10417 }, { kill = 10432 }, { kill = 10433 }, { kill = 10435 }, { kill = 10436 }, { kill = 10437 }, { kill = 10439 }, { kill = 10440 }, { kill = 10463 }, { kill = 10478 }, { kill = 10480 }, { kill = 10481 }, { kill = 10482 }, { kill = 10485 }, { kill = 10486 }, { kill = 10487 }, { kill = 10488 }, { kill = 10489 }, { kill = 10491 }, { kill = 10495 }, { kill = 10506 }, { kill = 10507 }, { kill = 10508 }, { kill = 10516 }, { kill = 10580 }, { kill = 10698 }, { kill = 10699 }, { kill = 10801 }, { kill = 10808 }, { kill = 10809 }, { kill = 10816 }, { kill = 10821 }, { kill = 10825 }, { kill = 10826 }, { kill = 10876 }, { kill = 10901 }, { kill = 10938 }, { kill = 10939 }, { kill = 10943 }, { kill = 10946 }, { kill = 10947 }, { kill = 10951 }, { kill = 10952 }, { kill = 10953 }, { kill = 10954 }, { kill = 11027 }, { kill = 11030 }, { kill = 11058 }, { kill = 11075 }, { kill = 11076 }, { kill = 11077 }, { kill = 11078 }, { kill = 11082 }, { kill = 11121 }, { kill = 11142 }, { kill = 11143 }, { kill = 11197 }, { kill = 11258 }, { kill = 11290 }, { kill = 11291 }, { kill = 11551 }, { kill = 11598 }, { kill = 11622 }, { kill = 12208 }, { kill = 12248 }, { kill = 12250 }, { kill = 12261 }, { kill = 12262 }, { kill = 12263 }, { kill = 14486 }, { kill = 14489 }, { kill = 14516 }, { kill = 14518 }, { kill = 14519 }, { kill = 14520 }, { kill = 14521 }, { kill = 14684 }, { kill = 14686 }, { kill = 14695 }, { kill = 15928 }, { kill = 15929 }, { kill = 15930 }, { kill = 15931 }, { kill = 15932 }, { kill = 15936 }, { kill = 15954 }, { kill = 15956 }, { kill = 15978 }, { kill = 15979 }, { kill = 15989 }, { kill = 15990 }, { kill = 16011 }, { kill = 16017 }, { kill = 16018 }, { kill = 16020 }, { kill = 16021 }, { kill = 16022 }, { kill = 16024 }, { kill = 16025 }, { kill = 16028 }, { kill = 16029 }, { kill = 16060 }, { kill = 16061 }, { kill = 16062 }, { kill = 16063 }, { kill = 16064 }, { kill = 16065 }, { kill = 16067 }, { kill = 16101 }, { kill = 16102 }, { kill = 16119 }, { kill = 16120 }, { kill = 16125 }, { kill = 16126 }, { kill = 16145 }, { kill = 16146 }, { kill = 16154 }, { kill = 16156 }, { kill = 16163 }, { kill = 16165 }, { kill = 16167 }, { kill = 16168 }, { kill = 16184 }, { kill = 16194 }, { kill = 16215 }, { kill = 16216 }, { kill = 16244 }, { kill = 16290 }, { kill = 16360 }, { kill = 16375 }, { kill = 16390 }, { kill = 16427 }, { kill = 16428 }, { kill = 16429 }, { kill = 16441 }, { kill = 16446 }, { kill = 16447 }, { kill = 16451 }, { kill = 16452 }, { kill = 16573 }, { kill = 16861 }, { kill = 16981 }, { kill = 16982 }, { kill = 16983 }, { kill = 16984 } },
      also = { "cult-of-the-damned", "scarlet-crusade", "argent-dawn", "fall-of-lordaeron", "the-forsaken" },
      text = {
        { "The Scourge is the army of the Lich King, a power that sits on a throne of ice in Northrend and speaks into the minds of the dead. It came to Lordaeron as a plague, carried in the grain by a cult of the Lich King's worshippers, and everyone who ate of it and died rose again to serve him. The kingdom's own prince, Arthas, finished the work, and later returned to Northrend, where he claimed the Frozen Throne." },
        { "What he left behind is the Plaguelands: a kingdom of the dead, with ghouls in the fields, abominations stitched together from corpses, and the plague cauldrons poisoning the earth. Stratholme is theirs, under the Baron Rivendare, and Scholomance, and the farmsteads of half the north. Now a black citadel hangs in the sky over the Eastern Plaguelands, Naxxramas, and its master is the lich Kel'Thuzad." },
        { "The dead do not tire, and they do not stop. The Argent Dawn, the Scarlet Crusade and the Forsaken all fight them, despite the distrust between them. At Light's Hope Chapel, the Dawn and Crusade have agreed to cooperate against Naxxramas." },
      },
    },
    ["sentinels"] = {
      title = "The Sentinels", kind = "faction", chapter = "peoples", portrait = 2035,
      unlock = { { npc = 2081 }, { npc = 2155 }, { npc = 2302 }, { npc = 2930 }, { npc = 3519 }, { npc = 3571 }, { npc = 3639 }, { npc = 3657 }, { npc = 3691 }, { npc = 3694 }, { npc = 3880 }, { npc = 3885 }, { npc = 3936 }, { npc = 4079 }, { npc = 4080 }, { npc = 4262 }, { npc = 5916 }, { npc = 6086 }, { npc = 6087 }, { npc = 7939 }, { npc = 7956 }, { npc = 7957 }, { npc = 7999 }, { npc = 8015 }, { npc = 8396 }, { npc = 8397 }, { npc = 10604 }, { npc = 10606 }, { npc = 11276 }, { npc = 11711 }, { npc = 11806 }, { npc = 12048 }, { npc = 12160 }, { npc = 12429 }, { npc = 12856 }, { npc = 12896 }, { npc = 12897 }, { npc = 13327 }, { npc = 13336 }, { npc = 13427 }, { npc = 14378 }, { npc = 14379 }, { npc = 14380 }, { npc = 14715 }, { npc = 14733 }, { npc = 14753 }, { npc = 15451 }, { npc = 15457 }, { read = { "The Sentinels and the Long Vigil", "파수꾼과 기나긴 철야", "Les Sentinelles et la longue veille", "Die Schildwachen und die lange Wacht", "哨兵和长期流放", "Los centinelas y la gran vigilia", "Часовые и долгое бдение", "As Sentinelas e a Longa Vigília", "哨兵和長期流放" } } },
      also = { "tyrande-whisperwind", "shandris-feathermoon", "night-elves", "elune", "cenarius" },
      text = {
        { "When the druids went to sleep in the Emerald Dream, someone had to keep the forests. Tyrande Whisperwind, High Priestess of Elune, gathered her sisters into an army of warrior women and called them the Sentinels. She asked Malfurion not to leave her for the Dream. He went all the same, and she kept watch." },
        { "They kept it for ten thousand years, patrolling Ashenvale by night while the druids slept, with Cenarius's sons, the Keepers of the Grove, and his shy daughters, the dryads, to call on in need. Tyrande never stopped fearing that the Legion would come back. In the end she was right." },
        { "The druids are awake now, and the Sentinels have not stood down. You will find them at every night elf post from Teldrassil to Feathermoon, under their general, Shandris Feathermoon. If one of them looks at you as though she has been on watch for a very long time, traveller, she may well have been." },
      },
    },
    ["shadow-council"] = {
      title = "The Shadow Council", kind = "faction", chapter = "peoples", portrait = 10198,
      unlock = { { npc = 3216 }, { npc = 4198 }, { npc = 9516 }, { npc = 14522 }, { kill = 2318 }, { kill = 2320 }, { kill = 2336 }, { kill = 2337 }, { kill = 2598 }, { kill = 3195 }, { kill = 3196 }, { kill = 3197 }, { kill = 3198 }, { kill = 3199 }, { kill = 3204 }, { kill = 3379 }, { kill = 3380 }, { kill = 3660 }, { kill = 3664 }, { kill = 3725 }, { kill = 3727 }, { kill = 3728 }, { kill = 3730 }, { kill = 3879 }, { kill = 4663 }, { kill = 4664 }, { kill = 4665 }, { kill = 4666 }, { kill = 4667 }, { kill = 4668 }, { kill = 4705 }, { kill = 5822 }, { kill = 6004 }, { kill = 6005 }, { kill = 6006 }, { kill = 6007 }, { kill = 6008 }, { kill = 6009 }, { kill = 7112 }, { kill = 7113 }, { kill = 7114 }, { kill = 7115 }, { kill = 7118 }, { kill = 7120 }, { kill = 7125 }, { kill = 7126 }, { kill = 7664 }, { kill = 7665 }, { kill = 7666 }, { kill = 7667 }, { kill = 9516 }, { kill = 9517 }, { kill = 9860 }, { kill = 9861 }, { kill = 9862 }, { kill = 9877 }, { kill = 11322 }, { kill = 11323 }, { kill = 11324 }, { kill = 11518 }, { kill = 11519 }, { kill = 12319 }, { kill = 12320 }, { kill = 13019 }, { kill = 14522 }, { kill = 14523 }, { read = { "Kil'jaeden and the Shadow Pact", "킬제덴과 암흑 조약", "Kil'jaeden et le Pacte des ombres", "Kil’jaeden und der Schattenpakt", "基尔加丹和阴影契约", "Kil'jaeden y el Pacto de las Sombras", "Кил'джеден и Пакт Тьмы", "Kil'jaeden e o Pacto Sombrio", "基爾加丹和陰影契約" } } },
      also = { "jaedenar", "burning-legion", "draenor", "orcs", "warlocks", "the-first-war" },
      text = {
        { "The old Horde was never quite ruled by its warchiefs. Behind them stood the Shadow Council, a secret circle the demon Kil'jaeden helped Gul'dan found on Draenor, to steer the clans and spread the warlocks' magic among them. It was the Council that summoned Mannoroth for the chieftains to drink from, the Council that set Blackhand up as warchief to do as he was told, and the Council, with Medivh, that opened the Dark Portal." },
        { "Doomhammer broke its hold when he killed Blackhand and took the Horde for himself, and Gul'dan died torn apart by the demons he loosed at the Tomb of Sargeras. The name outlived them both. Warlocks still gather under it, orcs and Forsaken among them, and still deal with the Legion." },
        { "Their greatest hold now is Jaedenar in Felwood, where Shadow Lord Fel'dan makes his pacts in the Shadow Hold below. While the druids labour to cleanse the forest, the Council's warlocks are still gathering beneath its roots." },
      },
    },
    ["silithid"] = {
      title = "The Silithid", kind = "creature", chapter = "peoples", portrait = 2731,
      unlock = { { kill = 3250 }, { kill = 3251 }, { kill = 3252 }, { kill = 3253 }, { kill = 3503 }, { kill = 4130 }, { kill = 4131 }, { kill = 4132 }, { kill = 4133 }, { kill = 4196 }, { kill = 5244 }, { kill = 5245 }, { kill = 5246 }, { kill = 5247 }, { kill = 5441 }, { kill = 5450 }, { kill = 5451 }, { kill = 5452 }, { kill = 5453 }, { kill = 5454 }, { kill = 5455 }, { kill = 5456 }, { kill = 5457 }, { kill = 5458 }, { kill = 5459 }, { kill = 5460 }, { kill = 5781 }, { kill = 6551 }, { kill = 6552 }, { kill = 6553 }, { kill = 6554 }, { kill = 6555 }, { kill = 7769 }, { kill = 9496 }, { kill = 9498 }, { kill = 10040 }, { kill = 10041 }, { kill = 11698 }, { kill = 11721 }, { kill = 11722 }, { kill = 11723 }, { kill = 11724 }, { kill = 11725 }, { kill = 11726 }, { kill = 11727 }, { kill = 11728 }, { kill = 11729 }, { kill = 11730 }, { kill = 11731 }, { kill = 11732 }, { kill = 11733 }, { kill = 11734 }, { kill = 13136 }, { kill = 13301 }, { kill = 15246 }, { kill = 15247 }, { kill = 15249 }, { kill = 15250 }, { kill = 15252 }, { kill = 15264 }, { kill = 15277 }, { kill = 15311 }, { kill = 15316 }, { kill = 15317 }, { kill = 15318 }, { kill = 15319 }, { kill = 15320 }, { kill = 15323 }, { kill = 15324 }, { kill = 15325 }, { kill = 15327 }, { kill = 15336 }, { kill = 15343 }, { kill = 15355 }, { kill = 15387 }, { kill = 15414 }, { kill = 15421 }, { kill = 15422 }, { kill = 15424 }, { kill = 15449 }, { kill = 15521 }, { kill = 15537 }, { kill = 15538 }, { kill = 15546 }, { kill = 15555 }, { kill = 15620 }, { kill = 15743 }, { kill = 15744 }, { kill = 15747 }, { kill = 15748 }, { kill = 15749 }, { kill = 15750 }, { kill = 15751 }, { kill = 15752 }, { kill = 15753 }, { kill = 15754 }, { kill = 15756 }, { kill = 15757 }, { kill = 15758 }, { kill = 15759 }, { kill = 15806 }, { kill = 15807 }, { kill = 15808 }, { kill = 15810 }, { kill = 15811 }, { kill = 15812 }, { kill = 15813 }, { kill = 15814 }, { kill = 15815 }, { kill = 15816 }, { kill = 15817 }, { kill = 15934 } },
      also = { "cenarion-circle", "twilights-hammer" },
      text = {
        { "Silithid occupy vast hives beneath southern Kalimdor. Their wasps can be the size of hounds, their reavers as large as ogres, and their tunnelers powerful enough to collapse caves. Hives have appeared in the Barrens, Thousand Needles, Feralas, Tanaris and Un'Goro. Silithus holds the greatest concentration." },
        { "The qiraji of Ahn'Qiraj command them. A thousand years ago their swarms drove north in the War of the Shifting Sands, until night elves and dragons sealed the city behind the Scarab Wall. The Cenarion Circle believes an older power beneath Ahn'Qiraj directs both masters and servants." },
        { "Movement around the hives now suggests preparation for a great expansion. The Circle watches closely. For a traveller studying these insects, the work includes finding out how far their tunnels and their masters' purposes already reach." },
      },
    },
    ["skyborne"] = {
      title = "The Skyborne", kind = "faction", chapter = "peoples",
      unlock = { { people = "Skyborne" } },
      also = { "zephras-isle", "the-shalnan", "the-high-order", "the-windshapers", "dire-maul" },
      text = {
        { "The Skyborne call themselves the shen'dorei, the hidden people, and until they came down from the sky the League did not know they existed. Their ancestors lived in Eldre'Thalas, the city the ogres now call Dire Maul, and rose against a prince who meant to bind a demon to feed their magic. Led by the masked Shal'nan, they fled by sea, and wind spirits lifted their island out of the world and into Skywall." },
        { "Zephras Isle hung there for ages. Now the wind spirits are gone, the isle is failing, and the Skyborne have come down to find help. The High Order looks for the arcane lore their people lost and goes to Dalaran's mages. The Windshapers look for their missing spirits and go to the shamans of the Horde." },
        { "They are few, traveller, and they know it. A Skyborne who seems careful with every life, their own included, is reckoning with how many of their people there are left to lose." },
      },
    },
    ["southsea-freebooters"] = {
      title = "The Southsea Freebooters", kind = "faction", chapter = "peoples", portrait = 3829,
      unlock = { { kill = 3381 }, { kill = 3382 }, { kill = 3383 }, { kill = 3384 }, { kill = 3467 }, { kill = 7855 }, { kill = 7856 }, { kill = 7857 }, { kill = 7858 }, { kill = 15685 } },
      also = { "steamwheedle-cartel" },
      text = {
        { "The Southsea Freebooters are pirates of the warm seas of Kalimdor, and they prey on the goblins above all, because the goblins have the most worth stealing. They hold camps along the Merchant Coast of the Barrens, south of Ratchet, and in the coves of Tanaris, and their ships lie in wait for anything leaving a Steamwheedle port." },
        { "Their captain on the Merchant Coast is Baron Longshore, and Gazlowe of Ratchet has a price on his head. The goblins of Gadgetzan pay just as well for pirates of Tanaris. There is no great story behind them, no exiled king or lost cause. They are thieves who own boats, and the sea is wide." },
      },
    },
    ["steamwheedle-cartel"] = {
      title = "The Steamwheedle Cartel", kind = "faction", chapter = "peoples", portrait = 7167,
      unlock = { { npc = 2496 }, { npc = 7564 }, { npc = 3391 }, { faction = 21, standing = 5 }, { faction = 369, standing = 5 }, { faction = 470, standing = 5 }, { faction = 577, standing = 5 } },
      also = { "venture-company", "southsea-freebooters" },
      text = {
        { "The Steamwheedle Cartel trades with both Alliance and Horde. Its goblins have found that people willing to fight each other still need supplies, and that both sets of coins are worth taking. Their towns offer a place to conduct the business." },
        { "Booty Bay, Gadgetzan, Ratchet and Everlook span jungle, desert, coast and snow. Bruisers enforce peace within them. Revilgaz oversees Booty Bay, while Gazlowe has work for visitors in Ratchet. Each port has troubles that trade alone will not settle." },
        { "A traveller can buy provisions, find employment and meet the other faction without immediately reaching for a weapon. The cartel charges for much of what it offers, but a neutral stopping place has value in a world whose roads run through so many wars." },
      },
    },
    ["syndicate"] = {
      title = "The Syndicate", kind = "faction", chapter = "peoples", portrait = 3706,
      unlock = { { kill = 2240 }, { kill = 2241 }, { kill = 2242 }, { kill = 2243 }, { kill = 2244 }, { kill = 2245 }, { kill = 2246 }, { kill = 2247 }, { kill = 2260 }, { kill = 2261 }, { kill = 2306 }, { kill = 2319 }, { kill = 2423 }, { kill = 2586 }, { kill = 2587 }, { kill = 2588 }, { kill = 2589 }, { kill = 2590 }, { kill = 2591 }, { kill = 2597 }, { kill = 2599 }, { kill = 2638 } },
      also = {  },
      text = {
        { "Alterac was the kingdom that sold the Alliance to the Horde in the Second War, and when the war was won its lands were taken and its nobles stripped of their titles. Some of those nobles have never accepted it. They call themselves the Syndicate, and they are thieves and cutthroats under a lord's banner." },
        { "Their leader was Lord Aliden Perenolde, son of the traitor king, and his dream was to put the orcs back in chains, as they were in the days of the internment camps. His people hold the ruined town of Strahnbrad in Alterac and Durnholde Keep in Hillsbrad, where they rob Southshore's roads and plot against its magistrate, and in Arathi Lord Falconcrest has seized the ruins of Stromgarde itself." },
        { "They are many and they are not very good. The assassins of Ravenholdt, who have fought them for years, call them hacks, and the Forsaken put a price on every head. But a great many thieves can still do a great deal of harm, and the Syndicate do." },
      },
    },
    ["tauren"] = {
      title = "The Tauren", kind = "faction", chapter = "peoples",
      unlock = { { people = "Tauren" }, { read = { "Mists of Dawn", "여명의 안개", "Brumes de l'Aube", "Nebel der Dämmerung", "黎明之雾", "Niebla del Amanecer", "Рассветные Туманы", "Brumas da Aurora", "黎明之霧" } }, { read = { "Sorrow of the Earthmother", "대지모신의 슬픔", "La tristesse de la Terre-mère", "Trauer der Erdenmutter", "大地母亲的悲伤", "Dolor de la Madre Tierra", "Скорбь Матери Земли", "Mágoa da Mãe Terra", "大地母親的悲傷" } } },
      also = { "cairne-bloodhoof", "thunder-bluff", "mulgore", "earth-mother", "centaurs", "grimtotem" },
      text = {
        { "The tauren are among the oldest peoples of Kalimdor's plains. For generations their tribes wandered, following the herds and the ways of the Earth Mother, while the centaurs harried them from one camp to the next. Cairne Bloodhoof gathered many of the tribes together, and when Thrall's orcs came ashore, they helped the tauren drive the centaurs back and reach the grasslands of Mulgore." },
        { "There the tauren raised Thunder Bluff on its mesas and settled, though they keep the habits of the road. They honour the Earth Mother, whose eyes are An'she, the sun, and Mu'sha, the moon. Their shamans speak with the spirits and their druids walk the Dream with the Cenarion Circle. Not every tribe follows Cairne. The Grimtotem keep their own counsel and their own grudges." },
        { "They are slow to anger and very hard to stop once angered, traveller. The League's archaeologists have found them the most patient hosts on Kalimdor, provided nobody digs where their ancestors are buried." },
      },
    },
    ["timbermaw"] = {
      title = "The Timbermaw", kind = "faction", chapter = "peoples", portrait = 2000,
      unlock = { { npc = 11516 }, { npc = 11552 }, { npc = 11553 }, { npc = 11554 }, { npc = 11555 }, { npc = 11556 }, { npc = 11557 }, { npc = 11558 }, { faction = 576, standing = 5 }, { area = 1769 } },
      also = { "furbolgs", "felwood", "winterspring", "moonglade" },
      text = {
        { "Of all the furbolg tribes of the north, only the Timbermaw have kept their minds. The corruption that seeped out of Felwood turned the Deadwood and the Winterfall into the snarling creatures you meet on the roads, and the Timbermaw had to watch it happen to their kin. They held on in their tunnels under the mountains between Felwood, Moonglade and Winterspring, and held them against everyone." },
        { "They have reason to be careful. Most travellers now kill any furbolg on sight without asking which tribe it belongs to, so the Timbermaw trust very few. Help them against the corrupted tribes and they will begin, slowly, to let you through their hold. A demon was found at the root of the Winterfall's madness. Killing it gave that tribe, in the Timbermaw's words, a chance at survival." },
        { "They take no pleasure in fighting their own brethren. One of their scouts asks those who fight for him to spare him the details. Earn their trust in full and they will send an offering of peace to your own king. It is the most civil thing a people under siege has offered anyone in this ledger." },
      },
    },
    ["rockjaw-troggs"] = {
      title = "The Troggs", kind = "creature", chapter = "peoples", portrait = 606,
      unlock = { { kill = 707 }, { kill = 724 }, { kill = 1115 }, { kill = 1116 }, { kill = 1117 }, { kill = 1118 }, { kill = 1161 }, { kill = 1162 }, { kill = 1163 }, { kill = 1164 }, { kill = 1165 }, { kill = 1166 }, { kill = 1167 }, { kill = 1197 }, { kill = 1393 }, { kill = 1718 }, { kill = 2158 }, { kill = 2159 }, { kill = 2160 }, { kill = 2892 }, { kill = 2893 }, { kill = 2894 }, { kill = 4850 }, { kill = 4851 }, { kill = 4852 }, { kill = 4853 }, { kill = 4854 }, { kill = 4855 }, { kill = 6206 }, { kill = 6207 }, { kill = 6211 }, { kill = 6329 }, { kill = 6733 }, { kill = 7175 }, { kill = 7320 }, { kill = 7321 }, { kill = 10987 }, { kill = 11318 } },
      also = { "ironforge", "kharanos", "gnomeregan", "platinum-discs", "uldaman" },
      text = {
        { "The Titan records in Uldaman describe troggs as a failed result of the earthen's making. They were sealed underground until dwarven excavations opened their halls. Our search for our own beginnings released creatures whose origins were uncomfortably close to them." },
        { "The Rockjaw occupy Dun Morogh's quarries and caves, the Stonesplinter Loch Modan's valleys, and the Stonevault Uldaman itself. Troggs also invaded Gnomeregan. Others have appeared in Darkshore and beneath Orgrimmar, though their route across the sea remains uncertain." },
        { "Mountaineers ask for help defending roads and settlements, and the gnomes still fight them in their capital. A traveller carrying this ledger will find Ironforge's scholars interested in trogg history. Those guarding a mine have a more immediate concern with keeping them out." },
      },
    },
    ["twilights-hammer"] = {
      title = "The Twilight's Hammer", kind = "faction", chapter = "peoples", portrait = 2882,
      unlock = { { kill = 2338 }, { kill = 2339 }, { kill = 4809 }, { kill = 4810 }, { kill = 4811 }, { kill = 4812 }, { kill = 4813 }, { kill = 4814 }, { kill = 4832 }, { kill = 5860 }, { kill = 5861 }, { kill = 5862 }, { kill = 8419 }, { kill = 8912 }, { kill = 8913 }, { kill = 8914 }, { kill = 8915 }, { kill = 9398 }, { kill = 11803 }, { kill = 11804 }, { kill = 11880 }, { kill = 11881 }, { kill = 11882 }, { kill = 11883 }, { kill = 14479 }, { kill = 15200 }, { kill = 15201 }, { kill = 15213 }, { kill = 15308 }, { kill = 15541 }, { kill = 15542 } },
      also = { "silithid" },
      text = {
        { "Cho'gall's Twilight's Hammer began as an orc clan in the Second War, led by a two-headed ogre mage. It fought in the belief that the world should end. The old Horde's defeat left that purpose alive in a cult with followers from many peoples." },
        { "The cult worships the Old Gods, ancient powers beneath the earth. Its members serve a horror in Blackfathom Deeps, gather at idols in the Searing Gorge and summon elemental lords in Silithus." },
      },
    },
    ["venture-company"] = {
      title = "The Venture Company", kind = "faction", chapter = "peoples", portrait = 7202,
      unlock = { { kill = 674 }, { kill = 675 }, { kill = 676 }, { kill = 677 }, { kill = 921 }, { kill = 1094 }, { kill = 1095 }, { kill = 1096 }, { kill = 1097 }, { kill = 2975 }, { kill = 2976 }, { kill = 2977 }, { kill = 2978 }, { kill = 2979 }, { kill = 3282 }, { kill = 3283 }, { kill = 3284 }, { kill = 3285 }, { kill = 3286 }, { kill = 3988 }, { kill = 3989 }, { kill = 3991 }, { kill = 3992 }, { kill = 3993 }, { kill = 4070 }, { kill = 4260 }, { kill = 7067 }, { kill = 7307 }, { kill = 7308 } },
      also = { "steamwheedle-cartel", "mulgore" },
      text = {
        { "If a thing can be dug up, cut down or pumped out of the ground, the Venture Company is already there with a shredder. It is a goblin concern, a trading company with no loyalty to anyone but its board, and its business is taking what belongs to other people and selling it before they notice." },
        { "On Kalimdor they are everywhere. They clear-cut the forests of Stonetalon, they have mined the cliffs of Mulgore against the tauren's express refusal and fouled the water wells while they were at it, and in the Barrens they have pumped the Sludge Fen into a black pool of oil. Across the sea they log the jungle of Stranglethorn and dig in its hills." },
        { "Their own kind think little of them. The goblins of the Steamwheedle Cartel, who keep the neutral ports, will pay good coin to anyone who makes the Company's life difficult, and so, I imagine, will every tauren in Mulgore." },
      },
    },
    ["wildkin"] = {
      title = "The Wildkin", kind = "creature", chapter = "peoples", portrait = 5927,
      unlock = { { npc = 12144 }, { kill = 2927 }, { kill = 2928 }, { kill = 2929 }, { kill = 7450 }, { kill = 7451 }, { kill = 7452 }, { kill = 7453 }, { kill = 7454 }, { kill = 7808 }, { kill = 10157 }, { kill = 10158 }, { kill = 10159 }, { kill = 10160 }, { kill = 12138 } },
      also = { "elune", "night-elves", "winterspring", "darkshore", "the-hinterlands" },
      text = {
        { "The great owl-bears of the north are called wildkin, or moonkin, and the night elves treat them with a reverence travellers do not always share. They are rumoured to have been made by Elune herself, and some say they were her pets. A night elf scholar who studies their feathers finds a magic in them that the creatures do not wield so much as carry, part of their very nature." },
        { "They are capable of great gentleness and of great ferocity, especially when something they hold important is threatened, and in Winterspring they are said to guard secrets of the night elves. Some there have gone mad, the reports say, from too long near the very thing they protect." },
        { "Lately the gentle ones have grown fewer. The moonkin of Darkshore are drawn to a great red crystal in the eastern hills, and the Sentinels of Auberdine no longer think them harmless. I would give any owl-bear a wide berth, traveller, and a mad one a wider." },
      },
    },
    ["wintersaber-trainers"] = {
      title = "The Wintersaber Trainers", kind = "faction", chapter = "peoples", portrait = 10190,
      unlock = { { faction = 589, standing = 5 }, { npc = 10618 }, { area = 2241 } },
      also = { "winterspring", "night-elves", "sentinels" },
      text = {
        { "High on Frostsaber Rock in northern Winterspring, a handful of night elves raise the white sabers of the north. Their leader, Rivern Frostwind, keeps to himself. His presence goes unnoticed by most, he says, which suits him." },
        { "The cats are not easily earned. Rivern begins anyone who wants one by sending them for meat, from the chimaera and the shardtooth bears, to feed the young sabers in training, and then for help against the Winterfall furbolgs who trouble the rock. It is a long apprenticeship, and few finish it." },
        { "Those who do ride out of Winterspring on a frostsaber, which I am told is worth every errand. The cats, for their part, seem to think the arrangement was their idea." },
      },
    },
    ["worgen"] = {
      title = "The Worgen", kind = "creature", chapter = "peoples", portrait = 657,
      unlock = { { kill = 205 }, { kill = 206 }, { kill = 533 }, { kill = 898 }, { kill = 920 }, { kill = 1769 }, { kill = 1770 }, { kill = 1779 }, { kill = 1782 }, { kill = 1892 }, { kill = 1893 }, { kill = 1896 }, { kill = 1924 }, { kill = 2529 }, { kill = 3529 }, { kill = 3531 }, { kill = 3533 }, { kill = 3851 }, { kill = 3853 }, { kill = 3854 }, { kill = 3855 }, { kill = 3857 }, { kill = 3859 }, { kill = 3863 }, { kill = 3914 }, { kill = 3927 }, { kill = 5097 } },
      also = {  },
      text = {
        { "Arugal summoned worgen from another world as Dalaran's defenders fell to the Scourge. The wolf-men attacked the dead, then turned on the living. The mage retreated to Shadowfang Keep, called them his children and cursed Pyrewood, whose people are human by day and worgen by night." },
        { "Duskwood presents a different trail. The Night Watch reports their sudden appearance in a mine south of Darkshire. Accounts point towards the Scythe of Elune, an old elven relic carried into the forest by someone who did not understand its power." },
        { "The creatures are strong, clever and able to run on all fours despite their upright form. Keep the two trails distinct, traveller. Knowing who brought them into one forest has not explained their appearance in the other." },
      },
    },
    ["gathilzogg"] = {
      title = "Gath'Ilzogg", kind = "figure", chapter = "redridge", portrait = 6050,
      unlock = { { kill = 334 }, { quest = 169 } },
      also = { "stonewatch-keep", "blackrock-clan", "black-dragonflight" },
      text = {
        { "Stonewatch was built to defend Redridge. Gath'Ilzogg's Blackrock warriors have made it the stronghold from which they raid Lakeshire instead, carrying the mountain's war down into the farms and roads around Lake Everstill." },
        { "Magistrate Solomon has offered a reward for his head. The keep must be reclaimed as well as its commander killed. Gath'Ilzogg's death is only the first step in that work. For Lakeshire, a fortress on the skyline has become a measure of how much of its own country the town can no longer reach." },
      },
    },
    ["lakeshire"] = {
      title = "Lakeshire", kind = "place", chapter = "redridge",
      unlock = { { area = 69 } },
      also = { "redridge-mountains", "stonewatch-keep", "katrana-prestor", "black-dragonflight" },
      text = {
        { "Lakeshire is a town of timber houses on the shore of Lake Everstill, with an inn, a town hall and a bridge across the water that the townsfolk are still rebuilding: in the last invasion they melted down their iron to make swords, and the gnolls stole the shipment that was meant to replace it." },
        { "Its magistrate, Solomon, is a careful man with a great many troubles. The Blackrock hold the keep to the north and pen his people in their town. He has written to Stormwind for help, and the answer came back that there were not enough soldiers to spare on speculation. He has since learned what really drives the orcs of Blackrock, and who in Stormwind did not want him heard. Lakeshire, I suspect, will not forget it." },
      },
    },
    ["morganth"] = {
      title = "Morganth", kind = "figure", chapter = "redridge", portrait = 3383,
      unlock = { { kill = 397 }, { area = 96 } },
      also = { "gnolls", "worgen", "redridge-mountains" },
      text = {
        { "In the eastern foothills of Redridge stands a lonely tower, Ilgalar, and in it lives a warlock named Morganth, who has bent the Shadowhide gnolls to his service through enchanted pendants. Lakeshire's law counts him an enemy of the kingdom, and anyone who aids him a criminal." },
        { "A mage of Elwynn, Theocritus of Tower Azora, has been listening to Morganth's gnolls through those same pendants, and what he has heard frightens him: Morganth is searching for an old elven relic called the Scythe of Elune, and may have found it. If he has, Theocritus says, all Stormwind will feel it. The same relic is spoken of in Duskwood, in connection with the worgen. I note it, and I do not like it." },
      },
    },
    ["redridge-mountains"] = {
      title = "Redridge Mountains", kind = "place", chapter = "redridge",
      unlock = { { area = 44 } },
      also = { "lakeshire", "stonewatch-keep", "blackrock-clan", "gnolls", "morganth" },
      text = {
        { "Redridge takes its name from the rust-red stone beneath its pine woods. Lake Everstill lies among the hills, with Lakeshire on its western shore. Timber and fishing support the country, but armies have passed through it often enough: the orcs came in the First War, and the Blackrock have returned." },
        { "They now hold Stonewatch Keep and the valleys beyond it. Gnolls roam the canyons, a warlock occupies the eastern hills, and black dragon whelps nest in the high caves. Lakeshire has repeatedly asked Stormwind for soldiers." },
      },
    },
    ["stonewatch-keep"] = {
      title = "Stonewatch Keep", kind = "place", chapter = "redridge",
      unlock = { { area = 2099 }, { area = 70 } },
      also = { "gathilzogg", "blackrock-clan", "lakeshire" },
      text = {
        { "Stonewatch Keep guarded the northern approach to Redridge. The Blackrock came down that approach and took it. Their raiders now strike the farms above Lakeshire, and their ambushers watch the road between the town and the keep. A fortification is useful to whoever holds its walls." },
        { "A regiment of Stormwind's soldiers was cut to pieces among the ruined towers. A few survivors are said to be held in the caves. Warlord Gath'Ilzogg occupies the keep itself, with a price on his head from Magistrate Solomon. Look carefully at the ground, traveller. Lakeshire has already lost men trying to recover it." },
      },
    },
    ["kalaran-windblade"] = {
      title = "Kalaran Windblade", kind = "figure", chapter = "searing-gorge", portrait = 7820,
      unlock = { { quest = 3454 }, { quest = 3463 } },
      also = { "the-cauldron", "dark-iron-dwarves", "twilights-hammer", "searing-gorge" },
      text = {
        { "Kalaran Windblade camps in the Searing Gorge with a squire and a grudge. The Dark Irons of the Cauldron killed his father, he says, and when he begged the magistrate in Stormwind for help, nobody listened. Stormwind, as he tells it, would rather not admit that this corner of the world exists, let alone send its precious soldiers to see justice done. So it is vengeance, plain and simple, and he asks whether there is a more passionate cause in the world." },
        { "He is one man, with what he calls a lumbering oaf of a squire, and he means the traveller to do the work. The Dark Irons' four sentry towers are to burn with a fire no element can put out, lit by a Torch of Retribution of his making: hearts of flame and golem oil, a shaft forged from the thorium daggers of the Cauldron's slavers, and a casing drawn from a Symbol of Ragnaros taken off the Twilight's Hammer, whose foul magic, he says, is perfectly suited to the task. Whoever takes up the torch feels waves of hatred and anger pulse through them." },
        { "His squire, Maltrake, lives only to serve his master, and thinks the burning towers glorious. Kalaran promises his helpers riches beyond their wildest dreams and keeps a sharp tongue for them in the meantime. I have some sympathy for a son nobody would listen to, and rather less for a weapon made from the Firelord's own symbol." },
      },
    },
    ["searing-gorge"] = {
      title = "Searing Gorge", kind = "place", chapter = "searing-gorge",
      unlock = { { area = 51 } },
      also = { "the-cauldron", "thorium-brotherhood", "dark-iron-dwarves", "war-of-the-three-hammers", "twilights-hammer" },
      text = {
        { "The Searing Gorge lies north of Blackrock Mountain, a basin of ash and cinders enclosed by cliffs. Routes from Loch Modan and the Badlands lead into it. This was once green country, burned when Thaurissan summoned Ragnaros. Smoke still rises from what the Firelord left behind." },
        { "Dark Iron dwarves work the great pit called the Cauldron with slaves and golems. Fire elementals cross the slag, and the Twilight's Hammer keeps an altar in the north-western hills. Above the pit, renegade Dark Irons hold a camp of their own. You can see much of the country from its cliffs, traveller, though little of the view makes a comfortable prospect." },
      },
    },
    ["the-cauldron"] = {
      title = "The Cauldron", kind = "place", chapter = "searing-gorge",
      unlock = { { area = 246 }, { area = 1443 }, { area = 247 } },
      also = { "searing-gorge", "thorium-brotherhood", "dark-iron-dwarves" },
      text = {
        { "The Cauldron is the Dark Irons' great mining pit in the Searing Gorge, surrounded by digging machines and worked in the heat with slave labour. Some of its captives have been driven to such madness that they attack even those who would release them." },
        { "The smaller Grimesilt dig lies south-east of it. Beneath the main pit, Overseer Maltorius commands the Slag Pit, having abandoned the Thorium Brotherhood to return to his former masters. There is also an outhouse at Grimesilt with a key. A traveller's business in this country can involve remarkably different sorts of confinement." },
      },
    },
    ["the-suntara-stones"] = {
      title = "The Suntara Stones", kind = "history", chapter = "searing-gorge",
      unlock = { { quest = 3566 } },
      also = { "the-cauldron", "dark-iron-dwarves", "explorers-league", "ragnaros" },
      text = {
        { "The Suntara stones were a digger's rumour until Dorius Stonetender went into the Searing Gorge after them. A traveller found him on the road out, badly hurt and begging to be taken home to Ironforge. He was shot before they got there. He left behind a letter to his brother, Curator Thorius of the Hall of Explorers. The stones were real, it said, the Dark Irons had them, and their leader, Lathoric the Black, was using their power to enslave Dorius's excavation team. The diggers had been taken to the Cauldron to work night and day on something called Obsidion. Free them, the letter asked. It was signed as the last wish of a dead man." },
        { "Thorius dried his eyes and vowed that his brother would have his wish. The diggers were found in the Slag Pit, still labouring after their bodies had given out, held to the work by the stones until a relic guarded by the Twilight's Hammer was laid on the altar of Suntara. One of them lived long enough to say that it had all been a trap, and to ask that the man behind it be killed, for Thorius's sake." },
        { "The head of Lathoric the Black, when it was carried back to the Hall, was Dorius's. He had staged his own death on the road, and the letter with it. Thorius blamed the Firelord and the Old Gods, whose hold on that country is still strong: if a dwarf as honourable as his brother could be turned to the will of Ragnaros, he said, no one was safe." },
        { "Read the letter again knowing who wrote it, traveller. Nearly every line of it is true. Only the signature lies." },
      },
    },
    ["thorium-brotherhood"] = {
      title = "The Thorium Brotherhood", kind = "faction", chapter = "searing-gorge", portrait = 14666,
      unlock = { { area = 1446 }, { faction = 59, standing = 5 } },
      also = { "dark-iron-dwarves", "the-cauldron", "blackrock-depths", "molten-core" },
      text = {
        { "The Thorium Brotherhood is made up of Dark Iron dwarves who left their emperor. Its smiths work at Thorium Point, above the Cauldron, and trade with those willing to help them against Thaurissan's forces. A Bronzebeard can admire their craft without much difficulty. The political arrangement takes a little more explaining." },
        { "They know how to forge the Firelord's arms and armour, provided someone brings the materials from within the mountain. One of their number even trades in Shadowforge City's tavern, under the emperor's nose. If you seek their work, traveller, bring what they need. Their quarrel with their old kin has not diminished their skill." },
      },
    },
    ["zamael-lunthistle"] = {
      title = "Zamael Lunthistle", kind = "figure", chapter = "searing-gorge", portrait = 7749,
      unlock = { { npc = 8436 }, { quest = 3378 } },
      also = { "twilights-hammer", "elune", "searing-gorge", "darnassus" },
      text = {
        { "In a cage among the Twilight's Hammer's camps in the Searing Gorge sits the spirit of a night elf, and he is glad of company. It has been many years, Zamael Lunthistle says, since he had a visitor." },
        { "As a young night elf in Darkshore he fell in with the Twilight's Hammer. Some of them befriended him, and to his shame he turned from Elune and took up the cult's vitriol and its old gods, and did a great deal of harm in the world on their behalf. Then a vision came to him from Elune and woke him. In repentance he began a prayer to her, his remorse, shame, regret and sorrow etched into a tablet of pure gold. The cult found the tablet, branded him a blasphemer and executed him with the prayer unfinished. His spirit is bound to this world, and the cage keeps it here as a warning to anyone who would betray the Hammer." },
        { "He has accepted the cage. What he asks is that the prayer be found among the Hammer's idol-worshippers and carried to Astarii Starseeker in Darnassus, so that it is heard. Absolution, he says, is the last thing he expects." },
      },
    },
    ["shen-dralas"] = {
      title = "Shen'dralas", kind = "place", chapter = "shen-dralas",
      unlock = { { area = 16651 } },
      also = { "the-valley-of-bones", "khans-of-desolace", "desolace", "quilboar" },
      text = {
        { "Shen'dralas begins at the Valley of Bones, in country the centaurs say was cursed long before they came, and nearly everything I know of it comes from the centaurs fighting at its door. Beyond the valley there is a forest, a temple whose artifact the Bristleback quilboar have carried off, and names on the maps, Evenshade's Overlook and the Forlorn Gardens, that nobody has yet explained to me." },
        { "What I can tell you is who got there first. The Magram crossed into the valley and made it a front. The Gelkis followed, some to stop them and some, it turns out, to join them. A Magram camp stands at the far end, waiting to march into the forest, and the Bristleback dug in just as early and have held the Magram back with whatever they took from the temple." },
        { "I will write more when travellers who go beyond the valley come back to tell me." },
      },
    },
    ["the-valley-of-bones"] = {
      title = "The Valley of Bones", kind = "history", chapter = "shen-dralas",
      unlock = { { area = 16675 }, { area = 16676 }, { quest = 93041 }, { quest = 92873 } },
      also = { "shen-dralas", "khans-of-desolace", "zaetar-and-theradras", "centaurs" },
      text = {
        { "The Valley of Bones is full of the dead: bones and bodies, the skeletons of the Twin Goliaths, and things walking that should lie still. Some necromantic power has soaked into the place, and the Magram, the first clan to brave it, have decided that the magic is theirs. Nobody, I notice, asked the dead. Those of them who do not fight with blade or mallet are being taught to raise the dead, and they have Necrokhans now." },
        { "The Gelkis came after them. Some Gelkis followed the Magram into the valley and took up the same art, in a twisted bid, one of their prisoners says, to defect to the Magram, and the clan has sentenced them all to exile. The Gelkis scout Nerlokh was sickened by something else. The skeletons walk on two legs, not four. They are not centaur dead at all, but whoever lay in that ground long before Desolace belonged to the centaurs. Nerlokh could not imagine how the Magram justified turning their backs on Mother Theradras to raise them." },
        { "The Magram mean to take the valley, raise an army there and bring the other clans to their knees. Orgrul, who gives the orders in their camp, has taken to asking recruits whether they are as eager as he is to rule over all of Desolace." },
      },
    },
    ["abyssal-council"] = {
      title = "The Abyssal Council", kind = "faction", chapter = "silithus", portrait = 12002,
      unlock = { { kill = 15203 }, { kill = 15204 }, { kill = 15205 }, { kill = 15206 }, { kill = 15207 }, { kill = 15208 }, { kill = 15209 }, { kill = 15211 }, { kill = 15212 }, { kill = 15220 }, { kill = 15305 }, { kill = 15307 } },
      also = { "twilights-hammer", "silithus", "cenarion-hold" },
      text = {
        { "Twilight's Hammer cultists gather at summoning stones in Silithus. With sigils, tablets and texts of power, they call templars, dukes and lords of fire, air, water and earth: the servants of the Abyssal Council. Each rite can bring a more powerful elemental into the desert." },
        { "The Cenarion Circle wants the cult stopped and its texts taken. The stones lie in the same desert as Ahn'Qiraj, a proximity that gives little comfort." },
      },
    },
    ["cenarion-hold"] = {
      title = "Cenarion Hold", kind = "place", chapter = "silithus",
      unlock = { { area = 3425 } },
      also = { "cenarion-circle", "silithus", "the-scarab-wall", "caverns-of-time" },
      text = {
        { "Cenarion Hold is the Cenarion Circle's fortress in the north of Silithus, raised to watch the hives and the sealed city in the south. The druids, Alliance and Horde alike, keep its walls, and the war against the silithid is fought from here." },
        { "Some at the Hold are not what they seem. Among the druids live the Brood of Nozdormu, the bronze dragonflight in mortal shape, who remember the war fought here a thousand years ago and are watching for its return." },
      },
    },
    ["cthun"] = {
      title = "C'Thun", kind = "figure", chapter = "silithus", portrait = 15787,
      unlock = { { kill = 15727 } },
      also = { "temple-of-ahnqiraj", "silithid", "uldum" },
      text = {
        { "C'Thun lies beneath the Temple of Ahn'Qiraj, one of the ancient powers called the Old Gods. An immense eye and masses of tentacles fill its chamber. The qiraji and their silithid swarms serve it." },
        { "Those who approach hear whispers in their minds, promises and threats that belong to the creature below. The expedition found and slew it. I can set those events down, traveller, but I take little pleasure in recording a thing capable of answering its observers inside their own thoughts." },
      },
    },
    ["natalia-maralith"] = {
      title = "Natalia Mar'alith", kind = "figure", chapter = "silithus", portrait = 15330,
      unlock = { { quest = 8306 } },
      also = { "cthun", "cenarion-hold", "silithid", "the-scarab-wall", "explorers-league" },
      text = {
        { "Natalia Mar'alith was a night elf priestess and the wife of Commander Mar'alith of Cenarion Hold, and she was the first of the Hold's people to go out with the League's diggers when they came to Silithus. They went into the hives after lost artifacts. In Hive'Regal she came on a crystal carved with glyphs, pressed her face to it as if called, and went still. The diggers carried her out, and the druids of the Circle woke her. For a few weeks she seemed well." },
        { "Then she came back to the diggers' camp and demanded that they return to the hive. Brann Bronzebeard, who has since gone missing, would not go back without an army: the swarm had grown threefold. Before the fighting began she was already talking to someone none of them could see, in a tongue none of them knew, though Frankal Stonebridge says the four of them, monkey included, know thirty-eight languages, a little Titan among them. She fought with the mind as much as the hand. The dwarves heard shadowed words in their heads and dropped one after another, until the expedition's monkey, Glibb, saw Brann fall and drove her off. She ran for Hive'Regal, and not one insect stood in her way." },
        { "Her husband sent travellers after her, with leave to do what they must. What they found in the hive bore the title of High Priestess of C'Thun. The Commander had never heard the name before. I doubt he will forget it." },
      },
    },
    ["prince-thunderaan"] = {
      title = "Prince Thunderaan", kind = "figure", chapter = "silithus", portrait = 14992,
      unlock = { { kill = 14435 }, { quest = 7786 } },
      also = { "ragnaros", "molten-core", "silithus" },
      text = {
        { "Thunderaan the Windseeker was a prince of the elemental lords of air, until Ragnaros the Firelord consumed his essence. What remained of him was bound in two halves of a binding, which the Firelord's lieutenants carry in the Molten Core." },
        { "In Silithus, a strange being who calls himself Highlord Demitrian knows how to bring him back. Bring him both halves of the bindings, the elementium to work them, and the essence of the Firelord, and the Windseeker will be reborn. What comes out of that rebirth is not grateful, but it can be beaten. And from it, they say, a blade of storms can be made." },
      },
    },
    ["ruins-of-ahnqiraj"] = {
      title = "Ruins of Ahn'Qiraj", kind = "place", chapter = "silithus",
      unlock = { { area = 3429 }, { area = 3454 }, { kill = 15339 } },
      also = { "the-scarab-wall", "temple-of-ahnqiraj", "silithid", "fandral-staghelm" },
      text = {
        { "When the gong was rung and the Scarab Wall opened, the armies of the Alliance and the Horde poured into the outer city of Ahn'Qiraj, the Ruins, a place of broken temples and sand, swarming with insects. The qiraji general Rajaxx commands here, the same who killed Valstann Staghelm a thousand years ago, and the Ruins are guarded at their heart by the great stone warrior Ossirian the Unscarred." },
        { "The Cenarion Circle sent its own champions into the Ruins, and for them, the battle in the city was the end of a very old war." },
      },
    },
    ["silithus"] = {
      title = "Silithus", kind = "place", chapter = "silithus",
      unlock = { { area = 1377 } },
      also = { "cenarion-hold", "the-scarab-wall", "silithid", "twilights-hammer", "cenarion-circle" },
      text = {
        { "Silithus is a desert of yellow sand and great silithid hives in south-western Kalimdor. Behind the Scarab Wall lies Ahn'Qiraj, the city of the insects' qiraji masters. Something older still lies beneath their rule." },
        { "The Cenarion Circle watches from its hold, while Twilight's Hammer cultists gather in desert camps. Alliance and Horde forces have been raised together to march on the wall." },
      },
    },
    ["temple-of-ahnqiraj"] = {
      title = "Temple of Ahn'Qiraj", kind = "place", chapter = "silithus",
      unlock = { { area = 3428 }, { area = 16076 } },
      also = { "ruins-of-ahnqiraj", "cthun", "silithid", "caverns-of-time" },
      text = {
        { "The twin emperors Vek'lor and Vek'nilash rule the qiraji from the Temple of Ahn'Qiraj. Their servants include the silithid swarms and the great worms within its halls. The bronze dragons regard this place with fear." },
        { "Beneath the emperors lies C'Thun. The temple and the empire around it serve this Old God, rather than the rulers a traveller first encounters. The emperors hold their court above the chamber of their own master." },
      },
    },
    ["the-scarab-wall"] = {
      title = "The Scarab Wall", kind = "history", chapter = "silithus",
      unlock = { { area = 2737 }, { area = 3077 } },
      also = { "fandral-staghelm", "silithid", "the-scepter-of-the-shifting-sands", "ruins-of-ahnqiraj" },
      text = {
        { "A thousand years ago, the qiraji and their silithid swarms came out of Ahn'Qiraj and fell on Kalimdor, and the night elves fought them in the War of the Shifting Sands. They could not win it alone. Fandral Staghelm, who led them, lost his son Valstann to the qiraji: the boy was captured and killed before his father's eyes." },
        { "The dragons saved them. The bronze, red, blue and green dragonflights came, and drove the insects back into their city. And with their magic the night elves raised a great wall of stone and a barrier across the south of Silithus, the Scarab Wall, and sealed them in. The dead of that war lie at Valor's Rest, outside it." },
      },
    },
    ["the-scepter-of-the-shifting-sands"] = {
      title = "The Scepter of the Shifting Sands", kind = "history", chapter = "silithus",
      unlock = { { area = 2741 }, { quest = 8305 } },
      also = { "the-scarab-wall", "fandral-staghelm", "caverns-of-time", "cenarion-hold" },
      text = {
        { "To seal Ahn'Qiraj, the bronze dragon Anachronos made a scepter, the Scepter of the Shifting Sands, and with it he closed the Scarab Wall and placed a gong before it on a dais. Only the scepter, struck on the gong, can open it again. He gave it to Fandral Staghelm." },
        { "Fandral did not want it. Thinking of his son, he broke the scepter on the ground, and said that he never wished to see it again. Its pieces went to the dragonflights, for safekeeping. A thousand years later, a crystalline tear in the southern desert still shows that memory to those who look into it, and the bronze dragons have been looking for someone to make the scepter whole." },
      },
    },
    ["ambermill"] = {
      title = "Ambermill", kind = "place", chapter = "silverpine",
      unlock = { { area = 233 } },
      also = { "silverpine-forest", "the-sepulcher" },
      text = {
        { "Ambermill is a village in the east of Silverpine that still holds out against the Forsaken, and it holds out because of the mages of Dalaran. The Kirin Tor have sent wizards, protectors and wagons of supplies from Hillsbrad, a great deal of attention for a backwater village." },
        { "The Forsaken have found out why: beneath Ambermill lies a dormant node of ley energy, and Dalaran means to wake it. What for, no one in the Sepulcher knows, and the wizards are not telling." },
      },
    },
    ["archmage-arugal"] = {
      title = "Archmage Arugal", kind = "figure", chapter = "silverpine", portrait = 2353,
      unlock = { { kill = 4275 }, { quest = 1014 } },
      also = { "shadowfang-keep", "worgen", "pyrewood-village" },
      text = {
        { "As Dalaran's defenders fell to the Scourge, Arugal sought a weapon against the dead. The Kirin Tor mage summoned worgen from another world. They fought the invaders, then turned upon the living they had been called to protect." },
        { "Arugal withdrew to Shadowfang Keep and came to regard the worgen as his children. Nearby Pyrewood suffered his curse, its people changed after nightfall. What began as an attempt to save one city has left a keep and a village in the grip of his answer." },
      },
    },
    ["greymane-wall"] = {
      title = "The Greymane Wall", kind = "history", chapter = "silverpine",
      unlock = { { area = 230 } },
      also = { "silverpine-forest", "pyrewood-village" },
      text = {
        { "The Greymane Wall closes southern Silverpine from sea to cliff, with Gilneas beyond its gate. After the Second War, King Genn Greymane quarrelled with the other Alliance rulers, including over the cost of keeping defeated orcs in internment camps. He withdrew his kingdom from the Alliance and shut it behind this wall." },
        { "Refugees from the north find the gate closed. No word has come out of Gilneas to explain its present affairs. You may see the wall plainly enough, traveller. It is the country behind it that remains beyond this record." },
      },
    },
    ["pyrewood-village"] = {
      title = "Pyrewood Village", kind = "place", chapter = "silverpine",
      unlock = { { area = 204 } },
      also = { "archmage-arugal", "worgen", "silverpine-forest" },
      text = {
        { "Pyrewood is a village near the Greymane Wall, and by day it looks like any other: farmers, a council, a lord mayor. By night its people turn into worgen. The mage Arugal laid this on them with enchanted shackles, and the Forsaken who have studied it say it is the strangest curse they have ever seen." },
        { "The villagers know, I think, and live with it the only way they can. It is the saddest place in Silverpine, and Silverpine has competition." },
      },
    },
    ["shadowfang-keep"] = {
      title = "Shadowfang Keep", kind = "place", chapter = "silverpine",
      unlock = { { area = 209 }, { area = 236 } },
      also = { "archmage-arugal", "worgen", "pyrewood-village" },
      text = {
        { "Before Arugal came, the fortress above Pyrewood belonged to Baron Silverlaine. The mage's worgen overran it, and the Baron's ghost still haunts its halls. Commander Springvale, a paladin, is among its other undead defenders." },
        { "Arugal retreated here with the worgen he calls his children. The fortress is now known as Shadowfang Keep, a stronghold the Forsaken want on their southern border. Their deathstalkers went in to scout it and have not returned." },
      },
    },
    ["silverpine-forest"] = {
      title = "Silverpine Forest", kind = "place", chapter = "silverpine",
      unlock = { { area = 130 } },
      also = { "the-sepulcher", "pyrewood-village", "shadowfang-keep", "greymane-wall", "worgen" },
      text = {
        { "Silverpine is a forest of tall grey pines on the coast south of Tirisfal, running down to the great wall that shuts Gilneas off from the world. It was a quiet land of farms and fishing villages, part of Lordaeron's realm. The plague came through it, then the dead, then worse." },
        { "Now it is a borderland. The Forsaken hold the north from the Sepulcher, the worgen of a mad mage's making hunt the woods, plague-ridden gnolls dig in the dead fields, and the mages of Dalaran keep a village in the east. Everyone in Silverpine is waiting for something, and none of them for anything good." },
      },
    },
    ["the-sepulcher"] = {
      title = "The Sepulcher", kind = "place", chapter = "silverpine",
      unlock = { { area = 228 } },
      also = { "the-forsaken", "archmage-arugal", "ambermill", "thule-ravenclaw", "varimathras" },
      text = {
        { "The Sepulcher is a cluster of crypts and mausoleums in Silverpine, held by Forsaken Deathguard and Deathstalkers. From this stronghold they mean to secure the forest. The Banshee Queen's orders reach further: Varimathras is charged with conquering the human and dwarven lands to the south." },
        { "For now, Arugal's worgen, the Rot Hide gnolls and Ambermill's mages keep its forces occupied close to home. The Forsaken want Arugal's work undone in particular." },
      },
    },
    ["thule-ravenclaw"] = {
      title = "Thule Ravenclaw", kind = "figure", chapter = "silverpine", portrait = 4430,
      unlock = { { kill = 1947 }, { area = 172 } },
      also = { "gnolls", "scourge", "the-sepulcher" },
      text = {
        { "Thule Ravenclaw was a young mage of great promise before the Third War. When the Lich King rose, he betrayed his own to serve the Scourge, and the Forsaken, some of whom studied beside him in life, did not know he still lived until they found his work." },
        { "He holds Fenris Isle, in Lordamere Lake beside Silverpine, and the gnolls of the Rot Hide clan are his: dead things, raised and steeped in his foul ichors, which dig up the graves of Tirisfal and carry the bodies to him. What he makes of them, the Forsaken would rather not discover the hard way." },
      },
    },
    ["darnassus-tune"] = {
      title = "Darnassus", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 76 } },
      also = {  },
      text = {
        { "Darnassus, the city of the night elves, grows in the branches of Teldrassil, and its tune is heard there and in the villages beneath. The night elves are a patient people. I have found it unwise to hurry them." },
      },
    },
    ["green-kingdoms"] = {
      title = "The Green Kingdoms", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 1 } },
      also = {  },
      text = {
        { "One tune serves the woods of the human kingdoms, from Elwynn Forest and Redridge to Loch Modan, the Hinterlands and the Hillsbrad Foothills. Men farmed and fought across these trees long before the Horde came through the Dark Portal, and the tune has outlasted all of it. If you want to hear it properly, stop walking." },
      },
    },
    ["ironforge-tune"] = {
      title = "Ironforge", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 232 } },
      also = {  },
      text = {
        { "Ironforge is my own city, and I will say only that its tune plays somewhere in it, since the halls are many. The Bronzebeards have kept the Great Forge lit under Magni for longer than most kingdoms have had names. You will find me in the Hall of Explorers, if you ever need a historian." },
      },
    },
    ["marsh-and-mire"] = {
      title = "Marsh and Mire", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 227 } },
      also = {  },
      text = {
        { "The Wetlands and Dustwallow Marsh share a tune of damp air and long grey water. Dwarves keep Menethil Harbor on the one, and Theramore stands on the other. Neither is a place I would choose for a long walk in good boots." },
      },
    },
    ["orgrimmar-tune"] = {
      title = "Orgrimmar", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 14 } },
      also = {  },
      text = {
        { "Orgrimmar carries the name of Orgrim Doomhammer, who led the Horde before Thrall, and Thrall raised it on Durotar's red earth. Its tune plays somewhere within the walls. I will not claim to know where, only that the orcs are not shy about anything." },
      },
    },
    ["stormwind-tune"] = {
      title = "Stormwind", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 13 } },
      also = {  },
      text = {
        { "Stormwind has its own tune, which plays among the canals and cathedrals of the human capital. The Horde burned the city in the First War, and the humans rebuilt it larger and prouder than before. I note that it is a city built by people who expected to be attacked again." },
      },
    },
    ["the-burning-lands"] = {
      title = "The Burning Lands", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 10 } },
      also = {  },
      text = {
        { "Blackrock Mountain, the Burning Steppes and the Searing Gorge are the same fire seen from three sides. The Dark Iron dwarves hold the Gorge, and Ragnaros holds the mountain's heart. I would not linger on either account." },
      },
    },
    ["the-dark-woods"] = {
      title = "The Dark Woods", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 2 } },
      also = {  },
      text = {
        { "Duskwood, Deadwind Pass, Tirisfal Glades and Silverpine Forest share one tune, and none of them is a comfortable place to stand. Tirisfal was the farmland of Lordaeron before the plague came, and the Forsaken now keep it. The tune did not have to change to suit them." },
      },
    },
    ["the-dry-lands"] = {
      title = "The Dry Lands", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 7 } },
      also = {  },
      text = {
        { "Dust and thorn from the Barrens to the Badlands, and on to the Blasted Lands, Desolace and the Stonetalon Mountains: one tune for all of it. The orcs made the Barrens their own after the Horde's war, and the Blasted Lands still carry the scar of the Dark Portal. I find it a fitting tune for a country that has been fought over so often." },
      },
    },
    ["the-high-mountains"] = {
      title = "The High Mountains", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 8 } },
      also = {  },
      text = {
        { "Dun Morogh, the Arathi Highlands and Winterspring all answer to this tune, and I will admit I am not impartial about the first. The Arathi Highlands once held Thoradin's capital, when Arathor ruled the human lands. Winterspring holds nothing but snow and a good deal of patience." },
      },
    },
    ["the-jungle"] = {
      title = "The Jungle", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 3 } },
      also = {  },
      text = {
        { "The same tune covers Stranglethorn Vale, Feralas and the troll ruins of Zul'Gurub and the Temple of Atal'Hakkar. The Gurubashi trolls once ruled this jungle from their great city. Their empire is gone and the trees are not." },
      },
    },
    ["the-living-forest"] = {
      title = "The Living Forest", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 11 } },
      also = {  },
      text = {
        { "The tune of Teldrassil, the great tree the night elves call home, carries on into the forests of Ashenvale. Both belong to a people who measure their years in millennia, and who were walking these woods before the dwarves had learned to dig." },
      },
    },
    ["the-open-plains"] = {
      title = "The Open Plains", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 9 } },
      also = {  },
      text = {
        { "Westfall's farms, Durotar's red hills, Mulgore's grass and the Thousand Needles share one tune, which is a great many peoples to ask of a single song. Humans plough Westfall, the orcs made Durotar their homeland under Thrall, and the tauren have walked Mulgore since long before either." },
      },
    },
    ["the-plagued-lands"] = {
      title = "The Plagued Lands", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 205 } },
      also = {  },
      text = {
        { "The Western and Eastern Plaguelands share this tune with the Scarlet Monastery. The plague began in the grain at Andorhal, and what it did to the northern farms of Lordaeron you may still read on the ground. The Scarlet Crusade, in its own way, is another face of the same wound." },
      },
    },
    ["the-sands"] = {
      title = "The Sands", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 176 } },
      also = {  },
      text = {
        { "Tanaris, Silithus and the troll city of Zul'Farrak share a tune of sand and sun. Silithus is also where the Gates of Ahn'Qiraj stand, which is a poor reason to visit it and an excellent reason to write about it." },
      },
    },
    ["the-sorrowful-swamp"] = {
      title = "The Sorrowful Swamp", kind = "tune", chapter = "soundtrack", group = "lands",
      unlock = { { music = 223 } },
      also = {  },
      text = {
        { "The Swamp of Sorrows and Un'Goro Crater, two places with nothing else in common, play the same tune. The first holds the orc village of Stonard and the sunken temple of Atal'Hakkar. The second holds a great many dinosaurs, which no history of mine has ever managed to explain." },
      },
    },
    ["thunder-bluff-tune"] = {
      title = "Thunder Bluff", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 226 } },
      also = {  },
      text = {
        { "Thunder Bluff stands on the high mesas of Mulgore, home of the tauren and of Cairne Bloodhoof, their chief. Its tune plays on the bluffs and in the villages of the plains below. The tauren build as they live, slowly and in the open." },
      },
    },
    ["undercity-tune"] = {
      title = "Undercity", kind = "tune", chapter = "soundtrack", group = "cities",
      unlock = { { music = 182 } },
      also = {  },
      text = {
        { "The Undercity lies beneath the ruins of Lordaeron's capital, and the Forsaken under Sylvanas keep it. Its tune plays somewhere in the halls below. It is the only city I know whose citizens would find the word welcoming an insult." },
      },
    },
    ["boulderslide-ravine"] = {
      title = "Boulderslide Ravine", kind = "place", chapter = "stonetalon",
      unlock = { { area = 2540 }, { area = 3157 } },
      also = { "stonetalon-mountains", "sun-rock-retreat", "kobolds" },
      text = {
        { "In the south-east of Stonetalon there is a ravine with a deep cave, and the kobolds in it have been digging like creatures possessed, after a rare crystal they call resonite. The shamans of Sun Rock felt something wrong under the mountains and went to see why, and at the bottom of the cave they found a cask of resonite, and sleeping inside it, one of the earthen: a being of living stone named Goggeroc." },
        { "The earthen, if the discs of Uldaman are to be believed, were made by the titans to shape the world, and they are the forefathers of my own people. I would have given a great deal to speak with one. The shamans of Sun Rock judge him a threat to the land, and mean to wake him while he is weak and destroy him before he finds his strength." },
        { "I do not say they are wrong. I have not seen him. But I would very much like to know what an earthen was doing asleep in a cask under Stonetalon, and who put him there." },
      },
    },
    ["stonetalon-mountains"] = {
      title = "Stonetalon Mountains", kind = "place", chapter = "stonetalon",
      unlock = { { area = 406 } },
      also = { "stonetalon-peak", "sun-rock-retreat", "windshear-crag", "venture-company", "harpies", "grimtotem" },
      text = {
        { "The Stonetalon Mountains rise between Ashenvale and the Barrens: high grey peaks, deep valleys and old forests, the ancestral home of the harpies, with the druids' sacred peak at their heart. The spirits of these mountains are angry, the Horde's shamans say, and they have reason." },
        { "The goblins of the Venture Company have come to cut, burn and dig, and whole valleys have gone with them. The Charred Vale in the south was burned to the ground by their machines. The Bloodfury harpies hold the high places, the Grimtotem raid tauren villages, and in the middle of it all the druids on the peak and the shamans of Sun Rock try to heal what they can." },
      },
    },
    ["stonetalon-peak"] = {
      title = "Stonetalon Peak", kind = "place", chapter = "stonetalon",
      unlock = { { area = 467 }, { area = 468 } },
      also = { "stonetalon-mountains", "cenarion-circle", "harpies" },
      text = {
        { "Stonetalon Peak is the highest summit of the range and a sacred place of the night elves' druids, who keep it with the forest spirits they call the sons and daughters of Cenarius. On it stands the Talon Den, where the druids store things of power behind locks of their own devising, and where at least one of them, Brother Ravenoak, sleeps in the shape of a bear, guarding them in his dreams." },
        { "The keepers of the peak watch the mountains below with grief: the burned vale, the felled forests, the harpies who will not let them pass to plant again. They are patient, as druids are, and they are losing." },
      },
    },
    ["sun-rock-retreat"] = {
      title = "Sun Rock Retreat", kind = "place", chapter = "stonetalon",
      unlock = { { area = 460 } },
      also = { "stonetalon-mountains", "grimtotem", "stonetalon-peak" },
      text = {
        { "Tauren and orcs share Sun Rock Retreat in the cliffs of central Stonetalon. Its shamans collect seeds to regrow the burned country. Hunters seek vengeance for Camp Aparaje, the tauren village all but destroyed by the Grimtotem. There is both restoration and reprisal in the camp's work." },
        { "A warlock staying here has a different purpose. He serves a master in Jaedenar and pays for help against the peak's druids, whom he accuses of stifling magic. Listen carefully to who offers each errand, traveller. Sharing a camp does not give its inhabitants the same intentions." },
      },
    },
    ["windshear-crag"] = {
      title = "Windshear Crag", kind = "place", chapter = "stonetalon",
      unlock = { { area = 461 }, { area = 465 } },
      also = { "venture-company", "stonetalon-mountains", "stonetalon-peak" },
      text = {
        { "Windshear Crag is the Venture Company's great logging and mining camp in the north of Stonetalon, a valley of stumps, saws, water wheels and shredders, the man-shaped machines that fell trees faster than any crew. Above it all, near the great wheel, lives its overseer, Gerenzo Wrenchwhistle, a goblin more metal than flesh by now." },
        { "The Charred Vale to the south is what the Company leaves behind: a whole forest, burned. The druids want to plant it again, the shamans want the machines stopped, and even some of the Company's own engineers have quit in disgust." },
      },
    },
    ["bloodsail-buccaneers"] = {
      title = "The Bloodsail Buccaneers", kind = "faction", chapter = "stranglethorn", portrait = 793,
      unlock = { { kill = 1561 }, { kill = 1562 }, { kill = 1563 }, { kill = 1564 }, { kill = 1565 }, { kill = 1653 }, { kill = 2546 }, { kill = 2548 }, { kill = 2550 }, { kill = 4505 }, { kill = 4506 } },
      also = { "booty-bay", "steamwheedle-cartel" },
      text = {
        { "The Bloodsail Buccaneers are the great pirate fleet of the southern seas, and their quarrel is with Booty Bay. The Baron and his Blackwater Raiders keep them from plundering where they please and hang them when they catch them. The Bloodsail want both the Baron and his fleet master dead, and will make an admiral of anyone who brings them their heads." },
        { "Their ships lie off the coast of Stranglethorn, the Crimson Veil among them, and their camps hold the coves of the Savage Coast. Their fleet master is Firallon, of whom the Blackwater sailors say he could not sail a skiff across a lake. They have not yet beaten him." },
      },
    },
    ["bloodscalp-and-skullsplitter"] = {
      title = "The Bloodscalp and the Skullsplitter", kind = "faction", chapter = "stranglethorn", portrait = 4570,
      unlock = { { kill = 587 }, { kill = 588 }, { kill = 595 }, { kill = 597 }, { kill = 660 }, { kill = 671 }, { kill = 694 }, { kill = 697 }, { kill = 698 }, { kill = 699 }, { kill = 701 }, { kill = 702 }, { kill = 667 }, { kill = 669 }, { kill = 670 }, { kill = 672 }, { kill = 696 }, { kill = 756 }, { kill = 780 }, { kill = 781 }, { kill = 782 }, { kill = 783 }, { kill = 784 } },
      also = { "gurubashi-empire", "gromgol-base-camp" },
      text = {
        { "The Bloodscalp hold north-western Stranglethorn. The Skullsplitter occupy the central jungle. Both live among the ruins of their Gurubashi ancestors. Their headhunters range through the north, taking heads and trophies, and the two tribes regard one another with considerable hostility." },
        { "Nimboya suspects the Bloodscalp of holding Yenniku, his chief's youngest son. The search leads elsewhere: Zanzil the Outcast has him under magical control. Follow that distinction, traveller. The first enemy named in an investigation is not always the one responsible." },
      },
    },
    ["booty-bay"] = {
      title = "Booty Bay", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 35 } },
      also = { "steamwheedle-cartel", "bloodsail-buccaneers", "stranglethorn-vale" },
      text = {
        { "Booty Bay clings to the cliffs of a sea-cave at Stranglethorn's southern tip. Wooden houses, stilts and rope bridges crowd its harbor. An enormous shark's open jaws mark the entrance. Baron Revilgaz runs the port for the Steamwheedle Cartel, with an interest in keeping it both neutral and profitable." },
        { "His Blackwater Raiders make their home here too. They are at war with the Bloodsail Buccaneers, who want the Baron dead. A trader can find a haven in the bay, while an armed traveller can find employment in the quarrel beyond it. Revilgaz has business for both." },
      },
    },
    ["gromgol-base-camp"] = {
      title = "Grom'gol Base Camp", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 117 } },
      also = { "darkspear-trolls", "bloodscalp-and-skullsplitter", "stranglethorn-vale" },
      text = {
        { "Grom'gol is a Horde stockade on Stranglethorn's northern coast, served by zeppelins from Orgrimmar and Undercity. For the Darkspear, a journey here is a return to their ancestors' country. Their business in the jungle includes losses that followed them when they left." },
        { "Nimboya seeks Yenniku, his chief's youngest son, given to the trolls of Zul'Gurub as a boy under the old custom. The Darkspear lost him when they departed with Thrall. Nimboya first suspects the Bloodscalp, but the search reveals Zanzil the Outcast's magical hold over him and leads to an attempt to free his soul." },
      },
    },
    ["gurubashi-arena"] = {
      title = "The Gurubashi Arena", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 1741 } },
      also = { "stranglethorn-vale", "gurubashi-empire" },
      text = {
        { "In the middle of the jungle stands a great stone arena, built by the Gurubashi for their blood sports long ago. The trolls have gone, but the fighting has not: the goblins and pirates who run it now hold regular contests, and every so often they throw a chest of treasure into the middle of the floor and let whoever is still standing take it." },
        { "It is open to everyone, Alliance and Horde alike, which is to say that it is the one place in Stranglethorn where they are encouraged to kill each other." },
      },
    },
    ["gurubashi-empire"] = {
      title = "The Gurubashi Empire", kind = "history", chapter = "stranglethorn",
      unlock = { { area = 102 }, { area = 103 }, { area = 123 }, { area = 127 }, { area = 128 }, { area = 129 }, { area = 122 }, { area = 125 }, { area = 126 }, { area = 477 }, { area = 311 }, { read = { "Empires' Fall", "제국의 몰락", "La chute de l'empire", "Der Falls des Imperiums", "帝国的陷落", "La caída de los imperios", "Падение Империи", "A Queda do Império", "帝國的陷落" } }, { read = { "The Twin Empires", "쌍둥이 제국", "Les empires jumeaux", "Die Zwillingsimperien", "两个帝国", "Los Imperios Gemelos", "Империи-близнецы", "Os Impérios Gêmeos", "兩個帝國" } }, { read = { "Legends of the Gurubashi, Volume 3", "구루바시의 전설 3권", "Légendes des Gurubashi, Volume 3", "Legenden der Gurubashi, Band 3", "古拉巴什传奇，第三卷", "Leyendas de los Gurubashi, Volumen 3", "\"Легенды Гурубаши\", том 3", "Lendas dos Gurubashi, Volume 3", "古拉巴什傳奇，第三卷" } } },
      also = { "zulgurub", "hakkar", "bloodscalp-and-skullsplitter", "darkspear-trolls" },
      text = {
        { "The jungle trolls of the Gurubashi once ruled an empire that stretched across the south of the Eastern Kingdoms and over the islands of the sea, and Stranglethorn was its heart, with the great temple-city of Zul'Gurub at its centre. Its ruins are everywhere in this jungle: stepped temples, broken idols and paved roads under the roots." },
        { "Its fall was the work of its own priests. The Atal'ai brought the blood god Hakkar the Soulflayer into the world, and his hunger for sacrifice turned the empire against itself. The tribes rose, drove the Atal'ai into exile, and broke apart. What was left became the tribes we know: the Skullsplitter and the Bloodscalp in the jungle, the Darkspear, who left with Thrall, and others. The trolls have not forgotten what they were." },
      },
    },
    ["hakkar"] = {
      title = "Hakkar the Soulflayer", kind = "figure", chapter = "stranglethorn", portrait = 15295,
      unlock = { { kill = 14834 }, { quest = 8183 } },
      also = { "zulgurub", "gurubashi-empire", "zandalar-tribe", "the-temple-of-atalhakkar" },
      text = {
        { "Hakkar the Soulflayer is the trolls' blood god, a winged serpent who feeds on blood and souls. Long ago the Atal'ai brought him into the world. His demand for sacrifice became so terrible that the tribes rose against his priests and drove them into exile." },
        { "He has returned through Zul'Gurub. The Zandalar warn that his reign will spread across the world unless he is stopped. Even his fallen heart holds power: those who have faced him describe it as still burning. Keep the Zandalar's warning close, traveller, if you enter that city. They know what his worship once cost their people." },
      },
    },
    ["kurzen-rebellion"] = {
      title = "The Kurzen Rebellion", kind = "history", chapter = "stranglethorn",
      unlock = { { area = 101 }, { area = 99 }, { kill = 813 } },
      also = { "stranglethorn-vale", "gurubashi-empire" },
      text = {
        { "Colonel Kurzen came to Stranglethorn with a soldier's reputation: a brilliant tactician, once considered a great and noble man. In the jungle he changed. His followers became a force loyal to him alone, raiding and hunting with a cruelty their former comrades would not accept." },
        { "Lieutenant Doren led the breakaways into a rebel camp in the hills. Outnumbered ten to one, they fight Kurzen with the tactics he taught them. Brother Nimetz first suspects troll magic, but his investigation leads to Mai'Zoth, an ogre mage, and the Mind's Eye used to control minds." },
        { "Nimetz asks for the mage's death and the recovery of the artifact. Bring particular care to that second task, traveller. He fears that leaving it behind would leave another soldier open to Kurzen's fate." },
      },
    },
    ["nesingwarys-expedition"] = {
      title = "Nesingwary's Expedition", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 100 }, { npc = 715 }, { read = { "Green Hills of Stranglethorn - Chapter I", "가시덤불 골짜기의 푸른 언덕 - 제1장", "Les vertes collines de Strangleronce - Chapitre I", "Die Grünen Hügel des Schlingendorntals - Kapitel I", "荆棘谷的青山 - 第一章", "Las verdes colinas de Tuercespina: Capítulo I", "Зеленые холмы Тернистой долины: глава I", "Grande Espinhaço: Veredas – Capítulo I", "荊棘谷的青山 - 第一章" } }, { read = { "Green Hills of Stranglethorn - Chapter II", "가시덤불 골짜기의 푸른 언덕 - 제2장", "Les vertes collines de Strangleronce - Chapitre II", "Die Grünen Hügel des Schlingendorntals - Kapitel II", "荆棘谷的青山 - 第二章", "Las verdes colinas de Tuercespina: Capítulo II", "Зеленые холмы Тернистой долины: глава II", "Grande Espinhaço: Veredas – Capítulo II", "荊棘谷的青山 - 第二章" } }, { read = { "Green Hills of Stranglethorn - Chapter III", "가시덤불 골짜기의 푸른 언덕 - 제3장", "Les vertes collines de Strangleronce - Chapitre III", "Die Grünen Hügel des Schlingendorntals - Kapitel III", "荆棘谷的青山 - 第三章", "Las verdes colinas de Tuercespina: Capítulo III", "Зеленые холмы Тернистой долины: глава III", "Grande Espinhaço: Veredas – Capítulo III", "荊棘谷的青山 - 第三章" } }, { read = { "Green Hills of Stranglethorn - Chapter IV", "가시덤불 골짜기의 푸른 언덕 - 제4장", "Les vertes collines de Strangleronce - Chapitre IV", "Die Grünen Hügel des Schlingendorntals - Kapitel IV", "荆棘谷的青山 - 第四章", "Las verdes colinas de Tuercespina: Capítulo IV", "Зеленые холмы Тернистой долины: глава IV", "Grande Espinhaço: Veredas – Capítulo IV", "荊棘谷的青山 - 第四章" } } },
      also = { "stranglethorn-vale" },
      text = {
        { "Hemet Nesingwary's camp occupies a clearing in northern Stranglethorn, well furnished with tents, trophies and gun racks. The renowned hunter has come for panthers, tigers and raptors, and to write The Green Hills of Stranglethorn. He offers visiting hunters ample opportunity to prove themselves." },
        { "His manuscript blew away and its pages are scattered across the jungle. The chapters recount his hunt, once someone has put them back in order. If you find a page, traveller, keep it. Authors are troublesome enough when they know where their work is." },
      },
    },
    ["stranglethorn-vale"] = {
      title = "Stranglethorn Vale", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 33 } },
      also = { "booty-bay", "gurubashi-empire", "zulgurub", "venture-company", "ogres", "naga" },
      text = {
        { "Stranglethorn is a jungle, the greatest in the Eastern Kingdoms: heat, rain, vines, panthers, raptors and gorillas, ruins swallowed by green, and a long coast of beaches and coves. It was the heart of the Gurubashi, the troll empire that ruled the south long before there were kingdoms of men, and the ruins of their temples stand everywhere." },
        { "Everyone comes here for something. Hunters come for trophies, goblins for gold and timber, pirates for plunder, and soldiers of both the Alliance and the Horde to fight the trolls, the ogres and each other. The jungle swallows most of them, sooner or later." },
      },
    },
    ["zandalar-tribe"] = {
      title = "The Zandalar Tribe", kind = "faction", chapter = "stranglethorn", portrait = 14993,
      unlock = { { area = 3357 }, { npc = 14875 }, { npc = 14910 } },
      also = { "hakkar", "zulgurub", "gurubashi-empire" },
      text = {
        { "The Zandalar describe themselves as the oldest troll tribe, from whom the others descend. Their priests and scholars preserve the memory of their people and their gods. They seldom intervene in the affairs of other peoples, but Hakkar's return has brought them to Yojamba Isle off Stranglethorn's coast." },
        { "Their leader, Molthor, will work with anyone prepared to oppose the Soulflayer. That invitation includes people the trolls would ordinarily have little reason to welcome." },
      },
    },
    ["zanzil-the-outcast"] = {
      title = "Zanzil the Outcast", kind = "figure", chapter = "stranglethorn", portrait = 314,
      unlock = { { quest = 592 } },
      also = { "gromgol-base-camp", "bloodscalp-and-skullsplitter", "gurubashi-empire", "booty-bay" },
      text = {
        { "Zanzil the Outcast holds the Ruins of Jubuwal and Aboraz on the coast north-east of Booty Bay, with followers who do not seem entirely their own. He was a witch doctor until his own tribe's leaders grew afraid of him and cast him out. His art is a mixture of jungle plants that suppresses the will and strengthens the body, and his zombies, hunters and witch doctors are all dosed with it." },
        { "The Darkspear have a particular grievance. By an old custom they gave Yenniku, their chief's youngest son, to the Gurubashi of Zul'Gurub, and they lost him when they left with Thrall. Nimboya came back from distant Orgrimmar to find the boy and learned that Zanzil held him, body and soul. It took the Mind's Eye, a jewel wrested from the ogre mage Mai'Zoth and reshaped into a soul gem, to carry Yenniku's soul out of Zanzil's keeping." },
        { "His mixture has buyers. Crank Fizzlebub of Booty Bay pays for samples, and a little extra for discretion. The trolls who exiled Zanzil feared what he could do to other people's minds." },
      },
    },
    ["zulgurub"] = {
      title = "Zul'Gurub", kind = "place", chapter = "stranglethorn",
      unlock = { { area = 1977 }, { read = { "Altar of Zanza", "잔자의 제단", "Autel de Zanza", "Altar von Zanza", "赞扎祭坛", "Altar de Zanza", "Алтарь Занзы", "贊札祭壇" } } },
      also = { "hakkar", "gurubashi-empire", "zandalar-tribe" },
      text = {
        { "Zul'Gurub was the temple-city at the heart of the Gurubashi empire. After centuries of quiet, it is Hakkar's city again. High priests sent to oppose him have fallen under his power, and the Zandalar must now seek help beyond their own people." },
        { "The captive priests take the shapes of the old animal gods: bat, panther, tiger, snake and spider. Sacrifice feeds the Soulflayer's altar. The Zandalar warn that his growing power threatens all Azeroth. If you enter, remember why they have asked you to go: even those sent to stop him became instruments of his rule." },
      },
    },
    ["eranikus"] = {
      title = "Eranikus", kind = "figure", chapter = "swamp-of-sorrows", portrait = 7806,
      unlock = { { kill = 5709 }, { area = 1777 }, { quest = 3374 } },
      also = { "the-temple-of-atalhakkar", "dragons-of-nightmare", "cenarion-circle" },
      text = {
        { "Eranikus is a dragon of Ysera's green flight, and the keeper of the sunken temple: his charge was to see that the trolls never again brought forth their god. He has failed, by his own account, and worse has happened to him. Sleeping over the temple, he has been caught in something dark in the Dream, and it is twisting his mind." },
        { "In the depths of the temple his shade lies in a state between sleep and death, tangled in nightmares, and what is left of his free will reaches out to travellers for help. Another green dragon, Itharius, waits in a cave in the swamp, hoping to redeem him. I wish Itharius luck. The Nightmare that holds Eranikus is the same one that has taken Ysera's lieutenants at the great trees." },
      },
    },
    ["stonard"] = {
      title = "Stonard", kind = "place", chapter = "swamp-of-sorrows",
      unlock = { { area = 75 } },
      also = { "swamp-of-sorrows", "the-fallen-hero", "the-temple-of-atalhakkar" },
      text = {
        { "Stonard is the Horde's fortress in the Swamp of Sorrows, a squat stone keep and a cluster of huts on a rise above the mire, held by orcs who keep watch on the Blasted Lands to the south and the Alliance roads to the north." },
        { "It is grim, damp and loyal, and its people send their warriors into the swamp's temple and the demon lands beyond with few illusions about how many will come back. Outside its walls a ghost waits for orders that never came." },
      },
    },
    ["swamp-of-sorrows"] = {
      title = "Swamp of Sorrows", kind = "place", chapter = "swamp-of-sorrows",
      unlock = { { area = 8 } },
      also = { "stonard", "the-temple-of-atalhakkar", "the-lost-ones", "naga" },
      text = {
        { "The Swamp of Sorrows lies east of Duskwood, under a sky that is always grey: willow and mangrove, black water, mist, and a great deal of mud. It earns its name. Crocolisks lurk in the pools, naga haunt the coast, and in the middle of the mire lies a pool where a troll temple sank long ago, with dragons sleeping over it." },
        { "The Horde has a town here, Stonard, and a few broken souls from another world live in the east of the swamp. There are not many reasons to come. The ones there are tend to be very old, or very dangerous, and usually both." },
      },
    },
    ["the-fallen-hero"] = {
      title = "The Fallen Hero", kind = "figure", chapter = "swamp-of-sorrows", portrait = 6775,
      unlock = { { npc = 7572 }, { quest = 2681 } },
      also = { "razelikh-the-defiler", "stonard", "burning-legion" },
      text = {
        { "Outside Stonard stands the ghost of a hero of the Horde, waiting for orders. In life he led his warriors into the Blasted Lands without waiting for them, and found there what the orders would have warned him of: the demon Razelikh and his lieutenants, who took his men and bound their spirits in stones of torment." },
        { "He blames himself for all of it, and he will tell his story to anyone who stops to listen. He wants his men freed, and Razelikh destroyed, and he will help any traveller willing to try, Horde or Alliance. It is the only thing left that he can do." },
      },
    },
    ["the-lost-ones"] = {
      title = "The Lost Ones", kind = "creature", chapter = "swamp-of-sorrows", portrait = 152,
      unlock = { { kill = 755 }, { kill = 757 }, { kill = 759 }, { kill = 760 }, { kill = 761 }, { kill = 762 }, { kill = 763 }, { kill = 1106 }, { kill = 6913 }, { area = 76 } },
      also = { "swamp-of-sorrows", "burning-legion" },
      text = {
        { "The exiles at the Harborage call themselves draenei. Hooved and tendrilled, with blue-grey skin, they are unlike the other peoples a traveller usually meets in Azeroth. They say they came from the orcs' world after a terrible journey. Those at the Harborage remain gentle and willing to speak." },
        { "Others live in the Fallow Sanctuary and are called the Lost Ones. The exiles say the journey broke their former brethren. They attack those who approach and have stolen crystals the exiles hold sacred. These local accounts tell us little about their earlier life or what happened before they came here. I would rather leave that portion of the page open than supply them with a past they have not described." },
      },
    },
    ["the-temple-of-atalhakkar"] = {
      title = "The Temple of Atal'Hakkar", kind = "place", chapter = "swamp-of-sorrows",
      unlock = { { area = 1477 }, { area = 74 }, { read = { "Wrath of Soulflayer", "영혼약탈자의 격노", "La colère du fléau des âmes", "Der Zorn des Seelenschinders", "噬灵者的愤怒", "La ira del Cazador de Almas", "Гнев Свежевателя Душ", "A Ira do Esfolador de Almas", "靈魂掠奪者的憤怒" } } },
      also = { "hakkar", "gurubashi-empire", "eranikus", "dragons-of-nightmare" },
      text = {
        { "When the Gurubashi rose against the priests who had brought Hakkar into the world, the Atal'ai fled into this swamp and built a temple to their god, and went on trying to call him back. The green dragons of Ysera found them. They sank the temple beneath the swamp, and Ysera set some of her own to guard it, so that Hakkar should never come through it again." },
        { "The Atal'ai are still in it, under the water, and their prophet Jammal'an has promised them that when Hakkar returns he will give them eternal life. They have nearly done it. The dragons who guard the temple are no longer what they were, and the Horde in Stonard and the Alliance alike want the Atal'ai stopped before the Soulflayer walks again." },
      },
    },
    ["atiesh"] = {
      title = "Atiesh", kind = "history", chapter = "tanaris",
      unlock = { { quest = 9251 }, { quest = 9257 } },
      also = { "the-guardians-of-tirisfal", "karazhan", "bronze-dragonflight", "kelthuzad", "naxxramas", "temple-of-ahnqiraj" },
      text = {
        { "Atiesh was the staff of the Guardians of Tirisfal, Medivh's in the end, and after his death it was broken and scattered. Its splinters were gathered from the necropolis of Naxxramas, where Kel'Thuzad sat on his throne holding what the bearer sought. Its base went into Ahn'Qiraj with the dwarf explorer Brann Bronzebeard, who came out again without it." },
        { "A staff that had carried a Guardian's power had carried Sargeras's too, as its last Guardian had, and the evil was still inside it. Anachronos of the bronze flight, by the Caverns of Time, sends whoever brings him the pieces to Stratholme, to the consecrated ground where the greatest knights of Lordaeron were murdered, to call out the thing within and destroy it." },
        { "Very few will ever hold it. The bronze dragon says that the one who does was always fated to. The bronze flight says that sort of thing a great deal." },
      },
    },
    ["caverns-of-time"] = {
      title = "The Caverns of Time", kind = "place", chapter = "tanaris",
      unlock = { { area = 2300 }, { npc = 15192 } },
      also = { "tanaris" },
      text = {
        { "In the east of Tanaris, among the rocks above the sea, a cave leads down into the Caverns of Time, the lair of the bronze dragonflight. Their master is Nozdormu, the Timeless One, the Dragon Aspect who watches over time, and his dragons guard its paths so that what was may not be undone." },
        { "No traveller goes far inside. But at the mouth of the caverns, a bronze dragon in mortal shape, Anachronos, has been seen waiting, and he knows a great deal about the war against the insects of Silithus a thousand years ago, and about the part his flight played in it." },
      },
    },
    ["gadgetzan"] = {
      title = "Gadgetzan", kind = "place", chapter = "tanaris",
      unlock = { { area = 976 } },
      also = { "steamwheedle-cartel", "tanaris", "zulfarrak" },
      text = {
        { "Gadgetzan is a goblin town in the north of the Tanaris desert, run for the Steamwheedle Cartel by Marin Noggenfogger. It has walls, wells, an auction house, an inn, a great many engineers and a guard of hired bruisers, who keep the peace with great enthusiasm. Alliance and Horde both trade here, and both behave, or else." },
        { "The town lives on its water. Its engineers dig the wells and divine where to dig the next ones, and everyone else pays for it. It is also the place to buy almost anything, from a goblin's elixir that may turn you into a skeleton to the eggs of strange birds, and to hear about almost everything going on in the south." },
      },
    },
    ["sandfury-trolls"] = {
      title = "The Sandfury Trolls", kind = "faction", chapter = "tanaris", portrait = 6413,
      unlock = { { kill = 5645 }, { kill = 5646 }, { kill = 5647 }, { kill = 5648 }, { kill = 5649 }, { kill = 5650 }, { kill = 7246 }, { kill = 7247 }, { kill = 7267 }, { kill = 7268 }, { kill = 7271 }, { kill = 7274 }, { kill = 7275 }, { kill = 7787 }, { kill = 7788 }, { kill = 7789 }, { kill = 7795 }, { kill = 7796 }, { kill = 7797 }, { kill = 8127 }, { kill = 8876 }, { kill = 8877 }, { kill = 11387 } },
      also = { "zulfarrak", "tanaris", "hakkar", "silithid" },
      text = {
        { "The Sandfury are the trolls of the Tanaris desert, tall, lean and hard as the sand they live on. Their capital is Zul'Farrak, in the west of the desert, and they defend what is left of their lands against everyone: Alliance, Horde, goblins, ogres, bandits, and above all the insects of the south." },
        { "They are an old people with old wars behind them. Their martyr Theka died fighting the insect warriors who came against his city, and the Sandfury say his killers were cursed to live on as scarabs at his shrine. They worship the great hydra Gahz'rilla in its sacred pool, and they raise their own dead to keep working when they fall." },
      },
    },
    ["tanaris"] = {
      title = "Tanaris", kind = "place", chapter = "tanaris",
      unlock = { { area = 440 } },
      also = { "gadgetzan", "sandfury-trolls", "uldum", "caverns-of-time", "steamwheedle-cartel", "silithid" },
      text = {
        { "Tanaris is the great desert of southern Kalimdor, an ocean of dunes and broken rock between the Thousand Needles and the sea. Water is worth more than gold here, and the goblins who run its only town know it." },
        { "It is a crowded desert for all its emptiness. The Sandfury trolls hold their city in the west, bandits of the Wastewander roam the dunes, pirates hold the southern coast, ogres the south, and in the Gaping Chasm the silithid are stirring. And in the far south, behind sealed gates, lies one of the titans' own works, which the Explorers' League would give its beards to enter." },
      },
    },
    ["the-tablets-of-mosharu"] = {
      title = "The Tablets of Mosh'aru", kind = "history", chapter = "tanaris",
      unlock = { { quest = 8181 } },
      also = { "hakkar", "zulfarrak", "the-temple-of-atalhakkar", "zulgurub", "zandalar-tribe" },
      text = {
        { "Yeh'kinya, a troll at Steamwheedle Port, knows a great deal about Hakkar the Soulflayer and says he believes none of it. There is a prophecy among the trolls, he explains, that the dead god will one day return, to trollkind's glory or to the end of all things. A myth, he calls it. But the god's essence holds great power, and that power ought to be kept from those who would abuse it." },
        { "So he gathers. First the spirits of the vale screechers of Feralas, cousins of the old god. Then the two tablets of the prophecy of Mosh'aru, carried to Zul'Farrak long ago, one held by Theka the Martyr, long dead, among the scarabs his persecutors were cursed into, the other by the hydromancer Velratha at Gahz'rilla's pool. Then an ancient egg from a cave behind the amphitheatre of Jintha'Alor. And at last the essence of Hakkar's avatar itself, drawn out in the Sunken Temple and sealed in the egg. You have touched a legend, he tells the traveller who brings it back. I have known scholars who said they believed none of what they studied. None of them collected it so carefully." },
        { "Prospector Ironboot, a dwarf at the same port, had been doing some reading of his own. There were six tablets of Mosh'aru, not two. The four Yeh'kinya never asked for, two with the Mossflayer trolls of the Eastern Plaguelands and two with the Smolderthorn in Blackrock Spire, reveal what the egg is for. It does not hold Hakkar. It brings him back. When the traveller confronted him, Yeh'kinya did not trouble to deny it. The Soulflayer was reborn, he said, in the old troll kingdom of Zul'Gurub, and he thanked the traveller for speeding his return. Ironboot sent them on to the Zandalar on Yojamba Isle, who might know how to stop him." },
      },
    },
    ["uldum"] = {
      title = "Uldum", kind = "history", chapter = "tanaris",
      unlock = { { area = 990 }, { npc = 7918 }, { quest = 2954 } },
      also = { "platinum-discs", "uldaman", "tanaris", "explorers-league" },
      text = {
        { "Uldum's sealed gates stand in the Valley of the Watchers, far south in Tanaris. Bring the platinum discs of Uldaman near them and the Stone Watcher of Norgannon wakes. It guards entry and requires the Plates of Uldum before it will admit anyone." },
        { "The Watcher describes a Titan research facility concerned with the life of this world. It does not tell us where the required plates lie. The League has a name, a purpose and a closed gate to investigate, traveller. We would very much like to add a way through it." },
      },
    },
    ["zulfarrak"] = {
      title = "Zul'Farrak", kind = "place", chapter = "tanaris",
      unlock = { { area = 1176 }, { kill = 7273 }, { kill = 7267 } },
      also = { "sandfury-trolls", "hakkar", "the-temple-of-atalhakkar", "tanaris" },
      text = {
        { "Zul'Farrak is the city of the Sandfury trolls, a walled city of sandstone in the west of Tanaris, with pyramids, shrines and a sacred pool where the hydra Gahz'rilla is called up from the deep. Chief Ukorz Sandscalp rules it, and the shrine of the martyr Theka stands within its walls." },
        { "Many come here for what the trolls guard. The tablets of the prophecy of Mosh'aru speak of a way to contain the god Hakkar's essence. There is a legendary blade too, and the trolls' own tempering agent, which smiths prize. And there is treasure, which brings goblins and fools in equal number. Most of them never leave." },
      },
    },
    ["darnassus"] = {
      title = "Darnassus", kind = "place", chapter = "teldrassil",
      unlock = { { area = 1657 } },
      also = { "tyrande-whisperwind", "fandral-staghelm", "teldrassil", "cenarion-circle" },
      text = {
        { "Darnassus stands in Teldrassil's crown, a new capital built after the Third War. Moonlight, waterfalls and the glow of the Temple of the Moon fill a city with few walls and halls grown among the branches. An Ironforge dwarf is accustomed to having rather more stone overhead." },
        { "The night elves have joined the Alliance, opening this city to visitors from peoples they long kept apart from. Tyrande Whisperwind leads the priestesses from the Temple, while Fandral Staghelm directs the druids in the Cenarion Enclave. Learn those two places, traveller. Much of the city's business begins in one or the other." },
      },
    },
    ["dolanaar"] = {
      title = "Dolanaar", kind = "place", chapter = "teldrassil",
      unlock = { { area = 186 } },
      also = { "teldrassil", "sickness-of-teldrassil" },
      text = {
        { "Dolanaar lies on the road from Shadowglen to Darnassus, gathered around a moonwell with an inn and buildings among the trees. Druids and Sentinels work here close to the forest's troubles. It is a useful stopping place before a traveller continues to the capital." },
        { "Lately their concerns include the Gnarlpine furbolgs, satyrs in the caves and sick creatures in the woods. The village's quiet appearance offers little measure of that work. Listen to what its keepers ask of you. They have watched the change in the country around them." },
      },
    },
    ["druids-of-the-talon"] = {
      title = "The Druids of the Talon and the Claw", kind = "faction", chapter = "teldrassil",
      unlock = { { area = 262 }, { quest = 486 }, { quest = 2561 } },
      also = { "druids", "the-emerald-dream", "malfurion-stormrage", "furbolgs", "teldrassil" },
      text = {
        { "Malfurion's druids were never one order. Some took the shape of the great bear and became the Druids of the Claw. Others took the shape of the storm crow and became the Druids of the Talon. Both kept the pact with Ysera and slept for centuries in the barrow dens while their spirits walked the Emerald Dream, and in the Third War Malfurion woke them to fight." },
        { "Some sleep still. In the Ban'ethil Barrow Den on Teldrassil, the Druids of the Talon lie hibernating under the watch of a Great Warden. The Gnarlpine furbolgs have broken in, and one of them, Ursal the Mauler, has meddled with the sleepers' calling until they are in danger of never waking at all. A druid of the Claw lost in the same den has had his own body turned against him." },
        { "They are not always easy to wake. Kerlonian Evershade, a druid of the Claw newly back from the Dream, can be found dozing by the road in Darkshore, and asks to be woken with his horn if he nods off on the way. Ten thousand years is a long time to have been tired." },
      },
    },
    ["fandral-staghelm"] = {
      title = "Arch Druid Fandral Staghelm", kind = "figure", chapter = "teldrassil", portrait = 1542,
      unlock = { { npc = 3516 } },
      also = { "darnassus", "sickness-of-teldrassil", "cenarion-circle", "silithid" },
      text = {
        { "Fandral Staghelm is the Arch Druid of the Cenarion Circle in Malfurion Stormrage's absence, and the one who led the druids in growing Teldrassil. He is old, proud and grave, and the druids follow him with something close to awe." },
        { "His people remember one grief above the others. A thousand years ago, in the war against the insect empire of Ahn'Qiraj, his son Valstann rode to save Southwind Village and did not come back. Days later the Qiraji general Rajaxx walked out in front of the night elf army holding the young elf in his claws, and tore him apart before his father's eyes. When the dragons and the druids at last sealed the Qiraji behind the Scarab Wall, Anachronos gave Fandral the scepter that would open it again, and Fandral smashed it against the gate. 'I will have my son back,' he told the dragon, 'though it takes millennia.' He keeps the Cenarion Enclave in Darnassus, studies the troubles of the tree he planted, and will tell you he has them in hand." },
      },
    },
    ["shadowglen"] = {
      title = "Shadowglen", kind = "place", chapter = "teldrassil",
      unlock = { { area = 188 }, { area = 256 } },
      also = { "teldrassil", "sickness-of-teldrassil" },
      text = {
        { "Shadowglen gathers the night elves' young recruits around Aldrassil, a great tree whose branches house their teachers. Druids, priestesses and Sentinels tend this hollow in Teldrassil's forest. Its Conservator teaches that nature's balance begins with small things." },
        { "The recruits have work before them almost at once. Spiders have grown large, and the sprites and grells have turned vicious. A traveller beginning here learns the guardians' concern for the forest by helping with what has gone wrong in it." },
      },
    },
    ["sickness-of-teldrassil"] = {
      title = "The Sickness of Teldrassil", kind = "history", chapter = "teldrassil",
      unlock = { { kill = 3535 }, { area = 262 }, { area = 258 }, { quest = 476 } },
      also = { "teldrassil", "furbolgs", "satyrs", "fandral-staghelm" },
      text = {
        { "Teldrassil lacks the blessings that Alexstrasza and Nozdormu once gave Nordrassil. The druids of Dolanaar speak plainly about this, and about the troubles of the new tree: strange beasts rise from its ground, and creatures once friendly have turned violent." },
        { "Fel moss took hold of Ursal the Mauler and spread through his Gnarlpine tribe. Blackmoss the timberling is so overgrown that his severed heart still beats beneath the dark growth. A satyr lord occupies Fel Rock. In Ban'ethil, where Druids of the Talon sleep in the Emerald Dream under their pact with Ysera, the warden has fallen silent." },
        { "Fandral acknowledges the problems and has remedies to offer. Other druids continue their investigations. Bring them what you find, traveller. A tree large enough to shelter a people is also rather large for its keepers to examine." },
      },
    },
    ["teldrassil"] = {
      title = "Teldrassil", kind = "place", chapter = "teldrassil",
      unlock = { { area = 141 } },
      also = { "darnassus", "sickness-of-teldrassil", "shadowglen" },
      text = {
        { "Teldrassil is a tree, and I write that sentence knowing how foolish it sounds. It rises out of the sea off the northern coast of Darkshore, so vast that forests grow on its branches and rivers run along them, and the night elves live in its crown. Its name means \"crown of the earth\"." },
        { "The night elves once had another such tree, Nordrassil, on Mount Hyjal, and while it stood they never aged. At the end of the last war they let it be broken to destroy the demon Archimonde, and gave up their immortality with it. When the war was over, the druids under Fandral Staghelm grew Teldrassil to take its place." },
        { "The old tree had the blessing of the great dragons. The new one does not, and its own keepers admit that its growth has not been without flaw. I will say more of that elsewhere. For now, take ship from Auberdine, pass through the gateway from Rut'theran, and see it: there is nothing else like it in the world." },
      },
    },
    ["tyrande-whisperwind"] = {
      title = "Tyrande Whisperwind", kind = "figure", chapter = "teldrassil", portrait = 7274,
      unlock = { { npc = 7999 } },
      also = { "darnassus", "cenarion-circle", "fandral-staghelm" },
      text = {
        { "Tyrande Whisperwind leads the night elves as High Priestess of Elune. Ten thousand years ago she was a young priestess fighting the Legion beside Malfurion and Illidan Stormrage. She loved Malfurion. Illidan's love for her went unanswered. She was the one who persuaded the others that Malfurion was right and the Well had to be destroyed, and before the end Azshara's satyrs took her prisoner. Along the way she took in a young orphaned archer, Shandris Feathermoon, who leads the Sentinels as their general now." },
        { "While the druids slept in the Emerald Dream, her priestesses and Sentinels guarded the forests through the long ages. In the Third War she rallied the night elves, woke Malfurion and stood at Hyjal when Archimonde fell." },
        { "Malfurion is now missing, and the druids do not know his fate. Tyrande leads from Darnassus's Temple of the Moon while Fandral Staghelm heads the druids. Treat her welcome with respect, traveller. The priestess greeting visitors has led her people through wars far older than our kingdoms." },
      },
    },
    ["arikara"] = {
      title = "Arikara", kind = "creature", chapter = "thousand-needles", portrait = 10183,
      unlock = { { quest = 5088 } },
      also = { "freewind-post", "thousand-needles", "grimtotem", "cairne-bloodhoof" },
      text = {
        { "Hagar Lightninghoof of Freewind Post wanted a look at an egg that the serpents of the canyons were guarding as though it were one of their own. When at last it was brought to him he took one look and sent for Motega Firemane at Whitereach Post. Vengeance had come to Thousand Needles, Hagar said, and Motega agreed: the legend of Arikara was true." },
        { "Arikara is not tracked but called. The way is the sacred fire of life, long dormant at Darkcloud Pinnacle on the isolated needle where the dead are buried. It is lit with a powder of Incendia agave, a herb that grows nowhere but the Needles. Motega sent the herbs to Magatha Grimtotem on the Elder Rise in Thunder Bluff to be enchanted, and Magatha gave a reason for haste. Too much of the tauren lore had changed, she said, and she feared it had angered Arikara, and that the serpent was stalking Cairne Bloodhoof." },
        { "Motega could not make sense of it when the deed was done. Why would Arikara be hunting Cairne? But Magatha could not be wrong, he decided. She was, after all, the tauren's most powerful shaman. He shook his head over it, and paid the hunter all the same." },
      },
    },
    ["dorn-plainstalkers-tests"] = {
      title = "Dorn Plainstalker's Tests", kind = "history", chapter = "thousand-needles", portrait = 10969,
      unlock = { { quest = 1394 } },
      also = { "thousand-needles", "freewind-post", "parqual-fintallas", "elementals", "tauren" },
      text = {
        { "Dorn Plainstalker, a tauren who lives on Splithoof Crag above the Thousand Needles, holds that a being is made of spirit, body and mind, and that each of them can be tried. He tries the young of any tribe of the Horde who come to him, because too many of them, in his experience, leave home before they are ready for what waits beyond." },
        { "Faith comes first: a leap from the planks above the Needles, with no promise of coming through it alive. The body is tried twice. Endurance means raiding the Roguefeather harpies' den west of Freewind Post until Grenka Bloodscreech comes out for the intruder herself. Strength means Rok'Alim the Pounder, an elemental of an older order. The Old Gods, Dorn says, once held the elementals to this world, and when the Old Gods fell most of the elementals went with them, returning now only at a summoner's call. A few were strong enough to stay. Rok'Alim is one." },
        { "The mind is not Dorn's to try. He sends his students to Braug Dimspirit, a shaman who waits by the Talondeep Path and calls everything they have done so far child's play. Braug sets them a book, the Legacy of the Aspects, from the bottom of Dor'danil in Ashenvale, and then a question about it. Then he sends them across the sea to the Undercity and Parqual Fintallas, who wants a book stolen from the Scarlet Monastery's library before he asks another. Those who come back to Splithoof Crag find Dorn waiting. It is the only rite of passage I know of that sends its candidates to the library, twice, and I approve." },
        { side = "Horde", aside = true, sign = "P. F.", "Braug's students reach me very sure of themselves, and I tell them they are a tavern rumour. The ones who prove me wrong are the ones I remember." },
      },
    },
    ["freewind-post"] = {
      title = "Freewind Post", kind = "place", chapter = "thousand-needles",
      unlock = { { area = 484 } },
      also = { "thousand-needles", "grimtotem", "centaurs" },
      text = {
        { "Freewind Post is a tauren village built on top of the needles in the middle of the canyon, a cluster of huts on the high rock joined by rope bridges, reached by lift. Wind riders come and go, and the tauren hunt the canyon floor below." },
        { "It is under pressure from two sides. The Galak centaurs have been raiding more and more, and the Grimtotem tauren, who hold Darkcloud Pinnacle nearby, have turned against their own kind. The Freewind tauren say they have been acting strangely for some time. It is a hard thing for a tauren to say about another tauren." },
      },
    },
    ["rustmaul-dig-site"] = {
      title = "The Rustmaul Dig Site", kind = "place", chapter = "thousand-needles",
      unlock = { { area = 479 } },
      also = { "silithid", "thousand-needles", "explorers-league" },
      text = {
        { "At the edge of the Shimmering Flats a team of dwarves set up a dig, Rustmaul, after whatever lies under the salt. The Horde sent a war party to drive them off. In the middle of the fight, the ground opened, and insects poured out of a cave in the dig: silithid, more than either side had ever seen, and they nearly killed everyone." },
        { "The dwarves have gone. The insects have not. The Horde's hunters who survived now count the silithid a far greater danger than any dig team, and so, having read the reports, do I. What the dwarves were looking for, no one has told me. I am not sure they found it." },
      },
    },
    ["shimmering-flats"] = {
      title = "The Shimmering Flats", kind = "place", chapter = "thousand-needles",
      unlock = { { area = 439 }, { area = 2240 } },
      also = { "thousand-needles", "steamwheedle-cartel" },
      text = {
        { "The Shimmering Flats are a broad salt pan in eastern Thousand Needles, white enough to dazzle a traveller's eyes. Goblins and gnomes have built the Mirage Raceway across it. Their rocket cars circle the track before crowds and bookmakers, with frequent interruptions for crashes." },
        { "Wreckage supplies Kravel Koalbeard with parts to sell back to the teams. The Brassbolts brothers need helmets for their pilots. A race produces winners, losers and a useful quantity of salvage. The people working beside the track have found occupations in all three." },
      },
    },
    ["thousand-needles"] = {
      title = "Thousand Needles", kind = "place", chapter = "thousand-needles",
      unlock = { { area = 400 } },
      also = { "freewind-post", "shimmering-flats", "centaurs", "grimtotem" },
      text = {
        { "South of the Barrens the ground drops away by a great lift into Thousand Needles: a deep canyon full of towering spires of stone, hundreds of them, standing up out of the dust like the bones of the earth. The tauren live on top of them, the centaurs of the Galak clan in the canyon below, and the wind riders and the harpies in between." },
        { "In the east the canyon opens into the Shimmering Flats, a dry white bed of salt where the heat shimmers off the ground. The goblins and the gnomes have built a race track on it. I am told this is a natural thing for goblins and gnomes to do with a desert." },
      },
    },
    ["alonsus-faol"] = {
      title = "Alonsus Faol", kind = "figure", chapter = "tirisfal",
      unlock = { { area = 173 }, { read = { "Archbishop Alonsus Faol", "대주교 알론수스 파올", "Archevêque Alonsus Faol", "Erzbischof Alonsus Faol", "大主教阿隆索斯·法奥", "Arzobispo Alonsus Faol", "Архиепископ Алонсий Фаол", "Arcebispo Alonso Faol", "大主教阿隆索斯·法奧" } } },
      also = { "church-of-the-holy-light", "paladins", "uthers-tomb", "northshire-abbey", "stratholme" },
      text = {
        { "Alonsus Faol led the clerics of Northshire before the First War, and when Stormwind fell and the abbey with it, the old man went north with the refugees. In Lordaeron, as Archbishop, he gave the Church of the Holy Light a sword: he founded the Knights of the Silver Hand and anointed his apprentice, Uther, the first of the paladins." },
        { "His work went further than the battlefield. A plaque in Stormwind's cathedral says he began it in Stratholme, helped reform the Brotherhood of Northshire after the Second War and raised the funds to rebuild Stormwind itself. He died before the plague came, of nothing worse than age, so far as anyone knows." },
        { "This is said to be where he lies. Before the Scourge it was a place of pilgrimage. Now it gathers the dead of the Scarlet Monastery, and no one comes to mourn him. He deserved better, and so did the order he founded." },
      },
    },
    ["brill"] = {
      title = "Brill", kind = "place", chapter = "tirisfal",
      unlock = { { area = 159 } },
      also = { "the-forsaken", "royal-apothecary-society" },
      text = {
        { "Brill was a quiet farming town on the road east of Deathknell, and the Forsaken have made it theirs: the town hall holds a magistrate, the Gallows' End Tavern serves its strange drinks to strange customers, and in its cellar the Deathguard keep their prisoners, dwarven mountaineers among them, until they can be dealt with." },
        { "It is also where the Royal Apothecary Society does a good deal of its work. I will say no more about that than that a dwarf should not accept a drink in Brill." },
      },
    },
    ["deathknell"] = {
      title = "Deathknell", kind = "place", chapter = "tirisfal",
      unlock = { { area = 154 } },
      also = { "the-forsaken", "scourge" },
      text = {
        { "Deathknell is a crypt and a ruined village at the western edge of Tirisfal, and it is where the Forsaken wake. The dead of Lordaeron who rise with their minds their own are brought here, and the caretaker of the crypt greets them with the words every one of them remembers: you are the Lich King's slave no more." },
        { "Not all who rise are so lucky. The north of the village is full of the mindless dead, who are still the Lich King's, and the newly awakened Forsaken's first duty is to destroy them: their former brothers and sisters, as the shadow priests of the chapel remind them." },
      },
    },
    ["fall-of-lordaeron"] = {
      title = "The Fall of Lordaeron", kind = "history", chapter = "tirisfal",
      unlock = { { area = 153 }, { read = { "The Scourge of Lordaeron", "로데론의 스컬지", "Le Fléau de Lordaeron", "Die Geißel von Lordaeron", "洛丹伦的天灾", "La Plaga de Lordaeron", "Падение Лордерона", "O Flagelo de Lordaeron", "羅德隆的天災" } }, { read = { "Here Lies King Terenas Menethil II", "국왕 테레나스 메네실 2세 여기 잠들다", "Ci-gît le roi Terenas Menethil II", "Hier ruht König Terenas Menethil II.", "泰瑞纳斯·米奈希尔二世在此长眠", "Aquí yace el rey Terenas Menethil II", "Здесь покоится Теренас Менетил II", "Aqui Jaz o Rei Terenas Menethil II", "泰瑞納斯·米奈希爾二世在此長眠" } } },
      also = { "undercity", "scourge", "sylvanas-windrunner" },
      text = {
        { "Lordaeron was the first among the kingdoms of men, and its king, Terenas Menethil, had led the Alliance through the Second War. When the plague came out of the north and the dead began to rise, it was his son, Prince Arthas, a paladin of the Silver Hand, who rode out against it." },
        { "Arthas pursued it too far. He put the plague-stricken city of Stratholme to the sword rather than see its people rise, followed the plague's masters to Northrend, and took up a cursed runeblade there, Frostmourne. When he came home the people cheered him through the gates. He walked into his father's throne room and killed him, and the kingdom fell to the dead behind him." },
        { "These ruins are where it happened. The Forsaken walk over them every day, and some of them were in the crowd that cheered." },
        { side = "Horde", aside = true, sign = "P. F.", "She writes that some of the Forsaken were in the crowd that cheered. Some of us were. I have tried more than once to write that day down, and I have not managed it yet." },
      },
    },
    ["parqual-fintallas"] = {
      title = "Parqual Fintallas", kind = "figure", chapter = "tirisfal", portrait = 10197,
      unlock = { { npc = 4488 } },
      also = { "undercity", "the-forsaken", "scarlet-monastery", "archesonus" },
      text = {
        { "Before the plague, Parqual Fintallas was one of Lordaeron's great historians. He is Forsaken now and keeps to the Apothecarium in the Undercity, still studying, though what he studies has changed along with him." },
        { "He sets the Horde's young heroes a test of lore. Before he will ask his question, he sends them to the Scarlet Monastery for the Beginnings of the Undead Threat, a book the Crusade uses to train its paladins against his kind, and he expects them to have read it. Knowledge, he holds, counts for more than strength. I have never heard a historian argue otherwise." },
        { "We have never met, and are unlikely to. I am told a copy of this ledger has reached him all the same, by roads I would rather not know about. I hope he finds it fair. He would know better than most where it is not." },
        { side = "Horde", aside = true, sign = "P. F.", "She is kinder to me than the Crusade's books are." },
      },
    },
    ["royal-apothecary-society"] = {
      title = "The Royal Apothecary Society", kind = "faction", chapter = "tirisfal", portrait = 1680,
      unlock = { { npc = 2055 } },
      also = { "the-forsaken", "brill", "scourge" },
      text = {
        { "Master Faranell's Royal Apothecary Society serves the Forsaken with alchemy, poisons and the promise of a new plague. Sylvanas has charged its members with finding a disease that can destroy the Lich King's Scourge. Their preparations reach far beyond the laboratories of the Undercity." },
        { "In Brill and Hillsbrad, travellers gather blood and other ingredients for experiments on beasts, murlocs and prisoners. Apothecary Lydon looks out over Hillsbrad's flowering country and longs to see his work bring death to it. Whatever the Society's declared enemy, his ambitions plainly include the living." },
        { "The Forsaken know better than most what it means to have a plague take one's home. That knowledge has not made all of their apothecaries reluctant to visit the same misery on someone else's." },
      },
    },
    ["ruins-of-lordaeron"] = {
      title = "The Ruins of Lordaeron", kind = "place", chapter = "tirisfal",
      unlock = { { area = 16611 }, { kill = 250657 }, { kill = 250660 } },
      also = { "undercity", "fall-of-lordaeron", "the-forsaken", "sylvanas-windrunner" },
      text = {
        { "Above the Undercity, the streets of Lordaeron's capital are less empty than they look from the gate. The Scourge still walk the deeper ruins in numbers, and an unholy fog has crept over the streets and the old graveyard, raised, the Deathguard believe, by a necromancer called Rath'mael on the Lordamere Overlook. The Forsaken send what forces they can spare, and their losses are such that a paladin of the Royal Quarter asks travellers for the intact limbs the dead leave behind." },
        { "Not everyone who goes up goes for the Banshee Queen. Edward Heartweaver walked to the graveyard every week, looking for the son he lost when Arthas razed the city, until one week he did not come home. And among the abominations stitched together up there is one the apothecaries call the Baron, whom they know by an older name: Othmar Garithos, the lord who made common cause with Sylvanas against the Scourge and did not survive the arrangement. Captain Truman, who served him, still waits in the ruins for his commander to return." },
        { side = "Horde", aside = true, sign = "P. F.", "Of everything on this page, it is Edward Heartweaver's weekly walk I keep coming back to." },
      },
    },
    ["scarlet-monastery"] = {
      title = "The Scarlet Monastery", kind = "place", chapter = "tirisfal",
      unlock = { { area = 796 } },
      also = { "scarlet-crusade", "whitemane-and-mograine", "the-forsaken" },
      text = {
        { "The Scarlet Crusade holds a monastery on a hill in northern Tirisfal, above the sea. Its walls enclose a library, an armoury, a graveyard and a cathedral. Knights, priests and inquisitors train there for a war that extends well beyond the Scourge." },
        { "The Forsaken are enemies too, as is any traveller the Crusade finds suspicious. High Inquisitor Whitemane and Scarlet Commander Mograine hold the cathedral, while Forsaken champions are sent against the fortress. The monastery has the outward furnishings of a house of the Light. Approach with more caution than that description might suggest." },
        { side = "Horde", aside = true, sign = "P. F.", "Behind those walls is a library, and in it a book they use to teach their paladins how to destroy my kind. I send heroes to fetch it, and I ask them to read it before they bring it back." },
      },
    },
    ["sylvanas-windrunner"] = {
      title = "Lady Sylvanas Windrunner", kind = "figure", chapter = "tirisfal", portrait = 11657,
      unlock = { { npc = 10181 } },
      also = { "the-forsaken", "undercity", "varimathras", "fall-of-lordaeron" },
      text = {
        { "Sylvanas Windrunner was the Ranger-General of Silvermoon, the high elves' greatest archer and the commander of their rangers, and she fought Prince Arthas every step of the way when he marched the Scourge into Quel'Thalas. When he finally broke through, he killed her, and as a punishment for her resistance he did not let her rest: he raised her as a banshee and bound her to his service." },
        { "When the Lich King's power faltered, Sylvanas broke free. She gathered the undead who had woken with her, turned a dreadlord to her service, and took the ruins of Lordaeron's capital for her own. The Forsaken call her the Dark Lady, and they would follow her anywhere." },
        { "She came of a family of rangers. Her elder sister, Alleria, went through the Dark Portal with the Alliance Expedition and never came back. It was Sylvanas who wrote the words on her plaque at Stormwind's gate. The youngest, Vereesa, was a ranger of Quel'Thalas too." },
        { "She wants Arthas dead. Beyond that, she keeps her own counsel, and her eyes give nothing away." },
        { side = "Horde", aside = true, sign = "P. F.", "She gave us back our minds, which is more than the Light managed. What she means to do with us next, she has not said." },
      },
    },
    ["the-agamands"] = {
      title = "The Agamands", kind = "history", chapter = "tirisfal", portrait = 646,
      unlock = { { area = 157 }, { kill = 1654 }, { kill = 1655 }, { kill = 1656 }, { kill = 1657 }, { quest = 354 }, { quest = 1821 } },
      also = { "tirisfal-glades", "brill", "the-forsaken", "scourge" },
      text = {
        { "The Agamands were the richest family in Tirisfal, and these mills were theirs. When the Scourge came, they fortified the house and told everyone in their employ to stay and help them hold it. The farmhands stayed. They were loyal, one of them says now, and fools." },
        { "None of it held. The family and their workers died together and rose together, and the Agamands still walk the mills for the Lich King: Gregor, the father, Nissa, his wife, and their sons. Their crypt lies at the north end of the property, among the Scourge." },
        { "Some of their workers broke free and are Forsaken now. Coleman Farthing, who worked their mills, sends travellers back to destroy what is left of the family and rob their crypt of its heirlooms. Revenge, he says, has a sweet taste. He hopes they knew fear before the end. It is a foolish hope, he admits. He keeps it anyway." },
      },
    },
    ["the-ashbringer"] = {
      title = "The Ashbringer", kind = "history", chapter = "tirisfal", portrait = 2605,
      unlock = { { kill = 4542 }, { kill = 3976 } },
      also = { "scarlet-crusade", "whitemane-and-mograine", "scarlet-monastery", "argent-dawn", "kelthuzad", "stratholme" },
      text = {
        { "The Ashbringer was a man before it was a sword. Highlord Mograine founded the Scarlet Crusade with High General Abbendis and High Inquisitor Isillien, when it was still a noble order, and he was called the Ashbringer for what he did to the Lich King's armies: he would walk into whole battalions of undead and come out the other side with nothing behind him but ash. His blade took the name from him." },
        { "High Inquisitor Fairbanks, who was there, tells how it ended. The Grand Crusader struck a deal with Kel'Thuzad, and Mograine was led into an ambush in Stratholme by his own son, Renault. As the Scourge closed in and the blade began to glow, Renault picked it up and drove it through his father's back. 'What have you done, Renault?' were the Highlord's last words. The man and the blade had been one, and the murder corrupted both. Mograine rose as a death knight of Kel'Thuzad." },
        { "Fairbanks escaped Stratholme after two days among the dead and told the tale to anyone in the Monastery who would listen. He was murdered for it and hidden in its cathedral. But some heard him, he says, and that is how the Argent Dawn began. Renault leads the Monastery now, as its Scarlet Commander." },
      },
    },
    ["the-bulwark"] = {
      title = "The Bulwark", kind = "place", chapter = "tirisfal",
      unlock = { { area = 152 } },
      also = { "the-forsaken", "argent-dawn", "scourge", "cult-of-the-damned" },
      text = {
        { "The Bulwark is the wall the Forsaken have built at the eastern edge of Tirisfal, where the glades end and the Plaguelands begin, and it is held day and night against the Scourge. Deathguard man its gate, and officers of the Argent Dawn keep a post there too, which tells you how much both of them fear what lies beyond." },
        { "There are stranger things at the Bulwark. Alexi Barov, the last of a noble house of Lordaeron that sold its castle to the Cult of the Damned, keeps company there with the Forsaken, and has opinions about his family's fortune that he is happy to share." },
      },
    },
    ["the-crusades-fallen"] = {
      title = "The Crusade's Fallen", kind = "history", chapter = "tirisfal",
      unlock = { { read = { "Arellas Fireleaf", "아렐라스 파이어리프", "阿雷拉斯·火叶", "Arellas Hojafuego", "Ареллас Огненный Лист", "Arellas Firafolha", "阿雷拉斯·火葉" } }, { read = { "Admiral Barean Westwind", "제독 바렌 웨스트윈드", "Amiral Barean Westwind", "海军上将巴利·韦斯温", "Almirante Barean Viento Oeste", "Адмирал Бареан Вествинд", "Almirante Barean Zefirália", "海軍上將巴瑞恩·韋斯溫" } }, { read = { "Dorgar Stoenbrow", "도르가르 스톤브로", "Dorgar Stonebrow", "多加尔·石眉", "Dorgar Petrocejas", "Доргар Камнелоб", "Dorgar Hefastão", "多加爾·石眉" } }, { read = { "Fellari Swiftarrow", "펠라리 스위프트애로우", "菲尔拉蕾·迅箭", "Fellari Flechaveloz", "Феллари Быстрая Стрела", "Fellari Velosseta", "菲爾拉蕾·迅箭" } }, { read = { "Ferren Marcus", "페렌 마커스", "费伦·玛库斯", "Феррен Маркус", "Fernando Marco", "費倫·馬庫斯" } }, { read = { "Holia Sunshield", "홀리아 선쉴드", "阳炎之盾", "Holia Escusol", "Холия Солнечный Щит", "Holia Solbroquel", "陽炎之盾" } }, { read = { "Invar One-Arm", "외팔이 이바르", "Invar le Manchot", "钢铁武器", "Invar Unibrazo", "Инвар Однорукий", "Invar Sem-braço", "『獨臂』因瓦爾" } }, { read = { "Orman of Stromgarde", "스트롬가드의 오르만", "Orman de Stromgarde", "Orman von Stromgarde", "激流堡的奥玛尔", "Орман из Стромгарда", "激流堡的奧瑪爾" } }, { read = { "Valea Twinblades", "발리아 트윈블레이즈", "瓦雷亚", "Valea Filosgemelos", "Валея Два Клинка", "Valea Bilâmina", "瓦雷亞·吐溫布萊德" } }, { read = { "Yana Bloodspear", "야나 블러드스피어", "亚娜·血矛", "Yana Lanza de Sangre", "Яна Кровавое Копье", "Yana Lanssang", "亞娜·血矛" } }, { read = { "Harthal Truesight", "하르탈 트루사이트", "真实视界", "Harthal Vistarreal", "Хартал Проницательный", "Hereno Justo", "哈薩爾·圖塞特" } } },
      also = { "scarlet-crusade", "scarlet-monastery", "the-ashbringer", "whitemane-and-mograine" },
      text = {
        { "The Scarlet Monastery buries its heroes in its own graveyard, and their stones say more about the Crusade than its sermons do. Read them and you find it was never only a human order of Lordaeron: a high wizard and a ranger captain who were citizens of Quel'Thalas, assassins from Dalaran, a warrior of Alterac, a lord of the Red Caverns, an admiral of Kul Tiras." },
        { "Read further and you find how far it went. Orman of Stromgarde, its first Captain General, was lost at the mouth of Icecrown Glacier. The Grand Admiral of the Scarlet Fleet was lost off the frozen coast of Northrend, and the first Chief Assassin on Northrend's shores. The Crusade carried its war to the Lich King's own door, and the stones are what came back." },
        { "Others fell nearer home: a High Abbot killed defending the Monastery itself, a defender who died slaying a dreadlord, an elf locked in endless combat with a necromancer. Whatever the Crusade has become since, traveller, these were the people who believed in it first." },
        { side = "Horde", aside = true, sign = "P. F.", "I have read those stones too. I came away with a less generous account." },
      },
    },
    ["the-forsaken"] = {
      title = "The Forsaken", kind = "faction", chapter = "tirisfal", portrait = 2858,
      unlock = { { people = "Scourge" }, { area = 154 }, { area = 159 }, { npc = 10181 }, { read = { "Civil War in the Plaguelands", "오염지대의 내란", "Guerre civile dans les Maleterres", "Bürgerkrieg in den Pestländern", "瘟疫之地的内战", "Guerra civil en las Tierras de la Peste", "Гражданская война в Чумных землях", "Guerra Civil nas Terras Pestilentas", "瘟疫之地的內戰" } } },
      also = { "sylvanas-windrunner", "undercity", "scourge", "deathknell" },
      text = {
        { "When the Lich King's grip on his dead faltered, some of them woke. They were still dead, but their minds were their own again, and they remembered what they had been and what had been done to them. They call themselves the Forsaken, and they follow the one who freed them: Sylvanas Windrunner, the Banshee Queen." },
        { "They have taken back the ruin of their kingdom's capital and built a city beneath it, and they wage their own war against the Scourge that made them. They have joined the Horde, which needed allies against the Alliance, and the Horde has accepted them, which the Forsaken needed more. It is not a warm friendship." },
        { "I will not pretend the Forsaken are easy company. Most of them were men and women of Lordaeron, who remember their old lives and cannot go back to them. What they want now, beyond vengeance on the Lich King, no one outside the Undercity can say." },
        { side = "Horde", aside = true, sign = "P. F.", "No one outside the Undercity can say what we want, she writes. Most of us inside cannot either. I want to know what was done to us, and to write it down properly." },
      },
    },
    ["tirisfal-glades"] = {
      title = "Tirisfal Glades", kind = "place", chapter = "tirisfal",
      unlock = { { area = 85 } },
      also = { "undercity", "the-forsaken", "fall-of-lordaeron", "scarlet-monastery", "scourge" },
      text = {
        { "Tirisfal was the heart of the kingdom of Lordaeron: rolling farmland, orchards and mills around the capital, the richest country in the north. It is old ground in other ways, too. The glades gave their name to the secret order of mages, the Guardians of Tirisfal, who kept the world's watch for centuries." },
        { "Now it is a grey land. The plague took Lordaeron, the dead walked, and the capital fell. The farms are empty or worse, the trees are leafless and the light is always dim. The Forsaken rule it from beneath the ruined city, the Scarlet Crusade from their monastery in the north, and the Scourge still wander the fields between." },
      },
    },
    ["undercity"] = {
      title = "Undercity", kind = "place", chapter = "tirisfal",
      unlock = { { area = 1497 } },
      also = { "the-forsaken", "sylvanas-windrunner", "fall-of-lordaeron", "royal-apothecary-society", "parqual-fintallas" },
      text = {
        { "Lordaeron's capital lies in ruins above the Forsaken's own city. Beyond its broken walls are the shattered throne room and lifeless courtyards. Beneath them, old crypts and catacombs have become the Undercity, arranged around rings of green ooze. Sylvanas holds court in its royal quarter." },
        { "Merchants, trainers and guards occupy the other quarters, and the Royal Apothecary Society works in the Apothecarium. The Forsaken have made a functioning capital below the wreck of the one they knew in life. A traveller looking only at the ruins above would miss where the kingdom's surviving affairs are now conducted." },
        { side = "Horde", aside = true, sign = "P. F.", "She has the Apothecarium right, as far as it goes. You will find me there, on the southern of its two bridges, where I put questions to heroes who believe strength is enough. Come and be examined, traveller." },
      },
    },
    ["varimathras"] = {
      title = "Varimathras", kind = "figure", chapter = "tirisfal", portrait = 11658,
      unlock = { { npc = 2425 } },
      also = { "sylvanas-windrunner", "burning-legion", "undercity" },
      text = {
        { "When Arthas departed for Northrend, Varimathras and his fellow dreadlords ruled the ruins of Lordaeron. Sylvanas, newly free of the Lich King's control, defeated him and offered a choice between service and death. He chose service, then helped her turn against his brothers." },
        { "He now stands beside the Banshee Queen in the Undercity. It is an imposing partnership, though its beginning offers little reassurance about the loyalty of either party. Varimathras found a way to survive one change of master. Sylvanas has kept him where she can see him." },
        { side = "Horde", aside = true, sign = "P. F.", "We pass him in the Royal Quarter and say nothing. I am less sure than the Dark Lady seems to be that keeping him close is the same as keeping him loyal." },
      },
    },
    ["whitemane-and-mograine"] = {
      title = "Whitemane and Mograine", kind = "figure", chapter = "tirisfal", portrait = 2043,
      unlock = { { kill = 3977 }, { kill = 3976 } },
      also = { "scarlet-monastery", "scarlet-crusade" },
      text = {
        { "High Inquisitor Sally Whitemane and Scarlet Commander Renault Mograine hold the Scarlet Monastery's cathedral. He commands its knights. She guides its faith. Her command of the Light can raise him when he falls, making a victory over the commander less final than a traveller might hope." },
        { "Renault is the son of Highlord Alexandros Mograine, the Ashbringer, a great champion of the Silver Hand against the Scourge. His father is dead. Fairbanks, another High Inquisitor hidden in the cathedral, claims to know how he died and says that Renault was there. The Crusade would prefer his silence. Those who bring the Highlord's blade may hear the account it does not wish told. The Ashbringer's page in this ledger tells what he says." },
        { side = "Horde", aside = true, sign = "P. F.", "Whitemane raises her commander from the dead, and the Crusade burns the rest of us for less." },
      },
    },
    ["crystal-pylons"] = {
      title = "The Crystal Pylons", kind = "history", chapter = "ungoro-crater",
      unlock = { { quest = 4321 }, { npc = 9117 } },
      also = { "ungoro-crater", "marshals-refuge", "uldum" },
      text = {
        { "J.D. Collie's work begins with the coloured crystals scattered across Un'Goro. Reports of great pylons lined with crystals send her enquiries into the wilderness, where three stand in the north, east and west of the crater." },
        { "Different combinations produce useful effects at those pylons, and Collie has written a manual for further experiments. The expedition can do something with the crystals now, even while their makers' purposes remain a mystery. There is honest satisfaction in a discovery that reaches the workbench before it reaches the history books." },
      },
    },
    ["fire-plume-ridge"] = {
      title = "Fire Plume Ridge", kind = "place", chapter = "ungoro-crater",
      unlock = { { area = 537 } },
      also = { "ungoro-crater", "marshals-refuge" },
      text = {
        { "Fire Plume Ridge rises in the middle of Un'Goro, with lava on its slopes and fire elementals among the flows. Blazerunner occupies a cave near the peak. The volcano gives the crater's explorers a conspicuous subject for study." },
        { "Ringo went to investigate and was found in a cave on its southern slope, lost and badly overheated. The scholars at Marshal's Refuge still want to know what lies at the ridge's heart. A traveller can share their curiosity without sharing Ringo's preparations." },
      },
    },
    ["larkorwi"] = {
      title = "Lar'korwi", kind = "creature", chapter = "ungoro-crater", portrait = 11318,
      unlock = { { quest = 4292 } },
      also = { "ungoro-crater", "marshals-refuge", "tauren" },
      text = {
        { "Torwa Pathfinder, a tauren camped in Un'Goro, has a score to settle with Lar'korwi, the great raptor who rules the crater's ravasaurs. Long ago, Torwa says, a brother of his helped himself to a carcass Lar'korwi had brought down, never knowing the raptor was watching from the trees. Lar'korwi stalked him for days and wrecked whatever he had touched. At last the brother tried to flee the crater, and Lar'korwi killed him not far from where Torwa now waits." },
        { "Torwa's plan is to make the beast come to him. Whoever steals meat from a fresh kill will be followed, as his brother was. The scent glands of Lar'korwi's mates, taken among the ravasaur eggs, make a lure, and the stolen meat, rubbed with it and left on a mountain trail among the bones of great creatures long gone, should draw him out. Torwa describes a massive beast with claws to rival any blade, and promises death to whoever meets his eyes." },
        { "Those who bring back his head are praised in the Earth Mother's name, and Torwa ranks the deed with those of his greatest ancestors. The plan was Torwa's. The stealing, the gathering and the fighting he left to whoever he could talk into it." },
      },
    },
    ["linken"] = {
      title = "Linken", kind = "figure", chapter = "ungoro-crater", portrait = 8012,
      unlock = { { quest = 3962 } },
      also = { "ungoro-crater", "marshals-refuge", "fire-plume-ridge" },
      text = {
        { "Linken turned up at Marshal's Refuge one day with no idea how he had got there. Nobody else knows either, he says cheerfully. It is a secret to everybody. He is a gnome, though the gnomes of the camp note that he shows none of their interest in gadgets, and he had a pack, a sword, and a bump on the head." },
        { "The memories come back a piece at a time, as travellers help him: a sword to be tempered in the hot springs of Winterspring, a totem made with the help of a friend in Felwood. In the end he remembers. He came to the crater to fight Blazerunner, the fire elemental that guards an artifact called the Golden Flame, and this was to be the last step of a long journey." },
        { "He does not take it himself. You are the hero now, he tells whoever has helped him, and sends them on with a warning that it is dangerous to go alone. The Flame, he promises, will be taken back to his homeland and kept from evil hands. I have not found that homeland on any map. I have looked." },
      },
    },
    ["marshals-refuge"] = {
      title = "Marshal's Refuge", kind = "place", chapter = "ungoro-crater",
      unlock = { { area = 541 } },
      also = { "ungoro-crater", "crystal-pylons", "fire-plume-ridge" },
      text = {
        { "Marshal's Refuge is a camp on a ledge at the northern edge of the crater, where the survivors of the Marshal expedition took shelter. The expedition came to explore the crater under Williden and Hol'anyee Marshal, and it underestimated the beasts: their camps were overrun, and they fled to the high ground." },
        { "They are still there, with a strange crowd of scholars, hunters and lost explorers who have joined them, all of them studying the crater from the one place where nothing will eat them. One of them, an explorer named Ringo, wandered off to the volcano. I hear he was found." },
      },
    },
    ["ungoro-crater"] = {
      title = "Un'Goro Crater", kind = "place", chapter = "ungoro-crater",
      unlock = { { area = 490 } },
      also = { "marshals-refuge", "crystal-pylons", "fire-plume-ridge", "silithid", "earth-mother" },
      text = {
        { "Un'Goro is a steaming green bowl sunk between the deserts of Tanaris and Silithus. Devilsaurs stride through its jungle, stegodons and great apes inhabit the basin, and pterrordaxes circle above it. The tauren who travel here speak of creatures nobler than their counterparts outside, and of the crater's connection to the Earth Mother." },
        { "Tar pits, hot springs and Fire Plume Ridge divide the forest, with a silithid hive in the south. At Marshal's Refuge, the expedition studies a country that seems to have preserved another age. J.D. Collie's experiments with the coloured crystals have begun to reveal their uses. Their origin remains a larger question." },
        { "The Shapers' Terrace has given that question a place to begin." },
      },
    },
    ["andorhal"] = {
      title = "Andorhal", kind = "history", chapter = "western-plaguelands",
      unlock = { { area = 193 } },
      also = { "cult-of-the-damned", "scourge", "fall-of-lordaeron", "chillwind-camp" },
      text = {
        { "Andorhal supplied grain to northern Lordaeron. Kel'Thuzad's Cult of the Damned tainted its granaries, and the shipments carried the plague into the villages beyond. A prosperous town became a means of spreading death through the country that depended on it." },
        { "Arthas killed Kel'Thuzad here while pursuing the plague's source. The necromancer's death did not end his work. Andorhal remains in Scourge hands, its ruins ruled by Araj the Summoner. Both Chillwind Camp and the Bulwark seek the lich's destruction." },
        { side = "Horde", aside = true, sign = "P. F.", "The plague came north in Andorhal's grain, not behind an army. That is the part of the story people forget first." },
      },
    },
    ["caer-darrow"] = {
      title = "Caer Darrow", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 2298 } },
      also = { "scholomance", "house-of-barov", "cult-of-the-damned" },
      text = {
        { "Caer Darrow is a castle on an island in Lake Darrowmere, in the south of the Western Plaguelands, and it was the seat of the house of Barov, one of the great noble families of Lordaeron. It is a quiet, misty, beautiful place. Its town is full of ghosts." },
        { "The Barovs gave it away. To keep their fortune when the plague came, they made a bargain with Kel'Thuzad, and handed their castle to the Cult of the Damned, who dug beneath it the Scholomance, the Scourge's school of necromancy. The Barovs did not, in the end, keep much of anything." },
      },
    },
    ["chillwind-camp"] = {
      title = "Chillwind Camp", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 3197 } },
      also = { "andorhal", "plague-cauldrons", "house-of-barov", "argent-dawn" },
      text = {
        { "Commander Ashlam Valorfist leads the Alliance's camp in the southern hills of the Western Plaguelands, near Lake Darrowmere. Its tents have drawn soldiers, exiles and scholars, including Weldon Barov, the last living lord of his house." },
        { "From here the Alliance attacks Andorhal and works against the plague cauldrons. The camp has little comfort or supply to spare. If you have help to offer, traveller, Valorfist has good use for it. His tents are a small beginning for the work ahead." },
      },
    },
    ["dalsons-tears"] = {
      title = "Dalson's Tears", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 200 }, { quest = 5058 } },
      also = { "western-plaguelands", "plague-cauldrons", "andorhal" },
      text = {
        { "The farm the Plaguelands call Dalson's Tears belonged to a family named Dalson, and their story lies open on a table in the house, in Mrs. Dalson's own hand. Her husband, Harold, had turned. It took everything she had to drag him into the only place she could find that would lock, and she kept the key on her." },
        { "She meant to leave, but she needed money, and their things were in the cabinet, and she rather thought Harold kept that key on him. She would rest on it, she wrote. She was dead tired. That is the last entry. What became of her, the diary does not say." },
        { "The Scourge has set one of its plague cauldrons in the family's field since, and the Alliance at Chillwind and the Forsaken at the Bulwark both send travellers to turn its poisons back. Farm by farm, the Plaguelands are full of houses like this one. This is the one where somebody wrote it down." },
      },
    },
    ["hearthglen"] = {
      title = "Hearthglen", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 190 }, { area = 203 }, { quest = 5944 } },
      also = { "tirion-fordring", "scarlet-crusade", "western-plaguelands" },
      text = {
        { "Hearthglen surrounds Mardenholde Keep in the northern Western Plaguelands. The Scarlet Crusade holds its walls, and Grand Inquisitor Isillien keeps a green, surviving town in the middle of the plague country by ruthless means." },
        { "The keep was once Tirion Fordring's seat. When he was exiled for defending an orc who had saved his life, his wife told their son Taelan that he was dead. Taelan now holds his father's home for the Crusade. Tirion lives in a hut beside the Thondroril, gathering what he can of the boy's past and looking for a way to reach him." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron exiled a paladin for sparing an orc. The orcs now share their Horde with Lordaeron's dead, and I have not yet decided what to make of that." },
      },
    },
    ["house-of-barov"] = {
      title = "The House of Barov", kind = "history", chapter = "western-plaguelands",
      unlock = { { quest = 5342 }, { npc = 11023 }, { npc = 11022 } },
      also = { "caer-darrow", "scholomance", "chillwind-camp", "the-bulwark" },
      text = {
        { "The Barovs were a noble house of Lordaeron, rich and proud, lords of Caer Darrow. When the plague came, they made their bargain with Kel'Thuzad: their castle to the Cult of the Damned, in return for the safety of their fortune. Kel'Thuzad kept his word in his own way. The lord and his family are in the Scholomance still, as the Scourge's servants." },
        { "Two sons are left. Weldon Barov is alive, and sits under Alliance protection at Chillwind Camp. Alexi Barov is not, and keeps company with the Forsaken at the Bulwark. Each wants the family fortune. Each would like his brother's head on a plate, and each will pay a traveller to fetch it. Undeath has not ended this family quarrel." },
      },
    },
    ["plague-cauldrons"] = {
      title = "The Plague Cauldrons", kind = "history", chapter = "western-plaguelands",
      unlock = { { area = 199 }, { area = 200 }, { area = 202 }, { area = 201 }, { quest = 5215 }, { quest = 5228 }, { read = { "Compendium of the Fallen", "타락의 개요", "Compendium des Déchus", "Kompendium der Gefallenen", "堕落者纲要", "Compendio de los Caídos", "\"Компендиум павших\"", "Compêndio dos Caídos", "墮落者綱要" } } },
      also = { "scourge", "cult-of-the-damned", "royal-apothecary-society", "chillwind-camp", "the-bulwark" },
      text = {
        { "Eight plague cauldrons stand on the farms of the Plaguelands, four in the west and four in the east. Cauldron lords and the dead of the surrounding farmsteads guard them. Their fumes keep poisoning country that has already lost its people." },
        { "Kel'Thuzad's power prevents the Alliance and Forsaken from simply putting them out. Instead, workers at Chillwind and the Bulwark seek samples to prepare counteragents. Added to the cauldrons, these mixtures alter their emissions to weaken the Scourge. The supply must be renewed." },
      },
    },
    ["ras-frostwhisper"] = {
      title = "Ras Frostwhisper", kind = "figure", chapter = "western-plaguelands", portrait = 7919,
      unlock = { { kill = 10508 }, { quest = 5461 }, { quest = 5466 } },
      also = { "scholomance", "cult-of-the-damned", "kelthuzad", "stratholme", "stromgarde-keep" },
      text = {
        { "The lich who rules the halls of Scholomance was a man of Stromgarde once, Ras Frostwhisper by name. When the Scourge came to Stratholme he gave his life to it on the city's bloodied ground, freely and with a purpose, to become one of the undying. He oversees the school of necromancy now." },
        { "The undead fear life as the living fear death, Magistrate Marduke says, and a sentient undead will often destroy every reminder of who it was. Ras missed something. A keepsake of his mortal years still lay in the ruins of Stromgarde, and attuned on the ground where he died, it can make him mortal again: long enough, at least, to be struck down for good." },
        { "It is a rare thing to undo a lich. It is rarer still that the undoing should begin with something he forgot to throw away." },
      },
    },
    ["scholomance"] = {
      title = "Scholomance", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 2057 } },
      also = { "caer-darrow", "cult-of-the-damned", "house-of-barov", "scourge" },
      text = {
        { "Beneath Caer Darrow lies the Scholomance, the school of the Cult of the Damned, where necromancers are trained and the Scourge's dark arts are studied. Its headmaster is Darkmaster Gandling, and its halls are full of students, teachers and the things they practise on. Its door is barred to anyone without a key." },
        { "The Barovs are there too, or what is left of them: the lord and his lady, raised by the masters they sold their home to. Both the Alliance and the Forsaken want into the Scholomance, and both have found that the way in runs through a great deal of bad history." },
      },
    },
    ["taelan-fordring"] = {
      title = "Taelan Fordring", kind = "figure", chapter = "western-plaguelands", portrait = 10341,
      unlock = { { quest = 5944 } },
      also = { "tirion-fordring", "hearthglen", "scarlet-crusade", "the-ashbringer" },
      text = {
        { "Taelan Fordring grew up believing his father was dead. When Tirion was stripped of his lands for keeping his word to an orc, Taelan's mother stayed behind and told the boy that much. He joined the Scarlet Crusade, rose under the Grand Crusader, cast down the standard of the Silver Hand at Northdale, and became Highlord of the Crusade at Hearthglen." },
        { "He never stopped dreaming of his father, he says: of Tirion standing beside him on the day he was made a knight, of fighting the Scourge together, of honour to Lordaeron. When travellers bring him the things Tirion kept for him, and the truth about what the Crusade has become, he breaks with it and rides out to find his father." },
        { "He does not get far. Grand Inquisitor Isillien cuts him down outside Hearthglen, within sight of the man he was riding to meet, and Tirion kills Isillien over his son's body. The Order of the Silver Hand, Tirion says afterwards, is reborn. It cost him his son to remember what it was for." },
      },
    },
    ["the-felstones"] = {
      title = "The Felstones", kind = "history", chapter = "western-plaguelands", portrait = 10129,
      unlock = { { quest = 5051 } },
      also = { "western-plaguelands", "dalsons-tears", "plague-cauldrons", "stormwind-city", "undercity", "the-forsaken" },
      text = {
        { "Janice Felstone's ghost keeps to an upstairs corner of her house at Felstone Field, in a panic that has lasted four years. She had a parcel to send and meant to ride out with it, and the plague came first. The parcel was still in the barn where her horse had stood, dusty and addressed in a hurry. It held her personal things, and the deed to the farm." },
        { "Where it went depends on who carried it. In the Alliance's account it was addressed to her sister Emma in Stormwind, and the census there found her: Ol' Emma, who wanders the city talking to herself and had not heard her own name in years. In the Horde's, it went to her brother Jeremiah in Lordaeron, who died and rose and now sells cockroaches near the Undercity's bank under the name Payson. I hold both accounts and have given up reconciling them. Either way, the parcel held half of a good luck charm, and the sibling sent it back to her." },
        { "Janice had one half, and her husband John the other. She still calls for him. The other half turned up on the farm, on one of the ghouls. When the two halves were joined and put in her hand, she looked for the first time at the person holding them out and said she was free. I have not asked which ghoul it was." },
        { side = "Horde", aside = true, sign = "P. F.", "Jeremiah Payson sells his cockroaches fair and cheap. What he was before is his business, and I would ask the Alliance's historian to leave him the name he chose." },
      },
    },
    ["uthers-tomb"] = {
      title = "Uther's Tomb", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 196 }, { area = 197 }, { read = { "Uther the Lightbringer", "빛의 수호자 우서", "Uther, le Porteur de Lumière", "Uther Lightbringer", "光明使者乌瑟尔", "Uther el Iluminado", "Утер Светоносный", "Uther, o Arauto da Luz", "光明使者烏瑟" } } },
      also = { "fall-of-lordaeron", "church-of-the-holy-light", "western-plaguelands" },
      text = {
        { "Uther the Lightbringer was the first of the paladins, anointed by Archbishop Faol, the commander of the Knights of the Silver Hand, Prince Arthas's teacher, and the greatest champion the Light has had among men. He refused to take part in the purge of Stratholme, and Arthas dismissed him for it. When Arthas came back from Northrend with his cursed sword, Uther stood against him, guarding the urn that held King Terenas's ashes, and told his old pupil he hoped there was a special place in hell waiting for him. Arthas killed him." },
        { "His tomb stands on the hill of Sorrow above Lake Darrowmere, a white stone hall with his statue inside, in the middle of the dead country. It is quiet there, as nowhere else in the Plaguelands is, and those who still believe in the Light come to pay their respects." },
        { side = "Horde", aside = true, sign = "P. F.", "Terenas was my king, and Uther died keeping his ashes. I would like to see that tomb." },
      },
    },
    ["western-plaguelands"] = {
      title = "Western Plaguelands", kind = "place", chapter = "western-plaguelands",
      unlock = { { area = 28 } },
      also = { "chillwind-camp", "andorhal", "hearthglen", "scholomance", "scourge", "the-bulwark" },
      text = {
        { "The Western Plaguelands were once rich Lordaeron farmland. Infected grain carried undeath through its villages. Grey fields, rotting barns and blighted trees now surround the dead who still walk them. Green poison hangs over land that once fed the kingdom." },
        { "Chillwind Camp shelters the Alliance and Argent Dawn in the south, the Forsaken hold the Bulwark in the west, and the Scarlet Crusade keeps Hearthglen in the north. Between those footholds lie Andorhal, the plague cauldrons and Scholomance on the lake. A traveller's route through this country is measured by where the living can still hold ground." },
      },
    },
    ["edwin-vancleef"] = {
      title = "Edwin VanCleef", kind = "figure", chapter = "westfall", portrait = 2029,
      unlock = { { kill = 639 }, { quest = 166 } },
      also = { "defias-brotherhood", "the-deadmines", "noble-conspiracy", "peoples-militia" },
      text = {
        { "Edwin VanCleef was the master of the Stonemasons' Guild, the man who rebuilt Stormwind, and when the nobles refused to pay his masons, he stood with the men who had worked under him. He led them in a riot through the streets they had built, and out of the city, and in Westfall the guild became the Defias Brotherhood." },
        { "He led it to the end, from his ship in the depths of the Deadmines, and he never forgave Stormwind. On his body, those who finally reached him found a letter, sealed and never sent, to the City Architect. Where that letter led is another story." },
        { "I have tried to write of him fairly. He was wronged, and he did great wrong in return, and the farmers of Westfall paid for both." },
      },
    },
    ["moonbrook"] = {
      title = "Moonbrook", kind = "place", chapter = "westfall",
      unlock = { { area = 20 } },
      also = { "the-deadmines", "defias-brotherhood", "westfall" },
      text = {
        { "Moonbrook was the market town of Westfall's farms and the home of its miners, burned by the orcs in the First War and rebuilt after the Second. Now it is a Defias town: its people driven out, its houses full of red-masked bandits, and its old smithy and its barn hiding the way down into the Deadmines." },
        { "It is a sad place to walk through, and not a safe one. The Brotherhood watches the road, and anyone who looks too long at a certain barn on the edge of town is likely to find out why." },
      },
    },
    ["peoples-militia"] = {
      title = "The People's Militia", kind = "faction", chapter = "westfall", portrait = 1690,
      unlock = { { npc = 234 } },
      also = { "sentinel-hill", "defias-brotherhood", "edwin-vancleef" },
      text = {
        { "When Stormwind's soldiers did not come, the people of Westfall raised their own. The People's Militia is a few soldiers, a great many farmers, and one paladin to lead them: Gryan Stoutmantle, who would not see Westfall given up to the Brotherhood." },
        { "From Sentinel Hill they patrol what roads they can, hunt the gnolls and the Defias, and send their scouts into the Dagger Hills and the ruins of Moonbrook. Stoutmantle has his own friends in low places, and it was through one of them, a rogue in Lakeshire, that he learned who leads the Brotherhood and where they hide." },
      },
    },
    ["sentinel-hill"] = {
      title = "Sentinel Hill", kind = "place", chapter = "westfall",
      unlock = { { area = 108 } },
      also = { "peoples-militia", "westfall" },
      text = {
        { "Sentinel Hill is a stone watchtower on a rise in the middle of Westfall, and it is the last place in the province where the law still means something. The People's Militia hold it: a handful of soldiers and a great many former farmers under the paladin Gryan Stoutmantle, who would rather fight for their land than walk away from it." },
        { "There is not much here: the tower, a few tents, a stable and an inn, and a good view of how bad things have become. But every traveller who wants to help Westfall comes here first, and the Militia have more work than hands." },
      },
    },
    ["the-deadmines"] = {
      title = "The Deadmines", kind = "place", chapter = "westfall",
      unlock = { { area = 1581 } },
      also = { "moonbrook", "edwin-vancleef", "defias-brotherhood" },
      text = {
        { "The Deadmines once supplied Stormwind with gold. Abandoned when the orcs came, they became an ogre's den during the First War. Sir Anduin Lothar entered them to recover a holy book stolen from Northshire and was captured himself. Soldiers from Stormwind brought out both the knight and the book." },
        { "The Defias have since dug deeper. Their workings contain goblin engineers, a foundry and a shredder, and below the old shafts a hidden cove holds a great warship under construction. VanCleef's plans extend well beyond stealing from farms. If you descend, traveller, be prepared for rather more than a disused mine." },
      },
    },
    ["westfall"] = {
      title = "Westfall", kind = "place", chapter = "westfall",
      unlock = { { area = 40 } },
      also = { "sentinel-hill", "moonbrook", "peoples-militia", "defias-brotherhood", "gnolls" },
      text = {
        { "Westfall was the breadbasket of Stormwind: wide golden fields, windmills and farmsteads running down to the sea. The orcs burned it in the wars, and the farmers came back and planted again. What the orcs could not finish, the Defias have." },
        { "The Brotherhood made Westfall its own. They drove the farm families off their land one stead at a time, took Moonbrook for their town and the old mines beneath it for their fortress, and the king's army never came. \"Stormwind has abandoned us,\" the men on Sentinel Hill will tell you, and it is hard to argue. Now the fields are dry, the gnolls of the Riverpaw raid the farms, and harvest golems stalk the furrows. Murlocs hold the coast, and even the lighthouse is haunted." },
        { "A few stubborn farmers have stayed. Ask Farmer Saldean why, and he will tell you it is his land." },
      },
    },
    ["dragonmaw-clan"] = {
      title = "The Dragonmaw Clan", kind = "faction", chapter = "wetlands", portrait = 4916,
      unlock = { { kill = 1034 }, { kill = 1035 }, { kill = 1036 }, { kill = 1037 }, { kill = 1038 }, { kill = 1057 }, { kill = 2102 }, { kill = 2103 }, { area = 1036 } },
      also = { "grim-batol", "red-dragonflight", "nekrosh" },
      text = {
        { "The Dragonmaw rode red dragons into battle in the Second War. At Grim Batol they held Alexstrasza captive and forced her children to serve the Horde. Their mastery of the sky rested on the imprisonment of a mother and her young." },
        { "The dragons' liberation broke the clan's strength, but Dragonmaw remnants still hold the hills of the Wetlands and raid its roads. These are survivors of the old Horde, rather than followers of the new one." },
      },
    },
    ["dun-modr"] = {
      title = "Dun Modr", kind = "place", chapter = "wetlands",
      unlock = { { area = 205 } },
      also = { "dark-iron-dwarves", "thandol-span" },
      text = {
        { "Dun Modr was built to guard the southern end of the Thandol Span, and for many years it did. Now it flies no Bronzebeard banner. The Dark Irons have taken it, and from its walls they strike at the Span and at anyone travelling the road north." },
        { "It is a bitter thing for any dwarf of Ironforge to see dwarven halls held against us by dwarves. It reminds us that the War of the Three Hammers never really ended." },
        { "If you pass close, keep your head down. Their riflemen are very good." },
      },
    },
    ["excavation-site-wetlands"] = {
      title = "Excavation Site: Wetlands", kind = "place", chapter = "wetlands",
      unlock = { { area = 16732 }, { area = 17732 }, { area = 16877 }, { area = 16878 }, { area = 16879 }, { area = 16880 }, { quest = 95810 }, { quest = 95795 } },
      also = { "whelgars-excavation-site", "explorers-league", "dragonmaw-clan", "deathstalkers", "earthen-ring", "wetlands" },
      text = {
        { "Prospector Whelgar's marsh is not the only dig in the Wetlands. A crew out of Loch Modan went up into the hills above it, into country no dwarf had set foot in, and found ruins, a second marsh up there with raptors and grasses taller than anything the diggers had seen, and something much older underneath. Not all of them have come back. Dorin Songblade, the smith in Lakeshire, has heard nothing from his brother Daewyn since the letters stopped, and Ardin Grassman of Menethil went up for the grasses and has not come back." },
        { "The crew's dig has turned up shards of a strange composite stone that throws light like a living prism, and pieces of a machine built of rock. Rethiel the Greenwarden feels an ancient energy stirring under that marsh and wants the digging stopped. The elders of Thunder Bluff, the Earthen Ring and our own Hall of Explorers all want the relics, and I expect each will find in them what it hoped to." },
        { "Others have noticed. The Dragonmaw have moved in, hoping the place will win them back their old power and the favour of Rend Blackhand, and the Dark Lady's Deathstalkers are watching them. A titan machine, a dragon clan and the Forsaken's spies, all on one damp hillside." },
      },
    },
    ["grim-batol"] = {
      title = "Grim Batol", kind = "history", chapter = "wetlands",
      unlock = { { area = 1037 }, { read = { "The Battle of Grim Batol", "그림 바톨의 전투", "La bataille de Grim Batol", "Die Schlacht von Grim Batol", "格瑞姆巴托之战", "La batalla de Grim Batol", "Битва при Грим Батол", "A Batalha de Grim Batol", "格瑞姆巴托之戰" } } },
      also = { "war-of-the-three-hammers", "red-dragonflight", "dragonmaw-clan" },
      text = {
        { "When the Wildhammers were driven from Ironforge, they carved Grim Batol out of the eastern mountains, and it was a fortress to rival Ironforge itself. Then the Dark Irons came against it, led by Queen Modgud, and though the Wildhammers won the battle and slew her, her death left a darkness in the stone. The Wildhammers would not stay. They went north to the Hinterlands, and Grim Batol stood empty." },
        { "It did not stay empty. In the Second War the orcs of the Dragonmaw clan made it their stronghold, and there they held Alexstrasza, the queen of the red dragons, prisoner, and forced her children to carry orcs into battle. She was freed in the end, and the Dragonmaw were scattered." },
        { "The red dragons are there still. Whatever they guard in Grim Batol, they guard it fiercely. Do not go near, traveller. The red dragonkin on its approaches are warning enough." },
      },
    },
    ["menethil-harbor"] = {
      title = "Menethil Harbor", kind = "place", chapter = "wetlands",
      unlock = { { area = 150 } },
      also = { "wetlands" },
      text = {
        { "Menethil Harbor stands on the western shore of the Wetlands, an Alliance port with ships bound for Auberdine and Theramore. The road through Dun Algaz joins it to the country inland. A damp little town can be an important place when so many journeys pass through it." },
        { "Captain Stoutfist needs help against the Dragonmaw orcs threatening the harbor. He asks for their catapults to be destroyed and Chieftain Nek'rosh defeated. Attend to him if you can, traveller. There are people here trying to keep a port open while an enemy prepares to besiege it." },
      },
    },
    ["mosshide-gnolls"] = {
      title = "The Mosshide Gnolls", kind = "faction", chapter = "wetlands", portrait = 3199,
      unlock = { { kill = 1007 }, { kill = 1008 }, { kill = 1009 }, { kill = 1010 }, { kill = 1011 }, { kill = 1012 }, { kill = 1013 }, { kill = 1014 }, { area = 1020 } },
      also = { "wetlands", "gnolls" },
      text = {
        { "The Mosshide inhabit the Wetlands fen that carries their name. Rethiel the Greenwarden remembers years in which they lived there peacefully. Now he sees growing numbers, flattened vegetation and too much timber cut for their fires." },
        { "He asks travellers to kill gnolls near Dun Algaz to restore the marsh's balance. His account makes this a quarrel over a shared home that has become crowded and damaged. The axes and fires are familiar enough to a dwarf. They are troubling things to find in somebody else's complaint about what is happening to the land." },
      },
    },
    ["nekrosh"] = {
      title = "Chieftain Nek'rosh", kind = "figure", chapter = "wetlands", portrait = 4915,
      unlock = { { kill = 2091 }, { quest = 474 } },
      also = { "dragonmaw-clan", "grim-batol" },
      text = {
        { "Nek'rosh Skullcrusher leads what remains of the Dragonmaw in the Wetlands, and he is his father's son: Nekros Skullcrusher was the orc who held the dragon queen captive at Grim Batol. When the dragons broke free, they took their revenge on the clan. Nek'rosh means to take his." },
        { "He is rebuilding the Dragonmaw's strength in the hills, and he has had catapults built to lay siege to Menethil Harbor and cut the road to Loch Modan." },
        { "If you are the one who stops him, traveller, the League would be grateful for an account of how. Brief, if you can manage it. Accounts of orc chieftains tend to run long." },
      },
    },
    ["red-dragonflight"] = {
      title = "The Red Dragonflight", kind = "creature", chapter = "wetlands", portrait = 363,
      unlock = { { kill = 1045 }, { kill = 1046 }, { kill = 1047 }, { kill = 1048 }, { kill = 1049 }, { kill = 1050 }, { read = { "The Skull of Tyrannistrasz", "티란니스트라즈의 뼈", "Le crâne de Tyrannistrasz", "Der Schädel des Tyrannistrasz", "塔兰尼斯塔兹的颅骨", "El cráneo de Tyrannistrasz", "Череп Тираннистраса", "O Crânio de Tyrannistrasz", "塔蘭尼斯塔茲的顱骨" } } },
      also = { "grim-batol", "dragonmaw-clan", "black-dragonflight" },
      text = {
        { "Alexstrasza is called the Life-Binder, queen of the red dragons and one of the world's oldest powers. During the Second War, the Dragonmaw held her captive at Grim Batol and forced her children into their service. The flight has since been freed." },
        { "Red dragonkin still guard the approaches to Grim Batol. They treat intruders as enemies, whatever business those intruders believe brings them there. Keep your distance, traveller. Knowing what happened to them here does not make an intruder welcome." },
      },
    },
    ["thandol-span"] = {
      title = "The Thandol Span", kind = "place", chapter = "wetlands",
      unlock = { { area = 881 }, { area = 880 } },
      also = { "dark-iron-dwarves", "dun-modr", "wetlands" },
      text = {
        { "The Thandol Span carried the road north from Khaz Modan into Arathi and the human kingdoms beyond. Its two great dwarven bridges served that road for generations. An engineer might ask you to admire the stonework. Those who depended on the crossing had reason to admire it too." },
        { "The Dark Irons have all but destroyed one bridge. Dwarven soldiers hold the other, and the road remains open under their guard. A fine piece of engineering is easier to praise when someone else is keeping it standing." },
        { "Look across at the broken span as you pass, traveller. Both bridges were built to carry people over the water. Only one still can." },
      },
    },
    ["the-third-fleet"] = {
      title = "The Third Fleet", kind = "history", chapter = "wetlands",
      unlock = { { quest = 293 } },
      also = { "menethil-harbor", "wetlands", "red-dragonflight", "dragonmaw-clan", "the-second-war" },
      text = {
        { "The wrecks on the Wetlands' northern shore were the Third Fleet of Kul Tiras. On its last voyage it was caught off this coast by red dragons, dragons ridden by orcs, and burned and sunk where it lay. The Kul Tirans call it the Doomed Fleet." },
        { "One man came out of it alive: Fitzsimmons, once first mate of the Wave Mistress, who drinks in Menethil Harbor and will tell the story for the price of a flagon. His shipmates are not all at rest. Something was stowed aboard the Intrepid, locked in the captain's strongbox, and its power keeps the drowned crews walking their rotting decks. Captain Halyndor still walks his ship with the key." },
        { "What lay in that box was an Eye of Paleth, one of the orbs human priests made to shine bright, cursed black by whatever it saw that night. The priests of Menethil could not cleanse it. The Archbishop in Stormwind could. A fleet does not always die all at once, traveller. Sometimes it takes a priest and a stubborn first mate to finish the matter." },
      },
    },
    ["wetlands"] = {
      title = "The Wetlands", kind = "place", chapter = "wetlands",
      unlock = { { area = 11 } },
      also = { "menethil-harbor", "grim-batol", "thandol-span", "algaz" },
      text = {
        { "North of the mountains the ground turns soft and the air turns grey, and you are in the Wetlands: marsh, reed and rain, from the pass of Dun Algaz to the sea at Menethil Harbor." },
        { "Once this was dwarven country, joined to the kingdoms of men by the Thandol Span. Now it is a crossroads of other people's wars. The Dragonmaw orcs hold the hills, the Dark Irons have taken our fortress at Dun Modr, gnolls and murlocs fill the marshes, and in the east, Grim Batol broods over all of it." },
        { "Keep to the road, keep your powder dry, and do not linger after dark." },
      },
    },
    ["whelgars-excavation-site"] = {
      title = "Whelgar's Excavation Site", kind = "place", chapter = "wetlands",
      unlock = { { area = 118 } },
      also = { "explorers-league", "wetlands" },
      text = {
        { "Another of the League's digs, this one in the marshes of the Wetlands, under Prospector Whelgar. The marsh keeps what it swallows, and the League had high hopes for what lay beneath it." },
        { "Then the raptors came. They moved into the dig and treated the diggers as fair game, and the League's people were driven out onto a ridge above the site, where some of them are waiting still for the beasts to leave." },
        { "If you are passing, look in on them. They will be very glad to see someone carrying a weapon." },
      },
    },
    ["everlook"] = {
      title = "Everlook", kind = "place", chapter = "winterspring",
      unlock = { { area = 2255 } },
      also = { "steamwheedle-cartel", "winterspring", "argent-dawn", "thorium-brotherhood" },
      text = {
        { "Everlook is a goblin town in the middle of Winterspring, the northernmost of the Steamwheedle Cartel's ports of call, with walls, an inn, a bank and a guard of goblin bruisers, where Alliance and Horde trade side by side. It is warmer inside than you would think, and far more expensive." },
        { "Everyone comes through Everlook. The Argent Dawn keeps a representative here, the Thorium Brotherhood a smith, and all the hunters, explorers and scholars of the north stop in to warm their feet." },
      },
    },
    ["mazthoril"] = {
      title = "Mazthoril", kind = "place", chapter = "winterspring",
      unlock = { { area = 2245 } },
      also = { "winterspring", "nefarian", "black-dragonflight", "azuregos" },
      text = {
        { "Mazthoril is a great cave of ice in the middle of Winterspring, deep and cold and full of blue dragons. It is the home of the blue dragonflight in Kalimdor, and runes of cobalt on its floor carry those who know their use to Haleh, their matron protectorate." },
        { "The blue dragons are the guardians of magic, and they are watching the black dragonflight very closely. They know what Nefarian is breeding in Blackrock Spire, and that it cannot be allowed. And since they cannot easily reach him in his mountain, they are ready to help mortals who can." },
      },
    },
    ["ruins-of-keltheril"] = {
      title = "The Ruins of Kel'Theril", kind = "history", chapter = "winterspring",
      unlock = { { area = 2252 }, { area = 2251 } },
      also = { "winterspring", "starfall-village", "the-sundering", "fandral-staghelm" },
      text = {
        { "By the frozen Lake Kel'Theril lie the ruins of a Highborne town, and its Highborne are still there, as ghosts. Long ago, they stole a sacred relic, the Crystal of Zin-Malor, from its temple, meaning to drain its power for themselves. The ritual went wrong. The crystal shattered in a great explosion, and its pieces were driven below the ice of the lake." },
        { "The Highborne were cursed to stay where they had done it, searching for the pieces forever. When at last someone gathered them and made the crystal whole, one of the ghosts spoke: it was sorry, and it knew that nothing could change the past, but it was at peace. The crystal's temple lies in ruins, so it went instead to the Arch Druid in Darnassus." },
      },
    },
    ["starfall-village"] = {
      title = "Starfall Village", kind = "place", chapter = "winterspring",
      unlock = { { area = 2253 } },
      also = { "winterspring", "ruins-of-keltheril", "cenarion-circle", "fandral-staghelm" },
      text = {
        { "Starfall Village is a small night elf settlement in the snows of Winterspring, where druids and scholars live among the trees. Its people study the land and its creatures, and the old ruins by the lake." },
        { "It was a scholar of Starfall who learned what the wildkin of Winterspring are: not beasts, but creatures of Elune, the moon goddess. The Arch Druid in Darnassus was very interested. So was I." },
      },
    },
    ["storm-shadowhoofs-trials"] = {
      title = "Storm Shadowhoof's Trials", kind = "creature", chapter = "winterspring", portrait = 10113,
      unlock = { { kill = 10806 }, { kill = 10807 }, { kill = 10737 }, { quest = 5054 }, { quest = 5055 }, { quest = 5056 } },
      also = { "winterspring", "everlook", "the-great-hunts", "tauren", "wintersaber-trainers" },
      text = {
        { "The hunter's path, as the tauren teach it, begins young and runs a long way. Old Skorn Whitecloud sends the eager to Melor Stonehoof on the Hunter's Rise in Thunder Bluff, and Melor sends them out. Through the Barrens with Sergra Darkthorn. To the Thousand Needles after Steelsnap, a hyena tyrant outside the Earthmother's blessing. Up into the snows of Alterac for Frostmaw, a yeti who rarely shows himself. Into Dustwallow to end the pain of Deadmire, an ancient crocolisk whose great spirit is tortured by his own old body. Such is the way of the hunter, Melor tells them: it leads at last through all the Earthmother's lands." },
        { "In Winterspring it reaches Storm Shadowhoof, who keeps to Everlook and sets three hunts. Ursius of the Shardtooth bears, in the hills north-west of the town, is so clever that those who hunt him soon find themselves the prey. Brumeran of the Chillwind glides among the chimaera of the south, graceful and swift, and makes those who cross her pay, often with their lives. Shy-Rotam is the matriarch of the frostsabers who gather at Frostsaber Rock, and she comes in anger to her stone when the meat of her kin is laid there." },
        { "The last trial is to go home. Storm gives the hunter a marker for Melor, who will remember them from the start of the road, long ago. I would not mention Shy-Rotam to the Sentinels who raise wintersabers on that same rock." },
      },
    },
    ["the-winterfall-firewater"] = {
      title = "The Winterfall Firewater", kind = "history", chapter = "winterspring",
      unlock = { { quest = 5123 }, { quest = 5128 } },
      also = { "winterspring", "furbolgs", "timbermaw", "felwood" },
      text = {
        { "Donova Snowden came to Winterspring to study the Frostfire Hot Springs. There are no volcanoes in this country, so she believes the demons of Darkwhisper Gorge, to the south, warm the water. What she had not counted on was the Winterfall. They are not normally an aggressive tribe, but they had begun to guard the larger springs as fiercely as she wanted to study them, and they carried little vials of a green liquid that almost glowed." },
        { "The trail led through Timbermaw Hold to the Deadwood, the Felwood furbolgs the fel has driven mad. In a Deadwood cauldron bubbled the same green stuff, and Donova found where it came from: toxic matter gathered from the corrupted elementals of the Irontree Woods. Raw, it is poison. Mixed with the water of the hot springs, it loses its poison and keeps only its hold on whoever drinks it. That is why the Winterfall guard the springs, and why their runners walk the long road to Felwood and back. Dwarves know a little about brewing, and I have never heard of a brewery quite like it. Donova wondered whether the brew made them more aggressive. The Winterfall did seem much larger." },
        { "She reckoned that with High Chief Winterfall dead the tribe would get no worse, though nothing could undo the harm already done. The High Chief's log is written in marks so crude that Donova could make nothing of it. Kelek Skykeeper of the Emerald Circle, druids who work to heal Felwood, has it now and has promised word once he can read it. Of the Winterfall themselves, Kelek admits, very little is known." },
      },
    },
    ["winterspring"] = {
      title = "Winterspring", kind = "place", chapter = "winterspring",
      unlock = { { area = 618 } },
      also = { "everlook", "starfall-village", "ruins-of-keltheril", "mazthoril", "furbolgs" },
      text = {
        { "Winterspring is the high, snowy valley north of Felwood and east of Moonglade, a land of deep snow, frozen lakes and hot springs that steam in the cold. Frostsabers hunt here, and owls, yetis, giants and the wildkin. The night elves raise their frostsabers at Frostsaber Rock, and the druids keep a village at Starfall." },
        { "The furbolgs of the Winterfall tribe are drinking a corrupted firewater, brought up from Felwood, and going mad with it. The blue dragons have their lair in the caves of Mazthoril, and the goblins of Everlook sell everything to everyone at the crossroads." },
      },
    },
    ["shrine-of-akir"] = {
      title = "The Shrine of Akir", kind = "place", chapter = "zephras-isle",
      unlock = { { quest = 93836 }, { quest = 94369 } },
      also = { "the-al-aketh", "talaanis-shadowsong", "the-high-order", "the-windshapers" },
      text = {
        { "The Shrine of Akir, in the Shen'dar Highlands, is the holy place of the Al'Aketh and was the seat of their leader, the High Priestess Lorthuna. Taking it needed the High Order, the Windshapers and the peacekeepers together, which tells you something about the cult's strength and more about how rarely those three agree. Valennia Stormfist, the peacekeepers' captain, was gravely wounded in the inner sanctum, and Lorthuna fled by a portal to the Rohashi Spires above." },
        { "What happened on the spires, the shen'dorei have not set down for us. Lorthuna is gone from Zephras and the cult has lost its head. But the wards that hid the island from Al'Akir came down with her, and the High Elder will not pretend to know how long the Windlord will take to notice." },
      },
    },
    ["talaanis-shadowsong"] = {
      title = "Talaanis Shadowsong", kind = "figure", chapter = "zephras-isle",
      unlock = { { npc = 252476 } },
      also = { "valanaar", "the-al-aketh", "shrine-of-akir" },
      text = {
        { "Talaanis Shadowsong is High Elder of Zephras Isle, and his people speak well of him. A good man, they say, and well loved, which the League has learned not to take for granted in a ruler. He governs from Valanaar with the island's other elders, Aetheen of the Gales among them." },
        { "His years in office have not been easy ones. The pylons are failing, the two orders of his people can barely agree on anything, and the Al'Aketh cult struck the western watchtower and killed his own nephew, a peacekeeper. When the cult's high priestess was at last driven out, he did not call it a victory. The wards that had hidden Zephras from Al'Akir were down, and he could only say that it might be years, even decades, before the Windlord turned his eye on them." },
      },
    },
    ["the-al-aketh"] = {
      title = "The Al'Aketh", kind = "faction", chapter = "zephras-isle",
      unlock = { { kill = 251145 }, { kill = 251160 }, { kill = 251448 }, { kill = 251451 }, { kill = 252068 }, { kill = 252664 }, { kill = 252665 }, { kill = 252762 }, { kill = 252763 }, { kill = 252764 }, { kill = 252765 }, { kill = 252767 }, { kill = 253195 }, { kill = 253511 }, { kill = 253782 }, { kill = 254596 }, { kill = 254626 }, { kill = 256996 }, { kill = 270201 } },
      also = { "shrine-of-akir", "talaanis-shadowsong", "the-silence-of-the-winds" },
      text = {
        { "The Al'Aketh are a cult of the shen'dorei, known by their grey robes and shaved heads, who worship Al'Akir the Windlord as the rightful ruler of Skywall. Their preachers tell a simple story: the shen'dorei grew proud and took the bounty of the winds for granted, and the spirits abandoned them for it. On an island that is coming apart, it finds listeners." },
        { "They hold Falaath Village in the Shen'dar Highlands, and the Shrine of Akir under their High Priestess, Lorthuna. They have struck at the pylon watchtowers, fallen on the druids of the Nightclaw for a pylon of their own, sent spies among the villages and found at least one traitor in Valanaar. A former peacekeeper, Belguilos, called the Breaker, commands their fighters." },
      },
    },
    ["the-high-order"] = {
      title = "The High Order", kind = "faction", chapter = "zephras-isle",
      unlock = { { npc = 252475 }, { npc = 253812 }, { npc = 253847 }, { quest = 92596 } },
      also = { "the-windshapers", "the-silence-of-the-winds", "dalaran" },
      text = {
        { "The High Order are the shen'dorei who hold to the arcane, and to their descent from the Highborne scholars of Eldre'Thalas. When the wind spirits left, they drew a hard lesson from it: their people had leaned on their elemental patrons so entirely that without them they were helpless. The High Order means to recover the lore their ancestors lost and stand on its own feet, and its Supreme Magister, Elaadrin Evengale, looks to the Kirin Tor of Dalaran to show them how." },
        { "The Windshapers call them reckless and arrogant. The High Order calls that hypocrisy. They have paid for their confidence. Elaadrin sent Belathaan Brightwish to open talks with the Al'Aketh at the Shrine of Akir, and Belathaan never came back. The cult returned his tongue in a box, dipped in silver. Afterwards, Elaadrin admitted that the Windshapers had been right." },
      },
    },
    ["the-shalnan"] = {
      title = "The Shal'nan", kind = "history", chapter = "zephras-isle",
      unlock = { { area = 16635 }, { area = 16638 } },
      also = { "foreword-skyborne", "zephras-isle", "valanaar" },
      text = {
        { "The shen'dorei remember the leader who brought them out of Eldre'Thalas only as the Shal'nan, the Veiled One, for the featureless golden mask that hid his face. When Prince Tortheldrin's ambitions turned dark, the Shal'nan's rebels broke the network of crystal foci the prince depended on, and fled. It was the Shal'nan who made peace with the wind spirits and led his people up into Skywall." },
        { "He ruled them for more than a century, a reluctant leader by their own account, and then gave up his authority to a council of the provinces once the island sanctuaries were founded. A crystal kept high in the great tree at Thendal Village tells his story. It does not say what became of him, and neither, so far, have the shen'dorei." },
      },
    },
    ["the-silence-of-the-winds"] = {
      title = "The Silence of the Winds", kind = "history", chapter = "zephras-isle",
      unlock = { { quest = 94414 }, { quest = 93552 }, { area = 16833 } },
      also = { "zephras-isle", "the-windshapers", "the-high-order", "the-al-aketh" },
      text = {
        { "For thousands of years the wind spirits kept Zephras Isle aloft and the shen'dorei in their care. Some centuries ago they left, and nothing the shen'dorei have tried since has brought them back or explained why. The sprites still playing over the island are echoes, without the minds of the spirits who once spoke with them." },
        { "What the spirits left behind is wearing out. Their anchor pylons bind the island together, and their magic now comes and goes. Ley lines have begun to break the surface like scars, and windstones, which hold the raw power of the winds, are gathered and studied in earnest. Each of the island's factions has its answer. The Windshapers would find the spirits and bring them home, the High Order would learn to live without them, and the Al'Aketh would kneel to the Windlord instead." },
      },
    },
    ["the-windshapers"] = {
      title = "The Windshapers", kind = "faction", chapter = "zephras-isle",
      unlock = { { npc = 251968 }, { npc = 253813 }, { npc = 253849 }, { quest = 92595 } },
      also = { "the-high-order", "the-silence-of-the-winds", "the-al-aketh" },
      text = {
        { "The Windshapers are the shen'dorei who keep faith with the wind spirits. They descend from the first of their people to receive the spirits' gift of skysight, and they tended the instruments and constructs the spirits left on the island. They have sworn to repay that old debt: to brave the elemental plane, find their missing mentors and bring them home. Their Grand Skyseer, Ayessa Dawnsinger, believes the way lies below, in Azeroth, and the shamans of the Earthen Ring have stood with them." },
        { "They are not a forgiving people. To the cult's violence Ayessa answered blood for blood, and the Windshapers say of themselves that they neither forgive nor forget. They want no peace with the Al'Aketh, and they hold the High Order's magic at their sacred sites to be a danger to an island already coming apart." },
      },
    },
    ["valanaar"] = {
      title = "Valanaar", kind = "place", chapter = "zephras-isle",
      unlock = { { area = 16638 }, { area = 16628 } },
      also = { "zephras-isle", "talaanis-shadowsong", "the-shalnan" },
      text = {
        { "Valanaar is the capital of Zephras Isle, on its south-eastern edge, and the seat of its High Elder. The skycutters put in at its docks: small flying ships that once ran between the islands of the shen'dorei and now, for the first time, go down to Azeroth, to Dalaran for the High Order and to Mulgore for the Windshapers." },
        { "If you pass through, look in at the Calmbreeze Inn. Upstairs the shen'dorei keep a crystal that recounts their ancestors' rebellion in Eldre'Thalas from their own side. I know of nothing older that speaks for them, and I would give a good deal to hear it." },
      },
    },
    ["zephras-isle"] = {
      title = "Zephras Isle", kind = "place", chapter = "zephras-isle",
      unlock = { { area = 16593 } },
      also = { "valanaar", "the-silence-of-the-winds", "the-shalnan", "foreword-skyborne" },
      text = {
        { "Zephras Isle is an island that flies. It hangs in Skywall, the elemental plane of air, where the wind spirits carried the shen'dorei long ago, and it is home to the Skyborne who have lately come down to us. Its people live in Valanaar on the south-eastern edge, in the villages of the Shen'dar Highlands and at Thendal, and on the farms of the Gustberry Lowlands." },
        { "The spirits who bound the island left it some centuries ago. Their great anchor pylons still hold Zephras up, but their magic grows unsteady, and Ban'aethal began to fall into the sky one night and had to be emptied before morning. No skycutter has crossed to the other islands, Anvilas and Siroccas, for some time, and there are shen'dorei who fear they are all that is left of their people." },
        { "I have never stood there, traveller, and I envy you a little. Do keep away from the edges." },
      },
    },
  },
